function proofIndexPool() {
  if (!proofIndexDatabaseConfigured()) {
    return null;
  }

  if (!proofIndexReadPool) {
    proofIndexReadPool = createProofIndexPool({
      env: {
        ...process.env,
        POW_INDEX_DB_APP_NAME:
          process.env.POW_INDEX_DB_APP_NAME ?? "proof-index-reader",
      },
    });
  }

  return proofIndexReadPool;
}

function workDefinitionStorageModel(row) {
  const metadata = objectRecord(row?.metadata);
  const q8 =
    String(row?.max_supply ?? "") === WORK_TOKEN_MAX_SUPPLY_ATOMS &&
    String(row?.mint_amount ?? "") === WORK_TOKEN_MINT_AMOUNT_ATOMS &&
    metadata.amountStorageModel === WORK_ATOMIC_PROJECTION_MODEL &&
    Number(metadata.decimals) === WORK_DECIMALS &&
    String(metadata.unitScale ?? "") === WORK_UNIT_SCALE_TEXT;
  const q16 =
    String(row?.max_supply ?? "") ===
      WORK_TOKEN_MAX_SUPPLY_SUBATOMS &&
    String(row?.mint_amount ?? "") ===
      WORK_TOKEN_MINT_AMOUNT_SUBATOMS &&
    metadata.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL &&
    Number(metadata.decimals) === WORK_SUBATOM_DECIMALS &&
    String(metadata.unitScale ?? "") ===
      WORK_SUBATOM_UNIT_SCALE_TEXT &&
    metadata.precisionModel === WORK_AMO_V8_GLOBAL_PRECISION_MODEL;
  return q8
    ? WORK_ATOMIC_PROJECTION_MODEL
    : q16
      ? WORK_SUBATOM_PROJECTION_MODEL
      : "";
}

async function currentWorkAmountStorageModel(pool, network) {
  const result = await pool.query(
    `
      SELECT max_supply::text, mint_amount::text, metadata
      FROM proof_indexer.credit_definitions
      WHERE network = $1 AND token_id = $2
      LIMIT 2
    `,
    [network, WORK_TOKEN_ID],
  );
  return result.rows.length === 1
    ? workDefinitionStorageModel(result.rows[0])
    : "";
}

async function workAmountStorageModelAtHeight(
  pool,
  network,
  blockHeight,
) {
  const currentModel = await currentWorkAmountStorageModel(
    pool,
    network,
  );
  if (!currentModel) {
    return "";
  }
  if (currentModel === WORK_ATOMIC_PROJECTION_MODEL) {
    return WORK_ATOMIC_PROJECTION_MODEL;
  }
  const height = safeBlockHeight(blockHeight);
  if (!height) {
    return WORK_SUBATOM_PROJECTION_MODEL;
  }
  const markerResult = await pool.query(
    `
      SELECT value
      FROM proof_indexer.meta
      WHERE key = $1
      LIMIT 2
    `,
    [WORK_PRECISION_V2_MIGRATION_META_KEY],
  );
  const marker = objectRecord(markerResult.rows[0]?.value);
  const activationHeight = safeBlockHeight(marker.activationHeight);
  if (
    markerResult.rows.length !== 1 ||
    marker.network !== network ||
    marker.status !== "complete" ||
    marker.model !== WORK_PRECISION_V2_MIGRATION_MODEL ||
    marker.projectionModel !== WORK_SUBATOM_PROJECTION_MODEL ||
    Number(marker.decimals) !== WORK_SUBATOM_DECIMALS ||
    String(marker.unitScale ?? "") !==
      WORK_SUBATOM_UNIT_SCALE_TEXT ||
    marker.globalPrecisionModel !== WORK_AMO_V8_GLOBAL_PRECISION_MODEL ||
    String(marker.maxSupplySubatoms ?? "") !==
      WORK_TOKEN_MAX_SUPPLY_SUBATOMS ||
    String(marker.mintAmountSubatoms ?? "") !==
      WORK_TOKEN_MINT_AMOUNT_SUBATOMS ||
    !activationHeight
  ) {
    return "";
  }
  return height < activationHeight
    ? WORK_ATOMIC_PROJECTION_MODEL
    : WORK_SUBATOM_PROJECTION_MODEL;
}

export async function closeProofIndexReadPool() {
  if (proofIndexReadPool) {
    await proofIndexReadPool.end();
    proofIndexReadPool = null;
  }
}

function featureEnabled(rawValue, feature) {
  const value = String(rawValue ?? "").trim().toLowerCase();
  if (!value || /^(?:0|false|no|none|off)$/iu.test(value)) {
    return false;
  }
  if (/^(?:1|true|yes|all|\*)$/iu.test(value)) {
    return true;
  }

  const aliases = new Set(
    String(feature ?? "")
      .split(/[,\s]+/u)
      .map((part) => part.trim().toLowerCase())
      .filter(Boolean),
  );
  const enabled = value
    .split(/[,\s]+/u)
    .map((part) => part.trim().toLowerCase())
    .filter(Boolean);
  return enabled.some((part) => aliases.has(part));
}

export function proofIndexReadFeatureEnabled(feature, env = process.env) {
  return (
    proofIndexDatabaseConfigured(env) &&
    featureEnabled(env.POW_INDEX_READS, feature)
  );
}

export function proofIndexShadowFeatureEnabled(feature, env = process.env) {
  return (
    proofIndexDatabaseConfigured(env) &&
    featureEnabled(env.POW_INDEX_SHADOW_READS, feature)
  );
}

export function proofIndexReadUnconfirmedTxStatus(env = process.env) {
  return /^(?:1|true|yes)$/iu.test(
    String(env.POW_INDEX_READ_UNCONFIRMED_TX_STATUS ?? ""),
  );
}

function dateIso(value, fallback = new Date()) {
  const date = value instanceof Date ? value : new Date(value ?? fallback);
  if (Number.isNaN(date.getTime())) {
    return fallback.toISOString();
  }
  return date.toISOString();
}

const BITCOIN_GENESIS_TIME_MS = Date.UTC(2009, 0, 3, 18, 15, 5);

function plausibleBitcoinEventTime(...values) {
  for (const value of values) {
    if (value === null || value === undefined || value === "") {
      continue;
    }
    const parsed = value instanceof Date ? value.getTime() : Date.parse(value);
    if (Number.isFinite(parsed) && parsed >= BITCOIN_GENESIS_TIME_MS) {
      return value;
    }
  }
  return undefined;
}

function safeBlockHeight(value) {
  const height = Number(value);
  return Number.isSafeInteger(height) && height > 0 ? height : 0;
}

async function verifiedWorkMarketV4Activation(
  pool,
  network,
  indexedThroughBlock = 0,
) {
  const configured = workMarketV4ConfiguredDeclaration();
  const checkpointHeight = safeBlockHeight(indexedThroughBlock);
  if (
    !pool ||
    network !== "livenet" ||
    (checkpointHeight > 0 &&
      configured &&
      !workMarketV4ActivationReached(configured, checkpointHeight))
  ) {
    return null;
  }
  const result = await pool.query(
    `
      SELECT
        declaration_tx.txid,
        declaration_tx.block_hash,
        declaration_tx.block_height,
        declaration_tx.status,
        (
          SELECT declaration_input.address
          FROM proof_indexer.tx_inputs declaration_input
          WHERE declaration_input.network = declaration_tx.network
            AND declaration_input.txid = declaration_tx.txid
            AND declaration_input.vin = 0
          LIMIT 1
        ) AS first_input_address,
        (
          SELECT COALESCE(sum(declaration_output.value_sats), 0)
          FROM proof_indexer.tx_outputs declaration_output
          WHERE declaration_output.network = declaration_tx.network
            AND declaration_output.txid = declaration_tx.txid
            AND declaration_output.address = $5
            AND declaration_output.vout < (
              SELECT min(declaration_first_message.vout)
              FROM proof_indexer.op_returns declaration_first_message
              WHERE declaration_first_message.network = declaration_tx.network
                AND declaration_first_message.txid = declaration_tx.txid
                AND left(
                  COALESCE(declaration_first_message.payload_text, ''),
                  7
                ) = 'pwm1:m:'
            )
        ) AS registry_payment_sats,
        ARRAY(
          SELECT declaration_message.payload_text
          FROM proof_indexer.op_returns declaration_message
          WHERE declaration_message.network = declaration_tx.network
            AND declaration_message.txid = declaration_tx.txid
            AND left(COALESCE(declaration_message.payload_text, ''), 7) =
              'pwm1:m:'
          ORDER BY
            declaration_message.vout ASC,
            declaration_message.output_index ASC
        ) AS memo_chunks
      FROM proof_indexer.transactions declaration_tx
      JOIN proof_indexer.blocks declaration_block
        ON declaration_block.network = declaration_tx.network
       AND declaration_block.block_hash = declaration_tx.block_hash
       AND declaration_block.height = declaration_tx.block_height
       AND declaration_block.canonical = true
      WHERE declaration_tx.network = $1
        AND ($2 = '' OR declaration_tx.txid = $2)
        AND declaration_tx.status = 'confirmed'
        AND ($3::integer = 0 OR declaration_tx.block_height = $3)
        AND ($4 = '' OR declaration_tx.block_hash = $4)
        AND ($7::integer = 0 OR declaration_tx.block_height <= $7)
        AND EXISTS (
          SELECT 1
          FROM proof_indexer.tx_inputs declaration_authority
          WHERE declaration_authority.network = declaration_tx.network
            AND declaration_authority.txid = declaration_tx.txid
            AND declaration_authority.vin = 0
            AND declaration_authority.address = $6
        )
        AND EXISTS (
          SELECT 1
          FROM proof_indexer.tx_outputs declaration_registry_output
          WHERE declaration_registry_output.network = declaration_tx.network
            AND declaration_registry_output.txid = declaration_tx.txid
            AND declaration_registry_output.address = $5
            AND declaration_registry_output.vout < (
              SELECT min(declaration_first_message.vout)
              FROM proof_indexer.op_returns declaration_first_message
              WHERE declaration_first_message.network = declaration_tx.network
                AND declaration_first_message.txid = declaration_tx.txid
                AND left(
                  COALESCE(declaration_first_message.payload_text, ''),
                  7
                ) = 'pwm1:m:'
            )
        )
        AND EXISTS (
          SELECT 1
          FROM proof_indexer.op_returns declaration_candidate_message
          WHERE declaration_candidate_message.network = declaration_tx.network
            AND declaration_candidate_message.txid = declaration_tx.txid
            AND left(
              COALESCE(declaration_candidate_message.payload_text, ''),
              7
            ) = 'pwm1:m:'
        )
        AND (
          SELECT
            'pwm1:m:' ||
            COALESCE(
              string_agg(
                substr(
                  COALESCE(declaration_exact_message.payload_text, ''),
                  8
                ),
                ''
                ORDER BY
                  declaration_exact_message.vout ASC,
                  declaration_exact_message.output_index ASC
              ),
              ''
            )
          FROM proof_indexer.op_returns declaration_exact_message
          WHERE declaration_exact_message.network = declaration_tx.network
            AND declaration_exact_message.txid = declaration_tx.txid
            AND left(
              COALESCE(declaration_exact_message.payload_text, ''),
              7
            ) = 'pwm1:m:'
        ) = $8
      ORDER BY declaration_tx.block_height ASC, declaration_tx.txid ASC
      LIMIT 32
    `,
    [
      network,
      WORK_MARKET_V4_DECLARATION_TXID,
      WORK_MARKET_V4_DECLARATION_HEIGHT,
      WORK_MARKET_V4_DECLARATION_BLOCK_HASH,
      WORK_MARKET_V4_DECLARATION_REGISTRY_ADDRESS,
      WORK_MARKET_V4_DECLARATION_AUTHORITY,
      checkpointHeight,
      WORK_MARKET_V4_DECLARATION_PAYLOAD,
    ],
  );
  for (const row of result.rows) {
    const memo = (Array.isArray(row.memo_chunks) ? row.memo_chunks : [])
      .map((chunk) => String(chunk ?? "").slice("pwm1:m:".length))
      .join("");
    const activation = workMarketV4ActivationFromDeclaration({
      blockHash: row.block_hash,
      blockHeight: row.block_height,
      confirmed: row.status === "confirmed",
      firstInputAddress: row.first_input_address,
      payload: `pwm1:m:${memo}`,
      registryPaymentSats: Number(row.registry_payment_sats),
      txid: row.txid,
    });
    if (
      activation &&
      Number(row.registry_payment_sats) >=
        WORK_MARKET_V4_DECLARATION_MIN_PAYMENT_SATS &&
      (checkpointHeight === 0 ||
        workMarketV4ActivationReached(activation, checkpointHeight))
    ) {
      return activation;
    }
  }
  return null;
}

export async function proofIndexWorkMarketV4Activation(
  network,
  indexedThroughBlock = 0,
) {
  const pool = proofIndexPool();
  return pool
    ? verifiedWorkMarketV4Activation(pool, network, indexedThroughBlock)
    : null;
}

function canonicalAmoPosition(row, prefix = "") {
  const field = (name) => row?.[`${prefix}${name}`];
  const presentInteger = (name, minimum) => {
    const value = field(name);
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const blockHeight = presentInteger("block_height", 1);
  const blockIndex = presentInteger("block_index", 0);
  const protocolVout = presentInteger("protocol_vout", 0);
  const recordOrdinal = presentInteger("record_ordinal", 0);
  return blockHeight !== null &&
    blockIndex !== null &&
    protocolVout !== null &&
    recordOrdinal !== null
    ? {
        blockHeight,
        blockIndex,
        blockTransactionIndex: blockIndex,
        protocolVout,
        recordOrdinal,
      }
    : null;
}

function normalizedWorkUsdQuoteRow(row) {
  const position = canonicalAmoPosition(row);
  const txid = String(row?.txid ?? "").trim().toLowerCase();
  const declarationTxid = String(row?.declaration_txid ?? "")
    .trim()
    .toLowerCase();
  const previousQuoteTxid = String(row?.previous_quote_txid ?? "")
    .trim()
    .toLowerCase();
  const sequence = String(row?.sequence ?? "").trim();
  const usdPer100mProofsQ8 = String(
    row?.usd_per_100m_proofs_q8 ?? "",
  ).trim();
  const blockHash = String(row?.block_hash ?? "").trim().toLowerCase();
  const recordCount = Number(row?.record_count);
  const registryAddress = String(row?.registry_address ?? "").trim();
  const registryPaymentSats = Number(row?.registry_payment_sats);
  const registryPaymentVout = Number(row?.registry_payment_vout);
  const firstInputPrevoutScriptPubKey = String(
    row?.authority_scriptpubkey ?? "",
  )
    .trim()
    .toLowerCase();
  const payload = String(row?.raw_payload ?? "");
  const payloadParts = payload.split(":");
  if (
    !position ||
    position.blockHeight < WORK_AMO_V1_ACTIVATION_HEIGHT ||
    position.recordOrdinal !== 0 ||
    !/^[0-9a-f]{64}$/u.test(txid) ||
    declarationTxid !== WORK_AMO_V1_DECLARATION_TXID ||
    !/^[0-9a-f]{64}$/u.test(previousQuoteTxid) ||
    !/^[1-9][0-9]*$/u.test(sequence) ||
    !/^[1-9][0-9]*$/u.test(usdPer100mProofsQ8) ||
    !/^[0-9a-f]{64}$/u.test(blockHash) ||
    recordCount !== 1 ||
    registryAddress !== WORK_AMO_V5_REGISTRY_ADDRESS ||
    !Number.isSafeInteger(registryPaymentSats) ||
    registryPaymentSats < WORK_AMO_V5_MIN_REGISTRY_PAYMENT_SATS ||
    !Number.isSafeInteger(registryPaymentVout) ||
    registryPaymentVout < 0 ||
    payloadParts.length !== 6 ||
    payloadParts[0] !== "pwa1" ||
    payloadParts[1] !== "usd1" ||
    payloadParts[2] !== declarationTxid ||
    payloadParts[3] !== sequence ||
    payloadParts[4] !== previousQuoteTxid ||
    payloadParts[5] !== usdPer100mProofsQ8 ||
    row?.status !== "confirmed" ||
    row?.valid !== true ||
    firstInputPrevoutScriptPubKey !== WORK_AMO_V5_AUTHORITY_SCRIPTPUBKEY
  ) {
    return null;
  }
  return {
    authorityScriptpubkey: WORK_AMO_V5_AUTHORITY_SCRIPTPUBKEY,
    blockHash,
    canonical: true,
    confirmed: true,
    declarationTxid,
    firstInputPrevoutScriptPubKey,
    indexedPayload:
      row?.payload && typeof row.payload === "object" ? row.payload : {},
    payload,
    previousQuoteTxid,
    recordCount,
    registryAddress,
    registryPaymentSats,
    registryPaymentVout,
    sequence,
    status: "confirmed",
    txid,
    usdPer100mProofsQ8,
    valid: true,
    v1DeclarationTxid: declarationTxid,
    ...position,
  };
}

function normalizedWorkAmoListingTermsRow(row) {
  const candidateFrozenTerms =
    row?.frozen_terms &&
    typeof row.frozen_terms === "object" &&
    !Array.isArray(row.frozen_terms)
      ? row.frozen_terms
      : null;
  const listingId = String(row?.listing_id ?? "").trim().toLowerCase();
  const listingTxid = String(row?.listing_txid ?? "").trim().toLowerCase();
  const quoteTxid = String(row?.unit_usd_quote_txid ?? "")
    .trim()
    .toLowerCase();
  const listingPosition = canonicalAmoPosition(row, "listing_");
  const quotePosition = {
    blockHash: String(row?.unit_usd_quote_block_hash ?? "")
      .trim()
      .toLowerCase(),
    blockHeight: Number(row?.unit_usd_quote_block_height),
    blockIndex: Number(row?.unit_usd_quote_block_index),
    blockTransactionIndex: Number(row?.unit_usd_quote_block_index),
    protocolVout: Number(row?.unit_usd_quote_vout),
    recordOrdinal: 0,
  };
  if (
    !candidateFrozenTerms ||
    !/^[0-9a-f]{64}$/u.test(listingId) ||
    listingTxid !== listingId ||
    !/^[0-9a-f]{64}$/u.test(quoteTxid) ||
    !listingPosition ||
    !Number.isSafeInteger(quotePosition.blockHeight) ||
    quotePosition.blockHeight <= 0 ||
    !Number.isSafeInteger(quotePosition.blockIndex) ||
    quotePosition.blockIndex < 0 ||
    !Number.isSafeInteger(quotePosition.protocolVout) ||
    quotePosition.protocolVout < 0 ||
    !/^[0-9a-f]{64}$/u.test(quotePosition.blockHash) ||
    row?.authorization_version !== WORK_AMO_V5_AUTH_VERSION ||
    String(row?.token_id ?? "").trim().toLowerCase() !== WORK_TOKEN_ID
  ) {
    return null;
  }
  const frozenValidation = validateWorkAmoV5FrozenTerms(
    candidateFrozenTerms,
    {
      listingPosition: {
        blockHash: String(row?.listing_block_hash ?? "")
          .trim()
          .toLowerCase(),
        blockHeight: listingPosition.blockHeight,
        blockTransactionIndex: listingPosition.blockIndex,
        protocolVout: listingPosition.protocolVout,
        recordOrdinal: listingPosition.recordOrdinal,
      },
    },
  );
  if (!frozenValidation.valid) {
    return null;
  }
  const frozen = frozenValidation.frozenTerms;
  const exactPositiveInteger = (value) => {
    const text = String(value ?? "").trim();
    return /^[1-9][0-9]*$/u.test(text) ? BigInt(text).toString() : "";
  };
  if (
    Number(row?.unit_face_usd_cents) !== frozen.unitFaceUsdCents ||
    exactPositiveInteger(row?.unit_amount_atoms) !== frozen.unitAmountAtoms ||
    exactPositiveInteger(row?.unit_price_sats) !== frozen.unitPriceSats ||
    exactPositiveInteger(row?.unit_minimum_price_sats) !==
      frozen.unitMinimumPriceSats ||
    quoteTxid !== frozen.unitUsdQuoteTxid ||
    Number(row?.unit_usd_quote_vout) !== frozen.unitUsdQuoteVout ||
    exactPositiveInteger(row?.unit_usd_quote_sequence) !==
      frozen.unitUsdQuoteSequence ||
    Number(row?.unit_usd_quote_block_height) !==
      frozen.unitUsdQuoteBlockHeight ||
    String(row?.unit_usd_quote_block_hash ?? "").trim().toLowerCase() !==
      frozen.unitUsdQuoteBlockHash ||
    Number(row?.unit_usd_quote_block_index) !==
      frozen.unitUsdQuoteBlockIndex ||
    exactPositiveInteger(row?.unit_usd_per_100m_proofs_q8) !==
      frozen.unitUsdPer100mProofsQ8 ||
    exactPositiveInteger(row?.unit_network_value_before_q8) !==
      frozen.unitNetworkValueBeforeQ8 ||
    exactPositiveInteger(row?.listing_bond_contribution_q8) !==
      frozen.listingBondContributionQ8 ||
    exactPositiveInteger(row?.unit_network_value_after_q8) !==
      frozen.unitNetworkValueAfterQ8
  ) {
    return null;
  }
  return {
    authorizationVersion: WORK_AMO_V5_AUTH_VERSION,
    createdAt: dateIso(row?.created_at),
    frozenTerms: frozen,
    listingId,
    listingPosition,
    listingTxid,
    quotePosition,
    tokenId: WORK_TOKEN_ID,
    unitAmountAtoms: String(row.unit_amount_atoms),
    unitFaceUsdCents: Number(row.unit_face_usd_cents),
    unitMinimumPriceSats: String(row.unit_minimum_price_sats),
    unitPriceSats: String(row.unit_price_sats),
    unitUsdQuoteTxid: quoteTxid,
  };
}

function workAmoV6MigrationMarkerBindsReader(
  marker,
  listingBlockHeight = null,
) {
  const value =
    marker && typeof marker === "object" && !Array.isArray(marker)
      ? marker
      : {};
  const evidence =
    value.declarationEvidence &&
    typeof value.declarationEvidence === "object" &&
    !Array.isArray(value.declarationEvidence)
      ? value.declarationEvidence
      : {};
  const safeInteger = (candidate, minimum = 0) => {
    const parsed = Number(candidate);
    return Number.isSafeInteger(parsed) && parsed >= minimum
      ? parsed
      : null;
  };
  const positiveInteger = (candidate) => {
    const text = String(candidate ?? "").trim();
    return /^[1-9][0-9]*$/u.test(text)
      ? BigInt(text).toString()
      : "";
  };
  const lower = (candidate) => String(candidate ?? "").trim().toLowerCase();
  const committed = {
    authorityScriptPubKey: lower(evidence.authorityScriptPubKey),
    blockHash: lower(evidence.blockHash),
    blockHeight: safeInteger(evidence.blockHeight, 1),
    blockTransactionIndex: safeInteger(
      evidence.blockTransactionIndex,
    ),
    inputCount: safeInteger(evidence.inputCount, 1),
    outputCount: safeInteger(evidence.outputCount, 1),
    payloadBytes: safeInteger(evidence.payloadBytes, 1),
    payloadSha256: lower(evidence.payloadSha256),
    protocol: lower(evidence.protocol),
    protocolVout: safeInteger(evidence.protocolVout),
    recordOrdinal: safeInteger(evidence.recordOrdinal),
    registryAddress: String(evidence.registryAddress ?? "").trim(),
    registryPaymentSats: positiveInteger(
      evidence.registryPaymentSats,
    ),
    registryPaymentVout: safeInteger(evidence.registryPaymentVout),
    txid: lower(evidence.txid),
  };
  if (
    value.model !== WORK_AMO_V6_INDEX_MIGRATION_MODEL ||
    value.status !== "complete" ||
    value.network !== "livenet" ||
    value.version !== WORK_AMO_V6_AUTH_VERSION ||
    value.amountModel !== WORK_AMO_V6_AMOUNT_MODEL ||
    value.blockSequencerModel !== WORK_AMO_V6_BLOCK_SEQUENCER_MODEL ||
    value.bondTransitionModel !== WORK_AMO_V6_BOND_TRANSITION_MODEL ||
    value.stateOrderModel !== WORK_AMO_V6_STATE_ORDER_MODEL ||
    value.unitModel !== WORK_AMO_V6_UNIT_MODEL ||
    value.unitWorkOracleModel !==
      WORK_AMO_V6_UNIT_WORK_ORACLE_MODEL ||
    evidence.model !==
      WORK_AMO_V6_DECLARATION_INDEX_EVIDENCE_MODEL ||
    evidence.evidenceComplete !== true ||
    evidence.coreVerified !== true ||
    evidence.indexVerified !== true ||
    !Object.values(committed).every(
      (field) => field !== null && field !== "",
    ) ||
    committed.authorityScriptPubKey !==
      WORK_AMO_V5_AUTHORITY_SCRIPTPUBKEY ||
    committed.txid !== lower(value.declarationTxid) ||
    committed.registryAddress !== WORK_AMO_V5_REGISTRY_ADDRESS ||
    BigInt(committed.registryPaymentSats) <
      BigInt(WORK_AMO_V5_MIN_REGISTRY_PAYMENT_SATS) ||
    committed.recordOrdinal !== 0 ||
    !/^[0-9a-f]{64}$/u.test(committed.blockHash) ||
    !/^[0-9a-f]{64}$/u.test(committed.payloadSha256) ||
    committed.protocol !== "pwm1" ||
    !Array.isArray(value.facesProofs) ||
    JSON.stringify(value.facesProofs) !==
      JSON.stringify(WORK_AMO_V6_ALLOWED_FACE_PROOFS) ||
    !Number.isFinite(Date.parse(String(value.completedAt ?? ""))) ||
    !Number.isFinite(Date.parse(String(value.updatedAt ?? "")))
  ) {
    return false;
  }
  let expectedDeclaration;
  try {
    expectedDeclaration = workAmoV6DeclarationCommitment();
  } catch {
    return false;
  }
  const commitment = createHash("sha256")
    .update(
      Buffer.from(
        `${WORK_AMO_V6_DECLARATION_INDEX_EVIDENCE_DOMAIN}\n${
          JSON.stringify(committed)
        }`,
        "utf8",
      ),
    )
    .digest("hex");
  const activationHeight = safeInteger(value.activationHeight, 2);
  const listingBlockHeightProvided =
    listingBlockHeight !== null && listingBlockHeight !== undefined;
  const normalizedListingBlockHeight = listingBlockHeightProvided
    ? safeInteger(listingBlockHeight, 1)
    : null;
  return Boolean(
    commitment === lower(evidence.commitmentSha256) &&
      activationHeight === committed.blockHeight + 1 &&
      (!listingBlockHeightProvided ||
        (
          normalizedListingBlockHeight !== null &&
          normalizedListingBlockHeight >= activationHeight
        )) &&
      lower(value.declarationTxid) === committed.txid &&
      lower(value.declarationBlockHash) === committed.blockHash &&
      Number(value.declarationHeight) === committed.blockHeight &&
      Number(value.declarationBlockIndex) ===
        committed.blockTransactionIndex &&
      lower(value.declarationMemoSha256) ===
        committed.payloadSha256 &&
      Number(value.declarationMemoBytes) === committed.payloadBytes &&
      committed.payloadBytes ===
        expectedDeclaration.protocolRecordBytes &&
      committed.payloadSha256 ===
        expectedDeclaration.protocolRecordSha256 &&
      Number(value.declarationProtocolRecordBytes) ===
        expectedDeclaration.protocolRecordBytes &&
      lower(value.declarationProtocolRecordSha256) ===
        expectedDeclaration.protocolRecordSha256 &&
      Number(value.declarationTextBytes) ===
        expectedDeclaration.payloadBytes &&
      lower(value.declarationTextSha256) ===
        expectedDeclaration.payloadSha256 &&
      Number(value.declarationProtocolVout) ===
        committed.protocolVout &&
      Number(value.declarationRecordOrdinal) ===
        committed.recordOrdinal &&
      String(value.declarationRegistryAddress ?? "").trim() ===
        committed.registryAddress &&
      Number(value.declarationRegistryMinimumPaymentSats) ===
        WORK_AMO_V5_MIN_REGISTRY_PAYMENT_SATS &&
      Number(value.declarationRegistryPaymentVout) ===
        committed.registryPaymentVout
  );
}

function normalizedWorkAmoV6ListingTermsRow(row) {
  const candidateFrozenTerms =
    row?.frozen_terms &&
    typeof row.frozen_terms === "object" &&
    !Array.isArray(row.frozen_terms)
      ? row.frozen_terms
      : null;
  const listingAuthorization =
    row?.listing_event_payload?.saleAuthorization &&
    typeof row.listing_event_payload.saleAuthorization === "object" &&
    !Array.isArray(row.listing_event_payload.saleAuthorization)
      ? row.listing_event_payload.saleAuthorization
      : null;
  const listingId = String(row?.listing_id ?? "").trim().toLowerCase();
  const listingTxid = String(row?.listing_txid ?? "").trim().toLowerCase();
  const listingPosition = canonicalAmoPosition(row, "listing_");
  const listingBlockHash = String(row?.listing_block_hash ?? "")
    .trim()
    .toLowerCase();
  if (
    !candidateFrozenTerms ||
    !listingAuthorization ||
    !/^[0-9a-f]{64}$/u.test(listingId) ||
    listingTxid !== listingId ||
    !listingPosition ||
    !/^[0-9a-f]{64}$/u.test(listingBlockHash) ||
    row?.authorization_version !== WORK_AMO_V6_AUTH_VERSION ||
    String(row?.token_id ?? "").trim().toLowerCase() !== WORK_TOKEN_ID ||
    !workAmoV6MigrationMarkerBindsReader(
      row?.migration_marker,
      listingPosition.blockHeight,
    )
  ) {
    return null;
  }
  const validation = validateWorkAmoV6FrozenTerms(
    candidateFrozenTerms,
    {
      authorization: listingAuthorization,
      listingPosition: {
        blockHash: listingBlockHash,
        blockHeight: listingPosition.blockHeight,
        blockTransactionIndex: listingPosition.blockIndex,
        protocolVout: listingPosition.protocolVout,
        recordOrdinal: listingPosition.recordOrdinal,
      },
    },
  );
  if (!validation.valid) {
    return null;
  }
  const frozen = validation.frozenTerms;
  const exactPositiveInteger = (value) => {
    const text = String(value ?? "").trim();
    return /^[1-9][0-9]*$/u.test(text) ? BigInt(text).toString() : "";
  };
  if (
    Number(row?.unit_face_proofs) !== frozen.unitFaceProofs ||
    exactPositiveInteger(row?.unit_amount_atoms) !== frozen.unitAmountAtoms ||
    exactPositiveInteger(row?.unit_price_sats) !== frozen.unitPriceSats ||
    exactPositiveInteger(row?.unit_minimum_price_sats) !==
      frozen.unitMinimumPriceSats ||
    exactPositiveInteger(row?.listing_network_value_before_q8) !==
      frozen.listingNetworkValueBeforeQ8 ||
    exactPositiveInteger(row?.listing_bond_contribution_q8) !==
      frozen.listingBondContributionQ8 ||
    exactPositiveInteger(row?.listing_network_value_after_q8) !==
      frozen.listingNetworkValueAfterQ8
  ) {
    return null;
  }
  return {
    authorizationVersion: WORK_AMO_V6_AUTH_VERSION,
    createdAt: dateIso(row?.created_at),
    frozenTerms: frozen,
    listingId,
    listingPosition,
    listingTxid,
    tokenId: WORK_TOKEN_ID,
    unitAmountAtoms: frozen.unitAmountAtoms,
    unitFaceProofs: frozen.unitFaceProofs,
    unitMinimumPriceSats: frozen.unitMinimumPriceSats,
    unitPriceSats: frozen.unitPriceSats,
  };
}
function validatedHistoricalV4ListingWitness({
  amountAtoms,
  anchorAddress,
  anchorScriptPubKey,
  anchorValueSats,
  blockHash,
  canonicalPricingBlockKeys,
  listingAuthorization,
  listingId,
  payload,
  position,
  priceSats,
  saleTicketTxid,
  saleTicketValueSats,
  saleTicketVout,
  sellerAddress,
  unitQuote,
}) {
  const pricing =
    payload?.workMarketPricing &&
    typeof payload.workMarketPricing === "object" &&
    !Array.isArray(payload.workMarketPricing)
      ? payload.workMarketPricing
      : null;
  const integerText = (value, { positive = true } = {}) => {
    const text = String(value ?? "").trim();
    if (!/^(?:0|[1-9][0-9]*)$/u.test(text)) {
      return "";
    }
    return positive && text === "0" ? "" : BigInt(text).toString();
  };
  const unitAmountAtoms = integerText(
    listingAuthorization?.unitAmountAtoms ??
      listingAuthorization?.amountAtoms,
  );
  const unitPriceSats = integerText(
    listingAuthorization?.unitPriceSats ??
      listingAuthorization?.priceSats,
  );
  const unitMinimumPriceSats = integerText(
    listingAuthorization?.unitMinimumPriceSats ??
      listingAuthorization?.minimumPriceSats,
  );
  const unitNetworkValueBeforeQ8 = integerText(
    listingAuthorization?.unitNetworkValueBeforeQ8 ??
      listingAuthorization?.unitNetworkValueQ8,
  );
  const unitFaceUsdCents = Number(
    listingAuthorization?.unitFaceUsdCents,
  );
  const unitFaceUsd = Number(listingAuthorization?.unitFaceUsd);
  const confirmationMinimumPriceSats = integerText(
    pricing?.confirmationMinimumPriceSats,
  );
  const confirmationNetworkValueQ8 = integerText(
    pricing?.confirmationOracleNetworkValueQ8,
  );
  const normalizedSaleTicketTxid = String(
    saleTicketTxid ?? listingId,
  )
    .trim()
    .toLowerCase();
  const normalizedSellerAddress = String(sellerAddress ?? "").trim();
  const authorizationSellerAddress = String(
    listingAuthorization?.sellerAddress ?? "",
  ).trim();
  const normalizedAnchorScriptPubKey = String(anchorScriptPubKey ?? "")
    .trim()
    .toLowerCase();
  const authorizationAnchorScriptPubKey = String(
    listingAuthorization?.anchorScriptPubKey ?? "",
  )
    .trim()
    .toLowerCase();
  const authorizationQuoteTxid = String(
    listingAuthorization?.unitUsdQuoteTxid ?? "",
  )
    .trim()
    .toLowerCase();
  const quotePosition = unitQuote
    ? {
        blockHeight: Number(unitQuote.blockHeight),
        blockIndex: Number(
          unitQuote.blockTransactionIndex ?? unitQuote.blockIndex,
        ),
        protocolVout: Number(unitQuote.protocolVout),
        recordOrdinal: Number(unitQuote.recordOrdinal),
      }
    : null;
  const quotePrecedesListing = Boolean(
    quotePosition &&
      [
        quotePosition.blockHeight,
        quotePosition.blockIndex,
        quotePosition.protocolVout,
        quotePosition.recordOrdinal,
      ].some((value, index, values) => {
        const listingValues = [
          position?.blockHeight,
          position?.blockIndex,
          position?.protocolVout,
          position?.recordOrdinal,
        ];
        return (
          values.slice(0, index).every(
            (prior, priorIndex) => prior === listingValues[priorIndex],
          ) && value < listingValues[index]
        );
      }),
  );
  const unitQuoteValueQ8 = integerText(
    unitQuote?.usdPer100mProofsQ8,
  );
  const targetNumerator =
    Number.isSafeInteger(unitFaceUsdCents) &&
    unitFaceUsdCents > 0 &&
    unitQuoteValueQ8
      ? BigInt(unitFaceUsdCents) * 100_000_000n * 100_000_000n
      : null;
  const targetDenominator =
    unitQuoteValueQ8 ? 100n * BigInt(unitQuoteValueQ8) : null;
  const expectedUnitPriceSats =
    targetNumerator !== null && targetDenominator !== null
      ? (targetNumerator + targetDenominator - 1n) / targetDenominator
      : null;
  const expectedUnitAmountAtoms =
    targetNumerator !== null &&
    targetDenominator !== null &&
    unitNetworkValueBeforeQ8
      ? (
          targetNumerator *
          21_000_000n *
          100_000_000n *
          100_000_000n
        ) / (
          targetDenominator * BigInt(unitNetworkValueBeforeQ8)
        )
      : null;
  const workValueDenominator =
    21_000_000n * 100_000_000n * 100_000_000n;
  const expectedUnitMinimumPriceSats =
    expectedUnitAmountAtoms !== null && unitNetworkValueBeforeQ8
      ? (
          expectedUnitAmountAtoms * BigInt(unitNetworkValueBeforeQ8) +
          workValueDenominator -
          1n
        ) / workValueDenominator
      : null;
  const quotedMinimum = workMarketV2MinimumPriceSats(
    unitAmountAtoms,
    unitNetworkValueBeforeQ8,
  );
  const confirmationMinimum = workMarketV2MinimumPriceSats(
    unitAmountAtoms,
    confirmationNetworkValueQ8,
  );
  const quoteOracleBlockKey = `${
    Number(listingAuthorization?.oracleBlockHeight)
  }:${
    String(listingAuthorization?.oracleBlockHash ?? "").trim().toLowerCase()
  }`;
  const confirmationOracleBlockKey = `${
    Number(pricing?.confirmationOracleBlockHeight)
  }:${
    String(pricing?.confirmationOracleBlockHash ?? "").trim().toLowerCase()
  }`;
  if (
    listingAuthorization?.version !== WORK_MARKET_V4_AUTH_VERSION ||
    String(listingAuthorization?.tokenId ?? "").trim().toLowerCase() !==
      WORK_TOKEN_ID ||
    listingAuthorization?.unitModel !== WORK_AMO_V4_UNIT_MODEL ||
    listingAuthorization?.unitUsdOracleModel !==
      WORK_AMO_UNIT_USD_ORACLE_MODEL ||
    listingAuthorization?.oracleModel !== WORK_MARKET_V4_ORACLE_MODEL ||
    !position ||
    position.blockHeight < WORK_AMO_V1_ACTIVATION_HEIGHT ||
    position.blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT ||
    !/^[0-9a-f]{64}$/u.test(blockHash) ||
    pricing?.valid !== true ||
    Number(pricing?.confirmationOracleBlockHeight) !==
      position.blockHeight - 1 ||
    !/^[0-9a-f]{64}$/u.test(
      String(pricing?.confirmationOracleBlockHash ?? "")
        .trim()
        .toLowerCase(),
    ) ||
    String(pricing?.oracleBlockHash ?? "").trim().toLowerCase() !==
      String(listingAuthorization?.oracleBlockHash ?? "")
        .trim()
        .toLowerCase() ||
    Number(pricing?.oracleBlockHeight) !==
      Number(listingAuthorization?.oracleBlockHeight) ||
    integerText(pricing?.oracleNetworkValueQ8) !==
      unitNetworkValueBeforeQ8 ||
    integerText(pricing?.minimumPriceSats) !== unitMinimumPriceSats ||
    !confirmationNetworkValueQ8 ||
    !unitAmountAtoms ||
    unitAmountAtoms !== integerText(amountAtoms) ||
    !unitPriceSats ||
    unitPriceSats !== integerText(priceSats) ||
    !unitMinimumPriceSats ||
    !unitNetworkValueBeforeQ8 ||
    !confirmationMinimumPriceSats ||
    quotedMinimum === null ||
    quotedMinimum.toString() !== unitMinimumPriceSats ||
    confirmationMinimum === null ||
    confirmationMinimum.toString() !== confirmationMinimumPriceSats ||
    expectedUnitAmountAtoms === null ||
    expectedUnitAmountAtoms.toString() !== unitAmountAtoms ||
    expectedUnitPriceSats === null ||
    expectedUnitPriceSats.toString() !== unitPriceSats ||
    expectedUnitMinimumPriceSats === null ||
    expectedUnitMinimumPriceSats.toString() !== unitMinimumPriceSats ||
    BigInt(unitPriceSats) < BigInt(unitMinimumPriceSats) ||
    BigInt(unitPriceSats) < BigInt(confirmationMinimumPriceSats) ||
    !WORK_AMO_V4_HISTORICAL_FACE_USD_CENTS.includes(
      unitFaceUsdCents,
    ) ||
    !Number.isSafeInteger(unitFaceUsd) ||
    unitFaceUsd !== unitFaceUsdCents / 100 ||
    !normalizedSellerAddress ||
    authorizationSellerAddress !== normalizedSellerAddress ||
    String(payload?.sellerAddress ?? authorizationSellerAddress).trim() !==
      normalizedSellerAddress ||
    String(payload?.registryAddress ?? listingAuthorization?.registryAddress)
      .trim() !== String(listingAuthorization?.registryAddress ?? "").trim() ||
    normalizedSaleTicketTxid !== listingId ||
    String(listingAuthorization?.anchorTxid ?? "")
      .trim()
      .toLowerCase() !== listingId ||
    Number(listingAuthorization?.anchorVout) !== Number(saleTicketVout) ||
    Number(listingAuthorization?.anchorValueSats) !==
      Number(saleTicketValueSats) ||
    Number(saleTicketVout) !== 2 ||
    Number(saleTicketValueSats) !== 546 ||
    Number(anchorValueSats) !== Number(saleTicketValueSats) ||
    !String(anchorAddress ?? "").trim() ||
    !/^[0-9a-f]+$/u.test(authorizationAnchorScriptPubKey) ||
    normalizedAnchorScriptPubKey !== authorizationAnchorScriptPubKey ||
    listingAuthorization?.anchorType !== "sale-ticket-v1" ||
    Number(listingAuthorization?.anchorSigHashType) !== 0x83 ||
    !/^(?:02|03)[0-9a-f]{64}$|^04[0-9a-f]{128}$/u.test(
      String(listingAuthorization?.sellerPublicKey ?? "")
        .trim()
        .toLowerCase(),
    ) ||
    !unitQuote ||
    unitQuote.canonical !== true ||
    unitQuote.confirmed !== true ||
    unitQuote.valid !== true ||
    authorizationQuoteTxid !==
      String(unitQuote.txid ?? "").trim().toLowerCase() ||
    Number(listingAuthorization?.unitUsdQuoteVout) !==
      quotePosition?.protocolVout ||
    String(listingAuthorization?.unitUsdQuoteSequence ?? "").trim() !==
      String(unitQuote.sequence ?? "").trim() ||
    Number(listingAuthorization?.unitUsdQuoteBlockHeight) !==
      quotePosition?.blockHeight ||
    String(listingAuthorization?.unitUsdQuoteBlockHash ?? "")
      .trim()
      .toLowerCase() !==
      String(unitQuote.blockHash ?? "").trim().toLowerCase() ||
    Number(listingAuthorization?.unitUsdQuoteBlockIndex) !==
      quotePosition?.blockIndex ||
    integerText(listingAuthorization?.unitUsdPer100mProofsQ8) !==
      unitQuoteValueQ8 ||
    quotePosition?.recordOrdinal !== 0 ||
    !quotePrecedesListing ||
    position.blockHeight >
      Number(quotePosition?.blockHeight) +
        WORK_AMO_V1_MAX_QUOTE_AGE_BLOCKS ||
    Number(listingAuthorization?.unitValidThroughHeight) !==
      Number(quotePosition?.blockHeight) +
        WORK_AMO_V1_MAX_QUOTE_AGE_BLOCKS ||
    !canonicalPricingBlockKeys ||
    typeof canonicalPricingBlockKeys.has !== "function" ||
    !canonicalPricingBlockKeys.has(quoteOracleBlockKey) ||
    !canonicalPricingBlockKeys.has(confirmationOracleBlockKey)
  ) {
    return null;
  }
  return {
    authorizationVersion: WORK_MARKET_V4_AUTH_VERSION,
    blockHash,
    blockHeight: position.blockHeight,
    blockIndex: position.blockIndex,
    blockTransactionIndex: position.blockIndex,
    canonical: true,
    confirmed: true,
    listingBlockHash: blockHash,
    listingBlockHeight: position.blockHeight,
    listingBlockIndex: position.blockIndex,
    listingProtocolVout: position.protocolVout,
    listingRecordOrdinal: position.recordOrdinal,
    protocolVout: position.protocolVout,
    recordOrdinal: position.recordOrdinal,
    tokenId: WORK_TOKEN_ID,
    unitAmountAtoms,
    unitFaceUsd,
    unitFaceUsdCents,
    unitMinimumPriceSats,
    unitNetworkValueBeforeQ8,
    unitPriceSats,
    valid: true,
  };
}

export async function proofIndexWorkAmoV5Declaration(
  network,
  indexedThroughBlock = 0,
) {
  const pool = proofIndexPool();
  const checkpointHeight = safeBlockHeight(indexedThroughBlock);
  if (!pool) {
    return {
      activationHeight: WORK_AMO_V5_ACTIVATION_HEIGHT,
      active: false,
      canonical: false,
      confirmed: false,
      configured: true,
      declarationTxid: WORK_AMO_V5_DECLARATION_TXID,
      txid: WORK_AMO_V5_DECLARATION_TXID,
      reasons: ["database-not-configured"],
    };
  }
  const result = await pool.query(
    `
      SELECT
        declaration_tx.txid,
        declaration_tx.status,
        declaration_tx.block_hash,
        declaration_tx.block_height,
        declaration_tx.block_index,
        declaration_tx.block_time,
        COALESCE(
          declaration_tx.raw_tx #>> '{vin,0,prevout,scriptPubKey,hex}',
          declaration_tx.raw_tx #>> '{vin,0,prevout,scriptpubkey}',
          ''
        ) AS first_input_scriptpubkey,
        (
          SELECT count(*)
          FROM proof_indexer.tx_inputs declaration_input
          WHERE declaration_input.network = declaration_tx.network
            AND declaration_input.txid = declaration_tx.txid
        )::integer AS input_count,
        (
          SELECT min(protocol_output.vout)
          FROM proof_indexer.op_returns protocol_output
          WHERE protocol_output.network = declaration_tx.network
            AND protocol_output.txid = declaration_tx.txid
            AND protocol_output.protocol = 'pwt1'
        ) AS work_protocol_vout,
        (
          SELECT count(*)
          FROM proof_indexer.op_returns protocol_output
          WHERE protocol_output.network = declaration_tx.network
            AND protocol_output.txid = declaration_tx.txid
            AND protocol_output.protocol = 'pwt1'
        )::integer AS work_protocol_count,
        (
          SELECT COALESCE(sum(registry_output.value_sats), 0)
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = declaration_tx.network
            AND registry_output.txid = declaration_tx.txid
            AND registry_output.address = $5
            AND registry_output.vout < (
              SELECT min(protocol_output.vout)
              FROM proof_indexer.op_returns protocol_output
              WHERE protocol_output.network = declaration_tx.network
                AND protocol_output.txid = declaration_tx.txid
                AND protocol_output.protocol = 'pwt1'
            )
        ) AS registry_payment_sats,
        (
          SELECT min(registry_output.vout)
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = declaration_tx.network
            AND registry_output.txid = declaration_tx.txid
            AND registry_output.address = $5
        ) AS registry_payment_vout,
        (
          SELECT count(*)
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = declaration_tx.network
            AND registry_output.txid = declaration_tx.txid
            AND registry_output.address = $5
        )::integer AS registry_payment_count,
        COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'output_index', declaration_message.output_index,
              'payload_text', declaration_message.payload_text,
              'vout', declaration_message.vout
            )
            ORDER BY declaration_message.vout, declaration_message.output_index
          )
          FROM proof_indexer.op_returns declaration_message
          WHERE declaration_message.network = declaration_tx.network
            AND declaration_message.txid = declaration_tx.txid
            AND left(
              COALESCE(declaration_message.payload_text, ''),
              7
            ) = 'pwm1:m:'
        ), '[]'::jsonb) AS memo_rows
      FROM proof_indexer.transactions declaration_tx
      JOIN proof_indexer.blocks declaration_block
        ON declaration_block.network = declaration_tx.network
       AND declaration_block.block_hash = declaration_tx.block_hash
       AND declaration_block.height = declaration_tx.block_height
       AND declaration_block.canonical = true
      WHERE declaration_tx.network = $1
        AND declaration_tx.txid = $2
        AND declaration_tx.block_height = $3
        AND declaration_tx.block_hash = $4
        AND declaration_tx.status = 'confirmed'
      LIMIT 1
    `,
    [
      network,
      WORK_AMO_V5_DECLARATION_TXID,
      WORK_AMO_V5_DECLARATION_HEIGHT,
      WORK_AMO_V5_DECLARATION_BLOCK_HASH,
      WORK_AMO_V5_REGISTRY_ADDRESS,
    ],
  );
  const row = result.rows[0];
  const reasons = [];
  if (!row) {
    reasons.push("declaration-not-canonical");
  }
  const memoRows = Array.isArray(row?.memo_rows) ? row.memo_rows : [];
  const memo = memoRows.length === 1
    ? String(memoRows[0]?.payload_text ?? "")
    : "";
  const memoHash = memo
    ? createHash("sha256").update(Buffer.from(memo, "utf8")).digest("hex")
    : "";
  const memoBytes = Buffer.byteLength(memo, "utf8");
  if (row && Number(row.block_index) !== WORK_AMO_V5_DECLARATION_BLOCK_INDEX) {
    reasons.push("declaration-block-index-mismatch");
  }
  if (
    row &&
    dateIso(row.block_time) !== WORK_AMO_V5_DECLARATION_BLOCK_TIME
  ) {
    reasons.push("declaration-block-time-mismatch");
  }
  if (
    row &&
    (
      memoRows.length !== 1 ||
      Number(memoRows[0]?.vout) !==
        WORK_AMO_V5_DECLARATION_PROTOCOL_VOUT ||
      Number(memoRows[0]?.output_index) !==
        WORK_AMO_V5_DECLARATION_RECORD_ORDINAL
    )
  ) {
    reasons.push("declaration-protocol-position-mismatch");
  }
  if (
    row &&
    String(row.first_input_scriptpubkey ?? "").trim().toLowerCase() !==
      WORK_AMO_V5_AUTHORITY_SCRIPTPUBKEY
  ) {
    reasons.push("declaration-authority-script-mismatch");
  }
  if (
    row &&
    (
      Number(row.registry_payment_count) !== 1 ||
      Number(row.registry_payment_sats) !==
        WORK_AMO_V5_MIN_REGISTRY_PAYMENT_SATS ||
      Number(row.registry_payment_vout) !==
        WORK_AMO_V5_DECLARATION_REGISTRY_PAYMENT_VOUT
    )
  ) {
    reasons.push("declaration-registry-payment-missing");
  }
  if (
    row &&
    (
      Number(row.work_protocol_count) !== 1 ||
      Number(row.work_protocol_vout) !==
        WORK_AMO_V5_DECLARATION_WORK_PROTOCOL_VOUT
    )
  ) {
    reasons.push("declaration-work-protocol-output-mismatch");
  }
  if (
    row &&
    (
      memoHash !== WORK_AMO_V5_DECLARATION_MEMO_SHA256 ||
      memoBytes !== WORK_AMO_V5_DECLARATION_MEMO_BYTES ||
      memoRows.length !== 1
    )
  ) {
    reasons.push("declaration-memo-mismatch");
  }
  const canonical = Boolean(row) && reasons.length === 0;
  const checkpointReached =
    checkpointHeight === 0 || checkpointHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT;
  if (canonical && !checkpointReached) {
    reasons.push("activation-height-not-reached");
  }
  return {
    activationHeight: WORK_AMO_V5_ACTIVATION_HEIGHT,
    active: canonical && checkpointReached,
    blockHash: row?.block_hash ?? WORK_AMO_V5_DECLARATION_BLOCK_HASH,
    blockHeight: Number(row?.block_height ?? WORK_AMO_V5_DECLARATION_HEIGHT),
    blockIndex: Number(row?.block_index ?? -1),
    blockTransactionIndex: Number(row?.block_index ?? -1),
    blockTime: row?.block_time ? dateIso(row.block_time) : "",
    canonical,
    confirmed: row?.status === "confirmed",
    configured: true,
    declarationTxid: WORK_AMO_V5_DECLARATION_TXID,
    evidenceComplete: canonical,
    firstInputPrevoutScriptPubKey: String(
      row?.first_input_scriptpubkey ?? "",
    ).toLowerCase(),
    firstInputScriptpubkey: String(
      row?.first_input_scriptpubkey ?? "",
    ).toLowerCase(),
    inputCount: Number(row?.input_count ?? 0),
    memoBytes,
    memoSha256: memoHash,
    payloadBytes: memoBytes,
    payloadSha256: memoHash,
    protocolOutputVout: Number(row?.work_protocol_vout ?? -1),
    protocolVout: WORK_AMO_V5_DECLARATION_PROTOCOL_VOUT,
    recordOrdinal: WORK_AMO_V5_DECLARATION_RECORD_ORDINAL,
    reasons,
    registryAddress: WORK_AMO_V5_REGISTRY_ADDRESS,
    registryPaymentSats: Number(row?.registry_payment_sats ?? 0),
    registryPaymentVout: Number(row?.registry_payment_vout ?? -1),
    status: row?.status ?? "missing",
    txid: WORK_AMO_V5_DECLARATION_TXID,
    workProtocolVout: Number(row?.work_protocol_vout ?? -1),
  };
}

async function readWorkUsdQuote(pool, network, whereSql, params) {
  const result = await pool.query(
    `
      SELECT
        quote.*
      FROM proof_indexer.work_usd_quotes quote
      JOIN proof_indexer.transactions quote_tx
        ON quote_tx.network = quote.network
       AND quote_tx.txid = quote.txid
       AND quote_tx.status = 'confirmed'
       AND quote_tx.block_hash = quote.block_hash
       AND quote_tx.block_height = quote.block_height
       AND quote_tx.block_index = quote.block_index
      JOIN proof_indexer.blocks quote_block
        ON quote_block.network = quote_tx.network
       AND quote_block.block_hash = quote_tx.block_hash
       AND quote_block.height = quote_tx.block_height
       AND quote_block.canonical = true
      WHERE quote.network = $1
        AND quote.status = 'confirmed'
        AND quote.valid = true
        AND ${whereSql}
      ORDER BY
        quote.block_height DESC,
        quote.block_index DESC,
        quote.protocol_vout DESC,
        quote.record_ordinal DESC
      LIMIT 1
    `,
    [network, ...params],
  );
  return result.rows.length > 0
    ? normalizedWorkUsdQuoteRow(result.rows[0])
    : null;
}

function compareAmoPositions(left, right) {
  for (const field of [
    "blockHeight",
    "blockIndex",
    "protocolVout",
    "recordOrdinal",
  ]) {
    const difference = Number(left?.[field]) - Number(right?.[field]);
    if (difference !== 0) {
      return difference;
    }
  }
  return 0;
}

async function canonicalWorkUsdQuoteChainRows(pool, network) {
  const result = await pool.query(
    `
      SELECT
        quote.txid,
        quote.declaration_txid,
        quote.sequence::text,
        quote.previous_quote_txid,
        quote.block_height,
        quote.block_index,
        quote.protocol_vout,
        quote.record_ordinal
      FROM proof_indexer.work_usd_quotes quote
      JOIN proof_indexer.transactions quote_tx
        ON quote_tx.network = quote.network
       AND quote_tx.txid = quote.txid
       AND quote_tx.status = 'confirmed'
       AND quote_tx.block_hash = quote.block_hash
       AND quote_tx.block_height = quote.block_height
       AND quote_tx.block_index = quote.block_index
      JOIN proof_indexer.blocks quote_block
        ON quote_block.network = quote_tx.network
       AND quote_block.block_hash = quote_tx.block_hash
       AND quote_block.height = quote_tx.block_height
       AND quote_block.canonical = true
      WHERE quote.network = $1
        AND quote.status = 'confirmed'
        AND quote.valid = true
      ORDER BY quote.sequence
    `,
    [network],
  );
  const chain = [];
  let expectedSequence = 1n;
  let expectedPreviousQuoteTxid = WORK_AMO_V1_DECLARATION_TXID;
  for (const row of result.rows) {
    const position = canonicalAmoPosition(row);
    const txid = String(row?.txid ?? "").trim().toLowerCase();
    const sequence = String(row?.sequence ?? "").trim();
    const previousQuoteTxid = String(row?.previous_quote_txid ?? "")
      .trim()
      .toLowerCase();
    if (
      !position ||
      position.blockHeight < WORK_AMO_V1_ACTIVATION_HEIGHT ||
      position.recordOrdinal !== 0 ||
      !/^[0-9a-f]{64}$/u.test(txid) ||
      String(row?.declaration_txid ?? "").trim().toLowerCase() !==
        WORK_AMO_V1_DECLARATION_TXID ||
      !/^[1-9][0-9]*$/u.test(sequence) ||
      BigInt(sequence) !== expectedSequence ||
      previousQuoteTxid !== expectedPreviousQuoteTxid ||
      (
        chain.length > 0 &&
        compareAmoPositions(chain.at(-1).position, position) >= 0
      )
    ) {
      return null;
    }
    chain.push({ position, sequence, txid });
    expectedSequence += 1n;
    expectedPreviousQuoteTxid = txid;
  }
  return chain;
}

export async function proofIndexWorkUsdQuoteHead(network, atPosition = null) {
  const pool = proofIndexPool();
  if (!pool) {
    return null;
  }
  const exactInteger = (value, minimum) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const position = atPosition && typeof atPosition === "object"
    ? {
        blockHeight: exactInteger(atPosition.blockHeight, 1),
        blockIndex: exactInteger(atPosition.blockIndex, 0),
        protocolVout: exactInteger(atPosition.protocolVout, 0),
        recordOrdinal: exactInteger(atPosition.recordOrdinal, 0),
      }
    : null;
  const completePosition =
    position &&
    position.blockHeight !== null &&
    position.blockIndex !== null &&
    position.protocolVout !== null &&
    position.recordOrdinal !== null;
  if (atPosition && !completePosition) {
    return null;
  }
  const chain = await canonicalWorkUsdQuoteChainRows(pool, network);
  if (!chain) {
    return null;
  }
  const eligible = completePosition
    ? chain.filter(
        (candidate) =>
          compareAmoPositions(candidate.position, position) < 0,
      )
    : chain;
  const head = eligible.at(-1);
  return head
    ? readWorkUsdQuote(pool, network, "quote.txid = $2", [head.txid])
    : null;
}

export async function proofIndexWorkUsdQuoteByTxid(network, txid) {
  const pool = proofIndexPool();
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  if (!pool || !/^[0-9a-f]{64}$/u.test(normalizedTxid)) {
    return null;
  }
  const chain = await canonicalWorkUsdQuoteChainRows(pool, network);
  if (!chain?.some((quote) => quote.txid === normalizedTxid)) {
    return null;
  }
  return readWorkUsdQuote(pool, network, "quote.txid = $2", [normalizedTxid]);
}

export async function proofIndexWorkAmoListingTerms(network, listingId) {
  const pool = proofIndexPool();
  const normalizedListingId = String(listingId ?? "").trim().toLowerCase();
  if (!pool || !/^[0-9a-f]{64}$/u.test(normalizedListingId)) {
    return null;
  }
  const result = await pool.query(
    `
      SELECT terms.*
      FROM proof_indexer.work_amo_listing_terms terms
      JOIN proof_indexer.transactions listing_tx
        ON listing_tx.network = terms.network
       AND listing_tx.txid = terms.listing_txid
       AND listing_tx.status = 'confirmed'
       AND listing_tx.block_hash = terms.listing_block_hash
       AND listing_tx.block_height = terms.listing_block_height
       AND listing_tx.block_index = terms.listing_block_index
      JOIN proof_indexer.blocks listing_block
        ON listing_block.network = listing_tx.network
       AND listing_block.block_hash = listing_tx.block_hash
       AND listing_block.height = listing_tx.block_height
       AND listing_block.canonical = true
      JOIN proof_indexer.events listing_event
        ON listing_event.network = terms.network
       AND listing_event.txid = terms.listing_txid
       AND listing_event.protocol = 'pwt1'
       AND listing_event.kind = 'token-listing'
       AND listing_event.status = 'confirmed'
       AND listing_event.valid = true
       AND listing_event.block_height = terms.listing_block_height
       AND listing_event.block_index = terms.listing_block_index
       AND listing_event.op_return_vout = terms.listing_protocol_vout
       AND listing_event.record_ordinal = terms.listing_record_ordinal
      JOIN proof_indexer.work_usd_quotes quote
        ON quote.network = terms.network
       AND quote.txid = terms.unit_usd_quote_txid
       AND quote.declaration_txid = $3
       AND quote.sequence = terms.unit_usd_quote_sequence
       AND quote.usd_per_100m_proofs_q8 =
         terms.unit_usd_per_100m_proofs_q8
       AND quote.block_hash = terms.unit_usd_quote_block_hash
       AND quote.block_height = terms.unit_usd_quote_block_height
       AND quote.block_index = terms.unit_usd_quote_block_index
       AND quote.protocol_vout = terms.unit_usd_quote_vout
       AND quote.record_ordinal = 0
       AND quote.authority_scriptpubkey = $4
       AND quote.record_count = 1
       AND quote.registry_address = $5
       AND quote.registry_payment_sats >= $6::bigint
       AND quote.registry_payment_vout >= 0
       AND quote.status = 'confirmed'
       AND quote.valid = true
      JOIN proof_indexer.transactions quote_tx
        ON quote_tx.network = quote.network
       AND quote_tx.txid = quote.txid
       AND quote_tx.status = 'confirmed'
       AND quote_tx.block_hash = quote.block_hash
       AND quote_tx.block_height = quote.block_height
       AND quote_tx.block_index = quote.block_index
      JOIN proof_indexer.blocks quote_block
        ON quote_block.network = quote_tx.network
       AND quote_block.block_hash = quote_tx.block_hash
       AND quote_block.height = quote_tx.block_height
       AND quote_block.canonical = true
      WHERE terms.network = $1
        AND terms.listing_id = $2
      LIMIT 2
    `,
    [
      network,
      normalizedListingId,
      WORK_AMO_V1_DECLARATION_TXID,
      WORK_AMO_V5_AUTHORITY_SCRIPTPUBKEY,
      WORK_AMO_V5_REGISTRY_ADDRESS,
      WORK_AMO_V5_MIN_REGISTRY_PAYMENT_SATS,
    ],
  );
  const terms = result.rows.length === 1
    ? normalizedWorkAmoListingTermsRow(result.rows[0])
    : null;
  if (!terms) {
    return null;
  }
  const quote = await proofIndexWorkUsdQuoteByTxid(
    network,
    terms.unitUsdQuoteTxid,
  );
  if (!quote) {
    return null;
  }
  const validation = validateWorkAmoV5FrozenTerms(terms.frozenTerms, {
    quote,
  });
  return validation.valid ? terms : null;
}

function normalizedWorkAmoV6ExpectedPins(value) {
  const pins =
    value && typeof value === "object" && !Array.isArray(value)
      ? value
      : {};
  const lowerHex = (...candidates) => {
    for (const candidate of candidates) {
      if (
        typeof candidate === "string" &&
        /^[0-9a-f]{64}$/u.test(candidate)
      ) {
        return candidate;
      }
    }
    return "";
  };
  const safeInteger = (minimum, ...candidates) => {
    for (const candidate of candidates) {
      if (candidate === undefined || candidate === null || candidate === "") {
        continue;
      }
      if (
        typeof candidate !== "number" &&
        (
          typeof candidate !== "string" ||
          !/^(?:0|[1-9][0-9]*)$/u.test(candidate)
        )
      ) {
        return null;
      }
      const parsed = Number(candidate);
      if (Number.isSafeInteger(parsed) && parsed >= minimum) {
        return parsed;
      }
      return null;
    }
    return null;
  };
  const declarationHeight = safeInteger(
    1,
    pins.declarationHeight,
    pins.blockHeight,
  );
  const activationHeight = safeInteger(
    2,
    pins.activationHeight,
  );
  const normalized = {
    activationHeight,
    declarationBlockHash: lowerHex(
      pins.declarationBlockHash,
      pins.blockHash,
    ),
    declarationBlockIndex: safeInteger(
      0,
      pins.declarationBlockIndex,
      pins.blockTransactionIndex,
      pins.blockIndex,
    ),
    declarationHeight,
    declarationMemoBytes: safeInteger(
      1,
      pins.declarationMemoBytes,
      pins.payloadBytes,
    ),
    declarationMemoSha256: lowerHex(
      pins.declarationMemoSha256,
      pins.payloadSha256,
    ),
    declarationProtocolVout: safeInteger(
      0,
      pins.declarationProtocolVout,
      pins.protocolVout,
    ),
    declarationRecordOrdinal: safeInteger(
      0,
      pins.declarationRecordOrdinal,
      pins.recordOrdinal,
    ),
    declarationRegistryPaymentVout: safeInteger(
      0,
      pins.declarationRegistryPaymentVout,
      pins.registryPaymentVout,
    ),
    declarationTxid: lowerHex(
      pins.declarationTxid,
      pins.txid,
    ),
  };
  return Object.values(normalized).some(
    (field) => field === "" || field === null,
  ) ||
    activationHeight !== declarationHeight + 1 ||
    normalized.declarationRecordOrdinal !== 0
    ? null
    : normalized;
}

function configuredWorkAmoV6ReaderPins(env = process.env) {
  const declarationHeight = Number(
    env.WORK_AMO_V6_DECLARATION_HEIGHT,
  );
  const pins = normalizedWorkAmoV6ExpectedPins({
    activationHeight:
      Number.isSafeInteger(declarationHeight) && declarationHeight > 0
        ? declarationHeight + 1
        : 0,
    declarationBlockHash:
      env.WORK_AMO_V6_DECLARATION_BLOCK_HASH,
    declarationBlockIndex:
      env.WORK_AMO_V6_DECLARATION_BLOCK_INDEX,
    declarationHeight,
    declarationMemoBytes:
      env.WORK_AMO_V6_DECLARATION_MEMO_BYTES,
    declarationMemoSha256:
      env.WORK_AMO_V6_DECLARATION_MEMO_SHA256,
    declarationProtocolVout:
      env.WORK_AMO_V6_DECLARATION_PROTOCOL_VOUT,
    declarationRecordOrdinal:
      env.WORK_AMO_V6_DECLARATION_RECORD_ORDINAL,
    declarationRegistryPaymentVout:
      env.WORK_AMO_V6_DECLARATION_REGISTRY_PAYMENT_VOUT,
    declarationTxid:
      env.WORK_AMO_V6_DECLARATION_TXID,
  });
  if (!pins) {
    return null;
  }
  let expectedDeclaration;
  try {
    expectedDeclaration = workAmoV6DeclarationCommitment();
  } catch {
    return null;
  }
  return pins.declarationMemoBytes ===
      expectedDeclaration.protocolRecordBytes &&
    pins.declarationMemoSha256 ===
      expectedDeclaration.protocolRecordSha256
    ? pins
    : null;
}

export function configuredWorkPrecisionV2ReaderPins(
  env = process.env,
) {
  const pins = normalizedWorkAmoV6ExpectedPins({
    activationHeight:
      env.WORK_AMO_V8_ACTIVATION_HEIGHT,
    declarationBlockHash:
      env.WORK_AMO_V8_DECLARATION_BLOCK_HASH,
    declarationBlockIndex:
      env.WORK_AMO_V8_DECLARATION_BLOCK_INDEX,
    declarationHeight:
      env.WORK_AMO_V8_DECLARATION_HEIGHT,
    declarationMemoBytes:
      env.WORK_AMO_V8_DECLARATION_MEMO_BYTES,
    declarationMemoSha256:
      env.WORK_AMO_V8_DECLARATION_MEMO_SHA256,
    declarationProtocolVout:
      env.WORK_AMO_V8_DECLARATION_PROTOCOL_VOUT,
    declarationRecordOrdinal:
      env.WORK_AMO_V8_DECLARATION_RECORD_ORDINAL,
    declarationRegistryPaymentVout:
      env.WORK_AMO_V8_DECLARATION_REGISTRY_PAYMENT_VOUT,
    declarationTxid:
      env.WORK_AMO_V8_DECLARATION_TXID,
  });
  if (!pins) {
    return null;
  }
  let expectedDeclaration;
  try {
    expectedDeclaration = workAmoV8DeclarationCommitment();
  } catch {
    return null;
  }
  return pins.declarationMemoBytes ===
      expectedDeclaration.protocolRecordBytes &&
    pins.declarationMemoSha256 ===
      expectedDeclaration.protocolRecordSha256
    ? pins
    : null;
}

function workAmoV6ReadinessIsCurrentAtSnapshot(
  readiness,
  pins,
  snapshotHeight,
) {
  const height = Number(snapshotHeight);
  return Boolean(
    pins &&
      readiness?.ready === true &&
      readiness?.active === true &&
      readiness?.canonical === true &&
      readiness?.confirmed === true &&
      readiness?.evidenceComplete === true &&
      Number(readiness?.activationHeight) === pins.activationHeight &&
      (
        height === 0 ||
        (
          Number.isSafeInteger(height) &&
          height >= pins.activationHeight
        )
      )
  );
}

async function currentWorkMarketAuthorizationVersionsAtSnapshot(
  network,
  snapshotHeight,
  workMarketV4Activation,
) {
  if (network !== "livenet") {
    return [WORK_MARKET_V2_AUTH_VERSION];
  }
  const configuredPrecisionPins =
    configuredWorkPrecisionV2ReaderPins();
  const precisionLatch =
    await proofIndexWorkAmoV8ActivationLatch(
      network,
      configuredPrecisionPins,
    ).catch(() => null);
  const precisionPins =
    configuredPrecisionPins ?? precisionLatch?.pins ?? null;
  const precisionBoundaryReached =
    precisionLatch?.reached === true ||
    (
      precisionPins &&
      (
        Number(snapshotHeight) === 0 ||
        Number(snapshotHeight) >= precisionPins.activationHeight
      )
    );
  if (precisionBoundaryReached) {
    if (!precisionPins) {
      return [];
    }
    const precisionReadiness =
      await proofIndexWorkPrecisionV2MigrationReadiness(
        network,
        precisionPins,
      ).catch(() => null);
    if (
      precisionReadiness?.ready === true &&
      precisionReadiness?.active === true &&
      precisionReadiness?.parityReady === true &&
      precisionReadiness?.replayReady === true
    ) {
      return [WORK_AMO_V8_AUTH_VERSION];
    }
    // Once the V8 declaration boundary or its persistent latch applies,
    // current balances and reservations must never fall back to Q8.
    // Historical records remain available through raw/history paths.
    return [];
  }
  const pins = configuredWorkAmoV6ReaderPins();
  if (
    pins &&
    (
      Number(snapshotHeight) === 0 ||
      Number(snapshotHeight) >= pins.activationHeight
    )
  ) {
    const readiness = await proofIndexWorkAmoV6MigrationReadiness(
      network,
      pins,
    ).catch(() => null);
    if (
      workAmoV6ReadinessIsCurrentAtSnapshot(
        readiness,
        pins,
        snapshotHeight,
      )
    ) {
      return [
        WORK_AMO_V6_AUTH_VERSION,
        WORK_AMO_V5_AUTH_VERSION,
        WORK_MARKET_V4_AUTH_VERSION,
      ];
    }
  }
  if (
    Number(snapshotHeight) === 0 ||
    Number(snapshotHeight) >= WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    return [
      WORK_AMO_V5_AUTH_VERSION,
      WORK_MARKET_V4_AUTH_VERSION,
    ];
  }
  return workMarketV4Activation
    ? [WORK_MARKET_V4_AUTH_VERSION]
    : [WORK_MARKET_V2_AUTH_VERSION];
}

function governedWorkListingVersion(record) {
  const payload = objectRecord(record?.payload);
  const saleAuthorization = objectRecord(
    record?.saleAuthorization ??
      payload.saleAuthorization ??
      payload.listingAuthorization,
  );
  const work =
    isWorkTokenId(
      record?.tokenId ??
        record?.token_id ??
        payload.tokenId ??
        saleAuthorization.tokenId,
    );
  const version = normalizedLowerText(saleAuthorization.version);
  return work && WORK_MARKET_GOVERNED_AUTH_VERSIONS.has(version)
    ? version
    : "";
}

function workListingAuthorizationAllowed(
  record,
  authorizationVersions,
) {
  const governedVersion = governedWorkListingVersion(record);
  return (
    !governedVersion ||
    new Set(
      (Array.isArray(authorizationVersions)
        ? authorizationVersions
        : []
      ).map(normalizedLowerText),
    ).has(governedVersion)
  );
}

function applyWorkAmoV6PublicListingReadPolicy(
  state,
  authorizationVersions,
) {
  if (
    !state ||
    typeof state !== "object" ||
    Array.isArray(state) ||
    !Array.isArray(state.listings)
  ) {
    return state;
  }
  return {
    ...state,
    listings: state.listings.filter(
      (listing) =>
        workListingAuthorizationAllowed(
          listing,
          authorizationVersions,
        ),
    ),
  };
}

async function payloadWithCurrentWorkMarketListingReadPolicy(
  network,
  payload,
) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return payload;
  }
  const snapshotHeight = Number(
    payload.indexedThroughBlock ??
      payload.stats?.indexedThroughBlock ??
      0,
  );
  const authorizationVersions =
    await currentWorkMarketAuthorizationVersionsAtSnapshot(
      network,
      snapshotHeight,
      payload.workMarketV4Activation,
    );
  return applyWorkAmoV6PublicListingReadPolicy(
    payload,
    authorizationVersions,
  );
}

export function workPrecisionV2ProjectCurrentPayload(payload) {
  const state = objectRecord(payload);
  const projectItems = (value) =>
    (Array.isArray(value) ? value : []).map((item) => {
      if (!isWorkTokenId(item?.tokenId)) {
        return item;
      }
      const amountPresent = [
        item?.amount,
        item?.tokenAmount,
        item?.amountAtoms,
        item?.tokenAmountAtoms,
        item?.amountSubatoms,
        item?.tokenAmountSubatoms,
        item?.saleAuthorization?.amount,
        item?.saleAuthorization?.amountAtoms,
        item?.saleAuthorization?.amountSubatoms,
      ].some(
        (candidate) =>
          candidate !== undefined &&
          candidate !== null &&
          candidate !== "",
      );
      if (!amountPresent) {
        return item;
      }
      const source = workAmountProjection(item, {
        allowZero: false,
      });
      const projected = workAmountProjection(item, {
        allowZero: false,
        targetStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
      });
      return {
        ...payloadWithWorkAmountProjection(item, projected),
        ...(source.amountStorageModel ===
        WORK_ATOMIC_PROJECTION_MODEL
          ? {
              sourceAmountEvidence: {
                amount: source.amount,
                ...workAmountProjectionMetadataForAmount(source),
              },
            }
          : {}),
      };
    });
  return {
    ...state,
    mints: projectItems(state.mints),
    transfers: projectItems(state.transfers),
    listings: projectItems(state.listings),
    closedListings: projectItems(state.closedListings),
    sales: projectItems(state.sales),
  };
}

export function workPrecisionV2CurrentPayloadIsExact(
  payload,
  activationHeight,
  { requireSupplyEnvelope = true } = {},
) {
  if (safeBlockHeight(activationHeight) === 0) {
    return false;
  }
  const state = objectRecord(payload);
  const tokens = Array.isArray(state.tokens) ? state.tokens : [];
  const workTokens = tokens.filter((token) =>
    isWorkTokenId(token?.tokenId),
  );
  const workItems = [
    ...(Array.isArray(state.mints) ? state.mints : []),
    ...(Array.isArray(state.transfers) ? state.transfers : []),
    ...(Array.isArray(state.listings) ? state.listings : []),
    ...(Array.isArray(state.closedListings)
      ? state.closedListings
      : []),
    ...(Array.isArray(state.sales) ? state.sales : []),
  ].filter((item) => isWorkTokenId(item?.tokenId));
  const carriesWork =
    workTokens.length > 0 ||
    workItems.length > 0 ||
    (Array.isArray(state.holders) &&
      state.holders.some((holder) =>
        isWorkTokenId(holder?.tokenId),
      ));
  if (!carriesWork) {
    return true;
  }
  if (
    workTokens.length !== 1 ||
    !validateWorkPrecisionMetadata(workTokens[0], {
      allowLegacy: false,
      allowSubatoms: true,
    }) ||
    workTokens[0].amountStorageModel !==
      WORK_SUBATOM_PROJECTION_MODEL ||
    workTokens[0].precisionModel !== WORK_PRECISION_V2_MODEL
  ) {
    return false;
  }
  const supplyEnvelopePresent =
    workTokens[0].confirmedSupplySubatoms !== undefined &&
    workTokens[0].pendingSupplySubatoms !== undefined;
  if (requireSupplyEnvelope && !supplyEnvelopePresent) {
    return false;
  }
  try {
    if (supplyEnvelopePresent) {
      normalizeWorkSubatoms(
        workTokens[0].confirmedSupplySubatoms,
        { allowZero: true },
      );
      normalizeWorkSubatoms(
        workTokens[0].pendingSupplySubatoms,
        { allowNegative: true, allowZero: true },
      );
    }
  } catch {
    return false;
  }
  if (
    workTokens[0].confirmedSupplyAtoms !== undefined ||
    workTokens[0].pendingSupplyAtoms !== undefined
  ) {
    return false;
  }
  if (requireSupplyEnvelope && tokens.length === 1) {
    if (
      !validateWorkPrecisionMetadata(state, {
        allowLegacy: false,
        allowSubatoms: true,
      }) ||
      state.amountStorageModel !== WORK_SUBATOM_PROJECTION_MODEL ||
      state.precisionModel !== WORK_PRECISION_V2_MODEL ||
      state.confirmedSupplyAtoms !== undefined ||
      state.pendingSupplyAtoms !== undefined
    ) {
      return false;
    }
    try {
      const confirmedSupplySubatoms = normalizeWorkSubatoms(
        state.confirmedSupplySubatoms,
        {
          allowZero: true,
        },
      );
      const pendingSupplySubatoms = normalizeWorkSubatoms(
        state.pendingSupplySubatoms,
        {
          allowNegative: true,
          allowZero: true,
        },
      );
      if (
        confirmedSupplySubatoms !==
          normalizeWorkSubatoms(
            workTokens[0].confirmedSupplySubatoms,
            { allowZero: true },
          ) ||
        pendingSupplySubatoms !==
          normalizeWorkSubatoms(
            workTokens[0].pendingSupplySubatoms,
            { allowNegative: true, allowZero: true },
          )
      ) {
        return false;
      }
    } catch {
      return false;
    }
  }
  const holders = (Array.isArray(state.holders)
    ? state.holders
    : []).filter((holder) => isWorkTokenId(holder?.tokenId));
  for (const holder of holders) {
    if (
      !validateWorkPrecisionMetadata(holder, {
        allowLegacy: false,
        allowSubatoms: true,
      }) ||
      holder.amountStorageModel !== WORK_SUBATOM_PROJECTION_MODEL ||
      holder.precisionModel !== WORK_PRECISION_V2_MODEL ||
      holder.balanceAtoms !== undefined ||
      holder.pendingDeltaAtoms !== undefined
    ) {
      return false;
    }
    try {
      normalizeWorkSubatoms(holder.balanceSubatoms, {
        allowZero: true,
      });
      normalizeWorkSubatoms(holder.pendingDeltaSubatoms, {
        allowNegative: true,
        allowZero: true,
      });
    } catch {
      return false;
    }
  }
  if (
    supplyEnvelopePresent &&
    holders.reduce(
      (total, holder) =>
        total + BigInt(String(holder.balanceSubatoms)),
      0n,
    ) !== BigInt(String(workTokens[0].confirmedSupplySubatoms))
  ) {
    return false;
  }
  for (const item of workItems) {
    const amountPresent = [
      item?.amount,
      item?.tokenAmount,
      item?.amountAtoms,
      item?.tokenAmountAtoms,
      item?.amountSubatoms,
      item?.tokenAmountSubatoms,
      item?.saleAuthorization?.amount,
      item?.saleAuthorization?.amountAtoms,
      item?.saleAuthorization?.amountSubatoms,
    ].some(
      (value) =>
        value !== undefined &&
        value !== null &&
        value !== "",
    );
    if (!amountPresent) {
      const pendingV7Intent =
        item?.confirmed !== true &&
        normalizedLowerText(
          item?.saleAuthorization?.version ??
            item?.listingAuthorization?.version,
        ) === WORK_AMO_V8_AUTH_VERSION;
      if (!pendingV7Intent) {
        return false;
      }
      continue;
    }
    if (
      !validateWorkPrecisionMetadata(item, {
        allowLegacy: false,
        allowSubatoms: true,
      }) ||
      item.amountStorageModel !== WORK_SUBATOM_PROJECTION_MODEL ||
      item.precisionModel !== WORK_PRECISION_V2_MODEL ||
      item.amountAtoms !== undefined ||
      item.tokenAmountAtoms !== undefined
    ) {
      return false;
    }
    let projection;
    try {
      projection = workAmountProjection(item, {
        allowZero: false,
      });
    } catch {
      return false;
    }
    if (
      projection.amountStorageModel !==
        WORK_SUBATOM_PROJECTION_MODEL
    ) {
      return false;
    }
  }
  return true;
}

async function payloadWithCurrentWorkPrecisionReadPolicy(
  network,
  payload,
  {
    allowCanonicalSummaryBootstrap = false,
    exactCheckpointHash = "",
    exactCheckpointHeight = 0,
    requireExactCheckpoint = false,
    requireSupplyEnvelope = true,
  } = {},
) {
  if (
    network !== "livenet" ||
    !payload ||
    typeof payload !== "object" ||
    Array.isArray(payload)
  ) {
    return payload;
  }
  const configuredPins = configuredWorkPrecisionV2ReaderPins();
  const latch = await proofIndexWorkAmoV8ActivationLatch(
    network,
    configuredPins,
  ).catch(() => null);
  const pins = configuredPins ?? latch?.pins ?? null;
  const payloadCarriesQ16Work = [
    ...(Array.isArray(payload.tokens) ? payload.tokens : []),
    ...(Array.isArray(payload.holders) ? payload.holders : []),
  ].some(
    (item) =>
      isWorkTokenId(item?.tokenId) &&
      item?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL,
  );
  if (!pins) {
    return payloadCarriesQ16Work ? null : payload;
  }
  const snapshotHeight = Number(
    payload.indexedThroughBlock ??
      payload.stats?.indexedThroughBlock ??
      0,
  );
  const boundaryApplies =
    latch?.reached === true ||
    snapshotHeight === 0 ||
    (
      Number.isSafeInteger(snapshotHeight) &&
      snapshotHeight >= pins.activationHeight
    );
  if (!boundaryApplies) {
    return payload;
  }
  const currentPayload =
    workPrecisionV2ProjectCurrentPayload(payload);
  const readiness =
    await proofIndexWorkPrecisionV2MigrationReadiness(
      network,
      pins,
    ).catch(() => null);
  const fullReadiness =
    readiness?.ready === true &&
    readiness?.active === true &&
    readiness?.evidenceComplete === true &&
    readiness?.parityReady === true &&
    readiness?.pendingReady === true &&
    readiness?.replayReady === true;
  const bootstrapReadiness =
    workPrecisionV2CanonicalSummaryBootstrapReady(readiness, pins, {
      allowCanonicalSummaryBootstrap,
      exactCheckpointHash,
      exactCheckpointHeight,
    });
  if (
    (!fullReadiness && !bootstrapReadiness) ||
    !workPrecisionV2CurrentPayloadIsExact(
      currentPayload,
      pins.activationHeight,
      { requireSupplyEnvelope },
    )
  ) {
    return null;
  }
  const snapshotBacked = normalizedLowerText(
    currentPayload.source,
  ).includes("snapshot");
  if (snapshotBacked || requireExactCheckpoint || bootstrapReadiness) {
    const payloadHash = normalizedLowerText(
      currentPayload.indexedThroughBlockHash,
    );
    if (
      snapshotHeight !== Number(readiness.tipHeight) ||
      payloadHash !== normalizedLowerText(readiness.tipHash)
    ) {
      return null;
    }
  }
  return currentPayload;
}

const WORK_PRECISION_V2_CANONICAL_BOOTSTRAP_CONSTRAINTS = Object.freeze([
  "activation",
  "definition",
  "markerImmutable",
  "transition",
  "v6",
  "v6Deactivation",
  "v6Immutable",
  "v7HistoryImmutable",
  "v7Immutable",
  "v8",
]);

function workPrecisionV2CanonicalSummaryBootstrapReady(
  readiness,
  pins,
  {
    allowCanonicalSummaryBootstrap = false,
    exactCheckpointHash = "",
    exactCheckpointHeight = 0,
  } = {},
) {
  const state =
    readiness && typeof readiness === "object" && !Array.isArray(readiness)
      ? readiness
      : {};
  const expected =
    pins && typeof pins === "object" && !Array.isArray(pins) ? pins : {};
  const precision =
    state.precision &&
    typeof state.precision === "object" &&
    !Array.isArray(state.precision)
      ? state.precision
      : {};
  const constraints =
    state.constraints &&
    typeof state.constraints === "object" &&
    !Array.isArray(state.constraints)
      ? state.constraints
      : {};
  const checkpointHeight = Number(exactCheckpointHeight);
  const checkpointHash = String(exactCheckpointHash ?? "")
    .trim()
    .toLowerCase();
  const lowerText = (value) => String(value ?? "").trim().toLowerCase();
  const sameInteger = (left, right) =>
    Number.isSafeInteger(Number(left)) && Number(left) === Number(right);
  return (
    allowCanonicalSummaryBootstrap === true &&
    Number.isSafeInteger(checkpointHeight) &&
    checkpointHeight >= Number(expected.activationHeight) &&
    /^[0-9a-f]{64}$/u.test(checkpointHash) &&
    state.canonical === true &&
    state.canonicalSummaryBootstrapReady === true &&
    state.confirmed === true &&
    state.confirmedReplayReady === true &&
    state.constraintsReady === true &&
    state.declarationIndexReady === true &&
    state.definitionReady === true &&
    state.evidenceComplete === true &&
    state.exactTipReady === true &&
    state.legacyProjectionReady === true &&
    state.markerReady === true &&
    state.openingReady === true &&
    state.parityReady === true &&
    sameInteger(state.activationHeight, expected.activationHeight) &&
    sameInteger(state.tipHeight, checkpointHeight) &&
    lowerText(state.tipHash) === checkpointHash &&
    precision.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL &&
    precision.decimals === WORK_SUBATOM_DECIMALS &&
    String(precision.unitScale ?? "") === WORK_SUBATOM_UNIT_SCALE_TEXT &&
    WORK_PRECISION_V2_CANONICAL_BOOTSTRAP_CONSTRAINTS.every(
      (constraint) => constraints[constraint] === true,
    )
  );
}

function workAmoV6PublicListingReadSql(
  listingAlias,
  authorizationVersions,
) {
  const alias = canonicalCreditListingAlias(listingAlias);
  const governedVersions = [
    ...WORK_MARKET_GOVERNED_AUTH_VERSIONS,
  ].sort(compareCanonicalUtf8);
  const allowedVersions = [
    ...new Set(
      (Array.isArray(authorizationVersions)
        ? authorizationVersions
        : []
      )
        .map(normalizedLowerText)
        .filter((version) =>
          WORK_MARKET_GOVERNED_AUTH_VERSIONS.has(version)
        ),
    ),
  ].sort(compareCanonicalUtf8);
  const sqlLiteralList = (versions) =>
    versions
      .map((version) => {
        if (!/^[a-z0-9-]+$/u.test(version)) {
          throw new Error(
            "WORK authorization version is not SQL-literal safe.",
          );
        }
        return `'${version}'`;
      })
      .join(", ");
  const allowedSql =
    allowedVersions.length > 0
      ? `OR lower(COALESCE(
        ${alias}.payload->'saleAuthorization'->>'version',
        ${alias}.payload->'listingAuthorization'->>'version',
        ''
      )) IN (${sqlLiteralList(allowedVersions)})`
      : "";
  return `(
    lower(COALESCE(${alias}.token_id, '')) <> '${WORK_TOKEN_ID}'
    OR lower(COALESCE(
      ${alias}.payload->'saleAuthorization'->>'version',
      ${alias}.payload->'listingAuthorization'->>'version',
      ''
    )) NOT IN (${sqlLiteralList(governedVersions)})
    ${allowedSql}
  )`;
}

function workAmoV6MarkerMatchesExpectedPins(marker, pins) {
  return Boolean(
    marker &&
      marker.activationHeight === pins.activationHeight &&
      String(marker.declarationBlockHash ?? "").toLowerCase() ===
        pins.declarationBlockHash &&
      Number(marker.declarationBlockIndex) ===
        pins.declarationBlockIndex &&
      Number(marker.declarationHeight) === pins.declarationHeight &&
      Number(marker.declarationMemoBytes) ===
        pins.declarationMemoBytes &&
      String(marker.declarationMemoSha256 ?? "").toLowerCase() ===
        pins.declarationMemoSha256 &&
      Number(marker.declarationProtocolVout) ===
        pins.declarationProtocolVout &&
      Number(marker.declarationRecordOrdinal) ===
        pins.declarationRecordOrdinal &&
      Number(marker.declarationRegistryPaymentVout) ===
        pins.declarationRegistryPaymentVout &&
      String(marker.declarationTxid ?? "").toLowerCase() ===
        pins.declarationTxid
  );
}

function workAmoV6IndexedEvidenceMatchesMarker(row, marker) {
  const evidence =
    marker?.declarationEvidence &&
    typeof marker.declarationEvidence === "object" &&
    !Array.isArray(marker.declarationEvidence)
      ? marker.declarationEvidence
      : {};
  const payloadHex = String(row?.payload_hex ?? "").trim().toLowerCase();
  if (!/^(?:[0-9a-f]{2})+$/u.test(payloadHex)) {
    return false;
  }
  const payload = Buffer.from(payloadHex, "hex");
  let expectedDeclaration;
  try {
    expectedDeclaration = workAmoV6DeclarationCommitment();
  } catch {
    return false;
  }
  if (
    !payload.equals(
      Buffer.from(expectedDeclaration.protocolRecord, "utf8"),
    ) ||
    row?.payload_text !== expectedDeclaration.protocolRecord ||
    Number(row?.data_bytes) !== payload.length
  ) {
    return false;
  }
  const facts = {
    authorityScriptPubKey: String(
      row?.authority_scriptpubkey ?? "",
    ).trim().toLowerCase(),
    blockHash: String(row?.block_hash ?? "").trim().toLowerCase(),
    blockHeight: Number(row?.block_height),
    blockTransactionIndex: Number(row?.block_index),
    inputCount: Number(row?.input_count),
    outputCount: Number(row?.output_count),
    payloadBytes: payload.length,
    payloadSha256: createHash("sha256").update(payload).digest("hex"),
    protocol: String(row?.protocol ?? "").trim().toLowerCase(),
    protocolVout: Number(row?.protocol_vout),
    recordOrdinal: Number(row?.record_ordinal),
    registryAddress: String(row?.registry_address ?? "").trim(),
    registryPaymentSats: String(
      row?.registry_payment_sats ?? "",
    ).trim(),
    registryPaymentVout: Number(row?.registry_payment_vout),
    txid: String(row?.txid ?? "").trim().toLowerCase(),
  };
  return Boolean(
    row?.status === "confirmed" &&
      Number(row?.raw_carrier_count) === 1 &&
      Number(row?.registry_output_count) === 1 &&
      Object.entries(facts).every(
        ([field, fact]) => evidence[field] === fact,
      )
  );
}

export async function proofIndexWorkAmoV6MigrationReadiness(
  network,
  expectedPins,
) {
  const pool = proofIndexPool();
  const pins = normalizedWorkAmoV6ExpectedPins(expectedPins);
  if (!pool || network !== "livenet" || !pins) {
    return null;
  }
  let expectedDeclaration;
  try {
    expectedDeclaration = workAmoV6DeclarationCommitment();
  } catch {
    return null;
  }
  const result = await pool.query(
    `
      SELECT
        migration.value AS migration_marker,
        declaration_tx.txid,
        declaration_tx.status,
        declaration_tx.block_hash,
        declaration_tx.block_height,
        declaration_tx.block_index,
        COALESCE(
          declaration_tx.raw_tx #>>
            '{vin,0,prevout,scriptPubKey,hex}',
          declaration_tx.raw_tx #>>
            '{vin,0,prevout,scriptpubkey}',
          ''
        ) AS authority_scriptpubkey,
        (
          SELECT count(*)::integer
          FROM proof_indexer.tx_inputs declaration_input
          WHERE declaration_input.network = declaration_tx.network
            AND declaration_input.txid = declaration_tx.txid
        ) AS input_count,
        (
          SELECT count(*)::integer
          FROM proof_indexer.tx_outputs declaration_output
          WHERE declaration_output.network = declaration_tx.network
            AND declaration_output.txid = declaration_tx.txid
        ) AS output_count,
        (
          SELECT count(*)::integer
          FROM proof_indexer.op_returns declaration_carrier
          WHERE declaration_carrier.network = declaration_tx.network
            AND declaration_carrier.txid = declaration_tx.txid
            AND declaration_carrier.vout = $7
            AND declaration_carrier.output_index = $8
        ) AS raw_carrier_count,
        (
          SELECT declaration_carrier.protocol
          FROM proof_indexer.op_returns declaration_carrier
          WHERE declaration_carrier.network = declaration_tx.network
            AND declaration_carrier.txid = declaration_tx.txid
            AND declaration_carrier.vout = $7
            AND declaration_carrier.output_index = $8
          LIMIT 1
        ) AS protocol,
        (
          SELECT declaration_carrier.payload_text
          FROM proof_indexer.op_returns declaration_carrier
          WHERE declaration_carrier.network = declaration_tx.network
            AND declaration_carrier.txid = declaration_tx.txid
            AND declaration_carrier.vout = $7
            AND declaration_carrier.output_index = $8
          LIMIT 1
        ) AS payload_text,
        (
          SELECT declaration_carrier.payload_hex
          FROM proof_indexer.op_returns declaration_carrier
          WHERE declaration_carrier.network = declaration_tx.network
            AND declaration_carrier.txid = declaration_tx.txid
            AND declaration_carrier.vout = $7
            AND declaration_carrier.output_index = $8
          LIMIT 1
        ) AS payload_hex,
        (
          SELECT declaration_carrier.data_bytes
          FROM proof_indexer.op_returns declaration_carrier
          WHERE declaration_carrier.network = declaration_tx.network
            AND declaration_carrier.txid = declaration_tx.txid
            AND declaration_carrier.vout = $7
            AND declaration_carrier.output_index = $8
          LIMIT 1
        ) AS data_bytes,
        $7::integer AS protocol_vout,
        $8::integer AS record_ordinal,
        (
          SELECT count(*)::integer
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = declaration_tx.network
            AND registry_output.txid = declaration_tx.txid
            AND registry_output.vout = $9
        ) AS registry_output_count,
        (
          SELECT registry_output.address
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = declaration_tx.network
            AND registry_output.txid = declaration_tx.txid
            AND registry_output.vout = $9
          LIMIT 1
        ) AS registry_address,
        (
          SELECT registry_output.value_sats::text
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = declaration_tx.network
            AND registry_output.txid = declaration_tx.txid
            AND registry_output.vout = $9
          LIMIT 1
        ) AS registry_payment_sats,
        $9::integer AS registry_payment_vout
      FROM proof_indexer.meta migration
      JOIN proof_indexer.transactions declaration_tx
        ON declaration_tx.network = $1
       AND declaration_tx.txid = $3
       AND declaration_tx.status = 'confirmed'
       AND declaration_tx.block_height = $4
       AND lower(declaration_tx.block_hash) = $5
       AND declaration_tx.block_index = $6
      JOIN proof_indexer.blocks declaration_block
        ON declaration_block.network = declaration_tx.network
       AND declaration_block.block_hash = declaration_tx.block_hash
       AND declaration_block.height = declaration_tx.block_height
       AND declaration_block.canonical = true
      WHERE migration.key = $2
      LIMIT 2
    `,
    [
      network,
      WORK_AMO_V6_INDEX_MIGRATION_META_KEY,
      pins.declarationTxid,
      pins.declarationHeight,
      pins.declarationBlockHash,
      pins.declarationBlockIndex,
      pins.declarationProtocolVout,
      pins.declarationRecordOrdinal,
      pins.declarationRegistryPaymentVout,
    ],
  );
  if (result.rows.length !== 1) {
    return null;
  }
  const row = result.rows[0];
  const marker = row.migration_marker;
  if (
    !workAmoV6MigrationMarkerBindsReader(marker) ||
    !workAmoV6MarkerMatchesExpectedPins(marker, pins) ||
    !workAmoV6IndexedEvidenceMatchesMarker(row, marker)
  ) {
    return null;
  }
  return {
    activationHeight: pins.activationHeight,
    active: true,
    canonical: true,
    confirmed: true,
    declarationEvidence: marker.declarationEvidence,
    evidenceComplete: true,
    marker,
    model: WORK_AMO_V6_INDEX_MIGRATION_MODEL,
    unitPolicy: {
      allowedFaceProofs: [...WORK_AMO_V6_ALLOWED_FACE_PROOFS],
      amountModel: WORK_AMO_V6_AMOUNT_MODEL,
      blockSequencerModel: WORK_AMO_V6_BLOCK_SEQUENCER_MODEL,
      bondTransitionModel: WORK_AMO_V6_BOND_TRANSITION_MODEL,
      declarationTxid: pins.declarationTxid,
      stateOrderModel: WORK_AMO_V6_STATE_ORDER_MODEL,
      unitModel: WORK_AMO_V6_UNIT_MODEL,
      unitWorkOracleModel: WORK_AMO_V6_UNIT_WORK_ORACLE_MODEL,
    },
    ready: true,
    status: "complete",
  };
}

function canonicalWorkPrecisionStateRows(
  rows,
  {
    amountField,
    keyField,
    pendingField = "",
  },
) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => ({
      amount: normalizeWorkSubatoms(row?.[amountField], {
        allowZero: true,
      }),
      key: String(row?.[keyField] ?? ""),
      ...(pendingField
        ? {
            pending: normalizeWorkSubatoms(row?.[pendingField], {
              allowNegative: true,
              allowZero: true,
            }),
          }
        : {}),
    }))
    .sort((left, right) =>
      compareCanonicalUtf8(left.key, right.key),
    );
}

function stableWorkPrecisionJson(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stableWorkPrecisionJson).join(",")}]`;
  }
  if (value && typeof value === "object") {
    return `{${
      Object.keys(value)
        .sort()
        .map(
          (key) =>
            `${JSON.stringify(key)}:${
              stableWorkPrecisionJson(value[key])
            }`,
        )
        .join(",")
    }}`;
  }
  return JSON.stringify(value ?? null);
}

function workPrecisionStateCommitment(rows, options) {
  const payload = stableWorkPrecisionJson(
    canonicalWorkPrecisionStateRows(rows, options),
  );
  return {
    count: rows.length,
    payloadBytes: Buffer.byteLength(payload, "utf8"),
    sha256: createHash("sha256")
      .update(Buffer.from(payload, "utf8"))
      .digest("hex"),
  };
}

function workQ16PendingCommitment(domain, rows) {
  return createHash("sha256")
    .update(
      Buffer.from(
        `ProofOfWork.Me/WORK-Q16-PENDING-${domain}/v1\n${
          stableWorkPrecisionJson(rows)
        }`,
        "utf8",
      ),
    )
    .digest("hex");
}

function workQ16PendingMembership({
  eventRows,
  listingRows,
  recoveryRows,
} = {}) {
  const isTxid = (value) => /^[0-9a-f]{64}$/u.test(value);
  const txids = new Set();
  const invalidMembers = [];
  const addRequiredTxid = (source, identity, value) => {
    const txid = normalizedLowerText(value);
    if (!isTxid(txid)) {
      invalidMembers.push({
        identity: String(identity ?? ""),
        reason: "missing-or-invalid-txid",
        source,
        value: String(value ?? ""),
      });
      return;
    }
    txids.add(txid);
  };
  const workMintDecisionCounts = new Map();
  const validProjectionCounts = new Map();
  for (const row of Array.isArray(eventRows) ? eventRows : []) {
    addRequiredTxid("event", row?.event_id, row?.txid);
    const txid = normalizedLowerText(row?.txid);
    const payload = objectRecord(row?.payload);
    const kind = normalizedLowerText(row?.kind);
    const workMintDecision =
      (kind === "token-mint" && row?.valid === true) ||
      (kind === "token-event-invalid" &&
        row?.valid === false &&
        (
          payload.provisionalReason === "supply-cap" ||
          String(payload.reason ?? "").startsWith(
            "WORK mint exceeds max supply:",
          )
        ));
    if (isTxid(txid) && workMintDecision) {
      workMintDecisionCounts.set(
        txid,
        Number(workMintDecisionCounts.get(txid) ?? 0) + 1,
      );
    }
    if (isTxid(txid) && row?.valid === true) {
      validProjectionCounts.set(
        txid,
        Number(validProjectionCounts.get(txid) ?? 0) + 1,
      );
    }
  }
  for (const row of Array.isArray(listingRows) ? listingRows : []) {
    addRequiredTxid(
      "listing",
      row?.listing_id,
      row?.membership_txid,
    );
    const txid = normalizedLowerText(row?.membership_txid);
    if (isTxid(txid)) {
      validProjectionCounts.set(
        txid,
        Number(validProjectionCounts.get(txid) ?? 0) + 1,
      );
    }
  }
  for (const row of Array.isArray(recoveryRows) ? recoveryRows : []) {
    const raw = objectRecord(row?.raw_tx);
    const attemptValue = raw.pendingWorkMintAttemptCount;
    const attemptValid =
      Number.isSafeInteger(attemptValue) && attemptValue >= 0;
    const attemptCount = attemptValid ? attemptValue : -1;
    const inspectionVersion =
      raw.pendingWorkMintInspectionVersion;
    const recoveryValue = raw.pendingWorkMintRecoveryNeeded;
    const recoveryDeclared = typeof recoveryValue === "boolean";
    const recoveryNeeded = recoveryValue === true;
    const resolvedInvalidValue =
      raw.pendingWorkMintResolvedInvalid;
    const resolvedInvalidDeclared =
      typeof resolvedInvalidValue === "boolean";
    const resolvedInvalid = resolvedInvalidValue === true;
    const protocolResolvedInvalidValue =
      raw.pendingProtocolResolvedInvalid;
    const protocolResolvedInvalidDeclared =
      typeof protocolResolvedInvalidValue === "boolean";
    const protocolResolvedInvalid =
      protocolResolvedInvalidValue === true;
    if (
      row?.status !== "pending" ||
      !attemptValid ||
      !Number.isSafeInteger(attemptCount) ||
      inspectionVersion !== 1 ||
      !recoveryDeclared ||
      !resolvedInvalidDeclared ||
      !protocolResolvedInvalidDeclared ||
      (attemptCount === 0 && (recoveryNeeded || resolvedInvalid))
    ) {
      invalidMembers.push({
        identity: String(row?.txid ?? ""),
        reason: "malformed-work-recovery-marker",
        source: "recovery",
        value: String(row?.txid ?? ""),
      });
      continue;
    }
    if (attemptCount === 0) {
      continue;
    }
    addRequiredTxid("recovery", row?.txid, row?.txid);
    const txid = normalizedLowerText(row?.txid);
    const decisionCount = Number(workMintDecisionCounts.get(txid) ?? 0);
    const validProjectionCount = Number(
      validProjectionCounts.get(txid) ?? 0,
    );
    const terminalMarker =
      resolvedInvalid || protocolResolvedInvalid;
    let invalidReason = "";
    if (recoveryNeeded) {
      invalidReason = "work-recovery-unresolved";
    } else if (protocolResolvedInvalid && validProjectionCount > 0) {
      invalidReason = "protocol-terminal-valid-projection-conflict";
    } else if (attemptCount > 1) {
      invalidReason = protocolResolvedInvalid
        ? ""
        : "ambiguous-multi-mint-recovery";
    } else if (decisionCount === 0 && !terminalMarker) {
      invalidReason = "work-decision-missing";
    } else if (decisionCount > 1 || (decisionCount > 0 && resolvedInvalid)) {
      invalidReason = "work-decision-conflict";
    }
    if (invalidReason) {
      invalidMembers.push({
        identity: String(row?.txid ?? ""),
        reason: invalidReason,
        source: "recovery",
        value: String(row?.txid ?? ""),
      });
    }
  }
  const expectedTxids = [...txids].sort(compareCanonicalUtf8);
  invalidMembers.sort((left, right) =>
    compareCanonicalUtf8(
      stableWorkPrecisionJson(left),
      stableWorkPrecisionJson(right),
    )
  );
  return {
    expectedTxidCount: expectedTxids.length,
    expectedTxids,
    expectedTxidsSha256: workQ16PendingCommitment(
      "MEMBERSHIP",
      expectedTxids,
    ),
    invalidCount: invalidMembers.length,
    invalidSha256: workQ16PendingCommitment(
      "INVALID-MEMBERSHIP",
      invalidMembers,
    ),
    model: "canonical-work-q16-pending-membership-v2",
  };
}

function workQ16PendingInspectionMarkerReason(
  row,
  decisionCount = 0,
  validProjectionCount = 0,
) {
  const raw = objectRecord(row?.raw_tx);
  const attemptCount = raw.pendingWorkMintAttemptCount;
  const inspectionVersion = raw.pendingWorkMintInspectionVersion;
  const recoveryNeeded = raw.pendingWorkMintRecoveryNeeded;
  const resolvedInvalid = raw.pendingWorkMintResolvedInvalid;
  const protocolResolvedInvalid = raw.pendingProtocolResolvedInvalid;
  if (
    row?.status !== "pending" ||
    !Number.isSafeInteger(attemptCount) ||
    attemptCount < 0 ||
    inspectionVersion !== 1 ||
    typeof recoveryNeeded !== "boolean" ||
    typeof resolvedInvalid !== "boolean" ||
    typeof protocolResolvedInvalid !== "boolean"
  ) {
    return "malformed-work-inspection-marker";
  }
  if (attemptCount === 0) {
    return recoveryNeeded ||
        resolvedInvalid ||
        decisionCount !== 0 ||
        (protocolResolvedInvalid && validProjectionCount > 0)
      ? "work-inspection-zero-attempt-conflict"
      : "";
  }
  if (recoveryNeeded) {
    return "work-recovery-unresolved";
  }
  if (protocolResolvedInvalid && validProjectionCount > 0) {
    return "protocol-terminal-valid-projection-conflict";
  }
  if (attemptCount > 1) {
    return protocolResolvedInvalid
      ? ""
      : "ambiguous-multi-mint-recovery";
  }
  const terminalMarker = resolvedInvalid || protocolResolvedInvalid;
  if (decisionCount === 0 && !terminalMarker) {
    return "work-decision-missing";
  }
  if (decisionCount > 1 || (decisionCount > 0 && resolvedInvalid)) {
    return "work-decision-conflict";
  }
  return "";
}

function workQ16PendingParity({
  balances,
  events,
  listings,
  mempoolTxids,
  recoveryRows,
  transactions,
}) {
  const isTxid = (value) => /^[0-9a-f]{64}$/u.test(value);
  const mempool = new Set(
    (Array.isArray(mempoolTxids) ? mempoolTxids : [])
      .map(normalizedLowerText)
      .filter(isTxid),
  );
  const membership = workQ16PendingMembership({
    eventRows: events,
    listingRows: listings,
    recoveryRows,
  });
  const expectedTxids = membership.expectedTxids;
  const outsideMempoolTxids = expectedTxids.filter(
    (txid) => !mempool.has(txid),
  );
  const transactionRows = new Map();
  let duplicateTransactionCount = 0;
  for (const row of Array.isArray(transactions) ? transactions : []) {
    const txid = normalizedLowerText(row?.txid);
    if (!isTxid(txid) || !mempool.has(txid)) {
      continue;
    }
    if (transactionRows.has(txid)) {
      duplicateTransactionCount += 1;
    }
    transactionRows.set(txid, row);
  }
  const missingTransactionTxids = expectedTxids.filter(
    (txid) =>
      !transactionRows.has(txid) ||
      transactionRows.get(txid)?.status !== "pending",
  );
  const workMintDecisionCounts = new Map();
  const validProjectionCounts = new Map();
  for (const row of Array.isArray(events) ? events : []) {
    const txid = normalizedLowerText(row?.txid);
    const payload = objectRecord(row?.payload);
    const kind = normalizedLowerText(row?.kind);
    const decision =
      (kind === "token-mint" && row?.valid === true) ||
      (kind === "token-event-invalid" &&
        row?.valid === false &&
        (
          payload.provisionalReason === "supply-cap" ||
          String(payload.reason ?? "").startsWith(
            "WORK mint exceeds max supply:",
          )
        ));
    if (isTxid(txid) && decision) {
      workMintDecisionCounts.set(
        txid,
        Number(workMintDecisionCounts.get(txid) ?? 0) + 1,
      );
    }
    if (isTxid(txid) && row?.valid === true) {
      validProjectionCounts.set(
        txid,
        Number(validProjectionCounts.get(txid) ?? 0) + 1,
      );
    }
  }
  for (const row of Array.isArray(listings) ? listings : []) {
    const txid = normalizedLowerText(row?.membership_txid);
    if (isTxid(txid)) {
      validProjectionCounts.set(
        txid,
        Number(validProjectionCounts.get(txid) ?? 0) + 1,
      );
    }
  }
  const invalidInspectionRows = expectedTxids.flatMap((txid) => {
    const row = transactionRows.get(txid);
    if (!row) {
      return [];
    }
    const reason = workQ16PendingInspectionMarkerReason(
      row,
      Number(workMintDecisionCounts.get(txid) ?? 0),
      Number(validProjectionCounts.get(txid) ?? 0),
    );
    return reason ? [{ reason, txid }] : [];
  });
  const observedNonzeroBalanceRows =
    Array.isArray(balances) ? balances : [];
  const {
    expectedTxids: _expectedTxids,
    ...membershipCommitment
  } = membership;
  return {
    balanceDeltas: {
      expectedNonzeroCount: 0,
      model:
        "pending-work-events-do-not-mutate-holder-balances-v1",
      observedNonzeroCount: observedNonzeroBalanceRows.length,
      observedSha256: workQ16PendingCommitment(
        "BALANCE-DELTA-PARITY",
        observedNonzeroBalanceRows,
      ),
    },
    membership: {
      ...membershipCommitment,
      outsideMempoolCount: outsideMempoolTxids.length,
      outsideMempoolTxidsSha256: workQ16PendingCommitment(
        "OUTSIDE-MEMPOOL",
        outsideMempoolTxids,
      ),
    },
    model: "canonical-work-q16-pending-parity-v2",
    ready:
      membership.invalidCount === 0 &&
      outsideMempoolTxids.length === 0 &&
      duplicateTransactionCount === 0 &&
      missingTransactionTxids.length === 0 &&
      invalidInspectionRows.length === 0 &&
      observedNonzeroBalanceRows.length === 0,
    transactions: {
      duplicateCount: duplicateTransactionCount,
      expectedCount: expectedTxids.length,
      inspectionInvalidCount: invalidInspectionRows.length,
      inspectionInvalidSha256: workQ16PendingCommitment(
        "INVALID-INSPECTION",
        invalidInspectionRows,
      ),
      matchedCount:
        expectedTxids.length - missingTransactionTxids.length,
      missingCount: missingTransactionTxids.length,
      missingTxidsSha256: workQ16PendingCommitment(
        "MISSING-TRANSACTIONS",
        missingTransactionTxids,
      ),
    },
  };
}

function workPrecisionMarkerMatchesPins(marker, pins) {
  return Boolean(
    marker &&
      marker.activationHeight === pins.activationHeight &&
      marker.declarationBlockHash ===
        pins.declarationBlockHash &&
      marker.declarationBlockIndex ===
        pins.declarationBlockIndex &&
      marker.declarationHeight === pins.declarationHeight &&
      marker.declarationMemoBytes ===
        pins.declarationMemoBytes &&
      marker.declarationMemoSha256 ===
        pins.declarationMemoSha256 &&
      marker.declarationProtocolVout ===
        pins.declarationProtocolVout &&
      marker.declarationRecordOrdinal ===
        pins.declarationRecordOrdinal &&
      marker.declarationRegistryPaymentVout ===
        pins.declarationRegistryPaymentVout &&
      marker.declarationTxid ===
        pins.declarationTxid
  );
}

function exactWorkPrecisionObjectKeys(value, expectedKeys) {
  const keys = Object.keys(objectRecord(value)).sort();
  const expected = [...expectedKeys].sort();
  return (
    keys.length === expected.length &&
    keys.every((key, index) => key === expected[index])
  );
}

function exactWorkPrecisionJsonInteger(value, minimum = 0) {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value >= minimum
  );
}

function workPrecisionCommitmentShapeReady(
  value,
  { model = "" } = {},
) {
  const commitment = objectRecord(value);
  return (
    (
      !model ||
      exactWorkPrecisionObjectKeys(
        commitment,
        ["model", "payloadBytes", "sha256"],
      )
    ) &&
    (!model || commitment.model === model) &&
    exactWorkPrecisionJsonInteger(
      commitment.payloadBytes,
      1,
    ) &&
    /^[0-9a-f]{64}$/u.test(String(commitment.sha256 ?? "")) &&
    commitment.sha256 === normalizedLowerText(commitment.sha256)
  );
}

function workPrecisionRowsCommitmentShapeReady(value) {
  const commitment = objectRecord(value);
  return (
    exactWorkPrecisionObjectKeys(
      commitment,
      ["count", "payloadBytes", "sha256"],
    ) &&
    exactWorkPrecisionJsonInteger(commitment.count) &&
    workPrecisionCommitmentShapeReady(commitment)
  );
}

function workPrecisionRelicCutoverReady(value) {
  const cutover = objectRecord(value);
  const items = Array.isArray(cutover.items) ? cutover.items : null;
  if (
    !items ||
    !exactWorkPrecisionObjectKeys(cutover, [
      "count",
      "items",
      "model",
      "payloadBytes",
      "sha256",
    ]) ||
    cutover.model !== WORK_AMO_V8_RELIC_CUTOVER_MODEL ||
    !exactWorkPrecisionJsonInteger(cutover.count) ||
    cutover.count !== items.length
  ) {
    return false;
  }
  let previousListingId = "";
  for (const itemValue of items) {
    const item = objectRecord(itemValue);
    const listingId = String(item.listingId ?? "");
    const sellerAddress = String(item.sellerAddress ?? "");
    if (
      !exactWorkPrecisionObjectKeys(item, [
        "amountAtoms",
        "listingId",
        "priceSats",
        "sellerAddress",
      ]) ||
      !/^[1-9][0-9]*$/u.test(String(item.amountAtoms ?? "")) ||
      !/^[0-9a-f]{64}$/u.test(listingId) ||
      !/^[1-9][0-9]*$/u.test(String(item.priceSats ?? "")) ||
      !sellerAddress ||
      sellerAddress !== sellerAddress.trim() ||
      sellerAddress.length > 128 ||
      (previousListingId &&
        compareCanonicalUtf8(previousListingId, listingId) >= 0)
    ) {
      return false;
    }
    previousListingId = listingId;
  }
  const payload = stableWorkPrecisionJson(items);
  return (
    cutover.payloadBytes === Buffer.byteLength(payload, "utf8") &&
    cutover.sha256 ===
      createHash("sha256")
        .update(Buffer.from(payload, "utf8"))
        .digest("hex")
  );
}

function workPrecisionV2MarkerBindsReader(marker, pins) {
  const evidence = objectRecord(marker?.declarationEvidence);
  const activationOpening = objectRecord(
    marker?.activationOpening,
  );
  const before = objectRecord(marker?.before);
  const after = objectRecord(marker?.after);
  const relicCutover = objectRecord(marker?.relicCutover);
  const legacyOpeningCommitment = objectRecord(
    activationOpening.legacyTokenStateCommitment,
  );
  const subatomOpeningCommitment = objectRecord(
    activationOpening.subatomTokenStateCommitment,
  );
  const committed = {
    authorityScriptPubKey: normalizedLowerText(
      evidence.authorityScriptPubKey,
    ),
    blockHash: normalizedLowerText(evidence.blockHash),
    blockHeight: Number(evidence.blockHeight),
    blockTransactionIndex: Number(
      evidence.blockTransactionIndex,
    ),
    inputCount: Number(evidence.inputCount),
    outputCount: Number(evidence.outputCount),
    payloadBytes: Number(evidence.payloadBytes),
    payloadSha256: normalizedLowerText(evidence.payloadSha256),
    protocol: normalizedLowerText(evidence.protocol),
    protocolVout: Number(evidence.protocolVout),
    recordOrdinal: Number(evidence.recordOrdinal),
    registryAddress: String(evidence.registryAddress ?? "").trim(),
    registryPaymentSats: String(
      evidence.registryPaymentSats ?? "",
    ).trim(),
    registryPaymentVout: Number(evidence.registryPaymentVout),
    txid: normalizedLowerText(evidence.txid),
  };
  let expectedDeclaration;
  try {
    expectedDeclaration = workAmoV8DeclarationCommitment();
  } catch {
    return false;
  }
  const evidenceCommitment = createHash("sha256")
    .update(
      Buffer.from(
        `${WORK_PRECISION_V2_DECLARATION_INDEX_EVIDENCE_DOMAIN}\n${
          JSON.stringify(committed)
        }`,
        "utf8",
      ),
    )
    .digest("hex");
  const markerKeys = [
    "activationHeight",
    "activationOpening",
    "after",
    "before",
    "completedAt",
    "conversionFactor",
    "declarationBlockHash",
    "declarationBlockIndex",
    "declarationEvidence",
    "declarationHeight",
    "declarationMemoBytes",
    "declarationMemoSha256",
    "declarationProtocolVout",
    "declarationRecordOrdinal",
    "declarationRegistryPaymentVout",
    "declarationTextBytes",
    "declarationTextSha256",
    "declarationTxid",
    "decimals",
    "derivedProjectionPolicy",
    "globalPrecisionModel",
    "legacyDecimals",
    "legacyProjectionModel",
    "maxSupplySubatoms",
    "migrationModel",
    "mintAmountSubatoms",
    "model",
    "network",
    "projectionModel",
    "rawConfirmedHistoryMutation",
    "relicCutover",
    "replayFromHeight",
    "snapshotPolicy",
    "status",
    "transferVersion",
    "unitScale",
    "updatedAt",
    "version",
  ];
  const evidenceKeys = [
    "authorityScriptPubKey",
    "blockHash",
    "blockHeight",
    "blockTransactionIndex",
    "commitmentSha256",
    "coreVerified",
    "evidenceComplete",
    "indexVerified",
    "inputCount",
    "model",
    "outputCount",
    "payloadBytes",
    "payloadSha256",
    "protocol",
    "protocolVout",
    "recordOrdinal",
    "registryAddress",
    "registryPaymentSats",
    "registryPaymentVout",
    "txid",
  ];
  return Boolean(
    sharedWorkPrecisionV2MarkerReady(marker, pins) &&
      exactWorkPrecisionObjectKeys(marker, markerKeys) &&
      exactWorkPrecisionObjectKeys(
        activationOpening,
        [
          "declarationClosingStatePayloadBytes",
          "declarationClosingStateSha256",
          "declarationTransitionModel",
          "legacyTokenStateCommitment",
          "subatomTokenStateCommitment",
        ],
      ) &&
      exactWorkPrecisionObjectKeys(before, [
        "balances",
        "listings",
      ]) &&
      exactWorkPrecisionObjectKeys(after, [
        "balances",
        "listings",
      ]) &&
      exactWorkPrecisionObjectKeys(evidence, evidenceKeys) &&
      marker?.model === WORK_PRECISION_V2_MIGRATION_MODEL &&
      marker?.migrationModel ===
        WORK_PRECISION_V2_MIGRATION_MODEL &&
      marker?.status === "complete" &&
      marker?.network === "livenet" &&
      marker?.version === WORK_AMO_V8_AUTH_VERSION &&
      marker?.globalPrecisionModel === WORK_PRECISION_V2_MODEL &&
      marker?.projectionModel === WORK_SUBATOM_PROJECTION_MODEL &&
      marker?.legacyProjectionModel ===
        WORK_ATOMIC_PROJECTION_MODEL &&
      marker?.transferVersion === WORK_AMO_V8_TRANSFER_VERSION &&
      marker?.legacyDecimals === WORK_DECIMALS &&
      marker?.decimals === WORK_SUBATOM_DECIMALS &&
      String(marker?.conversionFactor ?? "") === "100000000" &&
      String(marker?.unitScale ?? "") ===
        WORK_SUBATOM_UNIT_SCALE_TEXT &&
      String(marker?.maxSupplySubatoms ?? "") ===
        "210000000000000000000000" &&
      String(marker?.mintAmountSubatoms ?? "") ===
        WORK_AMO_V8_MINT_AMOUNT_SUBATOMS.toString() &&
      marker?.declarationTextBytes ===
        expectedDeclaration.payloadBytes &&
      marker?.declarationTextSha256 ===
        expectedDeclaration.payloadSha256 &&
      marker?.rawConfirmedHistoryMutation === "none" &&
      marker?.derivedProjectionPolicy ===
        "invalidate-and-replay-from-activation" &&
      marker?.replayFromHeight === pins.activationHeight &&
      marker?.snapshotPolicy ===
        "preserve-preactivation-canonical-invalidate-wrong-era-derived-require-post-migration-current-snapshot" &&
      activationOpening.declarationTransitionModel ===
        WORK_AMO_V6_BLOCK_SEQUENCER_MODEL &&
      exactWorkPrecisionJsonInteger(
        activationOpening.declarationClosingStatePayloadBytes,
        1,
      ) &&
      /^[0-9a-f]{64}$/u.test(
        normalizedLowerText(
          activationOpening.declarationClosingStateSha256,
        ),
      ) &&
      workPrecisionCommitmentShapeReady(
        legacyOpeningCommitment,
        { model: WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL },
      ) &&
      workPrecisionCommitmentShapeReady(
        subatomOpeningCommitment,
        { model: WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL },
      ) &&
      workPrecisionRowsCommitmentShapeReady(before.balances) &&
      workPrecisionRowsCommitmentShapeReady(before.listings) &&
      workPrecisionRowsCommitmentShapeReady(after.balances) &&
      workPrecisionRowsCommitmentShapeReady(after.listings) &&
      workPrecisionRelicCutoverReady(relicCutover) &&
      workPrecisionMarkerMatchesPins(marker, pins) &&
      evidence.model ===
        WORK_PRECISION_V2_DECLARATION_INDEX_EVIDENCE_MODEL &&
      evidence.coreVerified === true &&
      evidence.indexVerified === true &&
      evidence.evidenceComplete === true &&
      exactWorkPrecisionJsonInteger(evidence.blockHeight, 1) &&
      exactWorkPrecisionJsonInteger(
        evidence.blockTransactionIndex,
      ) &&
      exactWorkPrecisionJsonInteger(evidence.inputCount, 1) &&
      exactWorkPrecisionJsonInteger(evidence.outputCount, 1) &&
      exactWorkPrecisionJsonInteger(evidence.payloadBytes, 1) &&
      exactWorkPrecisionJsonInteger(evidence.protocolVout) &&
      exactWorkPrecisionJsonInteger(evidence.recordOrdinal) &&
      exactWorkPrecisionJsonInteger(
        evidence.registryPaymentVout,
      ) &&
      evidence.authorityScriptPubKey ===
        normalizedLowerText(evidence.authorityScriptPubKey) &&
      evidence.blockHash === normalizedLowerText(evidence.blockHash) &&
      evidence.payloadSha256 ===
        normalizedLowerText(evidence.payloadSha256) &&
      evidence.txid === normalizedLowerText(evidence.txid) &&
      evidence.registryAddress ===
        String(evidence.registryAddress ?? "").trim() &&
      evidence.registryPaymentSats ===
        String(evidence.registryPaymentSats ?? "").trim() &&
      normalizedLowerText(evidence.commitmentSha256) ===
        evidenceCommitment &&
      committed.authorityScriptPubKey ===
        WORK_AMO_V5_AUTHORITY_SCRIPTPUBKEY &&
      committed.blockHash === pins.declarationBlockHash &&
      committed.blockHeight === pins.declarationHeight &&
      committed.blockTransactionIndex ===
        pins.declarationBlockIndex &&
      committed.payloadBytes ===
        expectedDeclaration.protocolRecordBytes &&
      committed.payloadSha256 ===
        expectedDeclaration.protocolRecordSha256 &&
      committed.protocol === "pwm1" &&
      committed.protocolVout === pins.declarationProtocolVout &&
      committed.recordOrdinal === pins.declarationRecordOrdinal &&
      committed.registryAddress === WORK_AMO_V5_REGISTRY_ADDRESS &&
      /^[1-9][0-9]*$/u.test(committed.registryPaymentSats) &&
      BigInt(committed.registryPaymentSats) >=
        BigInt(WORK_AMO_V5_MIN_REGISTRY_PAYMENT_SATS) &&
      committed.registryPaymentVout ===
        pins.declarationRegistryPaymentVout &&
      committed.txid === pins.declarationTxid &&
      Number.isFinite(Date.parse(String(marker.completedAt ?? ""))) &&
      Number.isFinite(Date.parse(String(marker.updatedAt ?? "")))
  );
}

function indexedWorkPrecisionEvidenceMatchesMarker(row, marker) {
  const evidence = objectRecord(marker?.declarationEvidence);
  const payloadHex = normalizedLowerText(row?.payload_hex);
  if (!/^(?:[0-9a-f]{2})+$/u.test(payloadHex)) {
    return false;
  }
  const payload = Buffer.from(payloadHex, "hex");
  let expectedDeclaration;
  try {
    expectedDeclaration = workAmoV8DeclarationCommitment();
  } catch {
    return false;
  }
  return Boolean(
    payload.equals(
      Buffer.from(expectedDeclaration.protocolRecord, "utf8"),
    ) &&
      row?.payload_text === expectedDeclaration.protocolRecord &&
      Number(row?.data_bytes) === payload.length &&
      normalizedLowerText(row?.txid) === evidence.txid &&
      normalizedLowerText(row?.block_hash) === evidence.blockHash &&
      Number(row?.block_height) === evidence.blockHeight &&
      Number(row?.block_index) === evidence.blockTransactionIndex &&
      normalizedLowerText(row?.authority_scriptpubkey) ===
        evidence.authorityScriptPubKey &&
      Number(row?.input_count) === evidence.inputCount &&
      Number(row?.output_count) === evidence.outputCount &&
      normalizedLowerText(row?.protocol) === evidence.protocol &&
      String(row?.registry_address ?? "").trim() ===
        evidence.registryAddress &&
      String(row?.registry_payment_sats ?? "").trim() ===
        evidence.registryPaymentSats
  );
}

export async function proofIndexWorkPrecisionV2MigrationReadiness(
  network,
  expectedPins,
) {
  const pool = proofIndexPool();
  const pins = normalizedWorkAmoV6ExpectedPins(expectedPins);
  if (!pool || network !== "livenet" || !pins) {
    return null;
  }
  const client = await pool.connect();
  let transactionOpen = false;
  try {
    await client.query(
      "BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY",
    );
    transactionOpen = true;
  const stateResult = await client.query(
    `
      SELECT
        migration.value AS migration_marker,
        definition.max_supply::text,
        definition.mint_amount::text,
        definition.metadata AS definition_metadata,
        tx.txid,
        tx.block_hash,
        tx.block_height,
        tx.block_index,
        COALESCE(
          tx.raw_tx #>> '{vin,0,prevout,scriptPubKey,hex}',
          tx.raw_tx #>> '{vin,0,prevout,scriptpubkey}',
          ''
        ) AS authority_scriptpubkey,
        (SELECT count(*)::integer FROM proof_indexer.tx_inputs i
          WHERE i.network = tx.network AND i.txid = tx.txid) AS input_count,
        (SELECT count(*)::integer FROM proof_indexer.tx_outputs o
          WHERE o.network = tx.network AND o.txid = tx.txid) AS output_count,
        carrier.protocol,
        carrier.payload_text,
        carrier.payload_hex,
        carrier.data_bytes,
        registry.address AS registry_address,
        registry.value_sats::text AS registry_payment_sats,
        (
          SELECT max(block.height)::integer
          FROM proof_indexer.blocks block
          WHERE block.network = $1 AND block.canonical = true
        ) AS tip_height,
        (
          SELECT block.block_hash
          FROM proof_indexer.blocks block
          WHERE block.network = $1 AND block.canonical = true
          ORDER BY block.height DESC
          LIMIT 1
        ) AS tip_hash,
        (
          SELECT transition.block_height
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.complete = true
          ORDER BY transition.block_height DESC
          LIMIT 1
        ) AS transition_height,
        (
          SELECT transition.block_hash
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.complete = true
          ORDER BY transition.block_height DESC
          LIMIT 1
        ) AS transition_hash,
        (
          SELECT transition.model
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.complete = true
          ORDER BY transition.block_height DESC
          LIMIT 1
        ) AS transition_model,
        (
          SELECT transition.work_token_state_model
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.complete = true
          ORDER BY transition.block_height DESC
          LIMIT 1
        ) AS work_token_state_model,
        (
          SELECT transition.payload
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.complete = true
          ORDER BY transition.block_height DESC
          LIMIT 1
        ) AS transition_payload,
        (
          SELECT transition.model
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.block_height = $11
            AND transition.complete = true
          LIMIT 1
        ) AS activation_transition_model,
        (
          SELECT transition.work_token_state_model
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.block_height = $11
            AND transition.complete = true
          LIMIT 1
        ) AS activation_work_token_state_model,
        (
          SELECT transition.payload
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.block_height = $11
            AND transition.complete = true
          LIMIT 1
        ) AS activation_transition_payload,
        (
          SELECT count(*)::integer
          FROM proof_indexer.work_amo_block_transitions transition
          WHERE transition.network = $1
            AND transition.block_height >= $11
        ) AS transition_count,
        (
          SELECT count(*)::integer
          FROM proof_indexer.work_amo_block_transitions transition
          LEFT JOIN proof_indexer.blocks block
            ON block.network = transition.network
           AND block.height = transition.block_height
           AND block.block_hash = transition.block_hash
           AND block.canonical = true
          LEFT JOIN proof_indexer.blocks previous_block
            ON previous_block.network = transition.network
           AND previous_block.height = transition.block_height - 1
           AND previous_block.block_hash = transition.previous_block_hash
           AND previous_block.canonical = true
          LEFT JOIN proof_indexer.work_amo_block_transitions
            previous_transition
            ON previous_transition.network = transition.network
           AND previous_transition.block_height =
             transition.block_height - 1
           AND previous_transition.block_hash =
             transition.previous_block_hash
           AND previous_transition.complete = true
          WHERE transition.network = $1
            AND transition.block_height >= $11
            AND (
              transition.complete IS DISTINCT FROM true
              OR transition.model <> $13
              OR transition.work_token_state_model <> $14
              OR block.block_hash IS NULL
              OR block.previous_block_hash <>
                transition.previous_block_hash
              OR previous_block.block_hash IS NULL
              OR (
                transition.block_height = $11
                AND transition.previous_block_hash <> $5
              )
              OR (
                transition.block_height > $11
                AND (
                  previous_transition.block_hash IS NULL
                  OR transition.opening_state_sha256 <>
                    previous_transition.closing_state_sha256
                  OR transition.payload
                      ->'openingSufficientState'
                      ->'tokenStateCommitment'
                    IS DISTINCT FROM
                      previous_transition.payload
                        ->'closingSufficientState'
                        ->'tokenStateCommitment'
                )
              )
            )
        ) AS invalid_transition_count,
        current_snapshot.snapshot_height,
        current_snapshot.snapshot_hash,
        current_snapshot.snapshot_work_amount_storage_model,
        current_snapshot.snapshot_work_token_state,
        (
          SELECT count(*)::integer
          FROM proof_indexer.events event
          WHERE event.network = $1
            AND event.protocol = 'pwt1'
            AND event.status = 'confirmed'
            AND event.valid = true
            AND event.block_height >= $11
            AND lower(COALESCE(
              event.payload->>'tokenId',
              event.payload->'saleAuthorization'->>'tokenId',
              event.payload->'listingAuthorization'->>'tokenId',
              ''
            )) = $2
            AND (
              event.raw_payload LIKE 'pwt1:send:%'
              OR
              event.raw_payload LIKE 'pwt1:send2:%'
              OR (
                event.kind = 'token-listing'
                AND lower(COALESCE(
                  event.payload->'saleAuthorization'->>'version',
                  event.payload->'listingAuthorization'->>'version',
                  ''
                )) <> $12
              )
            )
        ) AS invalid_post_activation_legacy_count,
        (
          SELECT count(*)::integer
          FROM proof_indexer.events event
          WHERE event.network = $1
            AND event.protocol = 'pwt1'
            AND event.status = 'confirmed'
            AND event.valid = true
            AND event.block_height < $11
            AND lower(COALESCE(
              event.payload->>'tokenId',
              event.payload->'saleAuthorization'->>'tokenId',
              event.payload->'listingAuthorization'->>'tokenId',
              ''
            )) = $2
            AND (
              event.raw_payload LIKE 'pwt1:send3:%'
              OR (
                event.kind = 'token-listing'
                AND lower(COALESCE(
                  event.payload->'saleAuthorization'->>'version',
                  event.payload->'listingAuthorization'->>'version',
                  ''
                )) = $12
              )
            )
        ) AS invalid_pre_activation_v7_count,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.credit_definitions'::regclass
            AND constraint_row.conname =
              'credit_definitions_work_precision'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS definition_constraint,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.work_amo_v6_listing_terms'::regclass
            AND constraint_row.conname =
              'work_amo_v6_terms_values'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS v6_constraint,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.work_amo_v6_listing_terms'::regclass
            AND constraint_row.conname =
              'work_amo_v6_terms_deactivation'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS v6_deactivation_constraint,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.work_amo_v8_listing_terms'::regclass
            AND constraint_row.conname =
              'work_amo_v8_terms_values'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS v7_constraint,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.work_amo_v8_listing_terms'::regclass
            AND constraint_row.conname =
              'work_amo_v8_terms_identity'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS v8_identity_constraint,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.work_amo_v8_listing_terms'::regclass
            AND constraint_row.conname =
              'work_amo_v8_terms_positions'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS v8_positions_constraint,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.work_amo_v8_listing_terms'::regclass
            AND constraint_row.conname =
              'work_amo_v8_terms_frozen_payload'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS v8_frozen_constraint,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.work_amo_v8_listing_terms'::regclass
            AND constraint_row.conname =
              'work_amo_v8_terms_activation'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS activation_constraint,
        (
          SELECT pg_get_constraintdef(constraint_row.oid)
          FROM pg_constraint constraint_row
          WHERE constraint_row.conrelid =
              'proof_indexer.work_amo_block_transitions'::regclass
            AND constraint_row.conname =
              'work_amo_block_transitions_models'
            AND constraint_row.convalidated = true
          LIMIT 1
        ) AS transition_constraint,
        EXISTS (
          SELECT 1
          FROM pg_trigger trigger_row
          WHERE trigger_row.tgrelid =
              'proof_indexer.work_amo_v6_listing_terms'::regclass
            AND trigger_row.tgname =
              'work_amo_v6_listing_terms_immutable'
            AND trigger_row.tgenabled <> 'D'
            AND trigger_row.tgisinternal = false
        ) AS v6_immutable_trigger,
        EXISTS (
          SELECT 1
          FROM pg_trigger trigger_row
          WHERE trigger_row.tgrelid =
              'proof_indexer.work_amo_v7_listing_terms'::regclass
            AND trigger_row.tgname =
              'work_amo_v7_listing_terms_immutable'
            AND trigger_row.tgenabled <> 'D'
            AND trigger_row.tgisinternal = false
        ) AS v7_history_immutable_trigger,
        EXISTS (
          SELECT 1
          FROM pg_trigger trigger_row
          WHERE trigger_row.tgrelid =
              'proof_indexer.work_amo_v8_listing_terms'::regclass
            AND trigger_row.tgname =
              'work_amo_v8_listing_terms_immutable'
            AND trigger_row.tgenabled <> 'D'
            AND trigger_row.tgisinternal = false
        ) AS v7_immutable_trigger,
        EXISTS (
          SELECT 1
          FROM pg_trigger trigger_row
          WHERE trigger_row.tgrelid =
              'proof_indexer.meta'::regclass
            AND trigger_row.tgname =
              'work_precision_v2_marker_immutable'
            AND trigger_row.tgenabled <> 'D'
            AND trigger_row.tgisinternal = false
        ) AS marker_immutable_trigger
      FROM proof_indexer.meta migration
      JOIN proof_indexer.credit_definitions definition
        ON definition.network = $1 AND definition.token_id = $2
      JOIN proof_indexer.transactions tx
        ON tx.network = $1
       AND tx.txid = $3
       AND tx.status = 'confirmed'
       AND tx.block_height = $4
       AND lower(tx.block_hash) = $5
       AND tx.block_index = $6
      JOIN proof_indexer.blocks declaration_block
        ON declaration_block.network = tx.network
       AND declaration_block.block_hash = tx.block_hash
       AND declaration_block.height = tx.block_height
       AND declaration_block.canonical = true
      JOIN proof_indexer.op_returns carrier
        ON carrier.network = tx.network
       AND carrier.txid = tx.txid
       AND carrier.vout = $7
       AND carrier.output_index = $8
      JOIN proof_indexer.tx_outputs registry
        ON registry.network = tx.network
       AND registry.txid = tx.txid
       AND registry.vout = $9
      LEFT JOIN LATERAL (
        SELECT
          snapshot.indexed_through_block AS snapshot_height,
          lower(snapshot.source_hashes->>'blockScan') AS snapshot_hash,
          snapshot.payload->>'workAmountStorageModel'
            AS snapshot_work_amount_storage_model,
          snapshot.payload->'tokenStatePayloads'->$2
            AS snapshot_work_token_state
        FROM proof_indexer.ledger_snapshots snapshot
        WHERE snapshot.network = $1
          AND snapshot.generated_at >=
            (migration.value->>'completedAt')::timestamptz
          AND snapshot.payload ? 'tokenStatePayloads'
          AND snapshot.payload->'tokenStatePayloads' ? $2
          AND snapshot.payload->>'workAmountStorageModel' = $15
          AND COALESCE(
            snapshot.consistency->>'ok',
            snapshot.payload->>'ok',
            'false'
          ) = 'true'
          AND COALESCE(
            snapshot.consistency->>'status',
            snapshot.payload->>'status',
            ''
          ) = 'green'
          AND snapshot.payload->'summaryRefresh'->>'mode' =
            'canonical-summary-refresh'
          AND lower(COALESCE(
            snapshot.source_hashes->>'blockScan',
            ''
          )) ~ '^[0-9a-f]{64}$'
          AND lower(COALESCE(
            snapshot.payload->>'indexedThroughBlockHash',
            ''
          )) = lower(snapshot.source_hashes->>'blockScan')
          AND lower(COALESCE(
            snapshot.payload->'summaryRefresh'
              ->>'indexedThroughBlockHash',
            ''
          )) = lower(snapshot.source_hashes->>'blockScan')
        ORDER BY snapshot.indexed_through_block DESC NULLS LAST,
          snapshot.generated_at DESC
        LIMIT 1
      ) current_snapshot ON true
      WHERE migration.key = $10
      LIMIT 2
    `,
    [
      network,
      WORK_TOKEN_ID,
      pins.declarationTxid,
      pins.declarationHeight,
      pins.declarationBlockHash,
      pins.declarationBlockIndex,
      pins.declarationProtocolVout,
      pins.declarationRecordOrdinal,
      pins.declarationRegistryPaymentVout,
      WORK_PRECISION_V2_MIGRATION_META_KEY,
      pins.activationHeight,
      WORK_AMO_V8_AUTH_VERSION,
      WORK_AMO_V8_BLOCK_SEQUENCER_MODEL,
      WORK_AMO_V8_TOKEN_STATE_PREIMAGE_MODEL,
      WORK_SUBATOM_PROJECTION_MODEL,
    ],
  );
  if (stateResult.rows.length !== 1) {
    await client.query("ROLLBACK");
    transactionOpen = false;
    return null;
  }
  const [balanceResult, listingResult] = await Promise.all([
    client.query(
      `
        SELECT
          address,
          confirmed_balance::text,
          pending_delta::text
        FROM proof_indexer.credit_balances
        WHERE network = $1 AND token_id = $2
        ORDER BY address ASC
      `,
      [network, WORK_TOKEN_ID],
    ),
    client.query(
      `
        SELECT
          listing.listing_id,
          listing.seller_address,
          listing.amount::text,
          listing.price_sats::text,
          COALESCE(
            listing.payload->'saleAuthorization',
            listing.payload->'listingAuthorization'
          ) AS sale_authorization,
          CASE
            WHEN COALESCE(
              listing.payload->'saleAuthorization'->>'version',
              listing.payload->'listingAuthorization'->>'version',
              ''
            ) = $3
              THEN v7_terms.frozen_terms
            WHEN COALESCE(
              listing.payload->'saleAuthorization'->>'version',
              listing.payload->'listingAuthorization'->>'version',
              ''
            ) = $4
              THEN v6_terms.frozen_terms
            ELSE COALESCE(
              v5_terms.frozen_terms,
              listing.payload->'frozenTerms',
              listing.payload->'listingFrozenTerms',
              listing.payload->'workAmoFrozenTerms',
              listing.payload->'workAmoV6FrozenTerms',
              listing.payload->'workAmoV8FrozenTerms'
            )
          END AS frozen_terms
        FROM proof_indexer.credit_listings listing
        LEFT JOIN proof_indexer.work_amo_listing_terms v5_terms
          ON v5_terms.network = listing.network
         AND v5_terms.listing_id = listing.listing_id
         AND v5_terms.authorization_version = $5
         AND v5_terms.unit_amount_atoms * 100000000 = listing.amount
         AND v5_terms.unit_price_sats = listing.price_sats
        LEFT JOIN proof_indexer.work_amo_v6_listing_terms v6_terms
          ON v6_terms.network = listing.network
         AND v6_terms.listing_id = listing.listing_id
         AND v6_terms.authorization_version = $4
         AND v6_terms.unit_amount_atoms * 100000000 = listing.amount
         AND v6_terms.unit_price_sats = listing.price_sats
        LEFT JOIN proof_indexer.work_amo_v8_listing_terms v7_terms
          ON v7_terms.network = listing.network
         AND v7_terms.listing_id = listing.listing_id
         AND v7_terms.authorization_version = $3
         AND v7_terms.unit_amount_subatoms = listing.amount
         AND v7_terms.unit_price_sats = listing.price_sats
        WHERE listing.network = $1
          AND listing.token_id = $2
          AND listing.status IN ('active', 'sealing')
        ORDER BY listing.listing_id ASC
      `,
      [
        network,
        WORK_TOKEN_ID,
        WORK_AMO_V8_AUTH_VERSION,
        WORK_AMO_V6_AUTH_VERSION,
        WORK_AMO_V5_AUTH_VERSION,
      ],
    ),
  ]);
  const row = stateResult.rows[0];
  const marker = row.migration_marker;
  const metadata = objectRecord(row.definition_metadata);
  const constraintText = (value) =>
    String(value ?? "").replace(/\s+/gu, " ").trim();
  const exactHeightConstraint = (value, operator, height) => {
    const escapedOperator = operator.replace(
      /[.*+?^${}()|[\]\\]/gu,
      "\\$&",
    );
    return new RegExp(
      `^CHECK \\(\\(*listing_block_height ${escapedOperator} ${height}\\)*\\)$`,
      "u",
    ).test(constraintText(value));
  };
  const sharedConstraintAudit =
    sharedWorkPrecisionV2ConstraintAudit({
      definitionPrecision: row.definition_constraint,
      transitionModels: row.transition_constraint,
      v6Deactivation: row.v6_deactivation_constraint,
      v6Values: row.v6_constraint,
      v8Frozen: row.v8_frozen_constraint,
      v8Identity: row.v8_identity_constraint,
      v8Positions: row.v8_positions_constraint,
      v8Values: row.v7_constraint,
    });
  const constraints = {
    definition: sharedConstraintAudit.definitionPrecisionReady,
    transition: sharedConstraintAudit.transitionReady,
    markerImmutable: row.marker_immutable_trigger === true,
    v6: sharedConstraintAudit.v6Q8Ready,
    v6Deactivation:
      sharedConstraintAudit.v6DeactivationInstalled &&
      exactHeightConstraint(
        row.v6_deactivation_constraint,
        "<",
        pins.activationHeight,
      ),
    v8:
      sharedConstraintAudit.v8ValuesReady &&
      sharedConstraintAudit.v8IdentityReady &&
      sharedConstraintAudit.v8PositionsReady &&
      sharedConstraintAudit.v8FrozenReady,
    activation: exactHeightConstraint(
      row.activation_constraint,
      ">=",
      pins.activationHeight,
    ),
    v6Immutable: row.v6_immutable_trigger === true,
    v7HistoryImmutable:
      row.v7_history_immutable_trigger === true,
    v7Immutable: row.v7_immutable_trigger === true,
  };
  const activationTransitionPayload = objectRecord(
    row.activation_transition_payload,
  );
  const activationTransitionOpeningCommitment = objectRecord(
    activationTransitionPayload.precisionOpeningTokenStateCommitment,
  );
  const markerOpeningCommitment = objectRecord(
    marker?.activationOpening?.subatomTokenStateCommitment,
  );
  const activationOpeningReady =
    row.activation_transition_model ===
      WORK_AMO_V8_BLOCK_SEQUENCER_MODEL &&
    row.activation_work_token_state_model ===
      WORK_AMO_V8_TOKEN_STATE_PREIMAGE_MODEL &&
    activationTransitionPayload.precisionMigrationMarkerKey ===
      WORK_PRECISION_V2_MIGRATION_META_KEY &&
    Number(activationTransitionPayload.activationHeight) ===
      pins.activationHeight &&
    stableWorkPrecisionJson(
      activationTransitionOpeningCommitment,
    ) === stableWorkPrecisionJson(markerOpeningCommitment);
  const transitionPayload = objectRecord(row.transition_payload);
  const closingTokenState = objectRecord(
    transitionPayload.closingTokenState,
  );
  const closingSufficientState = objectRecord(
    transitionPayload.closingSufficientState,
  );
  const closingSufficientStateCommitment = objectRecord(
    closingSufficientState.tokenStateCommitment,
  );
  let closingTokenStateCommitment = null;
  let relationalParityReady = false;
  try {
    closingTokenStateCommitment =
      workAmoV8CanonicalTokenStateCommitment(
        closingTokenState,
      );
    const currentBalances = balanceResult.rows.filter(
      (balance) => BigInt(balance.confirmed_balance) !== 0n,
    );
    const relationalTokenState = {
      confirmedSupplySubatoms: currentBalances
        .reduce(
          (total, balance) =>
            total + BigInt(balance.confirmed_balance),
          0n,
        )
        .toString(),
      holders: currentBalances.map((balance) => ({
        address: balance.address,
        balanceSubatoms: balance.confirmed_balance,
      })),
      listings: listingResult.rows.map((listing) => ({
        amountSubatoms: listing.amount,
        frozenTerms: listing.frozen_terms,
        listingId: listing.listing_id,
        priceSats: listing.price_sats,
        saleAuthorization: listing.sale_authorization,
        sellerAddress: listing.seller_address,
      })),
    };
    const relationalCommitment =
      workAmoV8CanonicalTokenStateCommitment(
        relationalTokenState,
      );
    relationalParityReady =
      stableWorkPrecisionJson(relationalCommitment) ===
        stableWorkPrecisionJson(closingTokenStateCommitment);
  } catch {
    closingTokenStateCommitment = null;
    relationalParityReady = false;
  }
  const closingTokenStateReady =
    Boolean(closingTokenStateCommitment) &&
    stableWorkPrecisionJson(closingTokenStateCommitment) ===
      stableWorkPrecisionJson(
        closingSufficientStateCommitment,
      );
  const snapshotWorkTokenState = objectRecord(
    row.snapshot_work_token_state,
  );
  let snapshotTokenStateReady = false;
  try {
    const snapshotTokenStateCommitment =
      workAmoV8CanonicalTokenStateCommitment(
        snapshotWorkTokenState,
      );
    snapshotTokenStateReady =
      snapshotWorkTokenState.amountStorageModel ===
        WORK_SUBATOM_PROJECTION_MODEL &&
      Number(snapshotWorkTokenState.decimals) ===
        WORK_SUBATOM_DECIMALS &&
      String(snapshotWorkTokenState.unitScale ?? "") ===
        WORK_SUBATOM_UNIT_SCALE_TEXT &&
      snapshotWorkTokenState.precisionModel ===
        WORK_PRECISION_V2_MODEL &&
      stableWorkPrecisionJson(snapshotTokenStateCommitment) ===
        stableWorkPrecisionJson(closingTokenStateCommitment);
  } catch {
    snapshotTokenStateReady = false;
  }
  const tipHeight = Number(row.tip_height);
  const tipHash = normalizedLowerText(row.tip_hash);
  const snapshotHash = normalizedLowerText(row.snapshot_hash);
  const pendingWitnessResult = await client.query(
    `
      SELECT value
      FROM proof_indexer.meta
      WHERE key = $1
      LIMIT 2
    `,
    [WORK_Q16_PENDING_REBUILD_META_KEY],
  );
  const pendingWitness = objectRecord(
    pendingWitnessResult.rows[0]?.value,
  );
  const pendingMempool = objectRecord(
    pendingWitness.mempoolSnapshot,
  );
  const pendingMembershipSnapshot = objectRecord(
    pendingWitness.membershipSnapshot,
  );
  const pendingProjection = objectRecord(
    pendingWitness.projection,
  );
  const pendingMembershipTxids =
    Array.isArray(pendingMembershipSnapshot.txids)
      ? pendingMembershipSnapshot.txids.map(normalizedLowerText)
      : [];
  const pendingMembershipTxidsCanonical =
    pendingMembershipTxids.length ===
      new Set(pendingMembershipTxids).size &&
    pendingMembershipTxids.every((txid) =>
      /^[0-9a-f]{64}$/u.test(txid)
    ) &&
    pendingMembershipTxids.every(
      (txid, index) =>
        index === 0 ||
        compareCanonicalUtf8(
          pendingMembershipTxids[index - 1],
          txid,
        ) < 0,
    );
  let pendingReady = false;
  if (
    pendingWitnessResult.rows.length === 1 &&
    pendingMembershipTxidsCanonical
  ) {
    const [
      pendingBalanceResult,
      pendingEventResult,
      pendingListingResult,
      pendingRecoveryResult,
      pendingInvalidLegacyResult,
    ] = await Promise.all([
      client.query(
        `
          SELECT address, pending_delta::text
          FROM proof_indexer.credit_balances
          WHERE network = $1
            AND token_id = $2
            AND pending_delta <> 0
          ORDER BY address ASC
        `,
        [network, WORK_TOKEN_ID],
      ),
      client.query(
        `
          SELECT
            event_id,
            txid,
            kind,
            protocol,
            protocol_vout,
            record_ordinal,
            valid,
            raw_payload,
            payload
          FROM proof_indexer.events
          WHERE network = $1
            AND status = 'pending'
            AND protocol = 'pwt1'
            AND lower(COALESCE(
              payload->>'tokenId',
              payload->'saleAuthorization'->>'tokenId',
              payload->'listingAuthorization'->>'tokenId',
              payload->'actionAuthorization'->>'tokenId',
              ''
            )) = $2
          ORDER BY txid ASC, protocol_vout ASC, record_ordinal ASC,
            event_id ASC
        `,
        [network, WORK_TOKEN_ID],
      ),
      client.query(
        `
          SELECT
            listing_id,
            status,
            seller_address,
            buyer_address,
            amount::text,
            price_sats::text,
            sale_ticket_txid,
            seal_txid,
            CASE
              WHEN listing.status = 'pending'
                THEN lower(listing.listing_id)
              WHEN listing.status = 'sealing'
                AND COALESCE(seal_tx.status, '') <> 'confirmed'
                AND COALESCE(listing.seal_txid, '') <> ''
                THEN lower(listing.seal_txid)
              ELSE NULL
            END AS membership_txid,
            seal_tx.status AS seal_transaction_status,
            payload
          FROM proof_indexer.credit_listings listing
          LEFT JOIN proof_indexer.transactions seal_tx
            ON seal_tx.network = listing.network
           AND seal_tx.txid = lower(listing.seal_txid)
          WHERE listing.network = $1
            AND listing.token_id = $2
            AND (
              listing.status = 'pending'
              OR (
                listing.status = 'sealing'
                AND COALESCE(seal_tx.status, '') <> 'confirmed'
              )
            )
          ORDER BY listing.listing_id ASC
        `,
        [network, WORK_TOKEN_ID],
      ),
      client.query(
        `
          SELECT txid, status, raw_tx
          FROM proof_indexer.transactions
          WHERE network = $1
            AND status = 'pending'
            AND (
              raw_tx ? 'pendingWorkMintAttemptCount'
              OR raw_tx ? 'pendingWorkMintInspectionVersion'
              OR raw_tx ? 'pendingWorkMintRecoveryNeeded'
              OR raw_tx ? 'pendingWorkMintResolvedInvalid'
              OR raw_tx ? 'pendingProtocolResolvedInvalid'
            )
            AND (
              jsonb_typeof(
                raw_tx->'pendingWorkMintAttemptCount'
              ) = 'number'
              AND jsonb_typeof(
                raw_tx->'pendingWorkMintInspectionVersion'
              ) = 'number'
              AND jsonb_typeof(
                raw_tx->'pendingWorkMintRecoveryNeeded'
              ) = 'boolean'
              AND jsonb_typeof(
                raw_tx->'pendingWorkMintResolvedInvalid'
              ) = 'boolean'
              AND jsonb_typeof(
                raw_tx->'pendingProtocolResolvedInvalid'
              ) = 'boolean'
              AND raw_tx->>'pendingWorkMintAttemptCount' = '0'
              AND raw_tx->>'pendingWorkMintInspectionVersion' = '1'
              AND raw_tx->>'pendingWorkMintRecoveryNeeded' = 'false'
              AND raw_tx->>'pendingWorkMintResolvedInvalid' = 'false'
              AND raw_tx->>'pendingProtocolResolvedInvalid'
                IN ('false', 'true')
            ) IS NOT TRUE
          ORDER BY txid ASC
        `,
        [network],
      ),
      client.query(
        `
          SELECT count(*)::integer AS invalid_count
          FROM proof_indexer.events event
          WHERE event.network = $1
            AND event.status = 'pending'
            AND event.protocol = 'pwt1'
            AND event.valid = true
            AND lower(COALESCE(
              event.payload->>'tokenId',
              event.payload->'saleAuthorization'->>'tokenId',
              event.payload->'listingAuthorization'->>'tokenId',
              event.payload->'actionAuthorization'->>'tokenId',
              ''
            )) = $2
            AND (
              event.raw_payload LIKE 'pwt1:send:%'
              OR event.raw_payload LIKE 'pwt1:send2:%'
              OR (
                event.kind = 'token-listing'
                AND lower(COALESCE(
                  event.payload->'saleAuthorization'->>'version',
                  event.payload->'listingAuthorization'->>'version',
                  ''
                )) <> $3
              )
            )
        `,
        [network, WORK_TOKEN_ID, WORK_AMO_V8_AUTH_VERSION],
      ),
    ]);
    const pendingMembership = workQ16PendingMembership({
      eventRows: pendingEventResult.rows,
      listingRows: pendingListingResult.rows,
      recoveryRows: pendingRecoveryResult.rows,
    });
    const pendingTransactionResult = await client.query(
      `
        SELECT txid, status, raw_tx
        FROM proof_indexer.transactions
        WHERE network = $1
          AND status = 'pending'
          AND txid = ANY($2::text[])
        ORDER BY txid ASC
      `,
      [network, pendingMembership.expectedTxids],
    );
    const pendingProjectionParts = {
      balances: {
        count: pendingBalanceResult.rows.length,
        sha256: workQ16PendingCommitment(
          "BALANCES",
          pendingBalanceResult.rows,
        ),
      },
      events: {
        count: pendingEventResult.rows.length,
        sha256: workQ16PendingCommitment(
          "EVENTS",
          pendingEventResult.rows,
        ),
      },
      listings: {
        count: pendingListingResult.rows.length,
        sha256: workQ16PendingCommitment(
          "LISTINGS",
          pendingListingResult.rows,
        ),
      },
      transactions: {
        count: pendingTransactionResult.rows.length,
        sha256: workQ16PendingCommitment(
          "TRANSACTIONS",
          pendingTransactionResult.rows,
        ),
      },
    };
    const pendingGeneratedAtMs = Date.parse(
      String(pendingWitness.generatedAt ?? ""),
    );
    const pendingParity = workQ16PendingParity({
      balances: pendingBalanceResult.rows,
      events: pendingEventResult.rows,
      listings: pendingListingResult.rows,
      mempoolTxids: pendingMembershipTxids,
      recoveryRows: pendingRecoveryResult.rows,
      transactions: pendingTransactionResult.rows,
    });
    pendingReady =
      pendingWitness.model ===
        WORK_Q16_PENDING_REBUILD_MODEL &&
      pendingWitness.network === network &&
      pendingWitness.ready === true &&
      Number(pendingWitness.activationHeight) ===
        pins.activationHeight &&
      normalizedLowerText(pendingWitness.declarationTxid) ===
        pins.declarationTxid &&
      pendingWitness.amountStorageModel ===
        WORK_SUBATOM_PROJECTION_MODEL &&
      pendingWitness.precisionModel ===
        WORK_AMO_V8_GLOBAL_PRECISION_MODEL &&
      Number(pendingWitness.invalidLegacyMutationCount) === 0 &&
      Number(pendingInvalidLegacyResult.rows[0]?.invalid_count) === 0 &&
      Number(pendingWitness.canonicalTip?.height) === tipHeight &&
      normalizedLowerText(pendingWitness.canonicalTip?.hash) ===
        tipHash &&
      pendingMempool.model === WORK_Q16_PENDING_MEMPOOL_MODEL &&
      Number.isSafeInteger(pendingMempool.count) &&
      pendingMempool.count >= 0 &&
      /^[0-9a-f]{64}$/u.test(
        normalizedLowerText(pendingMempool.sha256),
      ) &&
      pendingMembershipSnapshot.model === pendingMembership.model &&
      Number.isSafeInteger(pendingMembershipSnapshot.count) &&
      pendingMembershipSnapshot.count ===
        pendingMembershipTxids.length &&
      normalizedLowerText(pendingMembershipSnapshot.sha256) ===
        pendingMembership.expectedTxidsSha256 &&
      stableWorkPrecisionJson(pendingMembershipSnapshot.txids) ===
        stableWorkPrecisionJson(pendingMembership.expectedTxids) &&
      pendingProjection.model ===
        WORK_Q16_PENDING_PROJECTION_MODEL &&
      pendingParity.ready === true &&
      stableWorkPrecisionJson(
        objectRecord(pendingWitness.parity),
      ) === stableWorkPrecisionJson(pendingParity) &&
      stableWorkPrecisionJson({
        balances: pendingProjection.balances,
        events: pendingProjection.events,
        listings: pendingProjection.listings,
        transactions: pendingProjection.transactions,
      }) === stableWorkPrecisionJson(pendingProjectionParts) &&
      normalizedLowerText(
        pendingProjection.commitmentSha256,
      ) ===
        workQ16PendingCommitment(
          "PROJECTION",
          pendingProjectionParts,
        ) &&
      pendingWitness.scan?.complete === true &&
      pendingWitness.scan?.completeModel ===
        "persisted-pending-work-projection-audit-v1" &&
      pendingWitness.scan?.discoveryModel ===
        "bounded-best-effort-unconfirmed-discovery-v1" &&
      Number.isSafeInteger(
        pendingWitness.scan?.mempoolMembershipCount,
      ) &&
      pendingWitness.scan.mempoolMembershipCount ===
        pendingMempool.count &&
      Number.isSafeInteger(pendingWitness.scan?.inspectedTxids) &&
      pendingWitness.scan.inspectedTxids >= 0 &&
      pendingWitness.scan.inspectedTxids <= pendingMempool.count &&
      Number.isFinite(
        pendingGeneratedAtMs,
      ) &&
      Date.now() >= pendingGeneratedAtMs &&
      Date.now() - pendingGeneratedAtMs <=
        WORK_Q16_PENDING_WITNESS_MAX_AGE_MS;
  }
  const expectedTransitionCount =
    Number.isSafeInteger(tipHeight) &&
    tipHeight >= pins.activationHeight
      ? tipHeight - pins.activationHeight + 1
      : -1;
  const confirmedReplayReady =
    Number.isSafeInteger(tipHeight) &&
    tipHeight >= pins.activationHeight &&
    Number(row.transition_height) === tipHeight &&
    /^[0-9a-f]{64}$/u.test(tipHash) &&
    normalizedLowerText(row.transition_hash) === tipHash &&
    row.transition_model === WORK_AMO_V8_BLOCK_SEQUENCER_MODEL &&
    row.work_token_state_model ===
      WORK_AMO_V8_TOKEN_STATE_PREIMAGE_MODEL &&
    Number(row.transition_count) === expectedTransitionCount &&
    Number(row.invalid_transition_count) === 0 &&
    activationOpeningReady &&
    closingTokenStateReady;
  const snapshotReplayReady =
    Number(row.snapshot_height) === tipHeight &&
    snapshotHash === tipHash &&
    row.snapshot_work_amount_storage_model ===
      WORK_SUBATOM_PROJECTION_MODEL &&
    snapshotTokenStateReady;
  const replayReady = confirmedReplayReady && snapshotReplayReady;
  const stateCommitmentsReady =
    closingTokenStateReady && relationalParityReady;
  const markerReady = workPrecisionV2MarkerBindsReader(marker, pins);
  const declarationIndexReady =
    indexedWorkPrecisionEvidenceMatchesMarker(row, marker);
  const definitionReady =
    String(row.max_supply ?? "") ===
      "210000000000000000000000" &&
    String(row.mint_amount ?? "") ===
      WORK_AMO_V8_MINT_AMOUNT_SUBATOMS.toString() &&
    metadata.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL &&
    Number(metadata.decimals) === WORK_SUBATOM_DECIMALS &&
    String(metadata.unitScale ?? "") ===
      WORK_SUBATOM_UNIT_SCALE_TEXT &&
    metadata.precisionModel === WORK_PRECISION_V2_MODEL;
  const constraintsReady = Object.values(constraints).every(Boolean);
  const legacyProjectionReady =
    Number(row.invalid_post_activation_legacy_count) === 0 &&
    Number(row.invalid_pre_activation_v7_count) === 0;
  const confirmedStateReadyWithinSnapshot =
    markerReady &&
    declarationIndexReady &&
    definitionReady &&
    constraintsReady &&
    stateCommitmentsReady &&
    confirmedReplayReady &&
    legacyProjectionReady;
  const readyWithinSnapshot =
    confirmedStateReadyWithinSnapshot &&
    snapshotReplayReady &&
    pendingReady;
  await client.query("COMMIT");
  transactionOpen = false;
  const freshTipResult = await client.query(
    `
      WITH maximum_tip AS (
        SELECT max(height)::integer AS height
        FROM proof_indexer.blocks
        WHERE network = $1 AND canonical = true
      )
      SELECT block.height, lower(block.block_hash) AS block_hash
      FROM proof_indexer.blocks block
      JOIN maximum_tip ON maximum_tip.height = block.height
      WHERE block.network = $1 AND block.canonical = true
      ORDER BY block.block_hash
      LIMIT 2
    `,
    [network],
  );
  const exactTipReady =
    freshTipResult.rows.length === 1 &&
    Number(freshTipResult.rows[0]?.height) === tipHeight &&
    normalizedLowerText(
      freshTipResult.rows[0]?.block_hash,
    ) === tipHash;
  const canonicalSummaryBootstrapReady =
    confirmedStateReadyWithinSnapshot && exactTipReady;
  const ready = readyWithinSnapshot && exactTipReady;
  return {
    activationHeight: pins.activationHeight,
    active: ready,
    canonicalSummaryBootstrapReady,
    canonical: true,
    confirmed: true,
    confirmedReplayReady,
    constraints,
    constraintsReady,
    declarationIndexReady,
    definitionReady,
    declarationEvidence: marker?.declarationEvidence ?? null,
    evidenceComplete:
      marker?.declarationEvidence?.evidenceComplete === true,
    exactTipReady,
    legacyProjectionReady,
    marker,
    markerReady,
    model: WORK_PRECISION_V2_MIGRATION_MODEL,
    openingReady: activationOpeningReady,
    parityReady: stateCommitmentsReady,
    pendingReady,
    pendingWitness,
    precision: {
      amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
      decimals: WORK_SUBATOM_DECIMALS,
      unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
    },
    ready,
    replayReady,
    snapshotReplayReady,
    snapshotTokenStateReady,
    snapshotHash,
    status: ready ? "complete" : "not-ready",
    tipHash,
    tipHeight,
  };
  } catch (error) {
    if (transactionOpen) {
      await client.query("ROLLBACK").catch(() => {});
      transactionOpen = false;
    }
    throw error;
  } finally {
    client.release();
  }
}

export async function proofIndexWorkAmoV8ActivationLatch(
  network,
  expectedPins,
) {
  const pool = proofIndexPool();
  const pins = normalizedWorkAmoV6ExpectedPins(expectedPins);
  if (!pool || network !== "livenet") {
    return null;
  }
  const result = await pool.query(
    `
      SELECT
        latch.value,
        migration.value AS migration_marker,
        definition.max_supply::text,
        definition.mint_amount::text,
        definition.metadata AS definition_metadata
      FROM proof_indexer.meta latch
      LEFT JOIN proof_indexer.meta migration
        ON migration.key = $2
      LEFT JOIN proof_indexer.credit_definitions definition
        ON definition.network = $1
       AND definition.token_id = $3
      WHERE latch.key = 'workAmoV8ActivationLatch:livenet'
      LIMIT 2
    `,
    [
      network,
      WORK_PRECISION_V2_MIGRATION_META_KEY,
      WORK_TOKEN_ID,
    ],
  );
  if (result.rows.length !== 1) {
    return null;
  }
  const value = objectRecord(result.rows[0]?.value);
  const marker = objectRecord(result.rows[0]?.migration_marker);
  const definitionModel = workDefinitionStorageModel({
    max_supply: result.rows[0]?.max_supply,
    metadata: result.rows[0]?.definition_metadata,
    mint_amount: result.rows[0]?.mint_amount,
  });
  const firstObservedTipHeight = safeBlockHeight(
    value.firstObservedTipHeight,
  );
  const firstObservedTipHash = normalizedLowerText(
    value.firstObservedTipHash,
  );
  const selfContainedPins = normalizedWorkAmoV6ExpectedPins({
    activationHeight: value.activationHeight,
    declarationBlockHash: value.declarationBlockHash,
    declarationBlockIndex: value.declarationBlockIndex,
    declarationHeight: value.declarationHeight,
    declarationMemoBytes: value.declarationMemoBytes,
    declarationMemoSha256: value.declarationMemoSha256,
    declarationProtocolVout: value.declarationProtocolVout,
    declarationRecordOrdinal: value.declarationRecordOrdinal,
    declarationRegistryPaymentVout:
      value.declarationRegistryPaymentVout,
    declarationTxid: value.declarationTxid,
  });
  const markerReady =
    Boolean(selfContainedPins) &&
    sharedWorkPrecisionV2MarkerReady(
      marker,
      selfContainedPins,
      { network },
    ) &&
    definitionModel === WORK_SUBATOM_PROJECTION_MODEL;
  const configuredPinsMatch =
    !pins ||
    stableWorkPrecisionJson(pins) ===
      stableWorkPrecisionJson(selfContainedPins);
  const reached =
    Boolean(selfContainedPins) &&
    sharedWorkAmoV8ActivationLatchReady(
      value,
      selfContainedPins,
      { network },
    ) &&
    configuredPinsMatch &&
    firstObservedTipHeight === selfContainedPins.activationHeight &&
    /^[0-9a-f]{64}$/u.test(firstObservedTipHash);
  return reached
    ? {
      ...value,
        markerReady,
        pins: selfContainedPins,
        firstObservedTipHash,
        firstObservedTipHeight,
        reached: true,
      }
    : null;
}

export async function proofIndexWorkAmoV6ListingTerms(
  network,
  listingId,
) {
  const pool = proofIndexPool();
  const normalizedListingId = String(listingId ?? "").trim().toLowerCase();
  if (!pool || !/^[0-9a-f]{64}$/u.test(normalizedListingId)) {
    return null;
  }
  const result = await pool.query(
    `
      SELECT
        terms.*,
        listing_event.payload AS listing_event_payload,
        v6_migration.value AS migration_marker
      FROM proof_indexer.work_amo_v6_listing_terms terms
      JOIN proof_indexer.transactions listing_tx
        ON listing_tx.network = terms.network
       AND listing_tx.txid = terms.listing_txid
       AND listing_tx.status = 'confirmed'
       AND listing_tx.block_hash = terms.listing_block_hash
       AND listing_tx.block_height = terms.listing_block_height
       AND listing_tx.block_index = terms.listing_block_index
      JOIN proof_indexer.blocks listing_block
        ON listing_block.network = listing_tx.network
       AND listing_block.block_hash = listing_tx.block_hash
       AND listing_block.height = listing_tx.block_height
       AND listing_block.canonical = true
      JOIN proof_indexer.events listing_event
        ON listing_event.network = terms.network
       AND listing_event.txid = terms.listing_txid
       AND listing_event.protocol = 'pwt1'
       AND listing_event.kind = 'token-listing'
       AND listing_event.status = 'confirmed'
       AND listing_event.valid = true
       AND listing_event.block_height = terms.listing_block_height
       AND listing_event.block_index = terms.listing_block_index
       AND listing_event.op_return_vout =
         terms.listing_protocol_vout
       AND listing_event.record_ordinal =
         terms.listing_record_ordinal
       AND listing_event.payload->>'tokenId' = terms.token_id
       AND listing_event.payload
         ->'saleAuthorization'
         ->>'version' = terms.authorization_version
      JOIN proof_indexer.meta v6_migration
        ON v6_migration.key = $3
       AND v6_migration.value->>'model' = $4
       AND v6_migration.value->>'status' = 'complete'
       AND v6_migration.value->>'network' = terms.network
       AND v6_migration.value->>'version' =
         terms.authorization_version
       AND (v6_migration.value->>'activationHeight')::integer <=
         terms.listing_block_height
      WHERE terms.network = $1
        AND terms.listing_id = $2
        AND terms.authorization_version = $5
      LIMIT 2
    `,
    [
      network,
      normalizedListingId,
      WORK_AMO_V6_INDEX_MIGRATION_META_KEY,
      WORK_AMO_V6_INDEX_MIGRATION_MODEL,
      WORK_AMO_V6_AUTH_VERSION,
    ],
  );
  return result.rows.length === 1
    ? normalizedWorkAmoV6ListingTermsRow(result.rows[0])
    : null;
}

function normalizedWorkAmoV8ListingTermsRow(row, pins) {
  const frozenTerms = objectRecord(row?.frozen_terms);
  const listingAuthorization = objectRecord(
    row?.listing_event_payload?.saleAuthorization ??
      row?.listing_event_payload?.listingAuthorization,
  );
  const listingId = normalizedLowerText(row?.listing_id);
  const listingTxid = normalizedLowerText(row?.listing_txid);
  const listingPosition = canonicalAmoPosition(row, "listing_");
  const listingBlockHash = normalizedLowerText(
    row?.listing_block_hash,
  );
  if (
    !pins ||
    !/^[0-9a-f]{64}$/u.test(listingId) ||
    listingTxid !== listingId ||
    !listingPosition ||
    !/^[0-9a-f]{64}$/u.test(listingBlockHash) ||
    listingPosition.blockHeight < pins.activationHeight ||
    row?.authorization_version !== WORK_AMO_V8_AUTH_VERSION ||
    normalizedLowerText(row?.token_id) !== WORK_TOKEN_ID ||
    !workPrecisionV2MarkerBindsReader(
      row?.migration_marker,
      pins,
    )
  ) {
    return null;
  }
  const validation = validateWorkAmoV8FrozenTerms(
    frozenTerms,
    {
      authorization: listingAuthorization,
      listingPosition: {
        blockHash: listingBlockHash,
        blockHeight: listingPosition.blockHeight,
        blockTransactionIndex: listingPosition.blockIndex,
        protocolVout: listingPosition.protocolVout,
        recordOrdinal: listingPosition.recordOrdinal,
      },
    },
  );
  if (!validation.valid) {
    return null;
  }
  const frozen = validation.frozenTerms;
  const exactPositiveInteger = (value) => {
    const text = String(value ?? "").trim();
    return /^[1-9][0-9]*$/u.test(text)
      ? BigInt(text).toString()
      : "";
  };
  if (
    Number(row?.unit_face_proofs) !== frozen.unitFaceProofs ||
    exactPositiveInteger(row?.unit_amount_subatoms) !==
      frozen.unitAmountSubatoms ||
    exactPositiveInteger(row?.unit_price_sats) !==
      frozen.unitPriceSats ||
    exactPositiveInteger(row?.unit_minimum_price_sats) !==
      frozen.unitMinimumPriceSats ||
    exactPositiveInteger(row?.listing_network_value_before_q8) !==
      frozen.listingNetworkValueBeforeQ8 ||
    exactPositiveInteger(row?.listing_bond_contribution_q8) !==
      frozen.listingBondContributionQ8 ||
    exactPositiveInteger(row?.listing_network_value_after_q8) !==
      frozen.listingNetworkValueAfterQ8
  ) {
    return null;
  }
  return {
    authorizationVersion: WORK_AMO_V8_AUTH_VERSION,
    createdAt: dateIso(row?.created_at),
    frozenTerms: frozen,
    listingId,
    listingPosition,
    listingTxid,
    tokenId: WORK_TOKEN_ID,
    unitAmountSubatoms: frozen.unitAmountSubatoms,
    unitFaceProofs: frozen.unitFaceProofs,
    unitMinimumPriceSats: frozen.unitMinimumPriceSats,
    unitPriceSats: frozen.unitPriceSats,
  };
}

export async function proofIndexWorkAmoV8ListingTerms(
  network,
  listingId,
) {
  const pool = proofIndexPool();
  const normalizedListingId = normalizedLowerText(listingId);
  if (
    !pool ||
    network !== "livenet" ||
    !/^[0-9a-f]{64}$/u.test(normalizedListingId)
  ) {
    return null;
  }
  const configuredPins =
    configuredWorkPrecisionV2ReaderPins();
  const latch = await proofIndexWorkAmoV8ActivationLatch(
    network,
    configuredPins,
  ).catch(() => null);
  const pins = configuredPins ?? latch?.pins ?? null;
  if (!pins) {
    return null;
  }
  const readiness =
    await proofIndexWorkPrecisionV2MigrationReadiness(
      network,
      pins,
    ).catch(() => null);
  if (
    readiness?.ready !== true ||
    readiness?.active !== true ||
    readiness?.parityReady !== true ||
    readiness?.replayReady !== true
  ) {
    return null;
  }
  const result = await pool.query(
    `
      SELECT
        terms.*,
        listing_event.payload AS listing_event_payload,
        migration.value AS migration_marker
      FROM proof_indexer.work_amo_v8_listing_terms terms
      JOIN proof_indexer.transactions listing_tx
        ON listing_tx.network = terms.network
       AND listing_tx.txid = terms.listing_txid
       AND listing_tx.status = 'confirmed'
       AND listing_tx.block_hash = terms.listing_block_hash
       AND listing_tx.block_height = terms.listing_block_height
       AND listing_tx.block_index = terms.listing_block_index
      JOIN proof_indexer.blocks listing_block
        ON listing_block.network = listing_tx.network
       AND listing_block.block_hash = listing_tx.block_hash
       AND listing_block.height = listing_tx.block_height
       AND listing_block.canonical = true
      JOIN proof_indexer.events listing_event
        ON listing_event.network = terms.network
       AND listing_event.txid = terms.listing_txid
       AND listing_event.protocol = 'pwt1'
       AND listing_event.kind = 'token-listing'
       AND listing_event.status = 'confirmed'
       AND listing_event.valid = true
       AND listing_event.block_height = terms.listing_block_height
       AND listing_event.block_index = terms.listing_block_index
       AND listing_event.op_return_vout =
         terms.listing_protocol_vout
       AND listing_event.record_ordinal =
         terms.listing_record_ordinal
       AND lower(COALESCE(
         listing_event.payload->>'tokenId',
         listing_event.payload->'saleAuthorization'->>'tokenId',
         listing_event.payload->'listingAuthorization'->>'tokenId',
         ''
       )) = terms.token_id
       AND lower(COALESCE(
         listing_event.payload->'saleAuthorization'->>'version',
         listing_event.payload->'listingAuthorization'->>'version',
         ''
       )) = terms.authorization_version
      JOIN proof_indexer.meta migration
        ON migration.key = $3
      WHERE terms.network = $1
        AND terms.listing_id = $2
        AND terms.authorization_version = $4
      LIMIT 2
    `,
    [
      network,
      normalizedListingId,
      WORK_PRECISION_V2_MIGRATION_META_KEY,
      WORK_AMO_V8_AUTH_VERSION,
    ],
  );
  return result.rows.length === 1
    ? normalizedWorkAmoV8ListingTermsRow(
        result.rows[0],
        pins,
      )
    : null;
}

export async function proofIndexCanonicalWorkListingById(
  network,
  listingId,
) {
  const pool = proofIndexPool();
  const normalizedListingId = String(listingId ?? "").trim().toLowerCase();
  if (!pool || !/^[0-9a-f]{64}$/u.test(normalizedListingId)) {
    return null;
  }
  const result = await pool.query(
    `
      SELECT
        listing.listing_id,
        listing.status AS listing_status,
        listing.seller_address,
        listing.amount::text AS amount_units,
        listing.price_sats::text AS price_sats,
        listing.sale_ticket_txid,
        listing.sale_ticket_vout,
        listing.sale_ticket_value_sats::text AS sale_ticket_value_sats,
        listing_anchor.address AS anchor_address,
        listing_anchor.scriptpubkey AS anchor_scriptpubkey,
        listing_anchor.value_sats::text AS anchor_value_sats,
        listing_event.payload AS listing_event_payload,
        listing_event.block_height,
        listing_event.block_index,
        listing_event.op_return_vout AS protocol_vout,
        listing_event.record_ordinal,
        listing_tx.block_hash,
        definition.metadata AS token_metadata
      FROM proof_indexer.credit_listings listing
      JOIN proof_indexer.credit_definitions definition
        ON definition.network = listing.network
       AND definition.token_id = listing.token_id
      JOIN proof_indexer.transactions listing_tx
        ON listing_tx.network = listing.network
       AND listing_tx.txid = listing.listing_id
       AND listing_tx.status = 'confirmed'
       AND listing_tx.block_index IS NOT NULL
      JOIN proof_indexer.blocks listing_block
        ON listing_block.network = listing_tx.network
       AND listing_block.block_hash = listing_tx.block_hash
       AND listing_block.height = listing_tx.block_height
       AND listing_block.canonical = true
      JOIN proof_indexer.events listing_event
        ON listing_event.network = listing.network
       AND listing_event.txid = listing.listing_id
       AND listing_event.protocol = 'pwt1'
       AND listing_event.kind = 'token-listing'
       AND listing_event.status = 'confirmed'
       AND listing_event.valid = true
       AND listing_event.block_height = listing_tx.block_height
       AND listing_event.block_index = listing_tx.block_index
       AND listing_event.op_return_vout IS NOT NULL
       AND listing_event.record_ordinal >= 0
       AND lower(COALESCE(
         listing_event.payload->'saleAuthorization'->>'version',
         listing_event.payload->'listingAuthorization'->>'version',
         ''
       )) = lower(COALESCE(
         listing.payload->'saleAuthorization'->>'version',
         listing.payload->'listingAuthorization'->>'version',
         ''
       ))
      JOIN proof_indexer.tx_outputs listing_anchor
        ON listing_anchor.network = listing.network
       AND listing_anchor.txid = COALESCE(
         NULLIF(lower(listing.sale_ticket_txid), ''),
         listing.listing_id
       )
       AND listing_anchor.vout = listing.sale_ticket_vout
       AND listing_anchor.value_sats = listing.sale_ticket_value_sats
       AND listing_anchor.spent_by_txid IS NULL
      WHERE listing.network = $1
        AND listing.listing_id = $2
        AND lower(listing.token_id) = $3
        AND listing.status IN ('active', 'sealing')
      ORDER BY listing_event.event_id
      LIMIT 2
    `,
    [network, normalizedListingId, WORK_TOKEN_ID],
  );
  if (result.rows.length !== 1) {
    return null;
  }
  const row = result.rows[0];
  const payload =
    row?.listing_event_payload &&
    typeof row.listing_event_payload === "object" &&
    !Array.isArray(row.listing_event_payload)
      ? row.listing_event_payload
      : {};
  const listingAuthorization =
    payload?.saleAuthorization &&
    typeof payload.saleAuthorization === "object" &&
    !Array.isArray(payload.saleAuthorization)
      ? payload.saleAuthorization
      : null;
  const position = canonicalAmoPosition(row);
  const blockHash = String(row?.block_hash ?? "").trim().toLowerCase();
  if (
    !listingAuthorization ||
    !position ||
    !/^[0-9a-f]{64}$/u.test(blockHash)
  ) {
    return null;
  }
  const version = String(listingAuthorization.version ?? "")
    .trim()
    .toLowerCase();
  let sourceWorkAmount;
  let currentWorkAmount;
  try {
    sourceWorkAmount = workAmountProjection(payload);
    currentWorkAmount = workListingAmountProjection(payload, {
      metadata: row.token_metadata,
      storedAmount: row.amount_units,
    });
  } catch {
    return null;
  }
  const v5Terms =
    version === WORK_AMO_V5_AUTH_VERSION
      ? await proofIndexWorkAmoListingTerms(network, normalizedListingId)
      : null;
  const v6Terms =
    version === WORK_AMO_V6_AUTH_VERSION
      ? await proofIndexWorkAmoV6ListingTerms(
          network,
          normalizedListingId,
        )
      : null;
  const v7Terms =
    version === WORK_AMO_V8_AUTH_VERSION
      ? await proofIndexWorkAmoV8ListingTerms(
          network,
          normalizedListingId,
        )
      : null;
  if (version === WORK_AMO_V5_AUTH_VERSION) {
    const termsPosition = v5Terms?.listingPosition;
    const frozenBlockHash = String(
      v5Terms?.frozenTerms?.listingBlockHash ?? "",
    )
      .trim()
      .toLowerCase();
    if (
      !termsPosition ||
      termsPosition.blockHeight !== position.blockHeight ||
      termsPosition.blockIndex !== position.blockIndex ||
      termsPosition.protocolVout !== position.protocolVout ||
      termsPosition.recordOrdinal !== position.recordOrdinal ||
      frozenBlockHash !== blockHash
    ) {
      return null;
    }
  }
  if (version === WORK_AMO_V6_AUTH_VERSION) {
    const termsPosition = v6Terms?.listingPosition;
    const frozenBlockHash = String(
      v6Terms?.frozenTerms?.listingBlockHash ?? "",
    )
      .trim()
      .toLowerCase();
    if (
      !termsPosition ||
      termsPosition.blockHeight !== position.blockHeight ||
      termsPosition.blockIndex !== position.blockIndex ||
      termsPosition.protocolVout !== position.protocolVout ||
      termsPosition.recordOrdinal !== position.recordOrdinal ||
      frozenBlockHash !== blockHash
    ) {
      return null;
    }
  }
  if (version === WORK_AMO_V8_AUTH_VERSION) {
    const termsPosition = v7Terms?.listingPosition;
    const frozenBlockHash = normalizedLowerText(
      v7Terms?.frozenTerms?.listingBlockHash,
    );
    if (
      !termsPosition ||
      termsPosition.blockHeight !== position.blockHeight ||
      termsPosition.blockIndex !== position.blockIndex ||
      termsPosition.protocolVout !== position.protocolVout ||
      termsPosition.recordOrdinal !== position.recordOrdinal ||
      frozenBlockHash !== blockHash
    ) {
      return null;
    }
  }
  let unitQuote = null;
  const canonicalPricingBlockKeys = new Set();
  if (version === WORK_MARKET_V4_AUTH_VERSION) {
    unitQuote = await proofIndexWorkUsdQuoteByTxid(
      network,
      listingAuthorization.unitUsdQuoteTxid,
    );
    const pricing =
      payload?.workMarketPricing &&
      typeof payload.workMarketPricing === "object" &&
      !Array.isArray(payload.workMarketPricing)
        ? payload.workMarketPricing
        : {};
    const quoteOracleHeight = Number(
      listingAuthorization.oracleBlockHeight,
    );
    const quoteOracleHash = String(
      listingAuthorization.oracleBlockHash ?? "",
    )
      .trim()
      .toLowerCase();
    const confirmationOracleHeight = Number(
      pricing.confirmationOracleBlockHeight,
    );
    const confirmationOracleHash = String(
      pricing.confirmationOracleBlockHash ?? "",
    )
      .trim()
      .toLowerCase();
    if (
      Number.isSafeInteger(quoteOracleHeight) &&
      quoteOracleHeight > 0 &&
      /^[0-9a-f]{64}$/u.test(quoteOracleHash) &&
      Number.isSafeInteger(confirmationOracleHeight) &&
      confirmationOracleHeight > 0 &&
      /^[0-9a-f]{64}$/u.test(confirmationOracleHash)
    ) {
      const pricingBlocks = await pool.query(
        `
          SELECT height, lower(block_hash) AS block_hash
          FROM proof_indexer.blocks
          WHERE network = $1
            AND canonical = true
            AND (
              (height = $2 AND lower(block_hash) = $3)
              OR
              (height = $4 AND lower(block_hash) = $5)
            )
        `,
        [
          network,
          quoteOracleHeight,
          quoteOracleHash,
          confirmationOracleHeight,
          confirmationOracleHash,
        ],
      );
      for (const pricingBlock of pricingBlocks.rows) {
        canonicalPricingBlockKeys.add(
          `${Number(pricingBlock.height)}:${String(
            pricingBlock.block_hash ?? "",
          ).toLowerCase()}`,
        );
      }
    }
  }
  const validatedV1FrozenTerms =
    version === WORK_MARKET_V4_AUTH_VERSION
      ? validatedHistoricalV4ListingWitness({
          amountAtoms: sourceWorkAmount.amountAtoms,
          anchorAddress: row.anchor_address,
          anchorScriptPubKey: row.anchor_scriptpubkey,
          anchorValueSats: row.anchor_value_sats,
          blockHash,
          canonicalPricingBlockKeys,
          listingAuthorization,
          listingId: normalizedListingId,
          payload,
          position,
          priceSats: row.price_sats,
          saleTicketTxid: row.sale_ticket_txid,
          saleTicketValueSats: row.sale_ticket_value_sats,
          saleTicketVout: row.sale_ticket_vout,
          sellerAddress: row.seller_address,
          unitQuote,
        })
      : null;
  return {
    amount: currentWorkAmount.amount,
    ...workAmountProjectionMetadataForAmount(currentWorkAmount),
    blockHash,
    canonical: true,
    confirmed: true,
    historicalV4ReplayValidated: Boolean(validatedV1FrozenTerms),
    listingAuthorization,
    listingFrozenTerms:
      version === WORK_AMO_V8_AUTH_VERSION
        ? v7Terms.frozenTerms
        : version === WORK_AMO_V6_AUTH_VERSION
          ? v6Terms.frozenTerms
          : version === WORK_AMO_V5_AUTH_VERSION
            ? v5Terms.frozenTerms
            : validatedV1FrozenTerms,
    listingId: normalizedListingId,
    priceSats: String(row.price_sats ?? ""),
    saleAuthorization: listingAuthorization,
    saleTicketTxid: String(
      row.sale_ticket_txid ?? normalizedListingId,
    ).toLowerCase(),
    saleTicketValueSats: String(row.sale_ticket_value_sats ?? ""),
    saleTicketVout: Number(row.sale_ticket_vout),
    status: row.listing_status,
    tokenId: WORK_TOKEN_ID,
    unspent: true,
    valid: true,
    validatedV1FrozenTerms,
    version,
    ...position,
  };
}

function exactWorkAmoV5PreUnitRelicAuthorization(authorization) {
  const exactString = (field, expected) =>
    typeof authorization?.[field] === "string" &&
    authorization[field] === expected;
  const exactInteger = (field, expected) =>
    typeof authorization?.[field] === "number" &&
    Number.isSafeInteger(authorization[field]) &&
    authorization[field] === expected;
  return (
    authorization &&
    typeof authorization === "object" &&
    !Array.isArray(authorization) &&
    exactString("version", WORK_AMO_V5_PRE_UNIT_RELIC_AUTH_VERSION) &&
    exactString("network", "livenet") &&
    exactString("tokenId", WORK_TOKEN_ID) &&
    exactString("ticker", "WORK") &&
    exactString("nonce", WORK_AMO_V5_PRE_UNIT_RELIC_NONCE) &&
    exactString("amountAtoms", WORK_AMO_V5_PRE_UNIT_RELIC_AMOUNT_ATOMS) &&
    exactInteger("priceSats", WORK_AMO_V5_PRE_UNIT_RELIC_PRICE_SATS) &&
    exactString(
      "minimumPriceSats",
      String(WORK_AMO_V5_PRE_UNIT_RELIC_MINIMUM_PRICE_SATS),
    ) &&
    exactString(
      "sellerAddress",
      WORK_AMO_V5_PRE_UNIT_RELIC_SELLER_ADDRESS,
    ) &&
    exactString(
      "registryAddress",
      WORK_AMO_V5_PRE_UNIT_RELIC_REGISTRY_ADDRESS,
    ) &&
    exactString(
      "sellerPublicKey",
      WORK_AMO_V5_PRE_UNIT_RELIC_SELLER_PUBLIC_KEY,
    ) &&
    exactString("buyerAddress", "") &&
    exactString("expiresAt", "") &&
    exactString("anchorTxid", "") &&
    exactString("anchorSignature", "") &&
    exactString("anchorType", "sale-ticket-v1") &&
    exactInteger("anchorVout", WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VOUT) &&
    exactInteger(
      "anchorValueSats",
      WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VALUE_SATS,
    ) &&
    exactInteger("anchorSigHashType", 0x83) &&
    exactString(
      "anchorScriptPubKey",
      WORK_AMO_V5_PRE_UNIT_RELIC_ANCHOR_SCRIPT_PUBKEY,
    ) &&
    exactString("oracleModel", WORK_AMO_V5_PRE_UNIT_RELIC_ORACLE_MODEL) &&
    exactInteger(
      "oracleBlockHeight",
      WORK_AMO_V5_PRE_UNIT_RELIC_ORACLE_BLOCK_HEIGHT,
    ) &&
    exactString(
      "oracleBlockHash",
      WORK_AMO_V5_PRE_UNIT_RELIC_ORACLE_BLOCK_HASH,
    ) &&
    exactString(
      "oracleNetworkValueQ8",
      WORK_AMO_V5_PRE_UNIT_RELIC_ORACLE_NETWORK_VALUE_Q8,
    )
  );
}

function exactWorkAmoV5PreUnitRelicPayloadAuthorizations(payload) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return false;
  }
  const present = [
    payload.saleAuthorization,
    payload.listingAuthorization,
  ].filter((authorization) => authorization !== undefined && authorization !== null);
  return (
    present.length > 0 &&
    present.every(exactWorkAmoV5PreUnitRelicAuthorization)
  );
}

function canonicalWorkAmoJson(value) {
  if (Array.isArray(value)) {
    return `[${value.map(canonicalWorkAmoJson).join(",")}]`;
  }
  if (value && typeof value === "object") {
    return `{${
      Object.keys(value)
        .sort(compareCanonicalUtf8)
        .map(
          (key) =>
            `${JSON.stringify(key)}:${canonicalWorkAmoJson(value[key])}`,
        )
        .join(",")
    }}`;
  }
  return JSON.stringify(value ?? null);
}

export function workAmoV5PreUnitRelicEvidenceFromRows(
  rows,
  activation = null,
) {
  const incomplete = (reason) => ({
    complete: false,
    model: WORK_AMO_V5_PRE_UNIT_RELIC_MODEL,
    reason,
  });
  const sourceRows = Array.isArray(rows) ? rows : [];
  if (sourceRows.length !== 1) {
    return incomplete("pre-unit-relic-event-cardinality");
  }
  const row = sourceRows[0];
  const payload =
    row?.listing_event_payload &&
    typeof row.listing_event_payload === "object" &&
    !Array.isArray(row.listing_event_payload)
      ? row.listing_event_payload
      : null;
  const listingPayload =
    row?.listing_row_payload &&
    typeof row.listing_row_payload === "object" &&
    !Array.isArray(row.listing_row_payload)
      ? row.listing_row_payload
      : null;
  const precisionMarker = objectRecord(
    row?.precision_migration_marker,
  );
  const precisionPins = normalizedWorkAmoV6ExpectedPins(
    precisionMarker,
  );
  const q16Definition =
    workDefinitionStorageModel({
      max_supply: row?.definition_max_supply,
      metadata: row?.definition_metadata,
      mint_amount: row?.definition_mint_amount,
    }) === WORK_SUBATOM_PROJECTION_MODEL;
  const precisionMarkerReady = Boolean(
    precisionPins &&
      sharedWorkPrecisionV2MarkerReady(
        precisionMarker,
        precisionPins,
        { network: "livenet" },
      ),
  );
  const precisionMigrationObserved =
    row?.precision_migration_marker !== undefined &&
      row?.precision_migration_marker !== null ||
    q16Definition;
  if (
    precisionMigrationObserved &&
    (!precisionMarkerReady || !q16Definition)
  ) {
    return incomplete("pre-unit-relic-precision-state-mismatch");
  }
  const postPrecisionMigration =
    precisionMarkerReady && q16Definition;
  const expectedMigratedListingPayload =
    postPrecisionMigration && payload
      ? {
          ...payload,
          legacyAmountAtoms: WORK_AMO_V5_PRE_UNIT_RELIC_AMOUNT_ATOMS,
          legacyAmountStorageModel:
            WORK_LEGACY_ATOMIC_PROJECTION_MODEL,
          precisionMigrationModel:
            WORK_PRECISION_V2_MIGRATION_MODEL,
        }
      : null;
  const listingPayloadMatchesEra = postPrecisionMigration
    ? Boolean(
        listingPayload &&
          expectedMigratedListingPayload &&
          canonicalWorkAmoJson(listingPayload) ===
            canonicalWorkAmoJson(expectedMigratedListingPayload),
      )
    : row?.listing_payload_matches_event === true;
  const relationalAmountForEra = postPrecisionMigration
    ? legacyWorkAtomsToSubatoms(
        WORK_AMO_V5_PRE_UNIT_RELIC_AMOUNT_ATOMS,
      )
    : WORK_AMO_V5_PRE_UNIT_RELIC_AMOUNT_ATOMS;
  const integer = (value, minimum = 0) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const lower = (value) => String(value ?? "").trim().toLowerCase();
  const text = (value) => String(value ?? "").trim();
  const listingId = lower(row?.listing_id);
  const blockHash = lower(row?.block_hash);
  const blockHeight = integer(row?.block_height, 1);
  const blockIndex = integer(row?.block_index);
  const protocolVout = integer(row?.protocol_vout);
  const recordOrdinal = integer(row?.record_ordinal);
  const saleTicketTxid = lower(
    row?.sale_ticket_txid || WORK_AMO_V5_PRE_UNIT_RELIC_LISTING_TXID,
  );
  const saleTicketVout = integer(row?.sale_ticket_vout);
  const saleTicketValueSats = integer(row?.sale_ticket_value_sats);
  const canonicalSpendCount = integer(row?.canonical_spend_count);
  const canonicalCloseCount = integer(row?.canonical_close_count);
  const canonicalCloseSaleCount = integer(
    row?.canonical_close_sale_count,
  );
  const canonicalCloseClosedCount = integer(
    row?.canonical_close_closed_count,
  );
  const listingEventCount = integer(row?.listing_event_count);
  const eventId = integer(row?.event_id, 1);
  const validSealCount = integer(row?.valid_seal_count);
  const registryPaymentCount = integer(row?.registry_payment_count);
  const registryPaymentSats = integer(row?.registry_payment_sats);
  const registryPaymentVout = integer(row?.registry_payment_vout);
  const pendingTicketSpendCount = integer(
    row?.pending_ticket_spend_count,
  );
  const v1DeclarationCount = integer(row?.v1_declaration_count);
  const transactionBlockHeight = integer(
    row?.transaction_block_height,
    1,
  );
  const transactionBlockIndex = integer(row?.transaction_block_index);
  const blockTime = dateIso(row?.block_time);
  const listingStatus = lower(row?.listing_status);
  const outputSpentByTxid = lower(row?.output_spent_by_txid);
  const canonicalSpendTxid = lower(row?.canonical_spend_txid);
  const canonicalCloseTxid = lower(row?.canonical_close_txid);
  const eventAuthorization = payload?.saleAuthorization;
  const listingAuthorization = listingPayload?.saleAuthorization;
  if (
    !payload ||
    !listingPayload ||
    !workAmoV5CutoverActivationIsExact(activation) ||
    lower(row?.network) !== "livenet" ||
    listingId !== WORK_AMO_V5_PRE_UNIT_RELIC_LISTING_TXID ||
    lower(row?.token_id) !== WORK_TOKEN_ID ||
    lower(row?.event_txid) !== listingId ||
    lower(row?.protocol) !== "pwt1" ||
    lower(row?.kind) !== "token-listing" ||
    lower(row?.event_status) !== "confirmed" ||
    lower(row?.transaction_status) !== "confirmed" ||
    row?.event_valid !== true ||
    row?.canonical_block !== true ||
    eventId === null ||
    listingEventCount !== 1 ||
    !listingPayloadMatchesEra ||
    text(row?.event_raw_payload) !== text(payload?.payload) ||
    text(row?.record_payload_text) !== text(row?.event_raw_payload) ||
    lower(row?.record_protocol) !== "pwt1" ||
    integer(row?.record_vout) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_PROTOCOL_VOUT ||
    integer(row?.record_output_index) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_RECORD_ORDINAL ||
    integer(row?.event_data_bytes) !== WORK_AMO_V5_PRE_UNIT_RELIC_DATA_BYTES ||
    integer(row?.record_data_bytes) !== WORK_AMO_V5_PRE_UNIT_RELIC_DATA_BYTES ||
    blockHash !== WORK_AMO_V5_PRE_UNIT_RELIC_BLOCK_HASH ||
    blockHeight !== WORK_AMO_V5_PRE_UNIT_RELIC_BLOCK_HEIGHT ||
    blockIndex !== WORK_AMO_V5_PRE_UNIT_RELIC_BLOCK_INDEX ||
    protocolVout !== WORK_AMO_V5_PRE_UNIT_RELIC_PROTOCOL_VOUT ||
    recordOrdinal !== WORK_AMO_V5_PRE_UNIT_RELIC_RECORD_ORDINAL ||
    transactionBlockHeight !== blockHeight ||
    transactionBlockIndex !== blockIndex ||
    blockTime !== WORK_AMO_V5_PRE_UNIT_RELIC_BLOCK_TIME ||
    text(row?.amount_atoms) !== relationalAmountForEra ||
    integer(row?.price_sats, 1) !== WORK_AMO_V5_PRE_UNIT_RELIC_PRICE_SATS ||
    text(row?.seller_address) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_SELLER_ADDRESS ||
    text(row?.definition_registry_address) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_REGISTRY_ADDRESS ||
    text(row?.ticker).toUpperCase() !== "WORK" ||
    saleTicketTxid !== WORK_AMO_V5_PRE_UNIT_RELIC_LISTING_TXID ||
    saleTicketVout !== WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VOUT ||
    saleTicketValueSats !==
      WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VALUE_SATS ||
    integer(row?.anchor_value_sats) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VALUE_SATS ||
    lower(row?.anchor_scriptpubkey) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_ANCHOR_SCRIPT_PUBKEY ||
    text(row?.anchor_address) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_SELLER_ADDRESS ||
    integer(row?.transaction_fee_sats) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_MINER_FEE_SATS ||
    integer(row?.event_amount_sats) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VALUE_SATS ||
    registryPaymentCount !== 1 ||
    registryPaymentSats !== WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VALUE_SATS ||
    registryPaymentVout !== 0 ||
    validSealCount !== 0 ||
    canonicalSpendCount === null ||
    canonicalSpendCount > 1 ||
    canonicalCloseCount === null ||
    canonicalCloseCount > 1 ||
    canonicalCloseSaleCount === null ||
    canonicalCloseClosedCount === null ||
    !(
      (
        canonicalCloseCount === 0 &&
        canonicalCloseSaleCount === 0 &&
        canonicalCloseClosedCount === 0
      ) ||
      (
        canonicalCloseCount === 1 &&
        canonicalCloseSaleCount <= 1 &&
        canonicalCloseClosedCount === 1
      )
    ) ||
    pendingTicketSpendCount !== 0 ||
    v1DeclarationCount !== 1 ||
    !exactWorkAmoV5PreUnitRelicPayloadAuthorizations(payload) ||
    !exactWorkAmoV5PreUnitRelicPayloadAuthorizations(listingPayload) ||
    !exactWorkAmoV5PreUnitRelicAuthorization(eventAuthorization) ||
    !exactWorkAmoV5PreUnitRelicAuthorization(listingAuthorization) ||
    lower(payload?.listingId ?? payload?.txid) !== listingId ||
    lower(payload?.tokenId) !== WORK_TOKEN_ID ||
    lower(payload?.network) !== "livenet" ||
    text(payload?.sellerAddress) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_SELLER_ADDRESS ||
    text(payload?.registryAddress) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_REGISTRY_ADDRESS ||
    text(payload?.amountAtoms) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_AMOUNT_ATOMS ||
    integer(payload?.priceSats, 1) !==
      WORK_AMO_V5_PRE_UNIT_RELIC_PRICE_SATS
  ) {
    return incomplete("pre-unit-relic-evidence-mismatch");
  }

  const terminal =
    canonicalSpendCount === 1 ||
    canonicalCloseCount === 1 ||
    Boolean(outputSpentByTxid);
  if (terminal) {
    if (
      canonicalSpendCount !== 1 ||
      !canonicalSpendTxid ||
      !outputSpentByTxid ||
      outputSpentByTxid !== canonicalSpendTxid ||
      (
        canonicalCloseCount === 1 &&
        (
          !canonicalCloseTxid ||
          canonicalCloseTxid !== canonicalSpendTxid
        )
      )
    ) {
      return incomplete("pre-unit-relic-terminal-evidence-mismatch");
    }
  } else if (
    outputSpentByTxid ||
    (
      postPrecisionMigration
        ? listingStatus !== "dropped"
        : !["active", "sealing"].includes(listingStatus)
    )
  ) {
    return incomplete("pre-unit-relic-open-state-mismatch");
  }

  const authorizationVersion = WORK_AMO_V5_PRE_UNIT_RELIC_AUTH_VERSION;
  const evidence = {
    activationBlockHash: WORK_AMO_V5_DECLARATION_BLOCK_HASH,
    activationBlockHeight: WORK_AMO_V5_DECLARATION_HEIGHT,
    activationBlockIndex: WORK_AMO_V5_DECLARATION_BLOCK_INDEX,
    activationBlockTime: String(activation?.blockTime ?? ""),
    activationTxid: WORK_AMO_V5_DECLARATION_TXID,
    amountAtoms: WORK_AMO_V5_PRE_UNIT_RELIC_AMOUNT_ATOMS,
    authorizationVersion,
    blockHash,
    blockHeight,
    blockIndex,
    canonical: true,
    canonicalCloseClosedCount,
    canonicalCloseCount,
    canonicalCloseSaleCount,
    canonicalCloseTxid,
    canonicalSpendCount,
    canonicalSpendTxid,
    complete: true,
    confirmed: true,
    disposition: terminal ? "terminal" : "relic",
    eventId,
    listingId,
    model: WORK_AMO_V5_PRE_UNIT_RELIC_MODEL,
    priceSats: WORK_AMO_V5_PRE_UNIT_RELIC_PRICE_SATS,
    protocolVout,
    recordOrdinal,
    registryAddress: WORK_AMO_V5_PRE_UNIT_RELIC_REGISTRY_ADDRESS,
    saleTicketTxid,
    saleTicketValueSats,
    saleTicketVout,
    sellerAddress: WORK_AMO_V5_PRE_UNIT_RELIC_SELLER_ADDRESS,
    terminal,
    txid: listingId,
    unspent: !terminal,
    valid: true,
  };
  if (!terminal) {
    evidence.listing = {
      _powEventIndex: WORK_AMO_V5_PRE_UNIT_RELIC_RECORD_ORDINAL,
      amount: formatWorkAtoms(WORK_AMO_V5_PRE_UNIT_RELIC_AMOUNT_ATOMS),
      amountAtoms: WORK_AMO_V5_PRE_UNIT_RELIC_AMOUNT_ATOMS,
      amountSats: WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VALUE_SATS,
      blockHash,
      blockHeight,
      blockIndex,
      confirmed: true,
      createdAt: blockTime,
      decimals: WORK_DECIMALS,
      kind: "token-listing",
      listingId,
      marketplaceMutationFeeSats:
        WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VALUE_SATS,
      minerFeeSats: WORK_AMO_V5_PRE_UNIT_RELIC_MINER_FEE_SATS,
      minimumPriceSats: WORK_AMO_V5_PRE_UNIT_RELIC_MINIMUM_PRICE_SATS,
      network: "livenet",
      priceSats: WORK_AMO_V5_PRE_UNIT_RELIC_PRICE_SATS,
      protocol: "pwt1",
      protocolVout,
      recordOrdinal,
      registryAddress: WORK_AMO_V5_PRE_UNIT_RELIC_REGISTRY_ADDRESS,
      saleAuthorization: eventAuthorization,
      saleTicketTxid,
      saleTicketValueSats,
      saleTicketVout,
      sellerAddress: WORK_AMO_V5_PRE_UNIT_RELIC_SELLER_ADDRESS,
      status: listingStatus,
      ticker: "WORK",
      tokenId: WORK_TOKEN_ID,
      txid: listingId,
      unitScale: WORK_UNIT_SCALE_TEXT,
      valid: true,
    };
  }
  return workAmoV5PreUnitRelicEvidenceIsExact(evidence)
    ? evidence
    : incomplete("pre-unit-relic-normalized-evidence-mismatch");
}

export async function proofIndexWorkAmoV5PreUnitRelicEvidence(
  network,
  indexedThroughBlock = WORK_AMO_V5_ACTIVATION_HEIGHT,
) {
  const pool = proofIndexPool();
  if (!pool) {
    return {
      complete: false,
      model: WORK_AMO_V5_PRE_UNIT_RELIC_MODEL,
      reason: "database-not-configured",
    };
  }
  const result = await pool.query(
    `
      SELECT
        listing.listing_id,
        listing.status AS listing_status,
        listing.token_id,
        listing.seller_address,
        listing.amount::text AS amount_atoms,
        listing.price_sats::text AS price_sats,
        listing.sale_ticket_txid,
        listing.sale_ticket_vout,
        listing.sale_ticket_value_sats::text AS sale_ticket_value_sats,
        listing.payload AS listing_row_payload,
        (listing.payload = listing_event.payload) AS
          listing_payload_matches_event,
        listing_event.event_id,
        listing_event.network,
        listing_event.txid AS event_txid,
        listing_event.protocol,
        listing_event.kind,
        listing_event.status AS event_status,
        listing_event.valid AS event_valid,
        listing_event.amount_sats::text AS event_amount_sats,
        listing_event.data_bytes AS event_data_bytes,
        listing_event.raw_payload AS event_raw_payload,
        listing_event.payload AS listing_event_payload,
        listing_event.block_height,
        listing_event.block_index,
        listing_event.op_return_vout AS protocol_vout,
        listing_event.record_ordinal,
        listing_tx.status AS transaction_status,
        listing_tx.block_hash,
        listing_tx.block_height AS transaction_block_height,
        listing_tx.block_index AS transaction_block_index,
        listing_tx.block_time,
        listing_tx.fee_sats::text AS transaction_fee_sats,
        listing_block.canonical AS canonical_block,
        listing_anchor.address AS anchor_address,
        listing_anchor.scriptpubkey AS anchor_scriptpubkey,
        listing_anchor.value_sats::text AS anchor_value_sats,
        listing_anchor.spent_by_txid AS output_spent_by_txid,
        listing_record.protocol AS record_protocol,
        listing_record.vout AS record_vout,
        listing_record.output_index AS record_output_index,
        listing_record.payload_text AS record_payload_text,
        listing_record.data_bytes AS record_data_bytes,
        definition.ticker,
        definition.registry_address AS definition_registry_address,
        definition.max_supply::text AS definition_max_supply,
        definition.mint_amount::text AS definition_mint_amount,
        definition.metadata AS definition_metadata,
        precision_migration.value AS precision_migration_marker,
        (
          SELECT count(*)::integer
          FROM proof_indexer.events counted_listing_event
          WHERE counted_listing_event.network = listing.network
            AND counted_listing_event.txid = listing.listing_id
            AND counted_listing_event.protocol = 'pwt1'
            AND counted_listing_event.kind = 'token-listing'
        ) AS listing_event_count,
        (
          SELECT count(*)::integer
          FROM proof_indexer.events seal_event
          JOIN proof_indexer.transactions seal_tx
            ON seal_tx.network = seal_event.network
           AND seal_tx.txid = seal_event.txid
           AND seal_tx.status = 'confirmed'
           AND seal_tx.block_height = seal_event.block_height
           AND seal_tx.block_index = seal_event.block_index
          JOIN proof_indexer.blocks seal_block
            ON seal_block.network = seal_tx.network
           AND seal_block.block_hash = seal_tx.block_hash
           AND seal_block.height = seal_tx.block_height
           AND seal_block.canonical = true
          WHERE seal_event.network = listing.network
            AND seal_event.valid = true
            AND seal_event.status = 'confirmed'
            AND seal_event.protocol = 'pwt1'
            AND seal_event.kind = 'token-listing-sealed'
            AND lower(seal_event.payload->>'listingId') = listing.listing_id
        ) AS valid_seal_count,
        (
          SELECT count(*)::integer
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = listing.network
            AND registry_output.txid = listing.listing_id
            AND registry_output.address = $3
            AND registry_output.value_sats = $4
        ) AS registry_payment_count,
        (
          SELECT COALESCE(sum(registry_output.value_sats), 0)::text
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = listing.network
            AND registry_output.txid = listing.listing_id
            AND registry_output.address = $3
        ) AS registry_payment_sats,
        (
          SELECT min(registry_output.vout)
          FROM proof_indexer.tx_outputs registry_output
          WHERE registry_output.network = listing.network
            AND registry_output.txid = listing.listing_id
            AND registry_output.address = $3
        ) AS registry_payment_vout,
        (
          SELECT count(*)::integer
          FROM proof_indexer.tx_inputs spend_input
          JOIN proof_indexer.transactions spend_tx
            ON spend_tx.network = spend_input.network
           AND spend_tx.txid = spend_input.txid
           AND spend_tx.status = 'confirmed'
          JOIN proof_indexer.blocks spend_block
            ON spend_block.network = spend_tx.network
           AND spend_block.block_hash = spend_tx.block_hash
           AND spend_block.height = spend_tx.block_height
           AND spend_block.canonical = true
          WHERE spend_input.network = listing.network
            AND spend_input.prev_txid = lower(COALESCE(
              NULLIF(listing.sale_ticket_txid, ''),
              listing.listing_id
            ))
            AND spend_input.prev_vout = listing.sale_ticket_vout
        ) AS canonical_spend_count,
        (
          SELECT min(spend_tx.txid)
          FROM proof_indexer.tx_inputs spend_input
          JOIN proof_indexer.transactions spend_tx
            ON spend_tx.network = spend_input.network
           AND spend_tx.txid = spend_input.txid
           AND spend_tx.status = 'confirmed'
          JOIN proof_indexer.blocks spend_block
            ON spend_block.network = spend_tx.network
           AND spend_block.block_hash = spend_tx.block_hash
           AND spend_block.height = spend_tx.block_height
           AND spend_block.canonical = true
          WHERE spend_input.network = listing.network
            AND spend_input.prev_txid = lower(COALESCE(
              NULLIF(listing.sale_ticket_txid, ''),
              listing.listing_id
            ))
            AND spend_input.prev_vout = listing.sale_ticket_vout
        ) AS canonical_spend_txid,
        (
          SELECT count(*)::integer
          FROM proof_indexer.tx_inputs spend_input
          LEFT JOIN proof_indexer.transactions spend_tx
            ON spend_tx.network = spend_input.network
           AND spend_tx.txid = spend_input.txid
          LEFT JOIN proof_indexer.blocks spend_block
            ON spend_block.network = spend_tx.network
           AND spend_block.block_hash = spend_tx.block_hash
           AND spend_block.height = spend_tx.block_height
           AND spend_block.canonical = true
          WHERE spend_input.network = listing.network
            AND spend_input.prev_txid = lower(COALESCE(
              NULLIF(listing.sale_ticket_txid, ''),
              listing.listing_id
            ))
            AND spend_input.prev_vout = listing.sale_ticket_vout
            AND (
              spend_tx.status IS DISTINCT FROM 'confirmed'
              OR spend_block.block_hash IS NULL
            )
        ) AS pending_ticket_spend_count,
        canonical_close.canonical_close_count,
        canonical_close.canonical_close_sale_count,
        canonical_close.canonical_close_closed_count,
        canonical_close.canonical_close_txid,
        (
          SELECT count(*)::integer
          FROM proof_indexer.transactions v1_declaration_tx
          JOIN proof_indexer.blocks v1_declaration_block
            ON v1_declaration_block.network = v1_declaration_tx.network
           AND v1_declaration_block.block_hash =
             v1_declaration_tx.block_hash
           AND v1_declaration_block.height =
             v1_declaration_tx.block_height
           AND v1_declaration_block.canonical = true
          WHERE v1_declaration_tx.network = listing.network
            AND v1_declaration_tx.txid = $6
            AND v1_declaration_tx.status = 'confirmed'
            AND v1_declaration_tx.block_height = $7
            AND lower(v1_declaration_tx.block_hash) = $8
            AND v1_declaration_tx.block_index = $9
        ) AS v1_declaration_count
      FROM proof_indexer.credit_listings listing
      JOIN proof_indexer.transactions listing_tx
        ON listing_tx.network = listing.network
       AND listing_tx.txid = listing.listing_id
       AND listing_tx.status = 'confirmed'
       AND listing_tx.block_index IS NOT NULL
      JOIN proof_indexer.blocks listing_block
        ON listing_block.network = listing_tx.network
       AND listing_block.block_hash = listing_tx.block_hash
       AND listing_block.height = listing_tx.block_height
       AND listing_block.canonical = true
      JOIN proof_indexer.events listing_event
        ON listing_event.network = listing.network
       AND listing_event.txid = listing.listing_id
       AND listing_event.protocol = 'pwt1'
       AND listing_event.kind = 'token-listing'
       AND listing_event.status = 'confirmed'
       AND listing_event.valid = true
       AND listing_event.block_height = listing_tx.block_height
       AND listing_event.block_index = listing_tx.block_index
      JOIN proof_indexer.tx_outputs listing_anchor
        ON listing_anchor.network = listing.network
       AND listing_anchor.txid = lower(COALESCE(
         NULLIF(listing.sale_ticket_txid, ''),
         listing.listing_id
       ))
       AND listing_anchor.vout = listing.sale_ticket_vout
       AND listing_anchor.value_sats = listing.sale_ticket_value_sats
      JOIN proof_indexer.op_returns listing_record
        ON listing_record.network = listing_event.network
       AND listing_record.txid = listing_event.txid
       AND listing_record.vout = listing_event.op_return_vout
       AND listing_record.output_index = listing_event.record_ordinal
      JOIN proof_indexer.credit_definitions definition
        ON definition.network = listing.network
       AND definition.token_id = listing.token_id
      LEFT JOIN proof_indexer.meta precision_migration
        ON precision_migration.key = $10
      LEFT JOIN LATERAL (
        SELECT
          count(DISTINCT close_event.txid)::integer AS
            canonical_close_count,
          count(*) FILTER (
            WHERE close_event.kind = 'token-sale'
          )::integer AS canonical_close_sale_count,
          count(*) FILTER (
            WHERE close_event.kind = 'token-listing-closed'
          )::integer AS canonical_close_closed_count,
          min(close_event.txid) AS canonical_close_txid
        FROM proof_indexer.events close_event
        JOIN proof_indexer.transactions close_tx
          ON close_tx.network = close_event.network
         AND close_tx.txid = close_event.txid
         AND close_tx.status = 'confirmed'
         AND close_tx.block_height = close_event.block_height
         AND close_tx.block_index = close_event.block_index
        JOIN proof_indexer.blocks close_block
          ON close_block.network = close_tx.network
         AND close_block.block_hash = close_tx.block_hash
         AND close_block.height = close_tx.block_height
         AND close_block.canonical = true
        WHERE close_event.network = listing.network
          AND close_event.valid = true
          AND close_event.status = 'confirmed'
          AND close_event.protocol = 'pwt1'
          AND close_event.kind =
            ANY(ARRAY['token-listing-closed','token-sale']::text[])
          AND lower(close_event.payload->>'listingId') = listing.listing_id
      ) canonical_close ON true
      WHERE listing.network = $1
        AND listing.listing_id = $2
        AND lower(listing.token_id) = $5
      ORDER BY listing_event.event_id
      LIMIT 2
    `,
    [
      network,
      WORK_AMO_V5_PRE_UNIT_RELIC_LISTING_TXID,
      WORK_AMO_V5_PRE_UNIT_RELIC_REGISTRY_ADDRESS,
      WORK_AMO_V5_PRE_UNIT_RELIC_TICKET_VALUE_SATS,
      WORK_TOKEN_ID,
      WORK_AMO_V1_DECLARATION_TXID,
      WORK_AMO_V5_V1_DECLARATION_HEIGHT,
      WORK_AMO_V5_V1_DECLARATION_BLOCK_HASH,
      WORK_AMO_V5_V1_DECLARATION_BLOCK_INDEX,
      WORK_PRECISION_V2_MIGRATION_META_KEY,
    ],
  );
  const activation = await proofIndexWorkAmoV5Declaration(
    network,
    indexedThroughBlock,
  );
  return workAmoV5PreUnitRelicEvidenceFromRows(result.rows, activation);
}

async function assertCurrentAmoV5CanonicalPositionUniqueness(pool, network) {
  const result = await pool.query(
    `
      SELECT
        event_row.block_height,
        event_row.block_index,
        event_row.op_return_vout,
        event_row.record_ordinal,
        min(event_row.event_id)::text AS first_event_id,
        max(event_row.event_id)::text AS second_event_id
      FROM proof_indexer.events event_row
      JOIN proof_indexer.transactions event_tx
        ON event_tx.network = event_row.network
       AND event_tx.txid = event_row.txid
       AND event_tx.status = 'confirmed'
       AND event_tx.block_height = event_row.block_height
       AND event_tx.block_index = event_row.block_index
      JOIN proof_indexer.blocks event_block
        ON event_block.network = event_tx.network
       AND event_block.block_hash = event_tx.block_hash
       AND event_block.height = event_tx.block_height
       AND event_block.canonical = true
      WHERE event_row.network = $1
        AND event_row.status = 'confirmed'
        AND event_row.block_height >= $2
        AND event_row.block_index >= 0
        AND event_row.op_return_vout >= 0
        AND event_row.record_ordinal >= 0
        AND event_row.protocol = ANY(
          ARRAY['pwm1','pwa1','pwid1','pwr1','pwt1']::text[]
        )
      GROUP BY
        event_row.block_height,
        event_row.block_index,
        event_row.op_return_vout,
        event_row.record_ordinal
      HAVING count(DISTINCT event_row.event_id) > 1
      ORDER BY
        event_row.block_height,
        event_row.block_index,
        event_row.op_return_vout,
        event_row.record_ordinal
      LIMIT 1
    `,
    [network, WORK_AMO_V5_ACTIVATION_HEIGHT],
  );
  const duplicate = result.rows[0];
  if (!duplicate) {
    return;
  }
  const position = [
    duplicate.block_height,
    duplicate.block_index,
    duplicate.op_return_vout,
    duplicate.record_ordinal,
  ].join(":");
  const error = new Error(
    `Proof index AMO V5 current state is ambiguous: canonical records ${duplicate.first_event_id} and ${duplicate.second_event_id} share position ${position}.`,
  );
  error.code = "PROOF_INDEX_AMO_V5_CANONICAL_POSITION_DUPLICATED";
  throw error;
}

export async function proofIndexWorkAmoCanonicalEvents(
  network,
  options = {},
) {
  const pool = proofIndexPool();
  if (!pool) {
    return {
      complete: false,
      items: [],
      reasons: ["database-not-configured"],
    };
  }
  const fromHeight = Math.max(
    WORK_AMO_V1_ACTIVATION_HEIGHT,
    Number.isSafeInteger(Number(options.fromHeight))
      ? Number(options.fromHeight)
      : WORK_AMO_V1_ACTIVATION_HEIGHT,
  );
  const toHeight =
    Number.isSafeInteger(Number(options.toHeight)) &&
    Number(options.toHeight) >= fromHeight
      ? Number(options.toHeight)
      : 2_147_483_647;
  const limit = Math.min(
    10_000,
    Math.max(
      1,
      Number.isSafeInteger(Number(options.limit)) ? Number(options.limit) : 1000,
    ),
  );
  const exactCursorInteger = (value, minimum) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const hasCallerCursor =
    options.after && typeof options.after === "object";
  const after = hasCallerCursor
    ? (() => {
        const blockHeight = exactCursorInteger(
          options.after.blockHeight,
          1,
        );
        const blockIndex = exactCursorInteger(options.after.blockIndex, 0);
        const protocolVout = exactCursorInteger(
          options.after.protocolVout,
          0,
        );
        const rawRecordOrdinal = options.after.recordOrdinal;
        const recordOrdinal =
          rawRecordOrdinal === undefined ||
          rawRecordOrdinal === null ||
          rawRecordOrdinal === ""
            ? blockHeight !== null &&
                blockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT
              ? 0
              : null
            : exactCursorInteger(rawRecordOrdinal, 0);
        return { blockHeight, blockIndex, protocolVout, recordOrdinal };
      })()
    : {
        blockHeight: fromHeight - 1,
        blockIndex: -1,
        protocolVout: -1,
        recordOrdinal: -1,
      };
  if (
    (hasCallerCursor &&
      (
        after.blockHeight === null ||
        after.blockIndex === null ||
        after.protocolVout === null ||
        after.recordOrdinal === null
      )) ||
    !Number.isSafeInteger(after.blockHeight) ||
    !Number.isSafeInteger(after.blockIndex) ||
    !Number.isSafeInteger(after.protocolVout) ||
    !Number.isSafeInteger(after.recordOrdinal)
  ) {
    return { complete: false, items: [], reasons: ["invalid-cursor"] };
  }
  const positionAudit = await pool.query(
    `
      WITH canonical_candidates AS (
        SELECT
          event_row.block_height,
          event_row.block_index,
          event_row.op_return_vout,
          event_row.record_ordinal,
          event_tx.block_height AS transaction_block_height,
          event_tx.block_index AS transaction_block_index
        FROM proof_indexer.events event_row
        JOIN proof_indexer.transactions event_tx
          ON event_tx.network = event_row.network
         AND event_tx.txid = event_row.txid
        JOIN proof_indexer.blocks event_block
          ON event_block.network = event_tx.network
         AND event_block.block_hash = event_tx.block_hash
         AND event_block.height = event_tx.block_height
         AND event_block.canonical = true
        WHERE event_row.network = $1
          AND event_row.status = 'confirmed'
          AND event_tx.status = 'confirmed'
          AND event_row.protocol = ANY(
            ARRAY['pwm1','pwa1','pwid1','pwr1','pwt1']::text[]
          )
          AND event_tx.block_height BETWEEN $2 AND $3
      )
      SELECT
        count(*) FILTER (
          WHERE block_height IS NULL
            OR block_height < 1
            OR block_height IS DISTINCT FROM transaction_block_height
            OR block_index IS NULL
            OR block_index < 0
            OR op_return_vout IS NULL
            OR op_return_vout < 0
            OR record_ordinal IS NULL
            OR record_ordinal < 0
            OR transaction_block_index IS NULL
            OR transaction_block_index < 0
            OR transaction_block_index IS DISTINCT FROM block_index
        )::integer AS incomplete_count,
        (
          SELECT count(*)::integer
          FROM (
            SELECT 1
            FROM canonical_candidates duplicate_candidate
            WHERE duplicate_candidate.block_height >= 1
              AND duplicate_candidate.block_height =
                duplicate_candidate.transaction_block_height
              AND duplicate_candidate.block_index >= 0
              AND duplicate_candidate.block_index =
                duplicate_candidate.transaction_block_index
              AND duplicate_candidate.op_return_vout >= 0
              AND duplicate_candidate.record_ordinal >= 0
            GROUP BY
              duplicate_candidate.block_height,
              duplicate_candidate.block_index,
              duplicate_candidate.op_return_vout,
              duplicate_candidate.record_ordinal
            HAVING count(*) > 1
          ) duplicate_positions
        ) AS duplicate_count
      FROM canonical_candidates
    `,
    [network, fromHeight, toHeight],
  );
  if (Number(positionAudit.rows[0]?.incomplete_count ?? 0) > 0) {
    return {
      complete: false,
      items: [],
      reasons: ["canonical-position-incomplete"],
    };
  }
  if (Number(positionAudit.rows[0]?.duplicate_count ?? 0) > 0) {
    return {
      complete: false,
      items: [],
      reasons: ["canonical-position-duplicated"],
    };
  }
  const result = await pool.query(
    `
      SELECT
        event_row.event_id,
        event_row.event_key,
        event_row.txid,
        event_row.protocol,
        event_row.kind,
        event_row.status,
        event_row.valid,
        event_row.validation_errors,
        event_row.block_height,
        event_row.block_index,
        event_row.op_return_vout AS protocol_vout,
        event_row.record_ordinal,
        event_tx.block_hash,
        event_tx.fee_sats,
        event_row.payload
      FROM proof_indexer.events event_row
      JOIN proof_indexer.transactions event_tx
        ON event_tx.network = event_row.network
       AND event_tx.txid = event_row.txid
       AND event_tx.status = 'confirmed'
       AND event_tx.block_height = event_row.block_height
       AND event_tx.block_index = event_row.block_index
      JOIN proof_indexer.blocks event_block
        ON event_block.network = event_tx.network
       AND event_block.block_hash = event_tx.block_hash
       AND event_block.height = event_tx.block_height
       AND event_block.canonical = true
      WHERE event_row.network = $1
        AND event_row.status = 'confirmed'
        AND event_row.protocol = ANY(
          ARRAY['pwm1','pwa1','pwid1','pwr1','pwt1']::text[]
        )
        AND event_row.block_height BETWEEN $2 AND $3
        AND (
          event_row.block_height,
          event_row.block_index,
          event_row.op_return_vout,
          event_row.record_ordinal
        ) > ($4::integer, $5::integer, $6::integer, $7::integer)
      ORDER BY
        event_row.block_height,
        event_row.block_index,
        event_row.op_return_vout,
        event_row.record_ordinal
      LIMIT $8
    `,
    [
      network,
      fromHeight,
      toHeight,
      after.blockHeight,
      after.blockIndex,
      after.protocolVout,
      after.recordOrdinal,
      limit,
    ],
  );
  return {
    complete: result.rows.length < limit,
    items: result.rows.map((row) => ({
      blockHash: String(row.block_hash ?? "").toLowerCase(),
      eventId: String(row.event_id),
      eventKey: row.event_key,
      feeSats: String(row.fee_sats ?? "0"),
      kind: row.kind,
      payload:
        row.payload && typeof row.payload === "object" ? row.payload : {},
      protocol: row.protocol,
      status: row.status,
      txid: row.txid,
      valid: row.valid === true,
      validationErrors: Array.isArray(row.validation_errors)
        ? row.validation_errors
        : [],
      ...canonicalAmoPosition(row),
    })),
    reasons: [],
  };
}

export async function proofIndexWorkAmoCanonicalReplayEvents(
  network,
  options = {},
) {
  const requestedLimit = Number(options.limit);
  const limit =
    Number.isSafeInteger(requestedLimit) && requestedLimit > 0
      ? Math.min(10_000, requestedLimit)
      : 10_000;
  const items = [];
  let after =
    options.after && typeof options.after === "object"
      ? options.after
      : undefined;
  let pageCount = 0;
  for (;;) {
    const page = await proofIndexWorkAmoCanonicalEvents(network, {
      ...options,
      after,
      limit,
    });
    pageCount += 1;
    if (page.complete !== true && page.items.length === 0) {
      return {
        complete: false,
        items,
        pageCount,
        reasons:
          Array.isArray(page.reasons) && page.reasons.length > 0
            ? page.reasons
            : ["canonical-event-replay-incomplete"],
      };
    }
    items.push(...page.items);
    if (page.complete === true) {
      return { complete: true, items, pageCount, reasons: [] };
    }
    const last = page.items.at(-1);
    const nextAfter = canonicalAmoPosition(last);
    if (!nextAfter || compareAmoPositions(after, nextAfter) >= 0) {
      return {
        complete: false,
        items,
        pageCount,
        reasons: ["canonical-event-replay-cursor-stalled"],
      };
    }
    after = nextAfter;
  }
}

export async function proofIndexWorkAmoBlockTransition(
  network,
  blockHeight,
  blockHash,
) {
  const pool = proofIndexPool();
  const height = Number(blockHeight);
  const hash = String(blockHash ?? "").trim().toLowerCase();
  if (
    !pool ||
    !String(network ?? "").trim() ||
    !Number.isSafeInteger(height) ||
    height < WORK_AMO_V5_ACTIVATION_HEIGHT ||
    !/^[0-9a-f]{64}$/u.test(hash)
  ) {
    return null;
  }
  const configuredPrecisionPins =
    configuredWorkPrecisionV2ReaderPins();
  const activationLatch =
    network === "livenet"
      ? await proofIndexWorkAmoV8ActivationLatch(
          network,
          configuredPrecisionPins ?? undefined,
        )
      : null;
  const precisionActivationHeight =
    activationLatch?.pins?.activationHeight ??
    configuredPrecisionPins?.activationHeight ??
    Number.POSITIVE_INFINITY;
  const q16Transition = height >= precisionActivationHeight;
  const expectedTransitionModel = q16Transition
    ? WORK_AMO_V8_BLOCK_SEQUENCER_MODEL
    : WORK_AMO_V5_BLOCK_SEQUENCER_MODEL;
  const expectedWorkTokenStateModel = q16Transition
    ? WORK_AMO_V8_TOKEN_STATE_PREIMAGE_MODEL
    : null;
  const result = await pool.query(
    `
      SELECT
        transition.network,
        transition.block_height,
        lower(transition.block_hash) AS block_hash,
        lower(transition.previous_block_hash) AS previous_block_hash,
        transition.model,
        transition.state_commitment_model,
        transition.work_token_state_model,
        transition.opening_network_value_q8::text,
        transition.closing_network_value_q8::text,
        transition.opening_state_sha256,
        transition.closing_state_sha256,
        transition.opening_state_payload_bytes,
        transition.closing_state_payload_bytes,
        transition.protocol_record_count,
        transition.raw_protocol_candidate_count,
        transition.transaction_count,
        transition.event_count,
        transition.event_set_model,
        transition.event_set_sha256,
        transition.event_set_payload_bytes,
        transition.block_atomic,
        transition.fee_once,
        transition.invalid_zero,
        transition.complete,
        transition.payload
      FROM proof_indexer.work_amo_block_transitions transition
      JOIN proof_indexer.blocks transition_block
        ON transition_block.network = transition.network
       AND transition_block.height = transition.block_height
       AND transition_block.block_hash = transition.block_hash
       AND transition_block.previous_block_hash =
         transition.previous_block_hash
       AND transition_block.canonical = true
      WHERE transition.network = $1
        AND transition.block_height = $2
        AND lower(transition.block_hash) = $3
        AND transition.model = $4
        AND transition.work_token_state_model IS NOT DISTINCT FROM $11
        AND transition.state_commitment_model = $5
        AND transition.event_set_model = $6
        AND transition.payload->>'transitionChainModel' = $7
        AND transition.payload
          ->'transitionChainCommitment'->>'model' = $7
        AND transition.payload
          ->'transitionChainCommitment'->>'sha256' ~
            '^[0-9a-f]{64}$'
        AND transition.payload
          ->'transitionChainCommitment'->>'payloadBytes' ~
            '^[1-9][0-9]*$'
        AND transition.payload->>'blockDescriptorModel' = $8
        AND transition.payload
          ->'blockDescriptorCommitment'->>'model' = $9
        AND transition.payload
          ->'blockDescriptorCommitment'->>'sha256' ~
            '^[0-9a-f]{64}$'
        AND transition.payload
          ->'blockDescriptorCommitment'->>'payloadBytes' ~
            '^[1-9][0-9]*$'
        AND transition.payload->>'blockTransactionCount' ~
            '^[1-9][0-9]*$'
        AND transition.payload
          ->'bip141Witness'->>'model' = $10
        AND transition.payload
          ->'bip141Witness'->>'required' IN ('true', 'false')
        AND transition.payload
          ->'bip141Witness'->>'witnessTransactionCount' ~
            '^(?:0|[1-9][0-9]*)$'
        AND (
          (
            transition.payload
              ->'bip141Witness'->>'required' = 'false'
            AND transition.payload
              ->'bip141Witness'->>'witnessTransactionCount' = '0'
            AND transition.payload
              ->'bip141Witness'->>'commitmentSha256' = ''
            AND transition.payload
              ->'bip141Witness'->>'witnessMerkleRootInternalHex' = ''
            AND transition.payload
              ->'bip141Witness'->>'commitmentVout' IS NULL
            AND NOT (
              transition.payload->'bip141Witness'
                ? 'commitmentScriptPubKeyHex'
            )
            AND NOT (
              transition.payload->'bip141Witness'
                ? 'coinbaseWitnessReservedValueHex'
            )
          )
          OR
          (
            transition.payload
              ->'bip141Witness'->>'required' = 'true'
            AND transition.payload
              ->'bip141Witness'->>'witnessTransactionCount' ~
                '^[1-9][0-9]*$'
            AND transition.payload
              ->'bip141Witness'->>'commitmentVout' ~
                '^(?:0|[1-9][0-9]*)$'
            AND transition.payload
              ->'bip141Witness'->>'commitmentSha256' ~
                '^[0-9a-f]{64}$'
            AND transition.payload
              ->'bip141Witness'->>'witnessMerkleRootInternalHex' ~
                '^[0-9a-f]{64}$'
            AND transition.payload
              ->'bip141Witness'->>'coinbaseWitnessReservedValueHex' ~
                '^[0-9a-f]{64}$'
            AND transition.payload
              ->'bip141Witness'->>'commitmentScriptPubKeyHex' ~
                '^6a24aa21a9ed[0-9a-f]+$'
            AND length(
              transition.payload
                ->'bip141Witness'->>'commitmentScriptPubKeyHex'
            ) % 2 = 0
            AND substring(
              transition.payload
                ->'bip141Witness'->>'commitmentScriptPubKeyHex'
              FROM 13 FOR 64
            ) = transition.payload
              ->'bip141Witness'->>'commitmentSha256'
          )
        )
        AND transition.block_atomic = true
        AND transition.fee_once = true
        AND transition.invalid_zero = true
        AND transition.complete = true
      LIMIT 2
    `,
    [
      network,
      height,
      hash,
      expectedTransitionModel,
      WORK_AMO_V5_STATE_COMMITMENT_MODEL,
      WORK_AMO_V5_EVENT_SET_COMMITMENT_MODEL,
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL,
      WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL,
      WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL,
      WORK_AMO_V5_RAW_BIP141_WITNESS_MODEL,
      expectedWorkTokenStateModel,
    ],
  );
  if (result.rows.length !== 1) {
    return null;
  }
  const row = result.rows[0];
  const payload =
    row?.payload &&
    typeof row.payload === "object" &&
    !Array.isArray(row.payload)
      ? row.payload
      : null;
  const transitionChainCommitment =
    payload?.transitionChainCommitment;
  const transitionChainPayloadBytes = Number(
    transitionChainCommitment?.payloadBytes,
  );
  const transitionChainSha256 = String(
    transitionChainCommitment?.sha256 ?? "",
  )
    .trim()
    .toLowerCase();
  const blockDescriptorCommitment =
    payload?.blockDescriptorCommitment;
  const blockDescriptorPayloadBytes = Number(
    blockDescriptorCommitment?.payloadBytes,
  );
  const blockDescriptorSha256 = String(
    blockDescriptorCommitment?.sha256 ?? "",
  )
    .trim()
    .toLowerCase();
  const blockTransactionCount = Number(
    payload?.blockTransactionCount,
  );
  const bip141Witness = normalizedWorkAmoV5Bip141Witness(
    payload?.bip141Witness,
    blockTransactionCount,
  );
  return payload?.transitionChainModel ===
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL &&
    transitionChainCommitment?.model ===
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL &&
    Number.isSafeInteger(transitionChainPayloadBytes) &&
    transitionChainPayloadBytes > 0 &&
    /^[0-9a-f]{64}$/u.test(transitionChainSha256) &&
    payload?.blockDescriptorModel ===
      WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL &&
    blockDescriptorCommitment?.model ===
      WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL &&
    Number.isSafeInteger(blockDescriptorPayloadBytes) &&
    blockDescriptorPayloadBytes > 0 &&
    /^[0-9a-f]{64}$/u.test(blockDescriptorSha256) &&
    Number.isSafeInteger(blockTransactionCount) &&
    blockTransactionCount > 0 &&
    Boolean(bip141Witness)
    ? {
        ...row,
        blockHeight: Number(row.block_height),
        blockHash: String(row.block_hash ?? "").toLowerCase(),
        previousBlockHash: String(
          row.previous_block_hash ?? "",
        ).toLowerCase(),
        payload,
        workTokenStateModel:
          row.work_token_state_model ?? null,
      }
    : null;
}

export function workAmoV5LegacyBootstrapCarryEvidenceFromRows(rows) {
  const incomplete = (reason) => ({
    complete: false,
    model: WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MODEL,
    reason,
  });
  const sourceRows = Array.isArray(rows) ? rows : [];
  if (sourceRows.length !== 1) {
    return incomplete("legacy-bootstrap-event-cardinality");
  }
  const row = sourceRows[0];
  const payload =
    row?.payload &&
    typeof row.payload === "object" &&
    !Array.isArray(row.payload)
      ? row.payload
      : null;
  if (!payload) {
    return incomplete("legacy-bootstrap-payload-missing");
  }
  const integer = (value, minimum = 0) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const text = (value) => String(value ?? "").trim();
  const lower = (value) => text(value).toLowerCase();
  const exactReasons = (value) =>
    Array.isArray(value) &&
    value.length === 1 &&
    text(value[0]) === WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_REASON_CODE;
  const listingStatuses = Array.isArray(row?.listing_statuses)
    ? row.listing_statuses.map(lower)
    : [];
  const authorizationVersions = [
    lower(payload?.saleAuthorization?.version),
    lower(payload?.listingAuthorization?.version),
  ].filter(Boolean);
  const eventId = integer(row?.event_id, 1);
  const mutationSats = integer(row?.amount_sats);
  const minerFeeSats = integer(row?.fee_sats);
  const payloadMutationSats = integer(payload?.amountSats);
  const payloadMinerFeeSats = integer(payload?.minerFeeSats);
  const blockHeight = integer(row?.block_height, 1);
  const blockIndex = integer(row?.block_index);
  const protocolVout = integer(row?.protocol_vout);
  const recordOrdinal = integer(row?.record_ordinal);
  const transactionBlockHeight = integer(
    row?.transaction_block_height,
    1,
  );
  const transactionBlockIndex = integer(row?.transaction_block_index);
  const listingCount = integer(row?.listing_count);
  const activeListingCount = integer(row?.active_listing_count);
  const txid = lower(row?.txid);
  const blockHash = lower(row?.block_hash);
  if (
    lower(row?.network) !== "livenet" ||
    txid !== WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_TXID ||
    blockHash !== WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_BLOCK_HASH ||
    lower(row?.protocol) !== "pwt1" ||
    lower(row?.kind) !== "token-listing" ||
    lower(row?.event_status ?? row?.status) !== "confirmed" ||
    lower(row?.transaction_status) !== "confirmed" ||
    row?.valid !== false ||
    row?.canonical_block !== true ||
    eventId === null ||
    blockHeight !== WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_BLOCK_HEIGHT ||
    blockIndex !== WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_BLOCK_INDEX ||
    protocolVout !== WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_PROTOCOL_VOUT ||
    recordOrdinal !== WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_RECORD_ORDINAL ||
    transactionBlockHeight !== blockHeight ||
    transactionBlockIndex !== blockIndex ||
    mutationSats !== WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MUTATION_SATS ||
    minerFeeSats !== WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MINER_FEE_SATS ||
    !exactReasons(row?.validation_errors) ||
    listingCount !== 1 ||
    activeListingCount !== 0 ||
    listingStatuses.length !== 1 ||
    listingStatuses[0] !== "dropped" ||
    lower(payload?.txid) !== txid ||
    lower(payload?.protocol) !== "pwt1" ||
    lower(payload?.kind) !== "token-listing" ||
    lower(payload?.network) !== "livenet" ||
    lower(payload?.status) !== "confirmed" ||
    payload?.confirmed !== true ||
    payload?.valid !== false ||
    payload?.relic !== false ||
    payload?.refundEligible !== false ||
    text(payload?.reasonCode) !==
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_REASON_CODE ||
    !exactReasons(payload?.validationErrors) ||
    lower(payload?.tokenId) !== WORK_TOKEN_ID ||
    lower(payload?.listingId) !== txid ||
    lower(payload?.saleTicketTxid) !== txid ||
    lower(payload?.blockHash) !== blockHash ||
    integer(payload?.blockHeight, 1) !== blockHeight ||
    integer(payload?.blockIndex) !== blockIndex ||
    integer(payload?.protocolVout) !== protocolVout ||
    integer(payload?._powEventIndex) !== recordOrdinal ||
    payloadMutationSats !== mutationSats ||
    payloadMinerFeeSats !== minerFeeSats ||
    authorizationVersions.length !== 1 ||
    authorizationVersions[0] !== "pwt-sale-v3"
  ) {
    return incomplete("legacy-bootstrap-evidence-mismatch");
  }
  const creditFixedSats = mutationSats + minerFeeSats;
  const growthValueSats = mutationSats * 5;
  return {
    activeListingCount,
    blockHash,
    blockHeight,
    blockIndex,
    complete: true,
    creditFixedQ8: (BigInt(creditFixedSats) * 100_000_000n).toString(),
    creditFixedSats,
    eventId,
    growthValueQ8: (BigInt(growthValueSats) * 100_000_000n).toString(),
    growthValueSats,
    listingCount,
    marketplaceMutationFeeSats: mutationSats,
    minerFeeSats,
    model: WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MODEL,
    protocolVout,
    reasonCode: WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_REASON_CODE,
    recordOrdinal,
    txid,
  };
}

export async function proofIndexWorkAmoLegacyBootstrapCarryEvidence(
  network,
) {
  const pool = proofIndexPool();
  if (!pool) {
    return {
      complete: false,
      model: WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MODEL,
      reason: "database-not-configured",
    };
  }
  const result = await pool.query(
    `
      SELECT
        event_row.event_id,
        event_row.network,
        event_row.txid,
        event_row.protocol,
        event_row.kind,
        event_row.status AS event_status,
        event_row.valid,
        event_row.validation_errors,
        event_row.block_height,
        event_row.block_index,
        event_row.op_return_vout AS protocol_vout,
        event_row.record_ordinal,
        event_row.amount_sats,
        event_row.payload,
        event_tx.status AS transaction_status,
        event_tx.block_hash,
        event_tx.block_height AS transaction_block_height,
        event_tx.block_index AS transaction_block_index,
        event_tx.fee_sats,
        event_block.canonical AS canonical_block,
        (
          SELECT count(*)::integer
          FROM proof_indexer.credit_listings listing
          WHERE listing.network = event_row.network
            AND listing.listing_id = event_row.txid
        ) AS listing_count,
        (
          SELECT count(*)::integer
          FROM proof_indexer.credit_listings listing
          WHERE listing.network = event_row.network
            AND listing.listing_id = event_row.txid
            AND listing.status IN ('active', 'sealing')
        ) AS active_listing_count,
        (
          SELECT COALESCE(
            jsonb_agg(listing.status ORDER BY listing.status),
            '[]'::jsonb
          )
          FROM proof_indexer.credit_listings listing
          WHERE listing.network = event_row.network
            AND listing.listing_id = event_row.txid
        ) AS listing_statuses
      FROM proof_indexer.events event_row
      JOIN proof_indexer.transactions event_tx
        ON event_tx.network = event_row.network
       AND event_tx.txid = event_row.txid
      JOIN proof_indexer.blocks event_block
        ON event_block.network = event_tx.network
       AND event_block.block_hash = event_tx.block_hash
       AND event_block.height = event_tx.block_height
      WHERE event_row.network = $1
        AND event_row.txid = $2
      ORDER BY event_row.event_id
    `,
    [network, WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_TXID],
  );
  return workAmoV5LegacyBootstrapCarryEvidenceFromRows(result.rows);
}

export async function proofIndexWorkAmoRelationalTokenStateEvidence(
  network,
  expectedTokenStateCommitment = null,
) {
  const pool = proofIndexPool();
  if (!pool) {
    return { complete: false, reason: "database-not-configured" };
  }
  const [balanceResult, listingResult] = await Promise.all([
    pool.query(
      `
        SELECT address, confirmed_balance::text AS balance_atoms
        FROM proof_indexer.credit_balances
        WHERE network = $1
          AND lower(token_id) = $2
          AND confirmed_balance > 0
        ORDER BY address
      `,
      [network, WORK_TOKEN_ID],
    ),
    pool.query(
      `
        SELECT
          listing.listing_id,
          listing.seller_address,
          listing.amount::text AS amount_atoms,
          listing.price_sats::text AS price_sats,
          listing.payload->'listingAuthorization'
            AS listing_authorization,
          listing.payload->'saleAuthorization'
            AS sale_authorization,
          COALESCE(
            listing.payload->'listingAuthorization'->>'version',
            listing.payload->'saleAuthorization'->>'version',
            ''
          ) AS authorization_version,
          CASE
            WHEN COALESCE(
              listing.payload->'listingAuthorization'->>'version',
              listing.payload->'saleAuthorization'->>'version',
              ''
            ) = $3
              THEN v6_terms.frozen_terms
            ELSE COALESCE(
              v5_terms.frozen_terms,
              listing.payload->'listingFrozenTerms'
            )
          END AS frozen_terms,
          CASE
            WHEN COALESCE(
              listing.payload->'listingAuthorization'->>'version',
              listing.payload->'saleAuthorization'->>'version',
              ''
            ) = $3
              THEN v6_terms.listing_id IS NOT NULL
            ELSE true
          END AS immutable_terms_complete
        FROM proof_indexer.credit_listings listing
        JOIN proof_indexer.transactions listing_tx
          ON listing_tx.network = listing.network
         AND listing_tx.txid = listing.listing_id
         AND listing_tx.status = 'confirmed'
        JOIN proof_indexer.blocks listing_block
          ON listing_block.network = listing_tx.network
         AND listing_block.block_hash = listing_tx.block_hash
         AND listing_block.height = listing_tx.block_height
         AND listing_block.canonical = true
        LEFT JOIN proof_indexer.work_amo_listing_terms v5_terms
          ON v5_terms.network = listing.network
         AND v5_terms.listing_id = listing.listing_id
        LEFT JOIN proof_indexer.work_amo_v6_listing_terms v6_terms
          ON v6_terms.network = listing.network
         AND v6_terms.listing_id = listing.listing_id
         AND v6_terms.listing_txid = listing.listing_id
         AND v6_terms.token_id = lower(listing.token_id)
         AND v6_terms.authorization_version = $3
         AND v6_terms.authorization_version = COALESCE(
           listing.payload->'listingAuthorization'->>'version',
           listing.payload->'saleAuthorization'->>'version',
           ''
         )
         AND v6_terms.unit_amount_atoms = listing.amount
         AND v6_terms.unit_price_sats = listing.price_sats
         AND (
           listing.payload->'listingFrozenTerms' IS NULL
           OR listing.payload->'listingFrozenTerms' =
             v6_terms.frozen_terms
         )
         AND (
           listing.payload->'frozenTerms' IS NULL
           OR listing.payload->'frozenTerms' =
             v6_terms.frozen_terms
         )
         AND (
           listing.payload->'workAmoFrozenTerms' IS NULL
           OR listing.payload->'workAmoFrozenTerms' =
             v6_terms.frozen_terms
         )
         AND (
           listing.payload->'workAmoV6FrozenTerms' IS NULL
           OR listing.payload->'workAmoV6FrozenTerms' =
             v6_terms.frozen_terms
         )
        WHERE listing.network = $1
          AND lower(listing.token_id) = $2
          AND listing.status IN ('active', 'sealing')
        ORDER BY listing.listing_id
      `,
      [network, WORK_TOKEN_ID, WORK_AMO_V6_AUTH_VERSION],
    ),
  ]);
  const holders = balanceResult.rows.map((row) => ({
    address: String(row.address ?? ""),
    balanceAtoms: String(row.balance_atoms ?? ""),
  }));
  let confirmedSupplyAtoms;
  try {
    confirmedSupplyAtoms = holders
      .reduce((total, holder) => {
        if (!/^[1-9][0-9]*$/u.test(holder.balanceAtoms)) {
          throw new Error("relational-token-state-balance-invalid");
        }
        return total + BigInt(holder.balanceAtoms);
      }, 0n)
      .toString();
  } catch (error) {
    return {
      complete: false,
      reason: error?.message ?? "relational-token-state-balance-invalid",
    };
  }
  const invalidV6Listing = listingResult.rows.find(
    (row) =>
      String(row.authorization_version ?? "").trim() ===
        WORK_AMO_V6_AUTH_VERSION &&
      row.immutable_terms_complete !== true,
  );
  if (invalidV6Listing) {
    return {
      complete: false,
      reason: "relational-v6-listing-terms-invalid",
    };
  }
  const listings =
    workAmoV5WorkStateWithoutLegacyListingReservations({
      listings: listingResult.rows.map((row) => ({
        amountAtoms: String(row.amount_atoms ?? ""),
        frozenTerms: row.frozen_terms,
        listingId: String(row.listing_id ?? "").trim().toLowerCase(),
        listingAuthorization: row.listing_authorization,
        priceSats: String(row.price_sats ?? ""),
        saleAuthorization:
          row.sale_authorization ?? row.listing_authorization,
        sellerAddress: String(row.seller_address ?? ""),
      })),
    }).listings;
  let commitment;
  try {
    commitment = workAmoV6CanonicalTokenStateCommitment({
      confirmedSupplyAtoms,
      holders,
      listings,
    });
  } catch (error) {
    return {
      complete: false,
      reason: error?.message ?? "relational-token-state-invalid",
    };
  }
  const expectedModel = String(expectedTokenStateCommitment?.model ?? "");
  const expectedSha256 = String(
    expectedTokenStateCommitment?.sha256 ?? "",
  )
    .trim()
    .toLowerCase();
  const expectedPayloadBytes = Number(
    expectedTokenStateCommitment?.payloadBytes,
  );
  const expectedMatches =
    expectedTokenStateCommitment === null ||
    (
      expectedModel === commitment.model &&
      expectedSha256 === commitment.sha256 &&
      expectedPayloadBytes === commitment.payloadBytes
    );
  return {
    commitment,
    complete: expectedMatches,
    confirmedSupplyAtoms,
    holderCount: holders.length,
    listingCount: listings.length,
    model: "canonical-work-amo-relational-token-state-audit-v1",
    ...(expectedMatches
      ? {}
      : { reason: "relational-token-state-commitment-mismatch" }),
  };
}

