export function workAmoV5GenericTokenStatePreimageFromRows({
  balanceRows,
  blockHash,
  blockHeight,
  definitionRows,
  listingRows,
} = {}) {
  const indexedThroughBlock = Number(blockHeight);
  const indexedThroughBlockHash = String(blockHash ?? "")
    .trim()
    .toLowerCase();
  if (
    !Number.isSafeInteger(indexedThroughBlock) ||
    indexedThroughBlock < 1 ||
    !/^[0-9a-f]{64}$/u.test(indexedThroughBlockHash)
  ) {
    return {
      complete: false,
      reason: "generic-token-state-checkpoint-invalid",
    };
  }
  const exactPositiveInteger = (value) => {
    const text = String(value ?? "");
    return /^[1-9][0-9]*$/u.test(text) ? text : "";
  };
  const definitions = new Map();
  let reason = "";
  for (const row of Array.isArray(definitionRows) ? definitionRows : []) {
    const tokenId = String(row.token_id ?? "").trim().toLowerCase();
    const ticker = String(row.ticker ?? "").trim().toUpperCase();
    const registryAddress = String(row.registry_address ?? "").trim();
    const bond = isBondTokenId(tokenId);
    const maxSupply = bond
      ? null
      : exactPositiveInteger(row.max_supply);
    const mintAmount = exactPositiveInteger(row.mint_amount);
    const mintPriceSats = exactPositiveInteger(row.mint_price_sats);
    if (
      !/^[0-9a-f]{64}$/u.test(tokenId) ||
      !/^[A-Z0-9]{1,12}$/u.test(ticker) ||
      !isWorkAmoV5LivenetAddress(registryAddress) ||
      (!bond && !maxSupply) ||
      !mintAmount ||
      !mintPriceSats ||
      definitions.has(tokenId)
    ) {
      reason = "generic-token-state-definition-invalid";
      break;
    }
    definitions.set(tokenId, {
      confirmedSupplyAtoms: "0",
      maxSupply,
      mintAmount,
      mintPriceSats,
      registryAddress,
      ticker,
      tokenId,
    });
  }
  const supply = new Map();
  const holders = [];
  if (!reason) {
    for (const row of Array.isArray(balanceRows) ? balanceRows : []) {
      const tokenId = String(row.token_id ?? "").trim().toLowerCase();
      const address = String(row.address ?? "").trim();
      const balance = exactPositiveInteger(row.confirmed_balance);
      if (
        !definitions.has(tokenId) ||
        !isWorkAmoV5LivenetAddress(address) ||
        !balance
      ) {
        reason = "generic-token-state-balance-invalid";
        break;
      }
      holders.push({ address, balance, tokenId });
      supply.set(
        tokenId,
        (supply.get(tokenId) ?? 0n) + BigInt(balance),
      );
    }
  }
  const listings = [];
  if (!reason) {
    for (const row of Array.isArray(listingRows) ? listingRows : []) {
      const listingId = String(row.listing_id ?? "")
        .trim()
        .toLowerCase();
      const tokenId = String(row.token_id ?? "").trim().toLowerCase();
      const sellerAddress = String(row.seller_address ?? "").trim();
      const amount = exactPositiveInteger(row.amount);
      const priceSats = exactPositiveInteger(row.price_sats);
      const definition = definitions.get(tokenId);
      const saleAuthorization =
        parseWorkAmoV5GenericSaleAuthorization(
          row.sale_authorization,
        );
      if (
        !/^[0-9a-f]{64}$/u.test(listingId) ||
        !definition ||
        !isWorkAmoV5LivenetAddress(sellerAddress) ||
        !amount ||
        !priceSats ||
        !saleAuthorization ||
        saleAuthorization.tokenId !== tokenId ||
        String(saleAuthorization.amount) !== amount ||
        String(saleAuthorization.priceSats) !== priceSats ||
        saleAuthorization.sellerAddress !== sellerAddress ||
        saleAuthorization.registryAddress !==
          definition.registryAddress ||
        saleAuthorization.ticker !== definition.ticker
      ) {
        reason = "generic-token-state-listing-invalid";
        break;
      }
      listings.push({
        amount,
        listingId,
        priceSats,
        saleAuthorization: row.sale_authorization,
        sellerAddress,
        tokenId,
      });
    }
  }
  const tokens = [...definitions.values()].map((definition) => ({
    ...definition,
    confirmedSupplyAtoms:
      (supply.get(definition.tokenId) ?? 0n).toString(),
  }));
  return {
    complete: !reason,
    holders: reason ? [] : holders,
    indexedThroughBlock,
    indexedThroughBlockHash,
    listings: reason ? [] : listings,
    model: "canonical-work-amo-v5-generic-token-state-sql-preimage-v1",
    ...(reason ? { reason } : {}),
    tokens: reason ? [] : tokens,
  };
}

export async function proofIndexWorkAmoGenericTokenStatePreimage(
  network,
  {
    blockHash,
    blockHeight,
  } = {},
) {
  const pool = proofIndexPool();
  const expectedHeight = Number(blockHeight);
  const expectedHash = String(blockHash ?? "").trim().toLowerCase();
  if (
    !pool ||
    network !== "livenet" ||
    !Number.isSafeInteger(expectedHeight) ||
    expectedHeight < 1 ||
    !/^[0-9a-f]{64}$/u.test(expectedHash)
  ) {
    return null;
  }
  const client = await pool.connect();
  let transactionOpen = false;
  try {
    await client.query(
      "BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY",
    );
    transactionOpen = true;
    const checkpointResult = await client.query(
      `
        SELECT height, lower(block_hash) AS block_hash
        FROM proof_indexer.blocks
        WHERE network = $1
          AND canonical = true
        ORDER BY height DESC, block_hash
        LIMIT 2
      `,
      [network],
    );
    const checkpoint = checkpointResult.rows[0];
    const checkpointUnique =
      !checkpointResult.rows[1] ||
      Number(checkpointResult.rows[1].height) !== Number(checkpoint?.height);
    if (
      !checkpointUnique ||
      Number(checkpoint?.height) !== expectedHeight ||
      String(checkpoint?.block_hash ?? "").trim().toLowerCase() !==
        expectedHash
    ) {
      await client.query("COMMIT");
      transactionOpen = false;
      return {
        complete: false,
        indexedThroughBlock: Number(checkpoint?.height ?? 0),
        indexedThroughBlockHash: String(
          checkpoint?.block_hash ?? "",
        )
          .trim()
          .toLowerCase(),
        reason: "generic-token-state-checkpoint-mismatch",
      };
    }
    const definitionResult = await client.query(
      `
        SELECT
          lower(definition.token_id) AS token_id,
          upper(definition.ticker) AS ticker,
          definition.registry_address,
          definition.max_supply::text AS max_supply,
          definition.mint_amount::text AS mint_amount,
          definition.mint_price_sats::text AS mint_price_sats
        FROM proof_indexer.credit_definitions definition
        WHERE definition.network = $1
          AND lower(definition.token_id) <> $2
          AND definition.confirmed = true
          AND (
            definition.metadata->>'canonicalSynthetic' = 'true'
            OR EXISTS (
              SELECT 1
              FROM proof_indexer.transactions definition_transaction
              JOIN proof_indexer.blocks definition_block
                ON definition_block.network =
                  definition_transaction.network
               AND definition_block.block_hash =
                  definition_transaction.block_hash
               AND definition_block.height =
                  definition_transaction.block_height
               AND definition_block.canonical = true
              WHERE definition_transaction.network =
                  definition.network
                AND definition_transaction.txid =
                  definition.create_txid
                AND definition_transaction.status = 'confirmed'
            )
          )
        ORDER BY lower(definition.token_id)
      `,
      [network, WORK_TOKEN_ID],
    );
    const balanceResult = await client.query(
      `
        SELECT
          lower(balance.token_id) AS token_id,
          balance.address,
          balance.confirmed_balance::text AS confirmed_balance
        FROM proof_indexer.credit_balances balance
        WHERE balance.network = $1
          AND lower(balance.token_id) <> $2
          AND balance.confirmed_balance > 0
        ORDER BY
          lower(balance.token_id),
          balance.address
      `,
      [network, WORK_TOKEN_ID],
    );
    const listingResult = await client.query(
      `
        SELECT
          lower(listing.listing_id) AS listing_id,
          lower(listing.token_id) AS token_id,
          listing.seller_address,
          listing.amount::text AS amount,
          listing.price_sats::text AS price_sats,
          COALESCE(
            listing.payload->'listingAuthorization',
            listing.payload->'saleAuthorization'
          ) AS sale_authorization
        FROM proof_indexer.credit_listings listing
        JOIN proof_indexer.transactions listing_transaction
          ON listing_transaction.network = listing.network
         AND listing_transaction.txid = listing.listing_id
         AND listing_transaction.status = 'confirmed'
        JOIN proof_indexer.blocks listing_block
          ON listing_block.network = listing_transaction.network
         AND listing_block.block_hash =
           listing_transaction.block_hash
         AND listing_block.height =
           listing_transaction.block_height
         AND listing_block.canonical = true
        WHERE listing.network = $1
          AND lower(listing.token_id) <> $2
          AND listing.status IN ('active', 'sealing')
          AND NOT EXISTS (
            SELECT 1
            FROM proof_indexer.tx_inputs spend_input
            JOIN proof_indexer.transactions spend_transaction
              ON spend_transaction.network = spend_input.network
             AND spend_transaction.txid = spend_input.txid
             AND spend_transaction.status = 'confirmed'
            JOIN proof_indexer.blocks spend_block
              ON spend_block.network = spend_transaction.network
             AND spend_block.block_hash =
               spend_transaction.block_hash
             AND spend_block.height =
               spend_transaction.block_height
             AND spend_block.canonical = true
            WHERE spend_input.network = listing.network
              AND spend_input.prev_txid = lower(
                COALESCE(
                  NULLIF(listing.sale_ticket_txid, ''),
                  listing.listing_id
                )
              )
              AND spend_input.prev_vout = listing.sale_ticket_vout
          )
        ORDER BY lower(listing.listing_id)
      `,
      [network, WORK_TOKEN_ID],
    );
    const preimage = workAmoV5GenericTokenStatePreimageFromRows({
      balanceRows: balanceResult.rows,
      blockHash: expectedHash,
      blockHeight: expectedHeight,
      definitionRows: definitionResult.rows,
      listingRows: listingResult.rows,
    });
    await client.query("COMMIT");
    transactionOpen = false;
    return preimage;
  } catch (error) {
    if (transactionOpen) {
      await client.query("ROLLBACK").catch(() => {});
    }
    throw error;
  } finally {
    client.release();
  }
}

function workAmoReplayReadinessCheckpointKey(network, options = {}) {
  const normalizedNetwork = String(network ?? "").trim();
  const throughHeight = Number(options.throughHeight);
  const throughBlockHash = String(options.throughBlockHash ?? "")
    .trim()
    .toLowerCase();
  return normalizedNetwork &&
    Number.isSafeInteger(throughHeight) &&
    throughHeight > 0 &&
    /^[0-9a-f]{64}$/u.test(throughBlockHash)
      ? `${normalizedNetwork}:${throughHeight}:${throughBlockHash}`
      : "";
}

function workAmoReplayReadinessRequest(network, options = {}) {
  const requestOptions = Object.freeze({ ...options });
  const checkpointKey =
    requestOptions.force === true ||
    requestOptions.singleFlightBypass === true
      ? ""
      : workAmoReplayReadinessCheckpointKey(network, requestOptions);
  return Object.freeze({
    checkpointKey,
    options: requestOptions,
  });
}

async function exactCheckpointSingleFlight(inFlight, key, load) {
  const existing = inFlight.get(key);
  if (existing) {
    return existing;
  }
  const pending = Promise.resolve().then(load);
  inFlight.set(key, pending);
  try {
    return await pending;
  } finally {
    if (inFlight.get(key) === pending) {
      inFlight.delete(key);
    }
  }
}

function deepFreezeReadinessSnapshot(value, seen = new WeakSet()) {
  if (
    value === null ||
    typeof value !== "object" ||
    seen.has(value)
  ) {
    return value;
  }
  const prototype = Object.getPrototypeOf(value);
  const plainObject =
    prototype === null ||
    Object.getPrototypeOf(prototype) === null;
  if (
    !Array.isArray(value) &&
    !plainObject
  ) {
    return value;
  }
  seen.add(value);
  for (const child of Object.values(value)) {
    deepFreezeReadinessSnapshot(child, seen);
  }
  return Object.freeze(value);
}

function workAmoReplayReadinessResultIsExactPositive(
  result,
  options = {},
) {
  const throughHeight = Number(options.throughHeight);
  const throughBlockHash = String(options.throughBlockHash ?? "")
    .trim()
    .toLowerCase();
  return (
    result?.ready === true &&
    result?.indexReady === true &&
    result?.requestedTipReady === true &&
    Number(result.requestedThroughHeight) === throughHeight &&
    Number(result.throughHeight) === throughHeight &&
    Number(result.canonicalTip) === throughHeight &&
    String(result.requestedThroughBlockHash ?? "")
      .trim()
      .toLowerCase() === throughBlockHash &&
    String(result.canonicalTipBlockHash ?? "")
      .trim()
      .toLowerCase() === throughBlockHash
  );
}

function rememberExactCheckpointReadiness(
  cache,
  key,
  result,
  maxEntries = 2,
) {
  cache.delete(key);
  cache.set(key, result);
  while (cache.size > maxEntries) {
    const oldestKey = cache.keys().next().value;
    if (oldestKey === undefined) {
      break;
    }
    cache.delete(oldestKey);
  }
}

async function exactCheckpointReadinessWithCache({
  checkpointKey,
  inFlight,
  load,
  options,
  readyCache,
}) {
  const settledReady = readyCache.get(checkpointKey);
  if (settledReady) {
    return settledReady;
  }
  const result = await exactCheckpointSingleFlight(
    inFlight,
    checkpointKey,
    load,
  );
  if (!workAmoReplayReadinessResultIsExactPositive(result, options)) {
    return result;
  }
  const immutableResult = deepFreezeReadinessSnapshot({ ...result });
  rememberExactCheckpointReadiness(
    readyCache,
    checkpointKey,
    immutableResult,
  );
  return immutableResult;
}

function proofIndexWorkAmoSeedEvidenceReadiness(
  evidenceSet,
  canonicalSeedBlock,
  markerSeed,
  seedBindings,
) {
  const set =
    evidenceSet &&
    typeof evidenceSet === "object" &&
    !Array.isArray(evidenceSet)
      ? evidenceSet
      : {};
  const rows = Array.isArray(set.rows) ? set.rows : [];
  const row =
    Number(set.rowCount) === 1 && rows.length === 1
      ? rows[0]
      : null;
  const payload =
    row?.payload &&
    typeof row.payload === "object" &&
    !Array.isArray(row.payload)
      ? row.payload
      : null;
  const evidence =
    validatedWorkAmoV5HMinusOneSeedEvidence(payload);
  if (!row || !evidence) {
    return null;
  }
  const sourceHashes =
    row.sourceHashes &&
    typeof row.sourceHashes === "object" &&
    !Array.isArray(row.sourceHashes)
      ? row.sourceHashes
      : {};
  const metrics =
    row.metrics &&
    typeof row.metrics === "object" &&
    !Array.isArray(row.metrics)
      ? row.metrics
      : {};
  const consistency =
    row.consistency &&
    typeof row.consistency === "object" &&
    !Array.isArray(row.consistency)
      ? row.consistency
      : {};
  const expectedMetrics = {
    complete: true,
    genericHolderCount:
      evidence.seedGenericTokenState.holders.length,
    genericListingCount:
      evidence.seedGenericTokenState.listings.length,
    genericTokenCount:
      evidence.seedGenericTokenState.tokens.length,
    idCount: evidence.seedIdState.records.length,
    workHolderCount: evidence.seedTokenState.holders.length,
    workListingCount: evidence.seedTokenState.listings.length,
  };
  const storedMarker =
    markerSeed &&
    typeof markerSeed === "object" &&
    !Array.isArray(markerSeed)
      ? markerSeed
      : {};
  const markerSnapshotIds = Array.isArray(storedMarker.snapshotIds)
    ? storedMarker.snapshotIds.map((value) => String(value ?? "").trim())
    : [];
  const markerSnapshotIdSet = new Set(markerSnapshotIds);
  const bindings =
    seedBindings &&
    typeof seedBindings === "object" &&
    !Array.isArray(seedBindings)
      ? seedBindings
      : {};
  const activationTransition =
    bindings.activationTransition &&
    typeof bindings.activationTransition === "object" &&
    !Array.isArray(bindings.activationTransition)
      ? bindings.activationTransition
      : {};
  const independentSeed =
    bindings.independentSeed &&
    typeof bindings.independentSeed === "object" &&
    !Array.isArray(bindings.independentSeed)
      ? bindings.independentSeed
      : {};
  const firstOpeningCommitment =
    bindings.firstOpeningCommitment &&
    typeof bindings.firstOpeningCommitment === "object" &&
    !Array.isArray(bindings.firstOpeningCommitment)
      ? bindings.firstOpeningCommitment
      : {};
  const storedSeedCommitment =
    bindings.bootstrapSeedCommitment &&
    typeof bindings.bootstrapSeedCommitment === "object" &&
    !Array.isArray(bindings.bootstrapSeedCommitment)
      ? bindings.bootstrapSeedCommitment
      : {};
  const evidenceSeedCommitment =
    evidence.commitments.sufficientState;
  const commitmentMatchesEvidence = (commitment) =>
    commitment?.model === evidenceSeedCommitment.model &&
    Number(commitment?.payloadBytes) ===
      evidenceSeedCommitment.payloadBytes &&
    String(commitment?.sha256 ?? "").trim().toLowerCase() ===
      evidenceSeedCommitment.sha256;
  const metadataReady =
    canonicalSeedBlock === true &&
    Object.keys(sourceHashes).sort().join(",") ===
      "amoSeedBlock,amoSeedCanonicalSummary,amoSeedEvidence" &&
    Object.keys(metrics).sort().join(",") ===
      "complete,genericHolderCount,genericListingCount,genericTokenCount,idCount,workHolderCount,workListingCount" &&
    Object.keys(consistency).sort().join(",") === "ok,status" &&
    String(row.snapshotId ?? "") === evidence.snapshotId &&
    Number(row.indexedThroughBlock) ===
      evidence.indexedThroughBlock &&
    sourceHashes.amoSeedBlock ===
      evidence.indexedThroughBlockHash &&
    sourceHashes.amoSeedCanonicalSummary ===
      evidence.canonicalSummary.canonicalSummaryHash &&
    sourceHashes.amoSeedEvidence ===
      evidence.evidenceCommitment.sha256 &&
    consistency.ok === true &&
    consistency.status ===
      WORK_AMO_V5_H_MINUS_ONE_SEED_EVIDENCE_STATUS &&
    Object.entries(expectedMetrics).every(
      ([key, value]) => metrics[key] === value,
    );
  const markerReady =
    Number(storedMarker.blockHeight) ===
      evidence.indexedThroughBlock &&
    String(storedMarker.blockHash ?? "").trim().toLowerCase() ===
      evidence.indexedThroughBlockHash &&
    String(storedMarker.networkValueQ8 ?? "") ===
      evidence.canonicalSummary.networkValueQ8 &&
    String(storedMarker.summaryHash ?? "").trim().toLowerCase() ===
      evidence.canonicalSummary.canonicalSummaryHash &&
    evidence.canonicalSummary.snapshotId ===
      WORK_AMO_V5_H_MINUS_ONE_CANONICAL_SUMMARY_SNAPSHOT_ID &&
    Number(storedMarker.snapshotCount) === 1 &&
    markerSnapshotIds.length === 1 &&
    markerSnapshotIdSet.size === 1 &&
    markerSnapshotIds[0] ===
      WORK_AMO_V5_H_MINUS_ONE_CANONICAL_SUMMARY_SNAPSHOT_ID &&
    commitmentMatchesEvidence(storedSeedCommitment) &&
    independentSeed.source ===
      "pinned-h-minus-one-seed-evidence" &&
    commitmentMatchesEvidence(independentSeed.commitment) &&
    commitmentMatchesEvidence(firstOpeningCommitment) &&
    Number(activationTransition.blockHeight) ===
      WORK_AMO_V5_ACTIVATION_HEIGHT &&
    /^[0-9a-f]{64}$/u.test(
      String(activationTransition.blockHash ?? "")
        .trim()
        .toLowerCase(),
    ) &&
    String(activationTransition.previousBlockHash ?? "")
      .trim()
      .toLowerCase() === evidence.indexedThroughBlockHash &&
    String(activationTransition.openingNetworkValueQ8 ?? "") ===
      evidence.seedSufficientState.networkValueQ8 &&
    activationTransition.openingStateModel ===
      evidenceSeedCommitment.model &&
    Number(activationTransition.openingStatePayloadBytes) ===
      evidenceSeedCommitment.payloadBytes &&
    String(activationTransition.openingStateSha256 ?? "")
      .trim()
      .toLowerCase() === evidenceSeedCommitment.sha256;
  if (!metadataReady || !markerReady) {
    return null;
  }
  return {
    evidence,
    evidenceSnapshotId: evidence.snapshotId,
    ready: true,
    seed: {
      blockHash: evidence.indexedThroughBlockHash,
      blockHeight: evidence.indexedThroughBlock,
      networkValueQ8: evidence.canonicalSummary.networkValueQ8,
      snapshotId: evidence.canonicalSummary.snapshotId,
      summaryHash: evidence.canonicalSummary.canonicalSummaryHash,
    },
  };
}

export async function proofIndexWorkAmoReplayReadiness(
  network,
  options = {},
) {
  const request = workAmoReplayReadinessRequest(network, options);
  const { checkpointKey, options: requestOptions } = request;
  if (checkpointKey) {
    return exactCheckpointReadinessWithCache({
      checkpointKey,
      inFlight: workAmoReplayReadinessInFlight,
      load: () =>
        proofIndexWorkAmoReplayReadiness(network, {
          ...requestOptions,
          singleFlightBypass: true,
        }),
      options: requestOptions,
      readyCache: workAmoReplayReadinessReadyCache,
    });
  }
  const pool = proofIndexPool();
  if (!pool) {
    return {
      declarationReady: false,
      indexReady: false,
      listingReady: false,
      migrationReady: false,
      positionsReady: false,
      preUnitRelicReady: false,
      quoteReady: false,
      ready: false,
      reasons: ["database-not-configured"],
    };
  }
  const tipResult = await pool.query(
    `
      SELECT height, lower(block_hash) AS block_hash
      FROM proof_indexer.blocks
      WHERE network = $1
        AND canonical = true
      ORDER BY height DESC, block_hash
      LIMIT 2
    `,
    [network],
  );
  const canonicalTip = Number(tipResult.rows[0]?.height ?? 0);
  const canonicalTipBlockHash = String(
    tipResult.rows[0]?.block_hash ?? "",
  )
    .trim()
    .toLowerCase();
  const canonicalTipUnique =
    Number.isSafeInteger(canonicalTip) &&
    canonicalTip > 0 &&
    /^[0-9a-f]{64}$/u.test(canonicalTipBlockHash) &&
    (
      !tipResult.rows[1] ||
      Number(tipResult.rows[1].height) !== canonicalTip
    );
  const requestedThroughHeight =
    Number.isSafeInteger(Number(requestOptions.throughHeight)) &&
    Number(requestOptions.throughHeight) > 0
      ? Number(requestOptions.throughHeight)
      : 0;
  const requestedThroughBlockHash = String(
    requestOptions.throughBlockHash ?? "",
  )
    .trim()
    .toLowerCase();
  const requestedTipReady =
    canonicalTipUnique &&
    requestedThroughHeight === canonicalTip &&
    requestedThroughBlockHash === canonicalTipBlockHash;
  const throughHeight = requestedThroughHeight;
  const [declaration, preUnitRelicEvidence] = await Promise.all([
    proofIndexWorkAmoV5Declaration(network, throughHeight),
    proofIndexWorkAmoV5PreUnitRelicEvidence(network, throughHeight),
  ]);
  const [
    auditResult,
    migrationResult,
    quoteHead,
    replayCheckpointResult,
  ] = await Promise.all([
    pool.query(
      `
        SELECT
          count(*) FILTER (
            WHERE event_row.block_height IS NULL
              OR event_row.block_height < 1
              OR event_row.block_height IS DISTINCT FROM
                event_tx.block_height
              OR event_row.block_index IS NULL
              OR event_row.block_index < 0
              OR event_row.op_return_vout IS NULL
              OR event_row.op_return_vout < 0
              OR event_row.record_ordinal IS NULL
              OR event_row.record_ordinal < 0
              OR event_tx.block_index IS NULL
              OR event_tx.block_index < 0
              OR event_tx.block_index IS DISTINCT FROM event_row.block_index
          )::integer AS missing_positions,
          (
            SELECT count(*)::integer
            FROM (
              SELECT 1
              FROM proof_indexer.events duplicate_event
              JOIN proof_indexer.transactions duplicate_tx
                ON duplicate_tx.network = duplicate_event.network
               AND duplicate_tx.txid = duplicate_event.txid
               AND duplicate_tx.status = 'confirmed'
               AND duplicate_tx.block_height = duplicate_event.block_height
               AND duplicate_tx.block_index = duplicate_event.block_index
              JOIN proof_indexer.blocks duplicate_block
                ON duplicate_block.network = duplicate_tx.network
               AND duplicate_block.block_hash = duplicate_tx.block_hash
               AND duplicate_block.height = duplicate_tx.block_height
               AND duplicate_block.canonical = true
              WHERE duplicate_event.network = $1
                AND duplicate_event.status = 'confirmed'
                AND duplicate_event.protocol = ANY(
                  ARRAY['pwm1','pwa1','pwid1','pwr1','pwt1']::text[]
                )
                AND duplicate_event.block_height BETWEEN $5 AND $3
                AND duplicate_event.block_height >= 1
                AND duplicate_event.block_index >= 0
                AND duplicate_event.op_return_vout >= 0
                AND duplicate_event.record_ordinal >= 0
              GROUP BY
                duplicate_event.block_height,
                duplicate_event.block_index,
                duplicate_event.op_return_vout,
                duplicate_event.record_ordinal
              HAVING count(*) > 1
            ) duplicate_positions
          ) AS duplicate_positions,
          (
            (
              SELECT count(*)::integer
              FROM proof_indexer.credit_listings conflict_listing
              WHERE conflict_listing.network = $1
                AND lower(conflict_listing.token_id) = $4
                AND NULLIF(lower(
                  conflict_listing.payload
                    ->'saleAuthorization'->>'version'
                ), '') IS NOT NULL
                AND NULLIF(lower(
                  conflict_listing.payload
                    ->'listingAuthorization'->>'version'
                ), '') IS NOT NULL
                AND lower(
                  conflict_listing.payload
                    ->'saleAuthorization'->>'version'
                ) <> lower(
                  conflict_listing.payload
                    ->'listingAuthorization'->>'version'
                )
            )
            +
            (
              SELECT count(*)::integer
              FROM proof_indexer.events conflict_event
              JOIN proof_indexer.transactions conflict_tx
                ON conflict_tx.network = conflict_event.network
               AND conflict_tx.txid = conflict_event.txid
               AND conflict_tx.status = 'confirmed'
               AND conflict_tx.block_height = conflict_event.block_height
               AND conflict_tx.block_index = conflict_event.block_index
              JOIN proof_indexer.blocks conflict_block
                ON conflict_block.network = conflict_tx.network
               AND conflict_block.block_hash = conflict_tx.block_hash
               AND conflict_block.height = conflict_tx.block_height
               AND conflict_block.canonical = true
              WHERE conflict_event.network = $1
                AND conflict_event.protocol = 'pwt1'
                AND conflict_event.status = 'confirmed'
                AND conflict_event.block_height BETWEEN $5 AND $3
                AND lower(COALESCE(
                  conflict_event.payload
                    ->'saleAuthorization'->>'tokenId',
                  conflict_event.payload
                    ->'listingAuthorization'->>'tokenId',
                  conflict_event.payload->>'tokenId',
                  ''
                )) = $4
                AND NULLIF(lower(
                  conflict_event.payload
                    ->'saleAuthorization'->>'version'
                ), '') IS NOT NULL
                AND NULLIF(lower(
                  conflict_event.payload
                    ->'listingAuthorization'->>'version'
                ), '') IS NOT NULL
                AND lower(
                  conflict_event.payload
                    ->'saleAuthorization'->>'version'
                ) <> lower(
                  conflict_event.payload
                    ->'listingAuthorization'->>'version'
                )
            )
          ) AS authorization_conflicts,
          (
            SELECT count(*)::integer
            FROM proof_indexer.credit_listings listing
            JOIN proof_indexer.transactions listing_tx
              ON listing_tx.network = listing.network
             AND listing_tx.txid = listing.listing_id
             AND listing_tx.status = 'confirmed'
            JOIN proof_indexer.blocks listing_block
              ON listing_block.network = listing_tx.network
             AND listing_block.block_hash = listing_tx.block_hash
             AND listing_block.height = listing_tx.block_height
             AND listing_block.canonical = true
            WHERE listing.network = $1
              AND lower(listing.token_id) = $4
              AND listing.status IN ('active', 'sealing')
              AND 'pwt-sale-v3' = ANY(ARRAY[
                lower(COALESCE(
                  listing.payload->'saleAuthorization'->>'version',
                  ''
                )),
                lower(COALESCE(
                  listing.payload->'listingAuthorization'->>'version',
                  ''
                ))
              ]::text[])
              AND listing_tx.block_height >= $5
          ) AS post_v1_v3_active,
          (
            SELECT count(*)::integer
            FROM proof_indexer.credit_listings listing
            JOIN proof_indexer.transactions listing_tx
              ON listing_tx.network = listing.network
             AND listing_tx.txid = listing.listing_id
             AND listing_tx.status = 'confirmed'
            JOIN proof_indexer.blocks listing_block
              ON listing_block.network = listing_tx.network
             AND listing_block.block_hash = listing_tx.block_hash
             AND listing_block.height = listing_tx.block_height
             AND listing_block.canonical = true
            WHERE listing.network = $1
              AND lower(listing.token_id) = $4
              AND listing.status IN ('active', 'sealing')
              AND $6 = ANY(ARRAY[
                lower(COALESCE(
                  listing.payload->'saleAuthorization'->>'version',
                  ''
                )),
                lower(COALESCE(
                  listing.payload->'listingAuthorization'->>'version',
                  ''
                ))
              ]::text[])
              AND listing_tx.block_height >= $2
          ) AS post_activation_v4_active,
          (
            SELECT count(*)::integer
            FROM proof_indexer.events post_v5_v4_event
            JOIN proof_indexer.transactions post_v5_v4_tx
              ON post_v5_v4_tx.network = post_v5_v4_event.network
             AND post_v5_v4_tx.txid = post_v5_v4_event.txid
             AND post_v5_v4_tx.status = 'confirmed'
             AND post_v5_v4_tx.block_height =
               post_v5_v4_event.block_height
             AND post_v5_v4_tx.block_index = post_v5_v4_event.block_index
            JOIN proof_indexer.blocks post_v5_v4_block
              ON post_v5_v4_block.network = post_v5_v4_tx.network
             AND post_v5_v4_block.block_hash = post_v5_v4_tx.block_hash
             AND post_v5_v4_block.height = post_v5_v4_tx.block_height
             AND post_v5_v4_block.canonical = true
            WHERE post_v5_v4_event.network = $1
              AND post_v5_v4_event.protocol = 'pwt1'
              AND post_v5_v4_event.status = 'confirmed'
              AND post_v5_v4_event.valid = true
              AND post_v5_v4_event.block_height >= $2
              AND post_v5_v4_event.kind IN (
                'token-listing',
                'token-listing-sealed',
                'token-sale',
                'token-listing-closed'
              )
              AND lower(COALESCE(
                post_v5_v4_event.payload
                  ->'saleAuthorization'->>'tokenId',
                post_v5_v4_event.payload
                  ->'listingAuthorization'->>'tokenId',
                post_v5_v4_event.payload->>'tokenId',
                ''
              )) = $4
              AND $6 = ANY(ARRAY[
                lower(COALESCE(
                  post_v5_v4_event.payload
                    ->'saleAuthorization'->>'version',
                  ''
                )),
                lower(COALESCE(
                  post_v5_v4_event.payload
                    ->'listingAuthorization'->>'version',
                  ''
                ))
              ]::text[])
          ) AS post_activation_v4_actions,
          (
            SELECT count(*)::integer
            FROM proof_indexer.events historical_v4_event
            JOIN proof_indexer.transactions historical_v4_tx
              ON historical_v4_tx.network = historical_v4_event.network
             AND historical_v4_tx.txid = historical_v4_event.txid
             AND historical_v4_tx.status = 'confirmed'
             AND historical_v4_tx.block_height =
               historical_v4_event.block_height
             AND historical_v4_tx.block_index =
               historical_v4_event.block_index
            JOIN proof_indexer.blocks historical_v4_block
              ON historical_v4_block.network = historical_v4_tx.network
             AND historical_v4_block.block_hash =
               historical_v4_tx.block_hash
             AND historical_v4_block.height =
               historical_v4_tx.block_height
             AND historical_v4_block.canonical = true
            WHERE historical_v4_event.network = $1
              AND historical_v4_event.protocol = 'pwt1'
              AND historical_v4_event.status = 'confirmed'
              AND historical_v4_event.block_height >= $5
              AND historical_v4_event.block_height < $2
              AND lower(COALESCE(
                historical_v4_event.payload
                  ->'saleAuthorization'->>'tokenId',
                historical_v4_event.payload->>'tokenId',
                ''
              )) = $4
              AND $6 = ANY(ARRAY[
                lower(COALESCE(
                  historical_v4_event.payload
                    ->'saleAuthorization'->>'version',
                  ''
                )),
                lower(COALESCE(
                  historical_v4_event.payload
                    ->'listingAuthorization'->>'version',
                  ''
                ))
              ]::text[])
              AND (
                historical_v4_event.kind IN (
                  'token-listing',
                  'token-listing-sealed',
                  'token-sale',
                  'token-listing-closed'
                )
                OR (
                  historical_v4_event.kind = 'token-event-invalid'
                  AND lower(COALESCE(
                    historical_v4_event.payload->>'attemptedKind',
                    ''
                  )) IN (
                    'list',
                    'seal',
                    'buy',
                    'delist',
                    'token-listing',
                    'token-listing-sealed',
                    'token-sale',
                    'token-listing-closed'
                  )
                )
              )
          ) AS pre_activation_v4_actions,
          (
            SELECT count(*)::integer
            FROM proof_indexer.events listing_event
            JOIN proof_indexer.transactions listing_tx
              ON listing_tx.network = listing_event.network
             AND listing_tx.txid = listing_event.txid
             AND listing_tx.status = 'confirmed'
             AND listing_tx.block_height = listing_event.block_height
             AND listing_tx.block_index = listing_event.block_index
            JOIN proof_indexer.blocks listing_block
              ON listing_block.network = listing_tx.network
             AND listing_block.block_hash = listing_tx.block_hash
             AND listing_block.height = listing_tx.block_height
             AND listing_block.canonical = true
            LEFT JOIN proof_indexer.work_amo_listing_terms terms
              ON terms.network = listing_event.network
             AND terms.listing_id = listing_event.txid
             AND terms.listing_txid = listing_event.txid
             AND terms.listing_block_height = listing_event.block_height
             AND terms.listing_block_index = listing_event.block_index
             AND terms.listing_protocol_vout =
               listing_event.op_return_vout
             AND terms.listing_record_ordinal =
               listing_event.record_ordinal
             AND lower(terms.listing_block_hash) =
               lower(listing_tx.block_hash)
            WHERE listing_event.network = $1
              AND listing_event.protocol = 'pwt1'
              AND listing_event.status = 'confirmed'
              AND listing_event.valid = true
              AND listing_event.kind = 'token-listing'
              AND $7 = ANY(ARRAY[
                lower(COALESCE(
                  listing_event.payload
                    ->'saleAuthorization'->>'version',
                  ''
                )),
                lower(COALESCE(
                  listing_event.payload
                    ->'listingAuthorization'->>'version',
                  ''
                ))
              ]::text[])
              AND listing_event.block_height BETWEEN $2 AND $3
              AND terms.listing_id IS NULL
          ) AS missing_frozen_terms
        FROM proof_indexer.events event_row
        JOIN proof_indexer.transactions event_tx
          ON event_tx.network = event_row.network
         AND event_tx.txid = event_row.txid
        JOIN proof_indexer.blocks event_block
          ON event_block.network = event_tx.network
         AND event_block.block_hash = event_tx.block_hash
         AND event_block.height = event_tx.block_height
         AND event_block.canonical = true
        WHERE event_row.network = $1
          AND event_row.status = 'confirmed'
          AND event_tx.status = 'confirmed'
          AND event_row.protocol = ANY(
            ARRAY['pwm1','pwa1','pwid1','pwr1','pwt1']::text[]
          )
          AND event_tx.block_height BETWEEN $5 AND $3
      `,
      [
        network,
        WORK_AMO_V5_ACTIVATION_HEIGHT,
        Math.max(WORK_AMO_V1_ACTIVATION_HEIGHT, throughHeight),
        WORK_TOKEN_ID,
        WORK_AMO_V1_ACTIVATION_HEIGHT,
        WORK_MARKET_V4_AUTH_VERSION,
        WORK_AMO_V5_AUTH_VERSION,
      ],
    ),
    pool.query(
      `
        SELECT value
        FROM proof_indexer.meta
        WHERE key = $1
        LIMIT 1
      `,
      [`workAmoV5Migration:${network}`],
    ),
    proofIndexWorkUsdQuoteHead(network),
    pool.query(
      `
        SELECT
          (
            SELECT value
            FROM proof_indexer.meta
            WHERE key = 'canonical:rebuild'
            LIMIT 1
          ) AS rebuild,
          (
            SELECT jsonb_build_object(
              'rowCount', count(*),
              'rows', COALESCE(
                jsonb_agg(
                  jsonb_build_object(
                    'consistency', seed_evidence.consistency,
                    'indexedThroughBlock',
                      seed_evidence.indexed_through_block,
                    'metrics', seed_evidence.metrics,
                    'payload', seed_evidence.payload,
                    'snapshotId', seed_evidence.snapshot_id,
                    'sourceHashes', seed_evidence.source_hashes
                  )
                  ORDER BY seed_evidence.snapshot_id
                ),
                '[]'::jsonb
              )
            )
            FROM proof_indexer.ledger_snapshots seed_evidence
            WHERE seed_evidence.network = $1
              AND seed_evidence.payload->>'model' =
                'canonical-work-amo-v5-h-minus-one-seed-evidence-v1'
              AND seed_evidence.payload->>'model' = $12
          ) AS seed_evidence_set,
          EXISTS (
            SELECT 1
            FROM proof_indexer.blocks seed_block
            WHERE seed_block.network = $1
              AND seed_block.height = $2
              AND lower(seed_block.block_hash) = $6
              AND seed_block.canonical = true
          ) AS seed_block_exact,
          (
            SELECT jsonb_build_object(
              'blockHash', lower(closing_block.block_hash),
              'blockHeight', closing_block.height,
              'networkValueQ8',
                closing_snapshot.payload->'totals'->>'workNetworkValueQ8',
              'snapshotId', closing_snapshot.snapshot_id,
              'summaryHash',
                lower(closing_snapshot.source_hashes->>'canonicalSummary')
            )
            FROM proof_indexer.blocks closing_block
            JOIN proof_indexer.ledger_snapshots closing_snapshot
              ON closing_snapshot.network = closing_block.network
             AND closing_snapshot.indexed_through_block =
               closing_block.height
             AND lower(
               closing_snapshot.payload->>'indexedThroughBlockHash'
             ) = lower(closing_block.block_hash)
             AND lower(closing_snapshot.source_hashes->>'blockScan') =
               lower(closing_block.block_hash)
             AND closing_snapshot.source_hashes ? 'canonicalSummary'
             AND closing_snapshot.payload ? 'summaryPayloads'
             AND closing_snapshot.consistency->>'ok' = 'true'
             AND closing_snapshot.payload->>'ok' = 'true'
             AND closing_snapshot.payload->>'status' = 'green'
             AND closing_snapshot.payload->'totals'
               ->>'workNetworkValueQ8' ~ '^[1-9][0-9]*$'
             AND closing_snapshot.source_hashes
               ->>'canonicalSummary' ~ '^[0-9a-fA-F]{64}$'
            WHERE closing_block.network = $1
              AND closing_block.canonical = true
              AND closing_block.height = $3
              AND lower(closing_block.block_hash) = $4
            ORDER BY closing_snapshot.generated_at DESC
            LIMIT 1
          ) AS closing,
          EXISTS (
            SELECT 1
            FROM proof_indexer.ledger_snapshots scan
            WHERE scan.network = $1
              AND scan.indexed_through_block = $3
              AND NOT COALESCE(
                scan.source_hashes ? 'canonicalSummary',
                false
              )
              AND (
                COALESCE(scan.source_hashes ? 'blockScan', false)
                OR scan.payload->>'source' =
                  'proof-indexer-block-scan'
              )
              AND lower(COALESCE(
                NULLIF(scan.payload->>'indexedThroughBlockHash', ''),
                NULLIF(scan.payload->>'blockHash', ''),
                NULLIF(scan.source_hashes->>'blockScan', '')
              )) = $4
              AND scan.payload->>'complete' = 'true'
          ) AS block_scan_complete,
          (
            SELECT jsonb_build_object(
              'blockHash', lower(activation.block_hash),
              'blockHeight', activation.block_height,
              'openingNetworkValueQ8',
                activation.opening_network_value_q8::text,
              'openingStateModel',
                activation.state_commitment_model,
              'openingStatePayloadBytes',
                activation.opening_state_payload_bytes,
              'openingStateSha256',
                lower(activation.opening_state_sha256),
              'previousBlockHash',
                lower(activation.previous_block_hash)
            )
            FROM proof_indexer.work_amo_block_transitions activation
            JOIN proof_indexer.blocks activation_block
              ON activation_block.network = activation.network
             AND activation_block.block_hash = activation.block_hash
             AND activation_block.height = activation.block_height
             AND activation_block.previous_block_hash =
               activation.previous_block_hash
             AND activation_block.canonical = true
            WHERE activation.network = $1
              AND activation.block_height = $5
              AND activation.model = $7
            LIMIT 1
          ) AS activation_transition,
          (
            SELECT jsonb_build_object(
              'blockCount', count(*),
              'maximumHeight', max(transition.block_height),
              'minimumHeight', min(transition.block_height),
              'allComplete', bool_and(
                transition.complete
                AND transition.block_atomic
                AND transition.fee_once
                AND transition.invalid_zero
              ),
              'allContinuous', bool_and(
                CASE
                  WHEN transition.block_height = $5
                    THEN transition.previous_block_hash = $6
                  ELSE
                    transition.previous_block_hash =
                      transition.prior_block_hash
                    AND transition.opening_state_sha256 =
                      transition.prior_closing_state_sha256
                END
              )
            )
            FROM (
              SELECT
                stored_transition.*,
                lag(stored_transition.block_hash) OVER (
                  ORDER BY stored_transition.block_height
                ) AS prior_block_hash,
                lag(stored_transition.closing_state_sha256) OVER (
                  ORDER BY stored_transition.block_height
                ) AS prior_closing_state_sha256
              FROM proof_indexer.work_amo_block_transitions
                stored_transition
              JOIN proof_indexer.blocks transition_block
                ON transition_block.network = stored_transition.network
               AND transition_block.block_hash =
                 stored_transition.block_hash
               AND transition_block.height =
                 stored_transition.block_height
               AND transition_block.previous_block_hash =
                 stored_transition.previous_block_hash
               AND transition_block.canonical = true
              WHERE stored_transition.network = $1
                AND stored_transition.block_height BETWEEN $5 AND $3
                AND stored_transition.model =
                  'canonical-work-amo-full-position-block-sequencer-v2'
                AND stored_transition.model = $7
                AND stored_transition.payload
                  ->>'transitionChainModel' =
                    'canonical-work-amo-raw-transition-chain-sha256-v1'
                AND stored_transition.payload
                  ->>'transitionChainModel' = $8
                AND stored_transition.payload
                  ->'transitionChainCommitment'->>'model' =
                    'canonical-work-amo-raw-transition-chain-sha256-v1'
                AND stored_transition.payload
                  ->'transitionChainCommitment'->>'model' = $8
                AND stored_transition.payload
                  ->'transitionChainCommitment'->>'sha256' ~
                    '^[0-9a-f]{64}$'
                AND stored_transition.payload
                  ->'transitionChainCommitment'->>'payloadBytes' ~
                    '^[1-9][0-9]*$'
                AND stored_transition.payload
                  ->>'blockDescriptorModel' =
                    'canonical-work-amo-raw-full-block-descriptor-v1'
                AND stored_transition.payload
                  ->>'blockDescriptorModel' = $9
                AND stored_transition.payload
                  ->'blockDescriptorCommitment'->>'model' =
                    'canonical-work-amo-payload-sha256-v1'
                AND stored_transition.payload
                  ->'blockDescriptorCommitment'->>'model' = $10
                AND stored_transition.payload
                  ->'blockDescriptorCommitment'->>'sha256' ~
                    '^[0-9a-f]{64}$'
                AND stored_transition.payload
                  ->'blockDescriptorCommitment'->>'payloadBytes' ~
                    '^[1-9][0-9]*$'
                AND stored_transition.payload
                  ->>'blockTransactionCount' ~ '^[1-9][0-9]*$'
                AND stored_transition.payload
                  ->'bip141Witness'->>'model' =
                    'canonical-work-amo-raw-bip141-witness-v1'
                AND stored_transition.payload
                  ->'bip141Witness'->>'model' = $11
                AND (
                  (
                    stored_transition.payload
                      ->'bip141Witness'->>'required' = 'false'
                    AND stored_transition.payload
                      ->'bip141Witness'
                      ->>'witnessTransactionCount' = '0'
                    AND stored_transition.payload
                      ->'bip141Witness'->>'commitmentSha256' = ''
                    AND stored_transition.payload
                      ->'bip141Witness'
                      ->>'witnessMerkleRootInternalHex' = ''
                    AND stored_transition.payload
                      ->'bip141Witness'->>'commitmentVout' IS NULL
                    AND NOT (
                      stored_transition.payload->'bip141Witness'
                        ? 'commitmentScriptPubKeyHex'
                    )
                    AND NOT (
                      stored_transition.payload->'bip141Witness'
                        ? 'coinbaseWitnessReservedValueHex'
                    )
                  )
                  OR
                  (
                    stored_transition.payload
                      ->'bip141Witness'->>'required' = 'true'
                    AND stored_transition.payload
                      ->'bip141Witness'
                      ->>'witnessTransactionCount' ~
                        '^[1-9][0-9]*$'
                    AND stored_transition.payload
                      ->'bip141Witness'->>'commitmentVout' ~
                        '^(?:0|[1-9][0-9]*)$'
                    AND stored_transition.payload
                      ->'bip141Witness'->>'commitmentSha256' ~
                        '^[0-9a-f]{64}$'
                    AND stored_transition.payload
                      ->'bip141Witness'
                      ->>'witnessMerkleRootInternalHex' ~
                        '^[0-9a-f]{64}$'
                    AND stored_transition.payload
                      ->'bip141Witness'
                      ->>'coinbaseWitnessReservedValueHex' ~
                        '^[0-9a-f]{64}$'
                    AND stored_transition.payload
                      ->'bip141Witness'
                      ->>'commitmentScriptPubKeyHex' ~
                        '^6a24aa21a9ed[0-9a-f]+$'
                    AND length(
                      stored_transition.payload
                        ->'bip141Witness'
                        ->>'commitmentScriptPubKeyHex'
                    ) % 2 = 0
                    AND substring(
                      stored_transition.payload
                        ->'bip141Witness'
                        ->>'commitmentScriptPubKeyHex'
                      FROM 13 FOR 64
                    ) = stored_transition.payload
                      ->'bip141Witness'->>'commitmentSha256'
                  )
                )
            ) transition
          ) AS transitions,
          (
            SELECT jsonb_build_object(
              'blockHash', transition.block_hash,
              'blockHeight', transition.block_height,
              'closingNetworkValueQ8',
                transition.closing_network_value_q8::text,
              'closingStateSha256', transition.closing_state_sha256,
              'closingTokenStateCommitment',
                transition.payload
                  ->'closingSufficientState'
                  ->'tokenStateCommitment',
              'eventSetSha256', transition.event_set_sha256,
              'blockDescriptorCommitment',
                transition.payload->'blockDescriptorCommitment',
              'blockDescriptorModel',
                transition.payload->>'blockDescriptorModel',
              'blockTransactionCount',
                transition.payload->>'blockTransactionCount',
              'bip141Witness',
                transition.payload->'bip141Witness',
              'transitionChainCommitment',
                transition.payload->'transitionChainCommitment',
              'transitionChainModel',
                transition.payload->>'transitionChainModel'
            )
            FROM proof_indexer.work_amo_block_transitions transition
            JOIN proof_indexer.blocks transition_block
              ON transition_block.network = transition.network
             AND transition_block.block_hash = transition.block_hash
             AND transition_block.height = transition.block_height
             AND transition_block.canonical = true
            WHERE transition.network = $1
              AND transition.block_height = $3
              AND transition.block_hash = $4
              AND transition.model = $7
              AND transition.payload->>'transitionChainModel' = $8
              AND transition.payload
                ->'transitionChainCommitment'->>'model' = $8
              AND transition.payload
                ->'transitionChainCommitment'->>'sha256' ~
                  '^[0-9a-f]{64}$'
              AND transition.payload
                ->'transitionChainCommitment'->>'payloadBytes' ~
                  '^[1-9][0-9]*$'
              AND transition.payload->>'blockDescriptorModel' = $9
              AND transition.payload
                ->'blockDescriptorCommitment'->>'model' = $10
              AND transition.payload
                ->'blockDescriptorCommitment'->>'sha256' ~
                  '^[0-9a-f]{64}$'
              AND transition.payload
                ->'blockDescriptorCommitment'->>'payloadBytes' ~
                  '^[1-9][0-9]*$'
              AND transition.payload->>'blockTransactionCount' ~
                  '^[1-9][0-9]*$'
              AND transition.payload
                ->'bip141Witness'->>'model' = $11
              AND (
                (
                  transition.payload
                    ->'bip141Witness'->>'required' = 'false'
                  AND transition.payload
                    ->'bip141Witness'
                    ->>'witnessTransactionCount' = '0'
                  AND transition.payload
                    ->'bip141Witness'->>'commitmentSha256' = ''
                  AND transition.payload
                    ->'bip141Witness'
                    ->>'witnessMerkleRootInternalHex' = ''
                  AND transition.payload
                    ->'bip141Witness'->>'commitmentVout' IS NULL
                  AND NOT (
                    transition.payload->'bip141Witness'
                      ? 'commitmentScriptPubKeyHex'
                  )
                  AND NOT (
                    transition.payload->'bip141Witness'
                      ? 'coinbaseWitnessReservedValueHex'
                  )
                )
                OR
                (
                  transition.payload
                    ->'bip141Witness'->>'required' = 'true'
                  AND transition.payload
                    ->'bip141Witness'
                    ->>'witnessTransactionCount' ~
                      '^[1-9][0-9]*$'
                  AND transition.payload
                    ->'bip141Witness'->>'commitmentVout' ~
                      '^(?:0|[1-9][0-9]*)$'
                  AND transition.payload
                    ->'bip141Witness'->>'commitmentSha256' ~
                      '^[0-9a-f]{64}$'
                  AND transition.payload
                    ->'bip141Witness'
                    ->>'witnessMerkleRootInternalHex' ~
                      '^[0-9a-f]{64}$'
                  AND transition.payload
                    ->'bip141Witness'
                    ->>'coinbaseWitnessReservedValueHex' ~
                      '^[0-9a-f]{64}$'
                  AND transition.payload
                    ->'bip141Witness'
                    ->>'commitmentScriptPubKeyHex' ~
                      '^6a24aa21a9ed[0-9a-f]+$'
                  AND length(
                    transition.payload
                      ->'bip141Witness'
                      ->>'commitmentScriptPubKeyHex'
                  ) % 2 = 0
                  AND substring(
                    transition.payload
                      ->'bip141Witness'
                      ->>'commitmentScriptPubKeyHex'
                    FROM 13 FOR 64
                  ) = transition.payload
                    ->'bip141Witness'->>'commitmentSha256'
                )
              )
            LIMIT 1
          ) AS transition_tip
      `,
      [
        network,
        WORK_AMO_V5_ACTIVATION_HEIGHT - 1,
        canonicalTip,
        canonicalTipBlockHash,
        WORK_AMO_V5_ACTIVATION_HEIGHT,
        WORK_AMO_V5_DECLARATION_BLOCK_HASH,
        WORK_AMO_V5_BLOCK_SEQUENCER_MODEL,
        WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL,
        WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL,
        WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL,
        WORK_AMO_V5_RAW_BIP141_WITNESS_MODEL,
        WORK_AMO_V5_H_MINUS_ONE_SEED_EVIDENCE_MODEL,
      ],
    ),
  ]);
  const audit = auditResult.rows[0] ?? {};
  const migration =
    migrationResult.rows[0]?.value &&
    typeof migrationResult.rows[0].value === "object"
      ? migrationResult.rows[0].value
      : {};
  const replayCheckpoint = replayCheckpointResult.rows[0] ?? {};
  const rebuild =
    replayCheckpoint.rebuild &&
    typeof replayCheckpoint.rebuild === "object" &&
    !Array.isArray(replayCheckpoint.rebuild)
      ? replayCheckpoint.rebuild
      : {};
  const replayEvidence =
    migration.replayEvidence &&
    typeof migration.replayEvidence === "object" &&
    !Array.isArray(migration.replayEvidence)
      ? migration.replayEvidence
      : {};
  const bootstrapCertificate =
    migration.bootstrapCertificate &&
    typeof migration.bootstrapCertificate === "object" &&
    !Array.isArray(migration.bootstrapCertificate)
      ? migration.bootstrapCertificate
      : {};
  const markerIndependentSeed =
    replayEvidence.independentSeed &&
    typeof replayEvidence.independentSeed === "object" &&
    !Array.isArray(replayEvidence.independentSeed)
      ? replayEvidence.independentSeed
      : {};
  const markerTransitionReplay =
    replayEvidence.transitionReplay &&
    typeof replayEvidence.transitionReplay === "object" &&
    !Array.isArray(replayEvidence.transitionReplay)
      ? replayEvidence.transitionReplay
      : {};
  const markerSeed =
    replayEvidence.seed &&
    typeof replayEvidence.seed === "object" &&
    !Array.isArray(replayEvidence.seed)
      ? replayEvidence.seed
      : {};
  const markerClosing =
    replayEvidence.closing &&
    typeof replayEvidence.closing === "object" &&
    !Array.isArray(replayEvidence.closing)
      ? replayEvidence.closing
      : {};
  const currentSeedReadiness =
    proofIndexWorkAmoSeedEvidenceReadiness(
      replayCheckpoint.seed_evidence_set,
      replayCheckpoint.seed_block_exact,
      markerSeed,
      {
        activationTransition:
          replayCheckpoint.activation_transition,
        bootstrapSeedCommitment:
          bootstrapCertificate.seedCommitment,
        firstOpeningCommitment:
          markerTransitionReplay.firstOpeningCommitment,
        independentSeed: markerIndependentSeed,
      },
    );
  const currentSeed = currentSeedReadiness?.seed ?? {};
  const currentClosing =
    replayCheckpoint.closing &&
    typeof replayCheckpoint.closing === "object" &&
    !Array.isArray(replayCheckpoint.closing)
      ? replayCheckpoint.closing
      : {};
  const currentTransitions =
    replayCheckpoint.transitions &&
    typeof replayCheckpoint.transitions === "object" &&
    !Array.isArray(replayCheckpoint.transitions)
      ? replayCheckpoint.transitions
      : {};
  const currentTransitionTip =
    replayCheckpoint.transition_tip &&
    typeof replayCheckpoint.transition_tip === "object" &&
    !Array.isArray(replayCheckpoint.transition_tip)
      ? replayCheckpoint.transition_tip
      : {};
  const bootstrapHeight = Number(bootstrapCertificate.throughHeight);
  const bootstrapBlockHash = String(
    bootstrapCertificate.throughBlockHash ?? "",
  )
    .trim()
    .toLowerCase();
  const bootstrapTransition =
    Number.isSafeInteger(bootstrapHeight) &&
    bootstrapHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT &&
    bootstrapHeight <= canonicalTip &&
    /^[0-9a-f]{64}$/u.test(bootstrapBlockHash)
      ? await proofIndexWorkAmoBlockTransition(
          network,
          bootstrapHeight,
          bootstrapBlockHash,
        )
      : null;
  const relationalTokenState =
    await proofIndexWorkAmoRelationalTokenStateEvidence(
      network,
      currentTransitionTip.closingTokenStateCommitment ?? {},
    );
  const markerRelationalTokenState =
    replayEvidence.relationalTokenState &&
    typeof replayEvidence.relationalTokenState === "object" &&
    !Array.isArray(replayEvidence.relationalTokenState)
      ? replayEvidence.relationalTokenState
      : {};
  const markerFinalTipCommitment =
    bootstrapCertificate.finalTipCommitment &&
    typeof bootstrapCertificate.finalTipCommitment === "object"
      ? bootstrapCertificate.finalTipCommitment
      : {};
  const markerFinalTransitionChainCommitment =
    bootstrapCertificate.finalTransitionChainCommitment &&
    typeof bootstrapCertificate.finalTransitionChainCommitment === "object"
      ? bootstrapCertificate.finalTransitionChainCommitment
      : {};
  const markerFinalBlockDescriptorCommitment =
    bootstrapCertificate.finalBlockDescriptorCommitment &&
    typeof bootstrapCertificate.finalBlockDescriptorCommitment === "object"
      ? bootstrapCertificate.finalBlockDescriptorCommitment
      : {};
  const currentTipBlockDescriptorCommitment =
    currentTransitionTip.blockDescriptorCommitment &&
    typeof currentTransitionTip.blockDescriptorCommitment === "object"
      ? currentTransitionTip.blockDescriptorCommitment
      : {};
  const currentTipTransitionChainCommitment =
    currentTransitionTip.transitionChainCommitment &&
    typeof currentTransitionTip.transitionChainCommitment === "object"
      ? currentTransitionTip.transitionChainCommitment
      : {};
  const markerFinalBip141Witness =
    normalizedWorkAmoV5Bip141Witness(
      bootstrapCertificate.finalBip141Witness,
      Number(bootstrapCertificate.finalBlockTransactionCount),
    );
  const replayFinalBip141Witness =
    normalizedWorkAmoV5Bip141Witness(
      replayEvidence.transitionReplay?.finalBip141Witness,
      Number(
        replayEvidence.transitionReplay?.finalBlockTransactionCount,
      ),
    );
  const bootstrapBip141Witness =
    normalizedWorkAmoV5Bip141Witness(
      bootstrapTransition?.payload?.bip141Witness,
      Number(bootstrapTransition?.payload?.blockTransactionCount),
    );
  const currentTipBip141Witness =
    normalizedWorkAmoV5Bip141Witness(
      currentTransitionTip.bip141Witness,
      Number(currentTransitionTip.blockTransactionCount),
    );
  const expectedTransitionBlockCount =
    canonicalTip - WORK_AMO_V5_ACTIVATION_HEIGHT + 1;
  const reasons = [];
  const declarationReady = declaration?.active === true;
  const positionsReady =
    Number(audit.missing_positions ?? 0) === 0 &&
    Number(audit.duplicate_positions ?? 0) === 0;
  const migrationReady =
    requestedTipReady &&
    migration.status === "complete" &&
    migration.model === "canonical-work-amo-v5-migration-v2" &&
    migration.declarationTxid === WORK_AMO_V5_DECLARATION_TXID &&
    Number(migration.activationHeight) === WORK_AMO_V5_ACTIVATION_HEIGHT &&
    Number(migration.replayFromHeight) === WORK_AMO_V5_ACTIVATION_HEIGHT &&
    replayEvidence.complete === true &&
    replayEvidence.endTipParity === true &&
    replayEvidence.blockAtomic === true &&
    replayEvidence.transitionReplay?.complete === true &&
    replayEvidence.transitionReplay?.endTipParity === true &&
    replayEvidence.transitionReplay?.blockAtomic === true &&
    replayEvidence.transitionReplay?.blockDescriptorModel ===
      WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL &&
    bootstrapCertificate.blockDescriptorModel ===
      WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL &&
    replayEvidence.transitionReplay?.transitionChainModel ===
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL &&
    bootstrapCertificate.transitionChainModel ===
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL &&
    markerRelationalTokenState.complete === true &&
    relationalTokenState.complete === true &&
    bootstrapTransition !== null &&
    Number(replayEvidence.throughHeight) === bootstrapHeight &&
    String(replayEvidence.throughBlockHash ?? "").trim().toLowerCase() ===
      bootstrapBlockHash &&
    Number(markerClosing.blockHeight) === bootstrapHeight &&
    String(markerClosing.blockHash ?? "").trim().toLowerCase() ===
      bootstrapBlockHash &&
    String(bootstrapTransition.closing_state_sha256 ?? "")
      .trim()
      .toLowerCase() ===
      String(markerFinalTipCommitment.sha256 ?? "").trim().toLowerCase() &&
    Number(bootstrapTransition.closing_state_payload_bytes) ===
      Number(markerFinalTipCommitment.payloadBytes) &&
    markerFinalBlockDescriptorCommitment.model ===
      WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL &&
    Number.isSafeInteger(
      Number(markerFinalBlockDescriptorCommitment.payloadBytes),
    ) &&
    Number(markerFinalBlockDescriptorCommitment.payloadBytes) > 0 &&
    /^[0-9a-f]{64}$/u.test(
      String(markerFinalBlockDescriptorCommitment.sha256 ?? "")
        .trim()
        .toLowerCase(),
    ) &&
    String(
      bootstrapTransition.payload?.blockDescriptorCommitment?.sha256 ?? "",
    )
      .trim()
      .toLowerCase() ===
      String(markerFinalBlockDescriptorCommitment.sha256 ?? "")
        .trim()
        .toLowerCase() &&
    Number(
      bootstrapTransition.payload?.blockDescriptorCommitment?.payloadBytes,
    ) === Number(markerFinalBlockDescriptorCommitment.payloadBytes) &&
    Number(bootstrapTransition.payload?.blockTransactionCount) ===
      Number(bootstrapCertificate.finalBlockTransactionCount) &&
    Number(
      replayEvidence.transitionReplay?.finalBlockTransactionCount,
    ) === Number(bootstrapCertificate.finalBlockTransactionCount) &&
    Boolean(markerFinalBip141Witness) &&
    Boolean(replayFinalBip141Witness) &&
    Boolean(bootstrapBip141Witness) &&
    workAmoV5Bip141WitnessesEqual(
      markerFinalBip141Witness,
      replayFinalBip141Witness,
      Number(bootstrapCertificate.finalBlockTransactionCount),
    ) &&
    workAmoV5Bip141WitnessesEqual(
      markerFinalBip141Witness,
      bootstrapBip141Witness,
      Number(bootstrapCertificate.finalBlockTransactionCount),
    ) &&
    markerFinalTransitionChainCommitment.model ===
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL &&
    Number.isSafeInteger(
      Number(markerFinalTransitionChainCommitment.payloadBytes),
    ) &&
    Number(markerFinalTransitionChainCommitment.payloadBytes) > 0 &&
    /^[0-9a-f]{64}$/u.test(
      String(markerFinalTransitionChainCommitment.sha256 ?? "")
        .trim()
        .toLowerCase(),
    ) &&
    String(
      bootstrapTransition.payload?.transitionChainCommitment?.sha256 ?? "",
    )
      .trim()
      .toLowerCase() ===
      String(markerFinalTransitionChainCommitment.sha256 ?? "")
        .trim()
        .toLowerCase() &&
    Number(
      bootstrapTransition.payload?.transitionChainCommitment?.payloadBytes,
    ) === Number(markerFinalTransitionChainCommitment.payloadBytes) &&
    currentSeedReadiness?.ready === true &&
    Number(markerSeed.blockHeight) ===
      WORK_AMO_V5_ACTIVATION_HEIGHT - 1 &&
    String(markerSeed.blockHash ?? "").trim().toLowerCase() ===
      String(currentSeed.blockHash ?? "").trim().toLowerCase() &&
    String(markerSeed.networkValueQ8 ?? "") ===
      String(currentSeed.networkValueQ8 ?? "") &&
    String(markerSeed.summaryHash ?? "").trim().toLowerCase() ===
      String(currentSeed.summaryHash ?? "").trim().toLowerCase() &&
    Number(currentClosing.blockHeight) === canonicalTip &&
    String(currentClosing.blockHash ?? "").trim().toLowerCase() ===
      canonicalTipBlockHash &&
    expectedTransitionBlockCount > 0 &&
    Number(currentTransitions.blockCount) === expectedTransitionBlockCount &&
    Number(currentTransitions.minimumHeight) ===
      WORK_AMO_V5_ACTIVATION_HEIGHT &&
    Number(currentTransitions.maximumHeight) === canonicalTip &&
    currentTransitions.allComplete === true &&
    currentTransitions.allContinuous === true &&
    Number(currentTransitionTip.blockHeight) === canonicalTip &&
    String(currentTransitionTip.blockHash ?? "").trim().toLowerCase() ===
      canonicalTipBlockHash &&
    currentTransitionTip.transitionChainModel ===
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL &&
    currentTransitionTip.blockDescriptorModel ===
      WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL &&
    currentTipBlockDescriptorCommitment.model ===
      WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL &&
    Number.isSafeInteger(
      Number(currentTipBlockDescriptorCommitment.payloadBytes),
    ) &&
    Number(currentTipBlockDescriptorCommitment.payloadBytes) > 0 &&
    /^[0-9a-f]{64}$/u.test(
      String(currentTipBlockDescriptorCommitment.sha256 ?? "")
        .trim()
        .toLowerCase(),
    ) &&
    Number.isSafeInteger(
      Number(currentTransitionTip.blockTransactionCount),
    ) &&
    Number(currentTransitionTip.blockTransactionCount) > 0 &&
    Boolean(currentTipBip141Witness) &&
    currentTipTransitionChainCommitment.model ===
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL &&
    Number.isSafeInteger(
      Number(currentTipTransitionChainCommitment.payloadBytes),
    ) &&
    Number(currentTipTransitionChainCommitment.payloadBytes) > 0 &&
    /^[0-9a-f]{64}$/u.test(
      String(currentTipTransitionChainCommitment.sha256 ?? "")
        .trim()
        .toLowerCase(),
    ) &&
    String(currentTransitionTip.closingNetworkValueQ8 ?? "") ===
      String(currentClosing.networkValueQ8 ?? "") &&
    /^[0-9a-f]{64}$/u.test(
      String(currentTransitionTip.closingStateSha256 ?? "")
        .trim()
        .toLowerCase(),
    ) &&
    replayCheckpoint.block_scan_complete === true &&
    rebuild.network === network &&
    rebuild.status === "complete" &&
    rebuild.complete === true &&
    rebuild.active === false &&
    Number(rebuild.indexedThroughBlock) === canonicalTip &&
    String(rebuild.indexedThroughBlockHash ?? "").trim().toLowerCase() ===
      canonicalTipBlockHash;
  const legacyStateReady =
    Number(audit.authorization_conflicts ?? 0) === 0 &&
    Number(audit.post_v1_v3_active ?? 0) === 0 &&
    Number(audit.post_activation_v4_active ?? 0) === 0 &&
    Number(audit.post_activation_v4_actions ?? 0) === 0;
  const frozenTermsReady = Number(audit.missing_frozen_terms ?? 0) === 0;
  const preUnitRelicReady = workAmoV5PreUnitRelicEvidenceIsExact(
    preUnitRelicEvidence,
  );
  const quoteReady = Boolean(quoteHead);
  const indexReady =
    declarationReady &&
    requestedTipReady &&
    migrationReady &&
    positionsReady &&
    legacyStateReady &&
    preUnitRelicReady &&
    frozenTermsReady;
  const listingReady = indexReady && quoteReady;
  if (!declarationReady) reasons.push("declaration-not-ready");
  if (!requestedTipReady) reasons.push("canonical-tip-not-current");
  if (!migrationReady) reasons.push("migration-not-complete");
  if (!positionsReady) reasons.push("canonical-positions-incomplete");
  if (Number(audit.authorization_conflicts ?? 0) !== 0) {
    reasons.push("market-authorization-conflict");
  }
  if (!legacyStateReady) reasons.push("legacy-market-state-active");
  if (!preUnitRelicReady) reasons.push("pre-unit-relic-evidence-incomplete");
  if (!frozenTermsReady) reasons.push("frozen-listing-terms-incomplete");
  return {
    activationHeight: WORK_AMO_V5_ACTIVATION_HEIGHT,
    canonicalTip,
    canonicalTipBlockHash,
    declaration,
    declarationReady,
    authorizationConflicts: Number(audit.authorization_conflicts ?? 0),
    duplicatePositions: Number(audit.duplicate_positions ?? 0),
    frozenTermsReady,
    indexReady,
    legacyStateReady,
    listingReady,
    migration,
    migrationReady,
    missingFrozenTerms: Number(audit.missing_frozen_terms ?? 0),
    missingPositions: Number(audit.missing_positions ?? 0),
    positionsReady,
    preUnitRelicEvidence,
    preUnitRelicReady,
    preActivationV4Actions: Number(
      audit.pre_activation_v4_actions ?? 0,
    ),
    postActivationV4Active: Number(audit.post_activation_v4_active ?? 0),
    postActivationV4Actions: Number(
      audit.post_activation_v4_actions ?? 0,
    ),
    postV1V3Active: Number(audit.post_v1_v3_active ?? 0),
    quoteHead,
    quoteReady,
    ready: indexReady,
    relationalTokenState,
    reasons,
    requestedThroughBlockHash,
    requestedThroughHeight,
    requestedTipReady,
    transitionBlockCount: Number(currentTransitions.blockCount ?? 0),
    transitionTip: currentTransitionTip,
    listingReasons: quoteReady ? reasons : [...reasons, "usd-quote-head-missing"],
    throughHeight,
  };
}

async function payloadWithVerifiedWorkMarketV4Activation(
  pool,
  network,
  payload,
) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return payload;
  }
  const { workMarketV4Activation: ignoredActivation, ...untrustedPayload } =
    payload;
  void ignoredActivation;
  const activation = await verifiedWorkMarketV4Activation(
    pool,
    network,
    untrustedPayload.indexedThroughBlock ??
      untrustedPayload.stats?.indexedThroughBlock,
  );
  return activation
    ? { ...untrustedPayload, workMarketV4Activation: activation }
    : untrustedPayload;
}

async function payloadWithVerifiedWorkAmoV5Activation(network, payload) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return payload;
  }
  const {
    workAmoV5Activation: ignoredActivation,
    workAmoV5PreUnitRelicEvidence: ignoredRelicEvidence,
    workAmoV5ProjectionReady: ignoredProjectionReady,
    ...untrustedPayload
  } = payload;
  void ignoredActivation;
  void ignoredRelicEvidence;
  void ignoredProjectionReady;
  const indexedThroughBlock = safeBlockHeight(
    untrustedPayload.indexedThroughBlock ??
      untrustedPayload.stats?.indexedThroughBlock,
  );
  if (
    network !== "livenet" ||
    indexedThroughBlock < WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    return untrustedPayload;
  }
  const [activation, relicEvidence] = await Promise.all([
    proofIndexWorkAmoV5Declaration(network, indexedThroughBlock),
    proofIndexWorkAmoV5PreUnitRelicEvidence(
      network,
      indexedThroughBlock,
    ),
  ]);
  return workAmoV5CutoverActivationIsExact(activation)
    ? {
        ...untrustedPayload,
        workAmoV5Activation: activation,
        workAmoV5PreUnitRelicEvidence: relicEvidence,
      }
    : untrustedPayload;
}

function summaryPayloadIndexedThroughBlock(payload, snapshot) {
  void snapshot;
  const parentHeight = Math.max(
    safeBlockHeight(payload?.indexedThroughBlock),
    safeBlockHeight(payload?.metrics?.indexedThroughBlock),
    safeBlockHeight(payload?.stats?.indexedThroughBlock),
  );
  if (parentHeight <= 0) {
    return undefined;
  }
  const nestedHeights = [payload?.floor, payload?.workFloor].flatMap(
    (nested) => {
      if (!nested || typeof nested !== "object" || Array.isArray(nested)) {
        return [];
      }
      const height = Math.max(
        safeBlockHeight(nested.indexedThroughBlock),
        safeBlockHeight(nested.metrics?.indexedThroughBlock),
        safeBlockHeight(nested.stats?.indexedThroughBlock),
      );
      return height > 0 ? [height] : [0];
    },
  );
  const height =
    nestedHeights.length > 0
      ? Math.min(parentHeight, ...nestedHeights)
      : parentHeight;
  return height > 0 ? height : undefined;
}

function newestDateIso(values, fallback = new Date()) {
  const times = (Array.isArray(values) ? values : [values])
    .map((value) => {
      const time = Date.parse(String(value ?? ""));
      return Number.isFinite(time) ? time : 0;
    })
    .filter((time) => time > 0);
  return times.length > 0
    ? new Date(Math.max(...times)).toISOString()
    : dateIso(fallback);
}

function boundedInteger(value, fallback, min, max) {
  const parsed = Number.parseInt(String(value ?? ""), 10);
  if (!Number.isFinite(parsed)) {
    return fallback;
  }
  return Math.min(max, Math.max(min, parsed));
}

function normalizedTxid(value) {
  const txid = String(value ?? "").trim().toLowerCase();
  return /^[0-9a-f]{64}$/u.test(txid) ? txid : "";
}

function normalizedSnapshotId(value) {
  const snapshotId = String(value ?? "").trim();
  if (!snapshotId || snapshotId.length > 128 || /\s/u.test(snapshotId)) {
    return "";
  }
  return snapshotId;
}

function historyCursorFromSearch(value) {
  const raw = String(value ?? "").trim();
  if (!raw) {
    return { offset: 0, snapshotId: "" };
  }

  const snapshotMatch = /^snapshot:([^:]+):(\d+)$/iu.exec(raw);
  if (snapshotMatch) {
    return {
      offset: boundedInteger(snapshotMatch[2], 0, 0, 100_000_000),
      snapshotId: normalizedSnapshotId(snapshotMatch[1]),
    };
  }

  return {
    offset: boundedInteger(raw, 0, 0, 100_000_000),
    snapshotId: "",
  };
}

function historyCursor(snapshotId, offset) {
  const pinnedSnapshotId = normalizedSnapshotId(snapshotId);
  return pinnedSnapshotId ? `snapshot:${pinnedSnapshotId}:${offset}` : String(offset);
}

function historyPaginationFromSearch(searchParams) {
  const params = searchParams ?? new URLSearchParams();
  const limit = boundedInteger(params.get("limit"), 200, 1, 500);
  const page = boundedInteger(params.get("page"), 0, 0, 1_000_000);
  const cursorRaw = String(params.get("cursor") ?? "").trim();
  const cursor = historyCursorFromSearch(cursorRaw);
  const offsetRaw = String(params.get("offset") ?? "").trim();
  const offset = cursorRaw
    ? cursor.offset
    : offsetRaw
      ? boundedInteger(offsetRaw, 0, 0, 100_000_000)
      : page * limit;
  const snapshotId =
    cursor.snapshotId ||
    normalizedSnapshotId(
      params.get("snapshot") ?? params.get("snapshotId") ?? "",
    );
  const query = [
    "q",
    "search",
    "txid",
    "transaction",
    "transactionId",
  ]
    .map((key) => String(params.get(key) ?? "").trim())
    .find(Boolean)
    ?.toLowerCase() ?? "";

  return { limit, offset, page, query, snapshotId };
}

function tokenHistorySafeKind(kind) {
  const value = String(kind ?? "").trim().toLowerCase();
  const kindMap = new Map([
    ["holders", "holders"],
    ["invalid", "invalidEvents"],
    ["invalid-events", "invalidEvents"],
    ["invalid_events", "invalidEvents"],
    ["closedlistings", "closedListings"],
    ["closed-listings", "closedListings"],
    ["closed_listing", "closedListings"],
    ["closed-listing", "closedListings"],
    ["listings", "listings"],
    ["marketlog", "market-log"],
    ["market-log", "market-log"],
    ["market_log", "market-log"],
    ["tokenmarketlog", "market-log"],
    ["token-market-log", "market-log"],
    ["mints", "mints"],
    ["sales", "sales"],
    ["tokens", "tokens"],
    ["transfers", "transfers"],
  ]);
  return kindMap.get(value) ?? "mints";
}

function tokenScopeKey(tokenScope) {
  const scope = String(tokenScope ?? "").trim().toLowerCase();
  return scope || "all";
}

function tokenHistoryFilterNeedles(searchParams, pagination) {
  const params = searchParams ?? new URLSearchParams();
  const values = [];
  if (pagination.query) {
    values.push(pagination.query);
  }
  for (const key of [
    "address",
    "owner",
    "ownerAddress",
    "seller",
    "sellerAddress",
    "buyer",
    "buyerAddress",
    "txid",
    "transaction",
    "transactionId",
  ]) {
    values.push(...params.getAll(key));
  }
  return [
    ...new Set(
      values
        .map((value) => String(value ?? "").trim().toLowerCase())
        .filter(Boolean),
    ),
  ];
}

function historyItemsMatchingNeedles(items, needles) {
  if (!Array.isArray(needles) || needles.length === 0) {
    return items;
  }
  return items.filter((item) => {
    const text = valueSearchText(item).toLowerCase();
    return needles.every((needle) => text.includes(needle));
  });
}

function commaNumber(value) {
  const number = Number(String(value ?? "").replace(/,/gu, ""));
  return Number.isFinite(number) && number > 0 ? number : 0;
}

function tokenMarketNumbersFromTags(payload) {
  const tags = Array.isArray(payload?.tags) ? payload.tags.map(String) : [];
  let amount = 0;
  let priceSats = 0;
  let ticker = "";

  for (const tag of tags) {
    const amountMatch =
      /^([\d,]+(?:\.\d{1,8})?)\s+([A-Z0-9]{1,16})$/u.exec(tag.trim());
    if (amountMatch && !amount) {
      amount = commaNumber(amountMatch[1]);
      ticker = amountMatch[2];
      continue;
    }

    const priceMatch = /^([\d,]+)\s+sale\s+proofs$/iu.exec(tag.trim());
    if (priceMatch && !priceSats) {
      priceSats = commaNumber(priceMatch[1]);
    }
  }

  return { amount, priceSats, ticker };
}

function tokenTransferAmountFromTags(payload, ticker = "") {
  const tags = Array.isArray(payload?.tags) ? payload.tags.map(String) : [];
  const normalizedTicker = String(ticker || "").trim().toUpperCase();
  for (const tag of tags) {
    const amountMatch =
      /^([\d,]+(?:\.\d{1,8})?)\s+([A-Z0-9]{1,16})$/u.exec(tag.trim());
    if (!amountMatch) {
      continue;
    }
    if (normalizedTicker && amountMatch[2] !== normalizedTicker) {
      continue;
    }
    return commaNumber(amountMatch[1]);
  }
  return 0;
}

function tokenRegistryAddressFromPayload(payload, actor, counterparty, fallback = "") {
  const actorKey = String(actor ?? "").toLowerCase();
  const counterpartyKey = String(counterparty ?? "").toLowerCase();
  const participants = Array.isArray(payload?.participants)
    ? payload.participants
    : [];
  return (
    participants.find((participant) => {
      const value = String(participant ?? "").trim();
      const key = value.toLowerCase();
      return value && key !== actorKey && key !== counterpartyKey;
    }) ??
    payload?.registryAddress ??
    fallback ??
    ""
  );
}

function canonicalMovementPositionFromEventRow(payload, row = {}) {
  const exactInteger = (value, minimum) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed =
      typeof value === "number"
        ? value
        : typeof value === "string" && /^(?:0|[1-9][0-9]*)$/u.test(value)
          ? Number(value)
          : Number.NaN;
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const eventStatus = String(row?.status ?? payload?.status ?? "")
    .trim()
    .toLowerCase();
  const transactionStatus = String(row?.transaction_status ?? "")
    .trim()
    .toLowerCase();
  const effectiveStatus = String(
    row?.effective_status ?? eventStatus,
  )
    .trim()
    .toLowerCase();
  const confirmed =
    effectiveStatus === "confirmed" || payload?.confirmed === true;
  const relationalHeight = exactInteger(row?.block_height, 1);
  const payloadHeight = exactInteger(payload?.blockHeight, 1);
  const transactionBlockHeight = exactInteger(
    row?.transaction_block_height,
    1,
  );
  const candidateHeight =
    relationalHeight ?? transactionBlockHeight ?? payloadHeight;
  const confirmedHeightUnknown =
    confirmed &&
    relationalHeight === null &&
    transactionBlockHeight === null;
  const postActivation =
    confirmed &&
    (
      confirmedHeightUnknown ||
      (relationalHeight !== null &&
        relationalHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT) ||
      (transactionBlockHeight !== null &&
        transactionBlockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT) ||
      (relationalHeight === null &&
        transactionBlockHeight === null &&
        payloadHeight !== null &&
        payloadHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT)
    );
  if (postActivation) {
    const blockIndex = exactInteger(row?.block_index, 0);
    const protocolVout = exactInteger(
      row?.op_return_vout ?? row?.protocol_vout,
      0,
    );
    const recordOrdinal = exactInteger(row?.record_ordinal, 0);
    const transactionBlockIndex = exactInteger(
      row?.transaction_block_index,
      0,
    );
    const blockHash = String(row?.block_hash ?? "").trim().toLowerCase();
    const canonicalBlockHash = String(
      row?.canonical_block_hash ?? "",
    )
      .trim()
      .toLowerCase();
    if (
      relationalHeight === null ||
      eventStatus !== "confirmed" ||
      transactionStatus !== "confirmed" ||
      blockIndex === null ||
      protocolVout === null ||
      recordOrdinal === null ||
      transactionBlockHeight !== relationalHeight ||
      transactionBlockIndex !== blockIndex ||
      !/^[0-9a-f]{64}$/u.test(blockHash) ||
      canonicalBlockHash !== blockHash
    ) {
      throw new Error(
        "Canonical AMO V5 movement position is incomplete or noncanonical.",
      );
    }
    return {
      blockHash,
      blockHeight: relationalHeight,
      blockIndex,
      protocolVout,
      recordOrdinal,
    };
  }
  const blockIndex = exactInteger(
    row?.block_index ?? payload?.blockIndex ?? payload?._powBlockIndex,
    0,
  );
  const protocolVout = exactInteger(
    row?.op_return_vout ??
      row?.protocol_vout ??
      payload?.protocolVout,
    0,
  );
  const recordOrdinal = exactInteger(
    row?.record_ordinal ?? payload?.recordOrdinal,
    0,
  );
  const blockHash = String(
    row?.block_hash ?? payload?.blockHash ?? payload?._powBlockHash ?? "",
  )
    .trim()
    .toLowerCase();
  return {
    ...(blockHash ? { blockHash } : {}),
    ...(candidateHeight !== null ? { blockHeight: candidateHeight } : {}),
    ...(blockIndex !== null ? { blockIndex } : {}),
    ...(protocolVout !== null ? { protocolVout } : {}),
    ...(recordOrdinal !== null ? { recordOrdinal } : {}),
  };
}

function tokenSaleFromEventPayload(payload, row = {}) {
  const tagNumbers = tokenMarketNumbersFromTags(payload);
  const tokenId = String(payload?.tokenId ?? "").trim().toLowerCase();
  const workAmount = isWorkTokenId(tokenId)
    ? workAmountProjection(payload)
    : null;
  const amount = workAmount
    ? workAmount.amount
    : isBondTokenId(tokenId)
      ? exactBondUnits(payload?.amount ?? payload?.tokenAmount, {
          positive: true,
        })
    : rowNumber(payload, "amount") ||
      rowNumber(payload, "tokenAmount") ||
      tagNumbers.amount;
  const priceSats =
    rowNumber(payload, "priceSats") ||
    rowNumber(payload, "salePriceSats") ||
    tagNumbers.priceSats;
  const ticker = String(payload?.ticker ?? tagNumbers.ticker ?? "").trim();
  const buyerAddress = String(payload?.actor ?? payload?.buyerAddress ?? "")
    .trim();
  const sellerAddress = String(
    payload?.counterparty ?? payload?.sellerAddress ?? "",
  ).trim();
  const registryAddress = tokenRegistryAddressFromPayload(
    payload,
    buyerAddress,
    sellerAddress,
  );
  const position = canonicalMovementPositionFromEventRow(payload, row);
  return {
    ...position,
    amount,
    ...(workAmount
      ? workAmountProjectionMetadataForAmount(workAmount)
      : {}),
    arbSats: rowNumber(payload, "arbSats"),
    buyerAddress,
    canonicalMinerFeeCovered: payload?.canonicalMinerFeeCovered === true,
    canonicalMinerFeeSats: rowNumber(payload, "canonicalMinerFeeSats"),
    closedMinerFeeCanonical:
      payload?.canonicalMinerFeeCovered === true &&
      String(payload?.kind ?? "").trim().toLowerCase() === "token-sale",
    closedMinerFeeSource:
      payload?.canonicalMinerFeeCovered === true
        ? String(payload?.minerFeeSource ?? "").trim()
        : String(payload?.closedMinerFeeSource ?? "").trim(),
    confirmed: payload?.confirmed === true,
    creditAmountMoved: isBondTokenId(tokenId)
      ? exactBondUnits(payload?.creditAmountMoved ?? amount, {
          positive: true,
        })
      : rowNumber(payload, "creditAmountMoved"),
    creditFloorAtConfirmSats: rowNumber(payload, "creditFloorAtConfirmSats"),
    creditLiveFloorSats: rowNumber(payload, "creditLiveFloorSats"),
    creditLiveValueSats: rowNumber(payload, "creditLiveValueSats"),
    creditValueAtConfirmSats: rowNumber(payload, "creditValueAtConfirmSats"),
    createdAt: dateIso(
      payload?.createdAt ?? payload?.timestamp ?? payload?.blockTime,
    ),
    dataBytes: rowNumber(payload, "dataBytes"),
    closedMinerFeeSats:
      rowNumber(payload, "closedMinerFeeSats") ||
      rowNumber(payload, "minerFeeSats"),
    frozenNetworkValueSats: rowNumber(payload, "frozenNetworkValueSats"),
    listingId: String(payload?.listingId ?? "").trim().toLowerCase(),
    liveNetworkValueSats: rowNumber(payload, "liveNetworkValueSats"),
    marketplaceMutationFeeSats: rowNumber(payload, "marketplaceMutationFeeSats"),
    minerFeeSats: rowNumber(payload, "minerFeeSats"),
    minerFeeSource: String(payload?.minerFeeSource ?? "").trim(),
    network: payload?.network,
    paidSats: rowNumber(payload, "paidSats") || rowNumber(payload, "amountSats"),
    priceSats,
    registryAddress,
    salePaymentSats: rowNumber(payload, "salePaymentSats"),
    sellerAddress,
    ticker,
    tokenId,
    txid: String(payload?.txid ?? "").trim().toLowerCase(),
  };
}

function tokenListingFromEventPayload(payload, row = {}) {
  const saleAuthorization =
    payload?.saleAuthorization &&
    typeof payload.saleAuthorization === "object" &&
    !Array.isArray(payload.saleAuthorization)
      ? payload.saleAuthorization
      : {};
  const { amount, priceSats, ticker } = tokenMarketNumbersFromTags(payload);
  const sellerAddress = String(
    payload?.sellerAddress ??
      payload?.actor ??
      saleAuthorization.sellerAddress ??
      "",
  ).trim();
  const registryAddress = tokenRegistryAddressFromPayload(
    payload,
    sellerAddress,
    payload?.counterparty,
    saleAuthorization.registryAddress,
  );
  const tokenId = String(payload?.tokenId ?? saleAuthorization.tokenId ?? "")
    .trim()
    .toLowerCase();
  const workAmount = isWorkTokenId(tokenId)
    ? workAmountProjection(payload)
    : null;
  const normalizedTicker = String(ticker || saleAuthorization.ticker || "").trim();
  const position = canonicalMovementPositionFromEventRow(payload, row);
  const exactPositionInteger = (value) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= 0 ? parsed : null;
  };
  const sealBlockIndex = exactPositionInteger(payload?.sealBlockIndex);
  const sealProtocolVout = exactPositionInteger(payload?.sealProtocolVout);
  const sealRecordOrdinal = exactPositionInteger(payload?.sealRecordOrdinal);
  return {
    amount: workAmount
      ? workAmount.amount
      : isBondTokenId(tokenId)
        ? exactBondUnits(
            payload?.amount ?? saleAuthorization?.amount,
            { positive: true },
          )
      : rowNumber(payload, "amount") ||
        rowNumber(saleAuthorization, "amount") ||
        amount,
    ...(workAmount
      ? workAmountProjectionMetadataForAmount(workAmount)
      : {}),
    canonicalMinerFeeCovered: payload?.canonicalMinerFeeCovered === true,
    canonicalMinerFeeSats: rowNumber(payload, "canonicalMinerFeeSats"),
    blockHash: String(position.blockHash ?? "").trim().toLowerCase(),
    ...(position.blockHeight !== undefined
      ? { blockHeight: position.blockHeight }
      : {}),
    ...(position.blockIndex !== undefined
      ? { blockIndex: position.blockIndex }
      : {}),
    ...(position.protocolVout !== undefined
      ? { protocolVout: position.protocolVout }
      : {}),
    ...(position.recordOrdinal !== undefined
      ? { recordOrdinal: position.recordOrdinal }
      : {}),
    confirmed: payload?.confirmed === true,
    createdAt: dateIso(payload?.createdAt),
    dataBytes: rowNumber(payload, "dataBytes"),
    frozenNetworkValueSats: rowNumber(payload, "frozenNetworkValueSats"),
    listingId: String(payload?.listingId ?? payload?.txid ?? "")
      .trim()
      .toLowerCase(),
    liveNetworkValueSats: rowNumber(payload, "liveNetworkValueSats"),
    marketplaceMutationFeeSats: rowNumber(payload, "marketplaceMutationFeeSats"),
    minerFeeSats: rowNumber(payload, "minerFeeSats"),
    minerFeeSource: String(payload?.minerFeeSource ?? "").trim(),
    network: payload?.network,
    priceSats:
      rowNumber(payload, "priceSats") ||
      rowNumber(saleAuthorization, "priceSats") ||
      priceSats,
    registryAddress,
    saleAuthorization,
    sealDataBytes: rowNumber(payload, "sealDataBytes"),
    sealFrozenNetworkValueSats: rowNumber(payload, "sealFrozenNetworkValueSats"),
    sealAt: dateIso(payload?.sealAt),
    sealBlockHash: String(payload?.sealBlockHash ?? "").trim().toLowerCase(),
    sealBlockHeight: rowNumber(payload, "sealBlockHeight") || undefined,
    ...(sealBlockIndex !== null ? { sealBlockIndex } : {}),
    ...(sealProtocolVout !== null ? { sealProtocolVout } : {}),
    ...(sealRecordOrdinal !== null ? { sealRecordOrdinal } : {}),
    sealConfirmed:
      typeof payload?.sealConfirmed === "boolean"
        ? payload.sealConfirmed
        : undefined,
    sealLiveNetworkValueSats: rowNumber(payload, "sealLiveNetworkValueSats"),
    sealMinerFeeCanonical:
      payload?.sealMinerFeeCanonical === true ||
      (payload?.canonicalMinerFeeCovered === true &&
        String(payload?.kind ?? "").trim().toLowerCase() ===
          "token-listing-sealed"),
    sealMinerFeeSource:
      payload?.canonicalMinerFeeCovered === true &&
      String(payload?.kind ?? "").trim().toLowerCase() ===
        "token-listing-sealed"
        ? String(payload?.minerFeeSource ?? "").trim()
        : String(payload?.sealMinerFeeSource ?? "").trim(),
    sealMinerFeeSats: rowNumber(payload, "sealMinerFeeSats"),
    sealTxid: String(payload?.sealTxid ?? "").trim().toLowerCase(),
    sellerAddress,
    status: payload?.status,
    ticker: normalizedTicker,
    tokenId,
  };
}

function validPublicKeyHex(value) {
  return (
    /^[0-9a-fA-F]{64}$/u.test(value) ||
    /^(02|03)[0-9a-fA-F]{64}$/u.test(value) ||
    /^04[0-9a-fA-F]{128}$/u.test(value)
  );
}

function tokenSaleAuthorizationUsesSpendableSaleTicketAnchor(authorization) {
  return (
    TOKEN_SALE_AUTH_VERSIONS.has(authorization?.version) &&
    (
      authorization?.version === TOKEN_SALE_AUTH_VERSION ||
      (
        (authorization?.version === "pwt-sale-v2" ||
          WORK_MARKET_GOVERNED_AUTH_VERSIONS.has(
            authorization?.version,
          )) &&
        isWorkTokenId(authorization?.tokenId) &&
        String(authorization?.ticker ?? "").trim().toUpperCase() ===
          WORK_TOKEN_TICKER
      )
    ) &&
    authorization.anchorType === TOKEN_LISTING_ANCHOR_TYPE &&
    authorization.anchorVout === TOKEN_LISTING_ANCHOR_VOUT &&
    authorization.anchorValueSats === TOKEN_LISTING_ANCHOR_VALUE_SATS &&
    authorization.anchorSigHashType === TOKEN_LISTING_ANCHOR_SIGHASH_TYPE &&
    /^[0-9a-f]+$/u.test(authorization.anchorScriptPubKey ?? "") &&
    validPublicKeyHex(authorization.sellerPublicKey ?? "")
  );
}

function compareTokenHolderBalances(left, right) {
  if (isWorkTokenId(left?.tokenId) && isWorkTokenId(right?.tokenId)) {
    const leftModel = left?.amountStorageModel;
    const rightModel = right?.amountStorageModel;
    if (
      leftModel !== rightModel ||
      (
        leftModel !== WORK_ATOMIC_PROJECTION_MODEL &&
        leftModel !== WORK_SUBATOM_PROJECTION_MODEL
      )
    ) {
      throw new Error(
        "WORK holder ordering requires one explicit precision model.",
      );
    }
    const subatomic = leftModel === WORK_SUBATOM_PROJECTION_MODEL;
    const leftUnits = BigInt(
      String(
        subatomic ? left?.balanceSubatoms : left?.balanceAtoms,
      ),
    );
    const rightUnits = BigInt(
      String(
        subatomic ? right?.balanceSubatoms : right?.balanceAtoms,
      ),
    );
    if (leftUnits !== rightUnits) {
      return leftUnits > rightUnits ? -1 : 1;
    }
  } else if (isBondTokenId(left?.tokenId) && isBondTokenId(right?.tokenId)) {
    const leftUnits = integerBigInt(left?.balance) ?? 0n;
    const rightUnits = integerBigInt(right?.balance) ?? 0n;
    if (leftUnits !== rightUnits) {
      return leftUnits > rightUnits ? -1 : 1;
    }
  } else {
    const difference =
      Number(right?.balance ?? 0) - Number(left?.balance ?? 0);
    if (difference !== 0) {
      return difference;
    }
  }
  return compareCanonicalUtf8(left?.address, right?.address);
}

function activeTokenListingHistoryItem(listing) {
  return (
    listing &&
    listing.status !== "dropped" &&
    listing.listingId &&
    listing.tokenId &&
    listing.registryAddress &&
    listing.sellerAddress &&
    tokenSaleAuthorizationUsesSpendableSaleTicketAnchor(
      listing.saleAuthorization,
    )
  );
}

function activeOrSealingListingStatus(status) {
  return ["active", "pending", "sealing"].includes(
    String(status ?? "").trim().toLowerCase(),
  );
}

function canonicalCreditListingAlias(value) {
  const alias = String(value ?? "").trim();
  if (!/^[a-z_][a-z0-9_]*$/u.test(alias)) {
    throw new Error("Canonical credit-listing SQL alias is invalid.");
  }
  return alias;
}

function tokenListingActiveLifecycleSql(listingAlias = "cl") {
  const alias = canonicalCreditListingAlias(listingAlias);
  return `(
    NOT EXISTS (
      SELECT 1
      FROM proof_indexer.events dropped_listing_event
      WHERE dropped_listing_event.network = ${alias}.network
        AND dropped_listing_event.protocol = 'pwt1'
        AND dropped_listing_event.kind = 'token-listing'
        AND dropped_listing_event.valid = true
        AND dropped_listing_event.status = 'dropped'
        AND dropped_listing_event.txid = lower(${alias}.listing_id)
        AND lower(COALESCE(
          dropped_listing_event.payload->>'listingId',
          dropped_listing_event.txid
        )) = lower(${alias}.listing_id)
        AND lower(COALESCE(
          NULLIF(dropped_listing_event.payload->>'tokenId', ''),
          NULLIF(
            dropped_listing_event.payload
              ->'saleAuthorization'->>'tokenId',
            ''
          ),
          ${alias}.token_id
        )) = lower(${alias}.token_id)
    )
    AND NOT EXISTS (
      SELECT 1
      FROM proof_indexer.tx_inputs active_listing_spend_input
      JOIN proof_indexer.transactions active_listing_spend_tx
        ON active_listing_spend_tx.network =
          active_listing_spend_input.network
       AND active_listing_spend_tx.txid =
          active_listing_spend_input.txid
       AND active_listing_spend_tx.status = 'confirmed'
      JOIN proof_indexer.blocks active_listing_spend_block
        ON active_listing_spend_block.network =
          active_listing_spend_tx.network
       AND active_listing_spend_block.block_hash =
          active_listing_spend_tx.block_hash
       AND active_listing_spend_block.height =
          active_listing_spend_tx.block_height
       AND active_listing_spend_block.canonical = true
      WHERE active_listing_spend_input.network = ${alias}.network
        AND active_listing_spend_input.prev_txid = lower(COALESCE(
          NULLIF(${alias}.sale_ticket_txid, ''),
          ${alias}.listing_id
        ))
        AND active_listing_spend_input.prev_vout =
          ${alias}.sale_ticket_vout
    )
  )`;
}

function canonicalWorkMarketV3ListingProjectionSql(listingAlias = "cl") {
  const alias = canonicalCreditListingAlias(listingAlias);
  return `(
    lower(COALESCE(${alias}.token_id, '')) <> '${WORK_TOKEN_ID}'
    OR lower(COALESCE(
      ${alias}.payload->'saleAuthorization'->>'version',
      ''
    )) NOT IN (
      '${WORK_MARKET_V2_AUTH_VERSION}',
      '${WORK_MARKET_V4_AUTH_VERSION}',
      '${WORK_AMO_V5_AUTH_VERSION}',
      '${WORK_AMO_V6_AUTH_VERSION}',
      '${WORK_AMO_V8_AUTH_VERSION}'
    )
    OR (
      EXISTS (
        SELECT 1
        FROM proof_indexer.events canonical_listing_event
        JOIN proof_indexer.transactions canonical_listing_tx
         ON canonical_listing_tx.network = canonical_listing_event.network
         AND canonical_listing_tx.txid = canonical_listing_event.txid
         AND canonical_listing_tx.status = 'confirmed'
         AND canonical_listing_tx.block_height =
           canonical_listing_event.block_height
         AND canonical_listing_tx.block_index =
           canonical_listing_event.block_index
        JOIN proof_indexer.blocks canonical_listing_block
          ON canonical_listing_block.network = canonical_listing_tx.network
         AND canonical_listing_block.block_hash = canonical_listing_tx.block_hash
         AND canonical_listing_block.height = canonical_listing_tx.block_height
         AND canonical_listing_block.canonical = true
        WHERE canonical_listing_event.network = ${alias}.network
          AND canonical_listing_event.txid = lower(${alias}.listing_id)
          AND canonical_listing_event.valid = true
          AND canonical_listing_event.status = 'confirmed'
          AND canonical_listing_event.protocol = 'pwt1'
          AND (
            canonical_listing_event.kind = 'token-listing'
            OR (
              canonical_listing_event.kind = 'token-listings'
              AND (
                lower(COALESCE(${alias}.token_id, '')) <>
                  '${WORK_TOKEN_ID}'
                OR NOT (
                  lower(COALESCE(
                    ${alias}.payload->'saleAuthorization'->>'version',
                    ''
                  )) IN (
                    '${WORK_AMO_V5_AUTH_VERSION}',
                    '${WORK_AMO_V6_AUTH_VERSION}',
                    '${WORK_AMO_V8_AUTH_VERSION}'
                  )
                  OR lower(COALESCE(
                    ${alias}.payload->'listingAuthorization'->>'version',
                    ''
                  )) IN (
                    '${WORK_AMO_V5_AUTH_VERSION}',
                    '${WORK_AMO_V6_AUTH_VERSION}',
                    '${WORK_AMO_V8_AUTH_VERSION}'
                  )
                )
              )
            )
          )
          AND lower(COALESCE(
            canonical_listing_event.payload->>'listingId',
            canonical_listing_event.txid
          )) = lower(${alias}.listing_id)
          AND lower(COALESCE(
            canonical_listing_event.payload->>'tokenId',
            canonical_listing_event.payload->'saleAuthorization'->>'tokenId',
            ''
          )) = '${WORK_TOKEN_ID}'
          AND lower(COALESCE(
            canonical_listing_event.payload->'saleAuthorization'->>'version',
            ''
          )) = lower(COALESCE(
            ${alias}.payload->'saleAuthorization'->>'version',
            ''
          ))
      )
    )
  )`;
}

function canonicalTokenListingEventJoinSql(listingAlias = "cl") {
  const alias = canonicalCreditListingAlias(listingAlias);
  return `LEFT JOIN LATERAL (
    SELECT
      canonical_listing_event_row.status AS listing_event_status,
      canonical_listing_tx.block_hash AS listing_event_block_hash,
      canonical_listing_event_row.block_height AS listing_event_block_height,
      canonical_listing_event_row.block_index AS listing_event_block_index,
      canonical_listing_event_row.op_return_vout AS listing_event_protocol_vout,
      canonical_listing_event_row.record_ordinal AS listing_event_record_ordinal,
      COUNT(*) OVER () AS listing_event_match_count
    FROM proof_indexer.events canonical_listing_event_row
    JOIN proof_indexer.transactions canonical_listing_tx
      ON canonical_listing_tx.network = canonical_listing_event_row.network
     AND canonical_listing_tx.txid = canonical_listing_event_row.txid
     AND canonical_listing_tx.status = 'confirmed'
     AND canonical_listing_tx.block_height =
       canonical_listing_event_row.block_height
     AND canonical_listing_tx.block_index =
       canonical_listing_event_row.block_index
    JOIN proof_indexer.blocks canonical_listing_block
      ON canonical_listing_block.network = canonical_listing_tx.network
     AND canonical_listing_block.block_hash = canonical_listing_tx.block_hash
     AND canonical_listing_block.height = canonical_listing_tx.block_height
     AND canonical_listing_block.canonical = true
    WHERE canonical_listing_event_row.network = ${alias}.network
      AND canonical_listing_event_row.txid = lower(${alias}.listing_id)
      AND canonical_listing_event_row.valid = true
      AND canonical_listing_event_row.status = 'confirmed'
      AND canonical_listing_event_row.protocol = 'pwt1'
      AND (
        canonical_listing_event_row.kind = 'token-listing'
        OR (
          canonical_listing_event_row.kind = 'token-listings'
          AND (
            lower(COALESCE(${alias}.token_id, '')) <> '${WORK_TOKEN_ID}'
            OR NOT (
              lower(COALESCE(
                ${alias}.payload->'saleAuthorization'->>'version',
                ''
              )) IN (
                '${WORK_AMO_V5_AUTH_VERSION}',
                '${WORK_AMO_V6_AUTH_VERSION}',
                '${WORK_AMO_V8_AUTH_VERSION}'
              )
              OR lower(COALESCE(
                ${alias}.payload->'listingAuthorization'->>'version',
                ''
              )) IN (
                '${WORK_AMO_V5_AUTH_VERSION}',
                '${WORK_AMO_V6_AUTH_VERSION}',
                '${WORK_AMO_V8_AUTH_VERSION}'
              )
            )
          )
        )
      )
      AND lower(COALESCE(
        canonical_listing_event_row.payload->>'listingId',
        canonical_listing_event_row.txid
      )) = lower(${alias}.listing_id)
      AND lower(COALESCE(
        canonical_listing_event_row.payload->>'tokenId',
        canonical_listing_event_row.payload->'saleAuthorization'->>'tokenId',
        ''
      )) = lower(${alias}.token_id)
      AND (
        lower(COALESCE(${alias}.token_id, '')) <> '${WORK_TOKEN_ID}'
        OR lower(COALESCE(
          canonical_listing_event_row.payload
            ->'saleAuthorization'->>'version',
          canonical_listing_event_row.payload
            ->'listingAuthorization'->>'version',
          ''
        )) = lower(COALESCE(
          ${alias}.payload->'saleAuthorization'->>'version',
          ${alias}.payload->'listingAuthorization'->>'version',
          ''
        ))
      )
    ORDER BY
      canonical_listing_event_row.block_height DESC,
      canonical_listing_event_row.block_index DESC,
      canonical_listing_event_row.op_return_vout DESC,
      canonical_listing_event_row.record_ordinal DESC
    LIMIT 1
  ) canonical_listing_event ON true`;
}

function canonicalTokenListingSealEventJoinSql(listingAlias = "cl") {
  const alias = canonicalCreditListingAlias(listingAlias);
  return `LEFT JOIN LATERAL (
    SELECT
      canonical_seal_event_row.status AS seal_event_status,
      canonical_seal_tx.block_hash AS seal_event_block_hash,
      canonical_seal_event_row.block_height AS seal_event_block_height,
      canonical_seal_event_row.block_index AS seal_event_block_index,
      canonical_seal_event_row.op_return_vout AS seal_event_protocol_vout,
      canonical_seal_event_row.record_ordinal AS seal_event_record_ordinal,
      COUNT(*) OVER () AS seal_event_match_count
    FROM proof_indexer.events canonical_seal_event_row
    JOIN proof_indexer.transactions canonical_seal_tx
      ON canonical_seal_tx.network = canonical_seal_event_row.network
     AND canonical_seal_tx.txid = canonical_seal_event_row.txid
     AND canonical_seal_tx.status = 'confirmed'
     AND canonical_seal_tx.block_height =
       canonical_seal_event_row.block_height
     AND canonical_seal_tx.block_index =
       canonical_seal_event_row.block_index
    JOIN proof_indexer.blocks canonical_seal_block
      ON canonical_seal_block.network = canonical_seal_tx.network
     AND canonical_seal_block.block_hash = canonical_seal_tx.block_hash
     AND canonical_seal_block.height = canonical_seal_tx.block_height
     AND canonical_seal_block.canonical = true
    WHERE canonical_seal_event_row.network = ${alias}.network
      AND canonical_seal_event_row.txid = lower(${alias}.seal_txid)
      AND canonical_seal_event_row.valid = true
      AND canonical_seal_event_row.status = 'confirmed'
      AND canonical_seal_event_row.protocol = 'pwt1'
      AND canonical_seal_event_row.kind = 'token-listing-sealed'
      AND lower(canonical_seal_event_row.payload->>'listingId') =
        lower(${alias}.listing_id)
      AND lower(COALESCE(
        canonical_seal_event_row.payload->>'tokenId',
        canonical_seal_event_row.payload->'saleAuthorization'->>'tokenId',
        ''
      )) = lower(${alias}.token_id)
      AND (
        lower(COALESCE(${alias}.token_id, '')) <> '${WORK_TOKEN_ID}'
        OR (
          lower(COALESCE(
            ${alias}.payload->'saleAuthorization'->>'version',
            ''
          )) IN (
            '${WORK_MARKET_V2_AUTH_VERSION}',
            '${WORK_MARKET_V4_AUTH_VERSION}',
            '${WORK_AMO_V5_AUTH_VERSION}',
            '${WORK_AMO_V6_AUTH_VERSION}',
            '${WORK_AMO_V8_AUTH_VERSION}'
          )
          AND lower(COALESCE(
            canonical_seal_event_row.payload->'saleAuthorization'->>'version',
            ''
          )) = lower(COALESCE(
            ${alias}.payload->'saleAuthorization'->>'version',
            ''
          ))
        )
      )
    ORDER BY
      canonical_seal_event_row.block_height DESC,
      canonical_seal_event_row.block_index DESC,
      canonical_seal_event_row.op_return_vout DESC,
      canonical_seal_event_row.record_ordinal DESC
    LIMIT 1
  ) canonical_seal_event ON true`;
}

function tokenListingSealConfirmedFromTransaction(row, sealTxid) {
  const transactionConfirmed =
    validTxid(sealTxid) &&
    normalizedLowerText(row?.seal_tx_status) === "confirmed";
  const saleAuthorization =
    row?.payload?.saleAuthorization &&
    typeof row.payload.saleAuthorization === "object" &&
    !Array.isArray(row.payload.saleAuthorization)
      ? row.payload.saleAuthorization
      : {};
  const governedWorkMarket =
    normalizedLowerText(row?.token_id ?? saleAuthorization.tokenId) ===
      WORK_TOKEN_ID &&
    WORK_MARKET_GOVERNED_AUTH_VERSIONS.has(
      normalizedLowerText(saleAuthorization.version),
    );
  const exactPositionInteger = (value, minimum) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const sealEventBlockHeight = exactPositionInteger(
    row?.seal_event_block_height,
    1,
  );
  const sealTransactionBlockHeight = exactPositionInteger(
    row?.seal_transaction_block_height,
    1,
  );
  const unknownConfirmedSealHeight =
    transactionConfirmed &&
    sealEventBlockHeight === null &&
    sealTransactionBlockHeight === null;
  const postAmoV5Seal =
    transactionConfirmed &&
    (
      unknownConfirmedSealHeight ||
      [
        sealEventBlockHeight,
        sealTransactionBlockHeight,
      ].some(
        (height) =>
          height !== null &&
          height >= WORK_AMO_V5_ACTIVATION_HEIGHT,
      )
    );
  const canonicalSealPositionComplete =
    /^[0-9a-f]{64}$/u.test(
      normalizedLowerText(row?.seal_event_block_hash),
    ) &&
    exactPositionInteger(row?.seal_event_block_height, 1) !== null &&
    exactPositionInteger(row?.seal_event_block_index, 0) !== null &&
    exactPositionInteger(row?.seal_event_protocol_vout, 0) !== null &&
    exactPositionInteger(row?.seal_event_record_ordinal, 0) !== null;
  const canonicalSealEventMatchCount =
    row?.seal_event_match_count === undefined
      ? null
      : exactPositionInteger(row.seal_event_match_count, 1);
  const canonicalSealEventSingleton =
    canonicalSealEventMatchCount === 1;
  const canonicalSealEventRequired =
    governedWorkMarket || postAmoV5Seal;
  return (
    transactionConfirmed &&
    (!canonicalSealEventRequired ||
      (
        normalizedLowerText(row?.seal_event_status) === "confirmed" &&
        canonicalSealEventSingleton &&
        (!postAmoV5Seal || canonicalSealPositionComplete)
      ))
  );
}

function tokenListingEffectiveCloseTxid(row, payload, status, sealTxid) {
  const closeTxid = String(row?.close_txid ?? payload?.closeTxid ?? "")
    .trim()
    .toLowerCase();
  if (
    activeOrSealingListingStatus(status) &&
    validTxid(closeTxid) &&
    closeTxid === String(sealTxid ?? "").trim().toLowerCase()
  ) {
    return "";
  }
  return closeTxid;
}

function tokenListingEffectiveSaleTicketTxid(
  row,
  payload,
  saleAuthorization,
  listingId,
  sealTxid,
) {
  const raw = String(
    row?.sale_ticket_txid ??
      payload?.saleTicketTxid ??
      saleAuthorization?.saleTicketTxid ??
      saleAuthorization?.anchorTxid ??
      "",
  )
    .trim()
    .toLowerCase();
  const normalizedListingId = String(listingId ?? "").trim().toLowerCase();
  const normalizedSealTxid = String(sealTxid ?? "").trim().toLowerCase();
  if (validTxid(raw) && raw !== normalizedSealTxid) {
    return raw;
  }
  if (validTxid(normalizedListingId)) {
    return normalizedListingId;
  }
  return raw;
}

function normalizeTokenHistoryListingItem(item) {
  if (!item || typeof item !== "object" || Array.isArray(item)) {
    return null;
  }

  const saleAuthorization =
    item.saleAuthorization &&
    typeof item.saleAuthorization === "object" &&
    !Array.isArray(item.saleAuthorization)
      ? item.saleAuthorization
      : {};
  const tokenId = String(item.tokenId ?? saleAuthorization.tokenId ?? "")
    .trim()
    .toLowerCase();
  const registryAddress = String(
    item.registryAddress ?? saleAuthorization.registryAddress ?? "",
  ).trim();
  const sellerAddress = String(
    item.sellerAddress ?? saleAuthorization.sellerAddress ?? "",
  ).trim();
  const ticker = String(item.ticker ?? saleAuthorization.ticker ?? "").trim();
  const workAmount = isWorkTokenId(tokenId)
    ? workAmountProjection(item)
    : null;

  return {
    ...item,
    amount: workAmount
      ? workAmount.amount
      : isBondTokenId(tokenId)
        ? exactBondUnits(item?.amount ?? saleAuthorization?.amount, {
            positive: true,
          })
      : rowNumber(item, "amount") ||
        rowNumber(saleAuthorization, "amount"),
    ...(workAmount
      ? workAmountProjectionMetadataForAmount(workAmount)
      : {}),
    priceSats:
      rowNumber(item, "priceSats") || rowNumber(saleAuthorization, "priceSats"),
    registryAddress,
    saleAuthorization,
    sellerAddress,
    ticker,
    tokenId,
  };
}

function normalizeTokenHistoryItemsForKind(items, safeKind) {
  if (!Array.isArray(items) || safeKind !== "listings") {
    return items;
  }

  return items
    .map(normalizeTokenHistoryListingItem)
    .filter(activeTokenListingHistoryItem);
}

const SNAPSHOT_TOKEN_ACTIVITY_KINDS = new Set([
  "token-create",
  "token-event-invalid",
  "token-listing",
  "token-listings",
  "token-listing-closed",
  "token-listing-sealed",
  "token-mint",
  "token-sale",
  "token-transfer",
]);

function snapshotTokenActivityCanonicalExemption(item) {
  return (
    item?.relic === true ||
    item?.canonicalSynthetic === true ||
    normalizedLowerText(item?.canonicalSynthetic) === "true" ||
    item?.metadata?.canonicalSynthetic === true ||
    normalizedLowerText(item?.metadata?.canonicalSynthetic) === "true"
  );
}

function snapshotTokenActivityPositionCanProject(
  item,
  options = {},
) {
  const selected = (key, fallback) =>
    Object.prototype.hasOwnProperty.call(options, key)
      ? options[key]
      : fallback;
  const blockHash = selected("blockHash", item?.blockHash);
  const blockHeight = selected("blockHeight", item?.blockHeight);
  const blockIndex = selected("blockIndex", item?.blockIndex);
  const confirmed = selected(
    "confirmed",
    item?.confirmed === true ||
      normalizedLowerText(item?.status) === "confirmed",
  );
  const protocolVout = selected("protocolVout", item?.protocolVout);
  const recordOrdinal = selected("recordOrdinal", item?.recordOrdinal);
  const transactionBlockHeight = selected(
    "transactionBlockHeight",
    undefined,
  );
  if (confirmed !== true || snapshotTokenActivityCanonicalExemption(item)) {
    return true;
  }
  const exactPositionInteger = (value, minimum) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const eventHeight = exactPositionInteger(blockHeight, 1);
  const transactionHeight = exactPositionInteger(transactionBlockHeight, 1);
  const knownHeights = [eventHeight, transactionHeight].filter(
    (height) => height !== null,
  );
  const knownPreAmoV5 =
    knownHeights.length > 0 &&
    knownHeights.every(
      (height) => height < WORK_AMO_V5_ACTIVATION_HEIGHT,
    );
  if (knownPreAmoV5) {
    return true;
  }
  return (
    eventHeight !== null &&
    (transactionHeight === null || transactionHeight === eventHeight) &&
    /^[0-9a-f]{64}$/u.test(normalizedLowerText(blockHash)) &&
    exactPositionInteger(blockIndex, 0) !== null &&
    exactPositionInteger(protocolVout, 0) !== null &&
    exactPositionInteger(recordOrdinal, 0) !== null
  );
}

function snapshotTokenActivityItemCanProject(item) {
  const kind = normalizedLowerText(item?.kind);
  if (!SNAPSHOT_TOKEN_ACTIVITY_KINDS.has(kind)) {
    return true;
  }
  if (kind === "token-listing-sealed") {
    return snapshotTokenActivityPositionCanProject(item, {
      blockHash: item?.sealBlockHash ?? item?.blockHash,
      blockHeight: item?.sealBlockHeight ?? item?.blockHeight,
      blockIndex: item?.sealBlockIndex ?? item?.blockIndex,
      confirmed:
        item?.sealConfirmed === true ||
        item?.confirmed === true ||
        normalizedLowerText(item?.status) === "confirmed",
      protocolVout: item?.sealProtocolVout ?? item?.protocolVout,
      recordOrdinal: item?.sealRecordOrdinal ?? item?.recordOrdinal,
      transactionBlockHeight: item?.sealTransactionBlockHeight,
    });
  }
  if (kind === "token-listing-closed") {
    return snapshotTokenActivityPositionCanProject(item, {
      blockHash: item?.closedBlockHash ?? item?.blockHash,
      blockHeight: item?.closedBlockHeight ?? item?.blockHeight,
      blockIndex: item?.closedBlockIndex ?? item?.blockIndex,
      confirmed:
        item?.closedConfirmed === true ||
        item?.confirmed === true ||
        normalizedLowerText(item?.status) === "confirmed",
      protocolVout: item?.closedProtocolVout ?? item?.protocolVout,
      recordOrdinal: item?.closedRecordOrdinal ?? item?.recordOrdinal,
      transactionBlockHeight: item?.closeTransactionBlockHeight,
    });
  }
  return snapshotTokenActivityPositionCanProject(item, {
    transactionBlockHeight: item?.closeTransactionBlockHeight,
  });
}

function snapshotTokenHistoryItemCanProject(item, safeKind) {
  if (!item || typeof item !== "object" || Array.isArray(item)) {
    return false;
  }
  if (safeKind === "holders") {
    return true;
  }
  if (safeKind === "market-log") {
    if (item.listing) {
      return snapshotTokenHistoryItemCanProject(item.listing, "listings");
    }
    if (item.sale) {
      return snapshotTokenHistoryItemCanProject(item.sale, "sales");
    }
    if (item.closedListing) {
      return snapshotTokenHistoryItemCanProject(
        item.closedListing,
        "closedListings",
      );
    }
    return snapshotTokenActivityItemCanProject(item);
  }
  if (safeKind === "listings") {
    if (
      !snapshotTokenActivityPositionCanProject(item, {
        confirmed:
          item?.confirmed === true ||
          normalizedLowerText(item?.status) === "confirmed",
      })
    ) {
      return false;
    }
    if (item?.sealConfirmed !== true) {
      return true;
    }
    return snapshotTokenActivityPositionCanProject(item, {
      blockHash: item?.sealBlockHash,
      blockHeight: item?.sealBlockHeight,
      blockIndex: item?.sealBlockIndex,
      confirmed: true,
      protocolVout: item?.sealProtocolVout,
      recordOrdinal: item?.sealRecordOrdinal,
      transactionBlockHeight: item?.sealTransactionBlockHeight,
    });
  }
  if (safeKind === "closedListings") {
    return snapshotTokenActivityPositionCanProject(item, {
      blockHash: item?.closedBlockHash,
      blockHeight: item?.closedBlockHeight,
      blockIndex: item?.closedBlockIndex,
      confirmed:
        item?.closedConfirmed === true ||
        (
          item?.closedConfirmed === undefined &&
          (
            item?.confirmed === true ||
            ["closed", "delisted", "disabled", "sold"].includes(
              normalizedLowerText(item?.status),
            )
          )
        ),
      protocolVout: item?.closedProtocolVout,
      recordOrdinal: item?.closedRecordOrdinal,
      transactionBlockHeight: item?.closeTransactionBlockHeight,
    });
  }
  if (safeKind === "tokens") {
    return snapshotTokenActivityItemCanProject({
      ...item,
      kind: "token-create",
    });
  }
  if (safeKind === "mints") {
    return snapshotTokenActivityItemCanProject({
      ...item,
      kind: "token-mint",
    });
  }
  if (safeKind === "transfers") {
    return snapshotTokenActivityItemCanProject({
      ...item,
      kind: "token-transfer",
    });
  }
  if (safeKind === "sales") {
    return snapshotTokenActivityItemCanProject({
      ...item,
      kind: "token-sale",
    });
  }
  if (safeKind === "invalidEvents") {
    return snapshotTokenActivityItemCanProject({
      ...item,
      kind: "token-event-invalid",
    });
  }
  return true;
}

function tokenClosedListingFromEventPayload(payload) {
  const row =
    arguments.length > 1 &&
    arguments[1] &&
    typeof arguments[1] === "object" &&
    !Array.isArray(arguments[1])
      ? arguments[1]
      : {};
  const { amount, priceSats, ticker } = tokenMarketNumbersFromTags(payload);
  const tokenId = String(payload?.tokenId ?? "").trim().toLowerCase();
  const workAmount = isWorkTokenId(tokenId)
    ? workAmountProjection(payload)
    : null;
  const sellerAddress = String(payload?.actor ?? payload?.sellerAddress ?? "")
    .trim();
  const registryAddress = tokenRegistryAddressFromPayload(
    payload,
    sellerAddress,
    payload?.counterparty,
    payload?.counterparty,
  );
  const createdAt = dateIso(
    payload?.createdAt ?? payload?.timestamp ?? payload?.blockTime,
  );
  const closedAt = dateIso(
    payload?.closedAt ?? payload?.blockTime ?? payload?.timestamp ?? createdAt,
  );
  const position = canonicalMovementPositionFromEventRow(payload, row);
  return {
    amount: workAmount
      ? workAmount.amount
      : isBondTokenId(tokenId)
        ? exactBondUnits(payload?.amount ?? payload?.tokenAmount, {
            positive: true,
          })
      : rowNumber(payload, "amount") ||
        rowNumber(payload, "tokenAmount") ||
        amount,
    ...(workAmount
      ? workAmountProjectionMetadataForAmount(workAmount)
      : {}),
    closedAt,
    closedBlockHash: String(position.blockHash ?? "").trim().toLowerCase(),
    ...(position.blockHeight !== undefined
      ? { closedBlockHeight: position.blockHeight }
      : {}),
    ...(position.blockIndex !== undefined
      ? { closedBlockIndex: position.blockIndex }
      : {}),
    closedConfirmed: payload?.confirmed === true,
    closedFrozenNetworkValueSats: rowNumber(
      payload,
      "closedFrozenNetworkValueSats",
    ),
    closedLiveNetworkValueSats: rowNumber(payload, "closedLiveNetworkValueSats"),
    closedMinerFeeSats: rowNumber(payload, "closedMinerFeeSats"),
    canonicalMinerFeeCovered: payload?.canonicalMinerFeeCovered === true,
    canonicalMinerFeeSats: rowNumber(payload, "canonicalMinerFeeSats"),
    closedMinerFeeCanonical: payload?.canonicalMinerFeeCovered === true,
    closedMinerFeeSource:
      payload?.canonicalMinerFeeCovered === true
        ? String(payload?.minerFeeSource ?? "").trim()
        : String(payload?.closedMinerFeeSource ?? "").trim(),
    ...(position.protocolVout !== undefined
      ? { closedProtocolVout: position.protocolVout }
      : {}),
    ...(position.recordOrdinal !== undefined
      ? { closedRecordOrdinal: position.recordOrdinal }
      : {}),
    closedTxid: String(payload?.txid ?? "").trim().toLowerCase(),
    confirmed: true,
    createdAt,
    dataBytes: rowNumber(payload, "dataBytes"),
    frozenNetworkValueSats: rowNumber(payload, "frozenNetworkValueSats"),
    liveNetworkValueSats: rowNumber(payload, "liveNetworkValueSats"),
    marketplaceMutationFeeSats: rowNumber(payload, "marketplaceMutationFeeSats"),
    minerFeeSats: rowNumber(payload, "minerFeeSats"),
    minerFeeSource: String(payload?.minerFeeSource ?? "").trim(),
    listingId: String(payload?.listingId ?? "").trim().toLowerCase(),
    network: payload?.network,
    priceSats:
      rowNumber(payload, "priceSats") ||
      rowNumber(payload, "salePriceSats") ||
      priceSats,
    registryAddress,
    saleAuthorization: objectRecord(payload?.saleAuthorization),
    sealAt: dateIso(payload?.sealAt),
    sealConfirmed: payload?.sealConfirmed === true,
    sealDataBytes: rowNumber(payload, "sealDataBytes"),
    sealMinerFeeSats: rowNumber(payload, "sealMinerFeeSats"),
    sealTxid: String(payload?.sealTxid ?? "").trim().toLowerCase(),
    sellerAddress,
    ticker,
    tokenId,
  };
}

function tokenTransferFromEventPayload(payload, row = {}) {
  const ticker = String(row.ticker ?? payload?.ticker ?? "").trim();
  const tokenId = String(payload?.tokenId ?? row.token_id ?? "")
    .trim()
    .toLowerCase();
  const senderAddress = String(
    payload?.senderAddress ?? payload?.from ?? payload?.actor ?? "",
  ).trim();
  const recipientAddress = String(
    payload?.recipientAddress ?? payload?.to ?? payload?.counterparty ?? "",
  ).trim();
  const registryAddress = tokenRegistryAddressFromPayload(
    payload,
    senderAddress,
    recipientAddress,
    row.registry_address,
  );
  const workAmount = isWorkTokenId(tokenId)
    ? workAmountProjection(payload)
    : null;
  const amount = workAmount
    ? workAmount.amount
    : isBondTokenId(tokenId)
      ? exactBondUnits(payload?.amount ?? payload?.tokenAmount, {
          positive: true,
        })
    : rowNumber(payload, "amount") ||
      rowNumber(payload, "tokenAmount") ||
      tokenTransferAmountFromTags(payload, ticker);
  const position = canonicalMovementPositionFromEventRow(payload, row);
  return {
    ...canonicalEventIdentityDetails({
      ...payload,
      eventId: payload?.eventId ?? row?.event_id,
    }),
    ...position,
    amount,
    ...(workAmount
      ? workAmountProjectionMetadataForAmount(workAmount)
      : {}),
    confirmed:
      row.status === "confirmed" || payload?.confirmed === true,
    createdAt: dateIso(
      payload?.createdAt ?? row.event_time ?? row.block_time ?? row.created_at,
    ),
    dataBytes: rowNumber(payload, "dataBytes"),
    arbSats: rowNumber(payload, "arbSats"),
    creditAmountMoved: isBondTokenId(tokenId)
      ? exactBondUnits(payload?.creditAmountMoved ?? amount, {
          positive: true,
        })
      : rowNumber(payload, "creditAmountMoved"),
    creditFloorAtConfirmSats: rowNumber(payload, "creditFloorAtConfirmSats"),
    creditLiveFloorSats: rowNumber(payload, "creditLiveFloorSats"),
    creditLiveValueSats: rowNumber(payload, "creditLiveValueSats"),
    creditValueAtConfirmSats: rowNumber(payload, "creditValueAtConfirmSats"),
    frozenNetworkValueSats: rowNumber(payload, "frozenNetworkValueSats"),
    liveNetworkValueSats: rowNumber(payload, "liveNetworkValueSats"),
    minerFeeSats: rowNumber(payload, "minerFeeSats"),
    network: payload?.network ?? row.network,
    paidSats: rowNumber(payload, "paidSats") || rowNumber(payload, "amountSats"),
    recipientAddress,
    registryMutationFeeSats: rowNumber(payload, "registryMutationFeeSats"),
    registryAddress,
    senderAddress,
    ticker,
    tokenId,
    txid: String(payload?.txid ?? row.txid ?? "").trim().toLowerCase(),
  };
}

function exactSafeInteger(value, { positive = false } = {}) {
  return safeIntegerNumber(
    canonicalIntegerText(value, { allowZero: !positive }),
  );
}

function isBondTokenId(tokenId) {
  return BOND_TOKEN_IDS.has(String(tokenId ?? "").trim().toLowerCase());
}

function exactBondUnits(value, { positive = false, signed = false } = {}) {
  return canonicalIntegerText(value, {
    allowNegative: signed,
    allowZero: !positive,
  });
}

function canonicalIncbAttachedWorkQuantity(payload = {}) {
  const source = objectRecord(payload);
  const storageModel = String(
    source.attachedWorkAmountStorageModel ?? "",
  );
  const amountVersion = String(
    source.attachedWorkAmountVersion ?? "",
  );
  const atomFieldPresent =
    source.attachedWorkAmountAtoms !== undefined &&
    source.attachedWorkAmountAtoms !== null &&
    source.attachedWorkAmountAtoms !== "";
  const subatomFieldPresent =
    source.attachedWorkAmountSubatoms !== undefined &&
    source.attachedWorkAmountSubatoms !== null &&
    source.attachedWorkAmountSubatoms !== "";
  if (storageModel === WORK_SUBATOM_PROJECTION_MODEL) {
    let amountSubatoms = "";
    try {
      amountSubatoms = normalizeWorkSubatoms(
        source.attachedWorkAmountSubatoms,
        { allowZero: true },
      );
    } catch {
      amountSubatoms = "";
    }
    if (
      !subatomFieldPresent ||
      atomFieldPresent ||
      !amountSubatoms ||
      BigInt(amountSubatoms) >
        BigInt(WORK_TOKEN_MAX_SUPPLY_SUBATOMS) ||
      amountVersion !== WORK_AMO_V8_TRANSFER_VERSION ||
      Number(source.attachedWorkAmountDecimals) !==
        WORK_SUBATOM_DECIMALS ||
      String(source.attachedWorkAmountUnitScale ?? "") !==
        WORK_SUBATOM_UNIT_SCALE_TEXT ||
      String(source.attachedWorkAmountPrecisionModel ?? "") !==
        WORK_PRECISION_V2_MODEL
    ) {
      return null;
    }
    return {
      amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
      amountSubatoms,
      amountVersion,
      decimals: WORK_SUBATOM_DECIMALS,
      precisionModel: WORK_PRECISION_V2_MODEL,
      unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
    };
  }
  if (
    storageModel !== "" &&
    storageModel !== WORK_ATOMIC_PROJECTION_MODEL
  ) {
    return null;
  }
  let amountAtoms = "";
  try {
    amountAtoms = normalizeWorkAtoms(
      source.attachedWorkAmountAtoms,
      { allowZero: true },
    );
  } catch {
    amountAtoms = "";
  }
  if (
    !atomFieldPresent ||
    subatomFieldPresent ||
    !amountAtoms ||
    BigInt(amountAtoms) > BigInt(WORK_TOKEN_MAX_SUPPLY_ATOMS)
  ) {
    return null;
  }
  const explicitLegacyMetadata =
    storageModel === WORK_ATOMIC_PROJECTION_MODEL ||
    amountVersion !== "" ||
    source.attachedWorkAmountDecimals !== undefined ||
    source.attachedWorkAmountUnitScale !== undefined ||
    source.attachedWorkAmountPrecisionModel !== undefined;
  if (
    explicitLegacyMetadata &&
    (
      storageModel !== WORK_ATOMIC_PROJECTION_MODEL ||
      !["historical-q8", "send", "send2"].includes(
        amountVersion,
      ) ||
      Number(source.attachedWorkAmountDecimals) !== WORK_DECIMALS ||
      String(source.attachedWorkAmountUnitScale ?? "") !==
        WORK_UNIT_SCALE_TEXT ||
      String(source.attachedWorkAmountPrecisionModel ?? "") !== ""
    )
  ) {
    return null;
  }
  return {
    amountAtoms,
    amountStorageModel: WORK_ATOMIC_PROJECTION_MODEL,
    amountSubatoms: legacyWorkAtomsToSubatoms(amountAtoms, {
      allowZero: true,
    }),
    amountVersion: amountVersion || "historical-q8",
    decimals: WORK_DECIMALS,
    precisionModel: "",
    unitScale: WORK_UNIT_SCALE_TEXT,
  };
}

function incbExactIssuanceMetadata(payload = {}) {
  const fieldNames = [
    "attachedWorkAmountAtoms",
    "attachedWorkAmountSubatoms",
    "attachedWorkAmountStorageModel",
    "attachedWorkLiveValueAtSendQ8",
    "issuanceDustQ8",
    "issuanceNetworkValueQ8",
    "issuanceValueSnapshotWorkNetworkValueQ8",
  ];
  const present = fieldNames.some(
    (field) =>
      payload?.[field] !== undefined &&
      payload?.[field] !== null &&
      payload?.[field] !== "",
  );
  if (!present) {
    return { complete: false, fault: "", present: false };
  }

  const attachedWork = canonicalIncbAttachedWorkQuantity(payload);
  const exact = {
    attachedWorkLiveValueAtSendQ8: canonicalIntegerText(
      payload?.attachedWorkLiveValueAtSendQ8,
    ),
    issuanceDustQ8: canonicalIntegerText(payload?.issuanceDustQ8),
    issuanceNetworkValueQ8: canonicalIntegerText(
      payload?.issuanceNetworkValueQ8,
      { allowZero: false },
    ),
    issuanceValueSnapshotWorkNetworkValueQ8: canonicalIntegerText(
      payload?.issuanceValueSnapshotWorkNetworkValueQ8,
      { allowZero: false },
    ),
  };
  if (
    !attachedWork ||
    Object.values(exact).some((value) => !value)
  ) {
    return {
      ...exact,
      complete: false,
      fault:
        "fractional exact issuance metadata is incomplete or noncanonical",
      present: true,
    };
  }

  const directUnitsText = canonicalIntegerText(
    payload?.directProofIssuanceUnits ??
      payload?.proofPaymentSats ??
      payload?.bondRecipientAmountSats,
    { allowZero: false },
  );
  if (!directUnitsText) {
    return {
      ...exact,
      complete: false,
      fault: "direct proof issuance units are missing or noncanonical",
      present: true,
    };
  }

  const attachedWorkAmountSubatoms = BigInt(
    attachedWork.amountSubatoms,
  );
  const attachedWorkLiveValueAtSendQ8 = BigInt(
    exact.attachedWorkLiveValueAtSendQ8,
  );
  const issuanceDustQ8 = BigInt(exact.issuanceDustQ8);
  const issuanceNetworkValueQ8 = BigInt(exact.issuanceNetworkValueQ8);
  const snapshotWorkNetworkValueQ8 = BigInt(
    exact.issuanceValueSnapshotWorkNetworkValueQ8,
  );
  const directUnits = BigInt(directUnitsText);
  const amount = issuanceNetworkValueQ8 / BOND_VALUE_Q8_SCALE;
  const attachedUnits =
    attachedWorkLiveValueAtSendQ8 / BOND_VALUE_Q8_SCALE;
  const expectedAttachedValueQ8 =
    (attachedWorkAmountSubatoms * snapshotWorkNetworkValueQ8) /
    (
      21_000_000n *
      BigInt(WORK_SUBATOM_UNIT_SCALE_TEXT)
    );
  let declaredAttachedWorkAmountUnits = "";
  try {
    declaredAttachedWorkAmountUnits =
      attachedWork.amountStorageModel ===
        WORK_SUBATOM_PROJECTION_MODEL
        ? parseWorkAmountToSubatoms(payload?.attachedWorkAmount, {
            allowZero: true,
          })
        : parseWorkAmountToAtoms(payload?.attachedWorkAmount, {
            allowZero: true,
          });
  } catch {
    declaredAttachedWorkAmountUnits = "";
  }
  const expectedDeclaredWorkAmountUnits =
    attachedWork.amountStorageModel ===
      WORK_SUBATOM_PROJECTION_MODEL
      ? attachedWork.amountSubatoms
      : attachedWork.amountAtoms;
  if (
    declaredAttachedWorkAmountUnits !==
      expectedDeclaredWorkAmountUnits ||
    attachedWorkLiveValueAtSendQ8 !== expectedAttachedValueQ8 ||
    issuanceNetworkValueQ8 !==
      directUnits * BOND_VALUE_Q8_SCALE + attachedWorkLiveValueAtSendQ8 ||
    issuanceDustQ8 !== issuanceNetworkValueQ8 % BOND_VALUE_Q8_SCALE
  ) {
    return {
      ...exact,
      complete: false,
      fault:
        declaredAttachedWorkAmountUnits !==
          expectedDeclaredWorkAmountUnits
          ? "fractional exact issuance metadata disagrees with projected values"
          : "fractional exact issuance metadata does not conserve value",
      present: true,
    };
  }

  const declaredUnitFields = [
    ["amount", amount],
    ["issuanceAmount", amount],
    ["confirmedIssuanceUnits", amount],
    ["attachedWorkIssuanceUnits", attachedUnits],
  ];
  for (const [field, expected] of declaredUnitFields) {
    const declared = canonicalIntegerText(payload?.[field]);
    // Legacy JSON numbers above 2^53 are already lossy compatibility fields.
    // Exact Q8 metadata is authoritative and reconstructs the canonical unit
    // value. Canonical string or safe-number declarations still have to agree.
    if (declared && BigInt(declared) !== expected) {
      return {
        ...exact,
        complete: false,
        fault: `exact issuance metadata disagrees with ${field}`,
        present: true,
      };
    }
  }

  return {
    ...exact,
    attachedWorkAmount: formatWorkSubatoms(
      attachedWork.amountSubatoms,
    ),
    attachedWorkAmountDecimals: attachedWork.decimals,
    attachedWorkAmountStorageModel:
      attachedWork.amountStorageModel,
    attachedWorkAmountUnitScale: attachedWork.unitScale,
    attachedWorkAmountVersion: attachedWork.amountVersion,
    ...(attachedWork.amountStorageModel ===
      WORK_SUBATOM_PROJECTION_MODEL
      ? {
          attachedWorkAmountSubatoms:
            attachedWork.amountSubatoms,
        }
      : {}),
    ...(attachedWork.precisionModel
      ? {
          attachedWorkAmountPrecisionModel:
            attachedWork.precisionModel,
        }
      : {}),
    ...(attachedWork.amountAtoms
      ? { attachedWorkAmountAtoms: attachedWork.amountAtoms }
      : BigInt(attachedWork.amountSubatoms) %
            WORK_SUBATOM_CONVERSION_FACTOR ===
          0n
        ? {
            attachedWorkAmountAtoms: (
              BigInt(attachedWork.amountSubatoms) /
              WORK_SUBATOM_CONVERSION_FACTOR
            ).toString(),
          }
        : {}),
    amount: amount.toString(),
    attachedWorkIssuanceUnits: attachedUnits.toString(),
    complete: true,
    confirmedIssuanceUnits: amount.toString(),
    directProofIssuanceUnits: directUnits.toString(),
    fault: "",
    issuanceAmount: amount.toString(),
    present: true,
  };
}

function incbIssuanceMetadataFault(payload, row = {}) {
  const tokenId = String(payload?.tokenId ?? row?.token_id ?? "")
    .trim()
    .toLowerCase();
  if (tokenId !== INCB_TOKEN_ID) {
    return "";
  }
  const effectiveStatus = String(row?.effective_status ?? row?.status ?? "")
    .trim()
    .toLowerCase();
  if (effectiveStatus !== "confirmed" && payload?.confirmed !== true) {
    return "";
  }
  if (
    String(payload?.issuanceAccountingModel ?? "") !==
    INCB_ISSUANCE_ACCOUNTING_MODEL
  ) {
    return "missing canonical pre-bond live-value accounting model";
  }
  const minterAddress = String(payload?.minterAddress ?? "").trim();
  const bondRecipientAddress = String(
    payload?.bondRecipientAddress ?? "",
  ).trim();
  const bondRecipientAmount = exactSafeInteger(
    payload?.bondRecipientAmountSats,
    { positive: true },
  );
  const bondRecipientVout = exactSafeInteger(payload?.bondRecipientVout);
  if (
    !minterAddress ||
    bondRecipientAddress !== minterAddress ||
    bondRecipientAmount === null ||
    bondRecipientVout === null ||
    payload?.issuanceValuationFixedAtSend !== true ||
    Number(payload?.issuanceUnitSats) !== 1
  ) {
    return "canonical Inception Bond recipient is missing";
  }
  const exactIssuance = incbExactIssuanceMetadata(payload);
  if (exactIssuance.fault) {
    return exactIssuance.fault;
  }
  const amountText = exactIssuance.complete
    ? exactIssuance.amount
    : exactBondUnits(payload?.amount, { positive: true });
  const issuanceAmountText = exactIssuance.complete
    ? exactIssuance.issuanceAmount
    : exactBondUnits(payload?.issuanceAmount, { positive: true });
  const confirmedIssuanceUnitsText = exactIssuance.complete
    ? exactIssuance.confirmedIssuanceUnits
    : exactBondUnits(payload?.confirmedIssuanceUnits, { positive: true });
  const directProofIssuanceUnitsText = exactIssuance.complete
    ? exactIssuance.directProofIssuanceUnits
    : exactBondUnits(payload?.directProofIssuanceUnits);
  const attachedWorkIssuanceUnitsText = exactIssuance.complete
    ? exactIssuance.attachedWorkIssuanceUnits
    : exactBondUnits(payload?.attachedWorkIssuanceUnits);
  const amount = integerBigInt(amountText, { allowZero: false });
  const issuanceAmount = integerBigInt(issuanceAmountText, {
    allowZero: false,
  });
  const confirmedIssuanceUnits = integerBigInt(confirmedIssuanceUnitsText, {
    allowZero: false,
  });
  const directProofIssuanceUnits = integerBigInt(
    directProofIssuanceUnitsText,
  );
  const attachedWorkIssuanceUnits = integerBigInt(
    attachedWorkIssuanceUnitsText,
  );
  if (
    amount === null ||
    issuanceAmount !== amount ||
    confirmedIssuanceUnits !== amount ||
    directProofIssuanceUnits === null ||
    directProofIssuanceUnits <= 0n ||
    attachedWorkIssuanceUnits === null ||
    directProofIssuanceUnits + attachedWorkIssuanceUnits !== amount
  ) {
    return "issuance units are missing or do not conserve supply";
  }
  const issuanceNetworkValueSats = exactIssuance.complete
    ? null
    : Number(payload?.issuanceNetworkValueSats);
  const issuanceDustSats = exactIssuance.complete
    ? null
    : Number(payload?.issuanceDustSats);
  const issuanceFloorSats = exactIssuance.complete
    ? null
    : Number(payload?.issuanceFloorSats);
  const attachedWorkLiveValueAtSendSats = exactIssuance.complete
    ? null
    : Number(payload?.attachedWorkLiveValueAtSendSats);
  if (
    !exactIssuance.complete &&
    (!Number.isFinite(issuanceNetworkValueSats) ||
      issuanceNetworkValueSats <= 0 ||
      BigInt(Math.floor(issuanceNetworkValueSats)) !== amount ||
      !Number.isFinite(issuanceDustSats) ||
      issuanceDustSats < 0 ||
      issuanceDustSats >= 1 ||
      Math.abs(
        issuanceDustSats - (issuanceNetworkValueSats - Number(amount)),
      ) > 1e-6 ||
      !Number.isFinite(issuanceFloorSats) ||
      issuanceFloorSats < 1 ||
      Math.abs(issuanceFloorSats - issuanceNetworkValueSats / Number(amount)) >
        1e-9 ||
      !Number.isFinite(attachedWorkLiveValueAtSendSats) ||
      attachedWorkLiveValueAtSendSats < 0 ||
      BigInt(Math.floor(attachedWorkLiveValueAtSendSats)) !==
        attachedWorkIssuanceUnits ||
      Math.abs(
        issuanceNetworkValueSats -
          (Number(directProofIssuanceUnits) +
            attachedWorkLiveValueAtSendSats),
      ) > 1e-6)
  ) {
    return "issuance value, dust, or one-proof unit floor is inconsistent";
  }
  const directProofPayment = exactSafeInteger(
    payload?.proofPaymentSats ?? payload?.paidSats,
  );
  if (
    BigInt(directProofPayment ?? -1) !== directProofIssuanceUnits ||
    BigInt(bondRecipientAmount ?? -1) !== directProofIssuanceUnits
  ) {
    return "direct issuance does not equal the confirmed proof payment";
  }
  if (exactIssuance.complete) {
    if (
      BigInt(exactIssuance.issuanceValueSnapshotWorkNetworkValueQ8) <= 0n
    ) {
      return "attached WORK valuation basis is missing or inconsistent";
    }
  } else if (attachedWorkIssuanceUnits > 0n) {
    const attachedWorkAmount = exactSafeInteger(payload?.attachedWorkAmount, {
      positive: true,
    });
    const attachedWorkLiveFloorAtSendSats = Number(
      payload?.attachedWorkLiveFloorAtSendSats,
    );
    if (
      attachedWorkAmount === null ||
      !Number.isFinite(attachedWorkLiveFloorAtSendSats) ||
      attachedWorkLiveFloorAtSendSats <= 0 ||
      Math.abs(
        attachedWorkLiveValueAtSendSats -
          attachedWorkAmount * attachedWorkLiveFloorAtSendSats,
      ) > 1e-5
    ) {
      return "attached WORK valuation basis is missing or inconsistent";
    }
  } else if (attachedWorkLiveValueAtSendSats !== 0) {
    return "proof-only issuance carries attached WORK value";
  }
  const checkpointMode = String(payload?.issuanceCheckpointMode ?? "");
  const checkpointHeight = exactSafeInteger(
    payload?.issuanceCheckpointBlockHeight,
    { positive: true },
  );
  const checkpointHash = String(
    payload?.issuanceCheckpointBlockHash ?? "",
  )
    .trim()
    .toLowerCase();
  const checkpointIndex = exactSafeInteger(
    payload?.issuanceCheckpointBlockIndex,
  );
  const checkpointWorkNetworkValueSats = exactIssuance.complete
    ? null
    : Number(payload?.issuanceValueSnapshotWorkNetworkValueSats);
  const attachedWorkLiveFloorAtSendSats = exactIssuance.complete
    ? null
    : Number(payload?.attachedWorkLiveFloorAtSendSats);
  if (
    checkpointMode !== "bond-transaction-provenance" ||
    checkpointHeight === null ||
    !/^[0-9a-f]{64}$/u.test(checkpointHash) ||
    checkpointIndex === null ||
    (exactIssuance.complete
      ? BigInt(exactIssuance.issuanceValueSnapshotWorkNetworkValueQ8) <= 0n
      : !Number.isFinite(checkpointWorkNetworkValueSats) ||
        checkpointWorkNetworkValueSats <= 0 ||
        !Number.isFinite(attachedWorkLiveFloorAtSendSats) ||
        attachedWorkLiveFloorAtSendSats <= 0 ||
        Math.abs(
          attachedWorkLiveFloorAtSendSats -
            checkpointWorkNetworkValueSats / 21_000_000,
        ) > 1e-9)
  ) {
    return "pre-bond valuation checkpoint is missing or inconsistent";
  }
  const valueSnapshotHeight = exactSafeInteger(
    payload?.issuanceValueSnapshotBlockHeight,
    { positive: true },
  );
  const valueSnapshotHash = String(
    payload?.issuanceValueSnapshotBlockHash ?? "",
  )
    .trim()
    .toLowerCase();
  const valueSnapshotCanonicalSummaryHash = String(
    payload?.issuanceValueSnapshotCanonicalSummaryHash ?? "",
  )
    .trim()
    .toLowerCase();
  const valueSnapshotGeneratedAt = String(
    payload?.issuanceValueSnapshotGeneratedAt ?? "",
  ).trim();
  if (
    payload?.issuanceValueSnapshotModel !== INCB_VALUE_SNAPSHOT_MODEL ||
    payload?.issuanceValueSnapshotMode !== "canonical-summary-refresh" ||
    valueSnapshotHeight !== checkpointHeight - 1 ||
    !/^[0-9a-f]{64}$/u.test(valueSnapshotHash) ||
    !/^[0-9a-f]{64}$/u.test(valueSnapshotCanonicalSummaryHash) ||
    !String(payload?.issuanceValueSnapshotId ?? "").trim() ||
    !Number.isFinite(Date.parse(valueSnapshotGeneratedAt))
  ) {
    return "H-1 canonical WORK value snapshot provenance is missing or inconsistent";
  }
  const txid = String(payload?.txid ?? row?.txid ?? "")
    .trim()
    .toLowerCase();
  const canonicalBlockHeight = exactSafeInteger(
    row?.block_height ??
      row?.transaction_block_height ??
      payload?.blockHeight,
    { positive: true },
  );
  const canonicalBlockHash = String(
    row?.block_hash ?? payload?.blockHash ?? payload?._powBlockHash ?? "",
  )
    .trim()
    .toLowerCase();
  const canonicalBlockIndex = exactSafeInteger(
    row?.block_index ?? payload?.blockIndex ?? payload?._powBlockIndex,
  );
  if (
    String(payload?.ticker ?? "").trim().toUpperCase() !== "INCB" ||
    String(payload?.sourceBondTxid ?? "").trim().toLowerCase() !== txid ||
    !/^[0-9a-f]{64}$/u.test(txid) ||
    String(payload?.validationMode ?? "") !==
      "canonical-incb-bond-projection" ||
    Number(payload?.amountSats) !== 0 ||
    canonicalBlockHeight !== checkpointHeight ||
    canonicalBlockHash !== checkpointHash ||
    canonicalBlockIndex !== checkpointIndex
  ) {
    return "mint is not bound to its canonical Inception Bond projection";
  }
  return "";
}

function assertCanonicalIncbDefinition(token, context) {
  if (String(token?.tokenId ?? "").trim().toLowerCase() !== INCB_TOKEN_ID) {
    return;
  }
  if (
    token?.issuanceAccountingModel !== INCB_ISSUANCE_ACCOUNTING_MODEL ||
    token?.issuanceValuationFixedAtSend !== true ||
    Number(token?.issuanceUnitSats) !== 1
  ) {
    throw new Error(
      `${context} cannot publish INCB without the canonical pre-bond live-value definition.`,
    );
  }
}

function canonicalLegacyDecimalValue(payload, field) {
  const value = payload?.[field];
  if (typeof value === "string") {
    const text = value.trim();
    const q8 = q8TextFromDecimal(text);
    if (q8) {
      return decimalTextFromQ8(q8);
    }
    const exactDecimal = /^(0|[1-9][0-9]*)(?:\.([0-9]+))?$/u.exec(text);
    if (!exactDecimal) {
      throw new Error(`Invalid exact legacy decimal alias for ${field}.`);
    }
    const fraction = (exactDecimal[2] ?? "").replace(/0+$/u, "");
    return `${exactDecimal[1]}${fraction ? `.${fraction}` : ""}`;
  }
  return rowNumber(payload, field);
}

function tokenMintFromEventPayload(payload, row = {}) {
  // node-postgres decodes JSONB numbers as binary JavaScript Numbers. Legacy
  // INCB rows predate explicit Q8 fields, so preserve the exact decimal text
  // selected alongside the JSONB payload before validating or aggregating it.
  // Exact Q8 metadata on current rows remains authoritative.
  const legacyDecimalColumns = [
    [
      "attachedWorkLiveFloorAtSendSats",
      "attached_work_live_floor_at_send_sats_text",
    ],
    [
      "attachedWorkLiveValueAtSendSats",
      "attached_work_live_value_at_send_sats_text",
    ],
    ["issuanceDustSats", "issuance_dust_sats_text"],
    ["issuanceFloorSats", "issuance_floor_sats_text"],
    ["issuanceNetworkValueSats", "issuance_network_value_sats_text"],
    [
      "issuanceValueSnapshotWorkNetworkValueSats",
      "issuance_value_snapshot_work_network_value_sats_text",
    ],
  ];
  const exactLegacyPayload = { ...payload };
  for (const [payloadField, rowField] of legacyDecimalColumns) {
    const exactDecimal = String(row?.[rowField] ?? "").trim();
    if (exactDecimal) {
      exactLegacyPayload[payloadField] = exactDecimal;
    }
  }
  payload = exactLegacyPayload;
  const tagNumbers = tokenMarketNumbersFromTags(payload);
  const tokenId = String(payload?.tokenId ?? row.token_id ?? "")
    .trim()
    .toLowerCase();
  const workAmount = isWorkTokenId(tokenId)
    ? workAmountProjection(payload)
    : null;
  const ticker = String(row.ticker ?? payload?.ticker ?? tagNumbers.ticker ?? "")
    .trim();
  const minterAddress = String(
    payload?.minterAddress ??
      payload?.actor ??
      payload?.senderAddress ??
      "",
  ).trim();
  const registryAddress = String(
    payload?.registryAddress ??
      row.registry_address ??
      payload?.counterparty ??
      "",
  ).trim();
  const effectiveStatus = String(row.effective_status ?? row.status ?? "")
    .trim()
    .toLowerCase();

  const issuanceFault = incbIssuanceMetadataFault(payload, row);
  if (issuanceFault) {
    throw new Error(
      `Proof index INCB mint ${String(payload?.txid ?? row?.txid ?? "unknown")} is invalid: ${issuanceFault}.`,
    );
  }
  const exactIncbIssuance =
    tokenId === INCB_TOKEN_ID
      ? incbExactIssuanceMetadata(payload)
      : { complete: false };
  const bondAmount = isBondTokenId(tokenId)
    ? tokenId === INCB_TOKEN_ID && exactIncbIssuance.complete
      ? exactIncbIssuance.amount
      : exactBondUnits(payload?.amount ?? payload?.tokenAmount, {
          positive: true,
        })
    : "";
  const position = canonicalMovementPositionFromEventRow(payload, row);

  return {
    ...canonicalEventIdentityDetails({
      ...payload,
      eventId: payload?.eventId ?? row?.event_id,
    }),
    ...position,
    amount: workAmount
      ? workAmount.amount
      : bondAmount ||
        rowNumber(payload, "amount") ||
        rowNumber(payload, "tokenAmount") ||
        tagNumbers.amount,
    ...(workAmount
      ? workAmountProjectionMetadataForAmount(workAmount)
      : {}),
    amountSats: rowNumber(payload, "amountSats"),
    bondRecipientAddress: String(payload?.bondRecipientAddress ?? "").trim(),
    bondRecipientAmountSats: rowNumber(payload, "bondRecipientAmountSats"),
    bondRecipientVout: rowNumber(payload, "bondRecipientVout"),
    attachedWorkAmount: exactIncbIssuance.complete
      ? exactIncbIssuance.attachedWorkAmount
      : rowNumber(payload, "attachedWorkAmount"),
    ...(exactIncbIssuance.complete
      ? {
          attachedWorkAmountDecimals:
            exactIncbIssuance.attachedWorkAmountDecimals,
          attachedWorkAmountStorageModel:
            exactIncbIssuance.attachedWorkAmountStorageModel,
          ...(exactIncbIssuance.attachedWorkAmountSubatoms
            ? {
                attachedWorkAmountSubatoms:
                  exactIncbIssuance.attachedWorkAmountSubatoms,
              }
            : {}),
          attachedWorkAmountUnitScale:
            exactIncbIssuance.attachedWorkAmountUnitScale,
          attachedWorkAmountVersion:
            exactIncbIssuance.attachedWorkAmountVersion,
          ...(exactIncbIssuance.attachedWorkAmountPrecisionModel
            ? {
                attachedWorkAmountPrecisionModel:
                  exactIncbIssuance.attachedWorkAmountPrecisionModel,
              }
            : {}),
          ...(exactIncbIssuance.attachedWorkAmountAtoms
            ? {
                attachedWorkAmountAtoms:
                  exactIncbIssuance.attachedWorkAmountAtoms,
              }
            : {}),
          attachedWorkLiveValueAtSendQ8:
            exactIncbIssuance.attachedWorkLiveValueAtSendQ8,
        }
      : {}),
    attachedWorkLiveFloorAtSendSats: exactIncbIssuance.complete
      ? decimalTextFromQ8(
          (
            BigInt(
              exactIncbIssuance.issuanceValueSnapshotWorkNetworkValueQ8,
            ) / 21_000_000n
          ).toString(),
        )
      : canonicalLegacyDecimalValue(
          payload,
          "attachedWorkLiveFloorAtSendSats",
        ),
    ...(exactIncbIssuance.complete
      ? {
          attachedWorkLiveFloorAtSendQ8: (
            BigInt(
              exactIncbIssuance.issuanceValueSnapshotWorkNetworkValueQ8,
            ) / 21_000_000n
          ).toString(),
        }
      : {}),
    attachedWorkIssuanceUnits: exactIncbIssuance.complete
      ? exactIncbIssuance.attachedWorkIssuanceUnits
      : rowNumber(payload, "attachedWorkIssuanceUnits"),
    attachedWorkLiveValueAtSendSats: exactIncbIssuance.complete
      ? decimalTextFromQ8(exactIncbIssuance.attachedWorkLiveValueAtSendQ8)
      : canonicalLegacyDecimalValue(
          payload,
          "attachedWorkLiveValueAtSendSats",
        ),
    confirmed: effectiveStatus === "confirmed" || payload?.confirmed === true,
    createdAt: dateIso(
      payload?.createdAt ??
        row.block_time ??
        row.event_time ??
        row.confirmed_at ??
        row.last_seen_at ??
        row.created_at,
    ),
    dataBytes: rowNumber(payload, "dataBytes") || rowNumber(row, "data_bytes"),
    confirmedIssuanceUnits: exactIncbIssuance.complete
      ? exactIncbIssuance.confirmedIssuanceUnits
      : rowNumber(payload, "confirmedIssuanceUnits"),
    directProofIssuanceUnits: exactIncbIssuance.complete
      ? exactIncbIssuance.directProofIssuanceUnits
      : rowNumber(payload, "directProofIssuanceUnits"),
    issuanceAccountingModel: String(
      payload?.issuanceAccountingModel ?? "",
    ),
    issuanceAmount: exactIncbIssuance.complete
      ? exactIncbIssuance.issuanceAmount
      : rowNumber(payload, "issuanceAmount"),
    issuanceDustSats: exactIncbIssuance.complete
      ? decimalTextFromQ8(exactIncbIssuance.issuanceDustQ8)
      : canonicalLegacyDecimalValue(payload, "issuanceDustSats"),
    ...(exactIncbIssuance.complete
      ? { issuanceDustQ8: exactIncbIssuance.issuanceDustQ8 }
      : {}),
    issuanceFloorSats: exactIncbIssuance.complete
      ? decimalTextFromQ8(
          (
            BigInt(exactIncbIssuance.issuanceNetworkValueQ8) /
            BigInt(exactIncbIssuance.confirmedIssuanceUnits)
          ).toString(),
        )
      : canonicalLegacyDecimalValue(payload, "issuanceFloorSats"),
    ...(exactIncbIssuance.complete
      ? {
          issuanceFloorQ8: (
            BigInt(exactIncbIssuance.issuanceNetworkValueQ8) /
            BigInt(exactIncbIssuance.confirmedIssuanceUnits)
          ).toString(),
        }
      : {}),
    issuanceNetworkValueSats: exactIncbIssuance.complete
      ? decimalTextFromQ8(exactIncbIssuance.issuanceNetworkValueQ8)
      : canonicalLegacyDecimalValue(payload, "issuanceNetworkValueSats"),
    ...(exactIncbIssuance.complete
      ? {
          issuanceNetworkValueQ8:
            exactIncbIssuance.issuanceNetworkValueQ8,
        }
      : {}),
    issuanceUnitSats: rowNumber(payload, "issuanceUnitSats"),
    issuanceValuationFixedAtSend:
      payload?.issuanceValuationFixedAtSend === true,
    issuanceCheckpointBlockHash: String(
      payload?.issuanceCheckpointBlockHash ?? "",
    )
      .trim()
      .toLowerCase(),
    issuanceCheckpointBlockHeight: rowNumber(
      payload,
      "issuanceCheckpointBlockHeight",
    ),
    issuanceCheckpointBlockIndex: rowNumber(
      payload,
      "issuanceCheckpointBlockIndex",
    ),
    issuanceCheckpointMode: String(
      payload?.issuanceCheckpointMode ?? "",
    ),
    issuanceValueSnapshotBlockHash: String(
      payload?.issuanceValueSnapshotBlockHash ?? "",
    )
      .trim()
      .toLowerCase(),
    issuanceValueSnapshotBlockHeight: rowNumber(
      payload,
      "issuanceValueSnapshotBlockHeight",
    ),
    issuanceValueSnapshotCanonicalSummaryHash: String(
      payload?.issuanceValueSnapshotCanonicalSummaryHash ?? "",
    )
      .trim()
      .toLowerCase(),
    issuanceValueSnapshotGeneratedAt: String(
      payload?.issuanceValueSnapshotGeneratedAt ?? "",
    ).trim(),
    issuanceValueSnapshotId: String(
      payload?.issuanceValueSnapshotId ?? "",
    ).trim(),
    issuanceValueSnapshotMode: String(
      payload?.issuanceValueSnapshotMode ?? "",
    ).trim(),
    issuanceValueSnapshotModel: String(
      payload?.issuanceValueSnapshotModel ?? "",
    ).trim(),
    issuanceValueSnapshotWorkNetworkValueSats: exactIncbIssuance.complete
      ? decimalTextFromQ8(
          exactIncbIssuance.issuanceValueSnapshotWorkNetworkValueQ8,
        )
      : canonicalLegacyDecimalValue(
          payload,
          "issuanceValueSnapshotWorkNetworkValueSats",
        ),
    ...(exactIncbIssuance.complete
      ? {
          issuanceValueSnapshotWorkNetworkValueQ8:
            exactIncbIssuance.issuanceValueSnapshotWorkNetworkValueQ8,
        }
      : {}),
    minterAddress,
    minerFeeSats: rowNumber(payload, "minerFeeSats"),
    network: payload?.network ?? row.network,
    paidSats:
      rowNumber(payload, "proofPaymentSats") ||
      rowNumber(payload, "paidSats") ||
      rowNumber(payload, "amountSats") ||
      rowNumber(row, "amount_sats"),
    proofPaymentSats: rowNumber(payload, "proofPaymentSats"),
    registryAddress,
    sourceBondTxid: String(payload?.sourceBondTxid ?? "")
      .trim()
      .toLowerCase(),
    sourceKind: String(payload?.sourceKind ?? "").trim().toLowerCase(),
    status: effectiveStatus || undefined,
    ticker,
    tokenId,
    txid: String(payload?.txid ?? row.txid ?? "").trim().toLowerCase(),
    validationMode: String(payload?.validationMode ?? "").trim(),
  };
}

function tokenHistoryItemFromMarketEventPayload(
  payload,
  safeKind,
  row = {},
  amoV5RelicEvidence = null,
) {
  if (
    row?.work_amo_v5_pre_unit_relic_projection === true &&
    workAmoV5PreUnitRelicEvidenceIsExact(amoV5RelicEvidence) &&
    amoV5RelicEvidence.disposition === "relic"
  ) {
    const closedListing = {
      ...amoV5RelicEvidence.listing,
      closedAt: amoV5RelicEvidence.activationBlockTime,
      closedConfirmed: true,
      closedTxid: WORK_AMO_V5_DECLARATION_TXID,
      confirmed: true,
      disabledAtBlockHeight: WORK_AMO_V5_ACTIVATION_HEIGHT,
      disabledByTxid: WORK_AMO_V5_DECLARATION_TXID,
      disabledReason: WORK_AMO_V5_PRE_UNIT_RELIC_DISABLED_REASON,
      kind: "token-listing-closed",
      originalStatus: amoV5RelicEvidence.listing.status ?? "active",
      refundEligible: false,
      relic: true,
      status: "disabled",
      txid: WORK_AMO_V5_DECLARATION_TXID,
    };
    if (safeKind === "closedListings") {
      return closedListing;
    }
    if (safeKind === "market-log") {
      return {
        closedListing,
        createdAt: closedListing.closedAt,
        kind: "closed-listing",
        txid: closedListing.closedTxid,
      };
    }
    return null;
  }

  if (payload?.kind === "token-listing" || payload?.kind === "token-listings") {
    const listing = tokenListingFromEventPayload(payload, row);
    if (!activeTokenListingHistoryItem(listing)) {
      return null;
    }
    if (safeKind === "listings") {
      return listing;
    }
    return {
      createdAt: listing.createdAt,
      kind: "listing",
      listing,
      txid: listing.listingId,
    };
  }

  if (payload?.kind === "token-listing-sealed") {
    const listing = tokenListingFromEventPayload(
      {
        ...payload,
        sealAt: payload.sealAt ?? payload.createdAt,
        sealBlockHash: payload.sealBlockHash ?? payload.blockHash,
        sealBlockHeight: payload.sealBlockHeight ?? payload.blockHeight,
        sealBlockIndex: payload.sealBlockIndex ?? payload.blockIndex,
        sealConfirmed: payload.confirmed !== false,
        sealProtocolVout:
          payload.sealProtocolVout ?? payload.protocolVout,
        sealRecordOrdinal:
          payload.sealRecordOrdinal ?? payload.recordOrdinal,
        sealTxid: payload.sealTxid ?? payload.txid,
        status: "sealing",
      },
      row,
    );
    if (!activeTokenListingHistoryItem(listing)) {
      return null;
    }
    if (safeKind === "listings") {
      return listing;
    }
    return {
      createdAt: listing.sealAt ?? listing.createdAt,
      kind: "listing",
      listing,
      txid: listing.listingId,
    };
  }

  if (payload?.kind === "token-sale") {
    const sale = tokenSaleFromEventPayload(payload, row);
    if (!sale.txid || !sale.listingId || !sale.tokenId) {
      return null;
    }
    if (safeKind === "closedListings") {
      return tokenClosedListingFromSalePayload(sale);
    }
    if (safeKind === "sales") {
      return sale;
    }
    return {
      createdAt: sale.createdAt,
      kind: "sale",
      sale,
      txid: sale.txid,
    };
  }

  if (payload?.kind === "token-listing-closed") {
    const closedListing = tokenClosedListingFromEventPayload(payload, row);
    if (
      !closedListing.closedTxid ||
      !closedListing.listingId ||
      !closedListing.tokenId
    ) {
      return null;
    }
    if (safeKind === "closedListings") {
      return closedListing;
    }
    return {
      closedListing,
      createdAt: closedListing.closedAt ?? closedListing.createdAt,
      kind: "closed-listing",
      txid: closedListing.closedTxid || closedListing.listingId,
    };
  }

  return null;
}

function tokenClosedListingFromSalePayload(salePayload) {
  const sale = salePayload?.txid
    ? salePayload
    : tokenSaleFromEventPayload(salePayload);
  if (!sale?.txid || !sale?.listingId || !sale?.tokenId) {
    return null;
  }
  const exactPositionInteger = (value, minimum) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const blockHeight = exactPositionInteger(sale.blockHeight, 1);
  const blockIndex = exactPositionInteger(sale.blockIndex, 0);
  const protocolVout = exactPositionInteger(sale.protocolVout, 0);
  const recordOrdinal = exactPositionInteger(sale.recordOrdinal, 0);
  const postAmoV5Sale =
    sale.confirmed === true &&
    blockHeight !== null &&
    blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT;
  if (
    postAmoV5Sale &&
    (
      !/^[0-9a-f]{64}$/u.test(normalizedLowerText(sale.blockHash)) ||
      blockIndex === null ||
      protocolVout === null ||
      recordOrdinal === null
    )
  ) {
    return null;
  }
  return {
    ...sale,
    buyerAddress: sale.buyerAddress,
    closedAt: sale.createdAt,
    ...(sale.blockHash ? { closedBlockHash: sale.blockHash } : {}),
    ...(blockHeight !== null
      ? { closedBlockHeight: blockHeight }
      : {}),
    ...(blockIndex !== null
      ? { closedBlockIndex: blockIndex }
      : {}),
    closedConfirmed: sale.confirmed === true,
    ...(protocolVout !== null
      ? { closedProtocolVout: protocolVout }
      : {}),
    ...(recordOrdinal !== null
      ? { closedRecordOrdinal: recordOrdinal }
      : {}),
    closedTxid: sale.txid,
    confirmed: sale.confirmed === true,
    saleTxid: sale.txid,
    status: "sold",
    txid: sale.txid,
  };
}

function compareTokenItemsByTime(left, right) {
  const leftTime = Date.parse(left?.createdAt ?? left?.closedAt ?? "");
  const rightTime = Date.parse(right?.createdAt ?? right?.closedAt ?? "");
  return (
    (Number.isFinite(rightTime) ? rightTime : 0) -
      (Number.isFinite(leftTime) ? leftTime : 0) ||
    compareCanonicalUtf8(
      right?.txid ?? right?.closedTxid ?? right?.listingId,
      left?.txid ?? left?.closedTxid ?? left?.listingId,
    )
  );
}

function tokenHistoryMarketEventKinds(safeKind) {
  if (safeKind === "listings") {
    return ["token-listings", "token-listing", "token-listing-sealed"];
  }
  if (safeKind === "sales") {
    return ["token-sale"];
  }
  if (safeKind === "closedListings") {
    return ["token-listing-closed", "token-sale"];
  }
  if (safeKind === "market-log") {
    return [
      "token-listings",
      "token-listing",
      "token-listing-sealed",
      "token-sale",
      "token-listing-closed",
    ];
  }
  return [];
}

function tokenHistoryCanonicalMarketEventsSql(
  safeKind,
  whereClause,
  {
    amoV5RelicClosedAtSql = "NULL",
    amoV5RelicClosedTxidSql = "''",
    amoV5RelicPredicateSql = "false",
  } = {},
) {
  const listingKinds =
    "ARRAY['token-listings','token-listing','token-listing-sealed']::text[]";
  const amoV5Relic = `(${amoV5RelicPredicateSql})`;
  const listingId = `lower(COALESCE(
    NULLIF(e.payload->>'listingId', ''),
    NULLIF(cl_event.listing_id, ''),
    e.txid
  ))`;
  const targetTokenId = `lower(COALESCE(
    NULLIF(e.payload->>'tokenId', ''),
    NULLIF(e.payload->'saleAuthorization'->>'tokenId', ''),
    NULLIF(cl_event.token_id, ''),
    NULLIF(cl_event.payload->>'tokenId', ''),
    NULLIF(cl_event.payload->'saleAuthorization'->>'tokenId', ''),
    ''
  ))`;
  const targetSaleAuthorizationVersion = `lower(COALESCE(
    NULLIF(e.payload->'saleAuthorization'->>'version', ''),
    NULLIF(cl_event.payload->'saleAuthorization'->>'version', ''),
    ''
  ))`;
  const canonicalSaleKey = `CASE
    WHEN e.status = 'confirmed'
      AND e.block_height >= ${WORK_AMO_V5_ACTIVATION_HEIGHT}
      THEN 'sale:' || lower(e.network) || ':' || lower(e.txid) || ':' ||
        e.block_height::text || ':' ||
        e.block_index::text || ':' ||
        e.op_return_vout::text || ':' ||
        e.record_ordinal::text
    ELSE 'sale:' || lower(e.txid)
  END`;
  const ordinaryCanonicalKey =
    safeKind === "listings"
      ? `'listing:' || ${listingId}`
      : safeKind === "sales"
        ? canonicalSaleKey
        : safeKind === "closedListings"
          ? `'closed:' || ${listingId} || ':' || lower(e.txid)`
          : `CASE
              WHEN e.kind = ANY(${listingKinds})
                THEN 'listing:' || ${listingId}
              WHEN e.kind = 'token-sale'
                THEN ${canonicalSaleKey}
              WHEN e.kind = 'token-listing-closed'
                THEN 'closed:' || ${listingId} || ':' || lower(e.txid)
              ELSE e.kind || ':' || e.event_id::text
            END`;
  const canonicalKey = `CASE
    WHEN ${amoV5Relic}
      THEN 'closed:' || ${listingId} || ':' || ${amoV5RelicClosedTxidSql}
    ELSE ${ordinaryCanonicalKey}
  END`;
  const itemTxid = `CASE
    WHEN ${amoV5Relic} THEN ${amoV5RelicClosedTxidSql}
    WHEN e.kind = ANY(${listingKinds}) THEN ${listingId}
    ELSE lower(e.txid)
  END`;
  const itemKindRank = `CASE
    WHEN ${amoV5Relic} THEN 1
    WHEN e.kind = 'token-sale' THEN 0
    WHEN e.kind = 'token-listing-closed' THEN 1
    WHEN e.kind = ANY(${listingKinds}) THEN 2
    ELSE 3
  END`;
  const projectionRank = `CASE
    WHEN ${amoV5Relic} THEN 1
    WHEN e.kind = ANY(ARRAY['token-listings','token-listing']::text[]) THEN 0
    WHEN e.kind = 'token-listing-sealed' THEN 1
    WHEN e.kind = 'token-listing-closed' THEN 1
    WHEN e.kind = 'token-sale' THEN 2
    ELSE 3
  END`;

  return `
    WITH ranked_market_events AS (
      SELECT
        e.payload,
        e.protocol,
        e.kind,
        e.status,
        CASE
          WHEN ${amoV5Relic} THEN ${amoV5RelicClosedAtSql}::timestamptz
          ELSE e.event_time
        END AS event_time,
        CASE
          WHEN ${amoV5Relic} THEN ${amoV5RelicClosedAtSql}::timestamptz
          ELSE e.block_time
        END AS block_time,
        CASE
          WHEN ${amoV5Relic} THEN ${amoV5RelicClosedAtSql}::timestamptz
          ELSE e.created_at
        END AS created_at,
        CASE
          WHEN ${amoV5Relic} THEN ${WORK_AMO_V5_ACTIVATION_HEIGHT}
          ELSE e.block_height
        END AS block_height,
        e.block_index,
        e.op_return_vout,
        e.record_ordinal,
        event_tx.status AS transaction_status,
        event_tx.block_height AS transaction_block_height,
        event_tx.block_index AS transaction_block_index,
        event_tx.block_hash AS block_hash,
        event_block.block_hash AS canonical_block_hash,
        e.txid,
        e.event_id,
        COALESCE(cd.token_id, cl_event.token_id) AS token_id,
        cd.ticker,
        cd.registry_address,
        cd.metadata AS token_metadata,
        cl_event.listing_id AS linked_listing_id,
        cl_event.seller_address AS listing_seller_address,
        cl_event.buyer_address AS listing_buyer_address,
        cl_event.amount AS listing_amount,
        cl_event.price_sats AS listing_price_sats,
        cl_event.payload AS listing_payload,
        canonical_seal_event.seal_event_payload,
        canonical_seal_event.seal_event_status,
        canonical_seal_event.seal_event_txid,
        canonical_seal_event.seal_event_block_hash,
        canonical_seal_event.seal_event_block_height,
        canonical_seal_event.seal_event_block_index,
        canonical_seal_event.seal_event_protocol_vout,
        canonical_seal_event.seal_event_record_ordinal,
        canonical_seal_event.seal_event_match_count,
        seal_transaction.block_height AS seal_transaction_block_height,
        ${amoV5Relic} AS work_amo_v5_pre_unit_relic_projection,
        (e.status = 'confirmed') AS history_item_confirmed,
        ${itemTxid} AS history_item_txid,
        ${itemKindRank} AS history_item_kind_rank,
        ROW_NUMBER() OVER (
          PARTITION BY ${canonicalKey}
          ORDER BY
            ${projectionRank} ASC,
            COALESCE(
              CASE
                WHEN ${amoV5Relic}
                  THEN ${amoV5RelicClosedAtSql}::timestamptz
                ELSE e.event_time
              END,
              e.block_time,
              e.created_at
            ) DESC,
            (e.status = 'confirmed') DESC,
            e.txid DESC,
            e.event_id DESC
        ) AS canonical_history_rank
      FROM proof_indexer.events e
      LEFT JOIN proof_indexer.transactions event_tx
        ON event_tx.network = e.network
       AND event_tx.txid = e.txid
      LEFT JOIN proof_indexer.blocks event_block
        ON event_block.network = event_tx.network
       AND event_block.block_hash = event_tx.block_hash
       AND event_block.height = event_tx.block_height
       AND event_block.canonical = true
      LEFT JOIN proof_indexer.credit_listings cl_event
        ON cl_event.network = e.network
       AND cl_event.listing_id = lower(e.payload->>'listingId')
       AND lower(cl_event.token_id) = lower(COALESCE(
         NULLIF(e.payload->>'tokenId', ''),
         NULLIF(e.payload->'saleAuthorization'->>'tokenId', '')
       ))
      LEFT JOIN proof_indexer.transactions seal_transaction
        ON seal_transaction.network = cl_event.network
       AND seal_transaction.txid = cl_event.seal_txid
      LEFT JOIN LATERAL (
        SELECT
          canonical_seal_event_row.payload AS seal_event_payload,
          canonical_seal_event_row.status AS seal_event_status,
          canonical_seal_event_row.txid AS seal_event_txid,
          canonical_seal_tx.block_hash AS seal_event_block_hash,
          canonical_seal_event_row.block_height AS seal_event_block_height,
          canonical_seal_event_row.block_index AS seal_event_block_index,
          canonical_seal_event_row.op_return_vout AS seal_event_protocol_vout,
          canonical_seal_event_row.record_ordinal AS seal_event_record_ordinal,
          COUNT(*) OVER () AS seal_event_match_count
        FROM proof_indexer.events canonical_seal_event_row
        JOIN proof_indexer.transactions canonical_seal_tx
          ON canonical_seal_tx.network = canonical_seal_event_row.network
         AND canonical_seal_tx.txid = canonical_seal_event_row.txid
         AND canonical_seal_tx.status = 'confirmed'
         AND canonical_seal_tx.block_height =
           canonical_seal_event_row.block_height
         AND canonical_seal_tx.block_index =
           canonical_seal_event_row.block_index
        JOIN proof_indexer.blocks canonical_seal_block
          ON canonical_seal_block.network = canonical_seal_tx.network
         AND canonical_seal_block.block_hash = canonical_seal_tx.block_hash
         AND canonical_seal_block.height = canonical_seal_tx.block_height
         AND canonical_seal_block.canonical = true
        WHERE canonical_seal_event_row.network = e.network
          AND canonical_seal_event_row.txid = lower(cl_event.seal_txid)
          AND canonical_seal_event_row.valid = true
          AND canonical_seal_event_row.status = 'confirmed'
          AND canonical_seal_event_row.protocol = 'pwt1'
          AND canonical_seal_event_row.kind = 'token-listing-sealed'
          AND lower(canonical_seal_event_row.payload->>'listingId') =
            lower(COALESCE(
              NULLIF(e.payload->>'listingId', ''),
              NULLIF(cl_event.listing_id, ''),
              e.txid
            ))
          AND lower(COALESCE(
            canonical_seal_event_row.payload->>'tokenId',
            canonical_seal_event_row.payload->'saleAuthorization'->>'tokenId',
            ''
          )) = ${targetTokenId}
          AND (
            ${targetTokenId} <> '${WORK_TOKEN_ID}'
            OR (
              ${targetSaleAuthorizationVersion} IN (
                '${WORK_MARKET_V2_AUTH_VERSION}',
                '${WORK_MARKET_V4_AUTH_VERSION}',
                '${WORK_AMO_V5_AUTH_VERSION}',
                '${WORK_AMO_V6_AUTH_VERSION}',
                '${WORK_AMO_V8_AUTH_VERSION}'
              )
              AND lower(COALESCE(
                canonical_seal_event_row.payload
                  ->'saleAuthorization'->>'version',
                ''
              )) = ${targetSaleAuthorizationVersion}
            )
          )
        ORDER BY
          canonical_seal_event_row.block_height DESC,
          canonical_seal_event_row.block_index DESC,
          canonical_seal_event_row.op_return_vout DESC,
          canonical_seal_event_row.record_ordinal DESC
        LIMIT 1
      ) canonical_seal_event ON true
      LEFT JOIN proof_indexer.credit_definitions cd
        ON cd.network = e.network
       AND cd.token_id = COALESCE(lower(e.payload->>'tokenId'), cl_event.token_id)
      WHERE ${whereClause}
        AND (
          ${amoV5Relic}
          OR e.protocol = 'pwt1'
        )
    ),
    canonical_market_events AS (
      SELECT *
      FROM ranked_market_events
      WHERE canonical_history_rank = 1
    )
  `;
}

function tokenHistoryPageWithScanCoverage(page, coverage) {
  // A scan checkpoint is operational evidence only. It cannot change the
  // generation height or source label of an older embedded history page.
  void coverage;
  return page;
}

function tokenListingId(item) {
  return String(item?.listingId ?? item?.listing?.listingId ?? "")
    .trim()
    .toLowerCase();
}

function canonicalTokenMarketHistorySaleKey(item, network = "") {
  const sale = item?.sale ?? item;
  const txid = normalizedLowerText(sale?.txid ?? item?.txid);
  const blockHeight =
    sale?.blockHeight !== undefined &&
    sale?.blockHeight !== null &&
    sale?.blockHeight !== "" &&
    Number.isSafeInteger(Number(sale.blockHeight)) &&
    Number(sale.blockHeight) >= 1
      ? Number(sale.blockHeight)
      : null;
  const legacyPositionExempt =
    sale?.relic === true || sale?.canonicalSynthetic === true;
  if (
    sale?.confirmed === true &&
    blockHeight === null &&
    !legacyPositionExempt
  ) {
    throw new Error("Canonical AMO V5 market sale position is incomplete.");
  }
  if (
    sale?.confirmed === true &&
    blockHeight !== null &&
    blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    const exactPositionInteger = (value) =>
      value !== undefined &&
      value !== null &&
      value !== "" &&
      Number.isSafeInteger(Number(value)) &&
      Number(value) >= 0
        ? Number(value)
        : null;
    const blockIndex = exactPositionInteger(sale?.blockIndex);
    const protocolVout = exactPositionInteger(sale?.protocolVout);
    const recordOrdinal = exactPositionInteger(sale?.recordOrdinal);
    if (
      blockIndex === null ||
      protocolVout === null ||
      recordOrdinal === null
    ) {
      throw new Error(
        "Canonical AMO V5 market sale position is incomplete.",
      );
    }
    return [
      normalizedLowerText(sale?.network ?? network),
      txid,
      "v5",
      blockHeight,
      blockIndex,
      protocolVout,
      recordOrdinal,
    ].join(":");
  }
  return txid;
}

function currentRelationalHistoryPageWithScanCoverage(page, scan) {
  if (!page) {
    return null;
  }
  return {
    ...page,
    indexedAt: dateIso(
      newestDateIso([page.indexedAt, scan?.generated_at]),
    ),
    indexedThroughBlock:
      Math.max(
        rowNumber(page, "indexedThroughBlock"),
        rowNumber(scan, "indexed_through_block"),
      ) || undefined,
  };
}

function tokenHistoryItemKey(item, safeKind) {
  if (safeKind === "market-log") {
    if (item?.kind === "sale") {
      return `sale:${canonicalTokenMarketHistorySaleKey(item)}`;
    }
    if (item?.kind === "closed-listing") {
      return `closed:${String(
        item.closedListing?.listingId ?? "",
      ).toLowerCase()}:${String(
        item.closedListing?.closedTxid ?? item.txid ?? "",
      ).toLowerCase()}`;
    }
    if (item?.kind === "listing") {
      return `listing:${String(
        item.listing?.listingId ?? item.txid ?? "",
      ).toLowerCase()}`;
    }
  }

  if (safeKind === "closedListings") {
    return `closed:${String(item?.listingId ?? "").toLowerCase()}:${String(
      item?.closedTxid ?? item?.txid ?? "",
    ).toLowerCase()}`;
  }

  if (safeKind === "sales") {
    return `sale:${canonicalTokenMarketHistorySaleKey(item)}`;
  }

  return String(item?.txid ?? item?.listingId ?? JSON.stringify(item));
}

function tokenHistoryItemCreatedAt(item) {
  if (item?.kind === "sale") {
    return item.sale?.createdAt ?? item.createdAt;
  }
  if (item?.kind === "closed-listing") {
    return item.closedListing?.closedAt ?? item.closedListing?.createdAt ?? item.createdAt;
  }
  if (item?.kind === "listing") {
    return item.listing?.createdAt ?? item.createdAt;
  }
  return item?.closedAt ?? item?.createdAt;
}

function tokenHistoryItemIsMarketLogItem(item) {
  return (
    item?.kind === "sale" ||
    item?.kind === "closed-listing" ||
    item?.kind === "listing"
  );
}

function tokenHistoryItemConfirmed(item) {
  if (item?.kind === "sale") {
    return item.sale?.confirmed === true;
  }
  if (item?.kind === "closed-listing") {
    return item.closedListing?.closedConfirmed === true;
  }
  return item?.kind === "listing" && item.listing?.confirmed === true;
}

function tokenHistoryItemKindRank(item) {
  if (item?.kind === "sale") {
    return 0;
  }
  if (item?.kind === "closed-listing") {
    return 1;
  }
  return item?.kind === "listing" ? 2 : 3;
}

function tokenHistoryItemTxid(item) {
  return String(
    item?.txid ?? item?.closedTxid ?? item?.listingId ?? "",
  );
}

function compareTokenHistoryMarketItems(left, right) {
  const leftTime = Date.parse(tokenHistoryItemCreatedAt(left) ?? "");
  const rightTime = Date.parse(tokenHistoryItemCreatedAt(right) ?? "");
  const marketLogPair =
    tokenHistoryItemIsMarketLogItem(left) &&
    tokenHistoryItemIsMarketLogItem(right);
  return (
    (Number.isFinite(rightTime) ? rightTime : 0) -
      (Number.isFinite(leftTime) ? leftTime : 0) ||
    (marketLogPair
      ? Number(tokenHistoryItemConfirmed(right)) -
        Number(tokenHistoryItemConfirmed(left))
      : 0) ||
    compareCanonicalUtf8(
      tokenHistoryItemTxid(right),
      tokenHistoryItemTxid(left),
    ) ||
    (marketLogPair
      ? tokenHistoryItemKindRank(left) - tokenHistoryItemKindRank(right)
      : 0)
  );
}

function validTxid(value) {
  return /^[0-9a-f]{64}$/u.test(String(value ?? "").trim().toLowerCase());
}

function tokenListingSealRank(listing) {
  if (!validTxid(listing?.sealTxid)) {
    return 0;
  }
  if (listing?.sealConfirmed !== true) {
    return 1;
  }
  return listing?.sealMinerFeeCanonical === true ? 3 : 2;
}

function tokenListingWithSealFrom(listing, sealSource) {
  if (!listing || tokenListingSealRank(sealSource) === 0) {
    return listing;
  }
  const selectedSealTxid = String(sealSource.sealTxid ?? "")
    .trim()
    .toLowerCase();
  const currentSealTxid = String(listing.sealTxid ?? "")
    .trim()
    .toLowerCase();
  const sameSealTransaction =
    validTxid(selectedSealTxid) &&
    validTxid(currentSealTxid) &&
    selectedSealTxid === currentSealTxid;
  const sealFallback = sameSealTransaction ? listing : {};

  return {
    ...listing,
    saleAuthorization:
      sealSource.saleAuthorization ?? sealFallback.saleAuthorization,
    sealAt: sealSource.sealAt ?? sealFallback.sealAt,
    sealBlockHash: sealSource.sealBlockHash ?? sealFallback.sealBlockHash,
    sealBlockHeight:
      sealSource.sealBlockHeight ?? sealFallback.sealBlockHeight,
    sealBlockIndex: sealSource.sealBlockIndex ?? sealFallback.sealBlockIndex,
    sealConfirmed: sealSource.sealConfirmed === true,
    sealDataBytes: sealSource.sealDataBytes ?? sealFallback.sealDataBytes,
    sealFrozenNetworkValueSats:
      sealSource.sealFrozenNetworkValueSats ??
      sealFallback.sealFrozenNetworkValueSats,
    sealLiveNetworkValueSats:
      sealSource.sealLiveNetworkValueSats ??
      sealFallback.sealLiveNetworkValueSats,
    sealMinerFeeCanonical:
      sealSource.sealMinerFeeCanonical === true ||
      (
        sameSealTransaction &&
        listing.sealMinerFeeCanonical === true
      ),
    sealMinerFeeSource:
      sealSource.sealMinerFeeSource ?? sealFallback.sealMinerFeeSource,
    sealMinerFeeSats:
      sealSource.sealMinerFeeSats ?? sealFallback.sealMinerFeeSats,
    sealProtocolVout:
      sealSource.sealProtocolVout ?? sealFallback.sealProtocolVout,
    sealRecordOrdinal:
      sealSource.sealRecordOrdinal ?? sealFallback.sealRecordOrdinal,
    sealTransactionBlockHeight:
      sealSource.sealTransactionBlockHeight ??
      sealFallback.sealTransactionBlockHeight,
    sealTxid: selectedSealTxid,
  };
}

function tokenListingSealTimeMs(listing) {
  const timeMs = Date.parse(listing?.sealAt ?? listing?.createdAt ?? "");
  return Number.isFinite(timeMs) ? timeMs : 0;
}

function preferredTokenListingSealSource(left, right) {
  const leftRank = tokenListingSealRank(left);
  const rightRank = tokenListingSealRank(right);
  if (leftRank === 0) {
    return rightRank > 0 ? right : null;
  }
  if (rightRank === 0) {
    return left;
  }
  if (leftRank !== rightRank) {
    return leftRank > rightRank ? left : right;
  }

  const leftTime = tokenListingSealTimeMs(left);
  const rightTime = tokenListingSealTimeMs(right);
  if (leftTime !== rightTime) {
    return leftTime > rightTime ? left : right;
  }

  return compareCanonicalUtf8(left?.sealTxid, right?.sealTxid) >= 0
    ? left
    : right;
}

function tokenListingCloseRank(listing) {
  if (!validTxid(listing?.closedTxid)) {
    return 0;
  }
  if (listing?.closedConfirmed !== true) {
    return 1;
  }
  return listing?.closedMinerFeeCanonical === true ? 3 : 2;
}

function tokenListingWithCloseFrom(listing, closeSource) {
  if (!listing || tokenListingCloseRank(closeSource) === 0) {
    return listing;
  }

  const selectedCloseTxid = String(closeSource.closedTxid ?? "")
    .trim()
    .toLowerCase();
  const currentCloseTxid = String(listing.closedTxid ?? "")
    .trim()
    .toLowerCase();
  const sameCloseTransaction =
    validTxid(selectedCloseTxid) &&
    validTxid(currentCloseTxid) &&
    selectedCloseTxid === currentCloseTxid;
  const closeFallback = sameCloseTransaction ? listing : {};
  const selectedCloseField = (field) =>
    Object.prototype.hasOwnProperty.call(closeSource, field)
      ? closeSource[field]
      : closeFallback[field];
  const selectedCloseAliasField = (...fields) => {
    for (const field of fields) {
      if (Object.prototype.hasOwnProperty.call(closeSource, field)) {
        return closeSource[field];
      }
    }
    for (const field of fields) {
      if (Object.prototype.hasOwnProperty.call(closeFallback, field)) {
        return closeFallback[field];
      }
    }
    return undefined;
  };

  return {
    ...listing,
    buyerAddress: selectedCloseAliasField(
      "buyerAddress",
      "saleBuyerAddress",
    ),
    canonicalSaleEvidence: selectedCloseField("canonicalSaleEvidence"),
    closeTxid: undefined,
    closedAt: selectedCloseField("closedAt"),
    closedBlockHash: selectedCloseAliasField(
      "closedBlockHash",
      "blockHash",
    ),
    closedBlockHeight: selectedCloseAliasField(
      "closedBlockHeight",
      "blockHeight",
    ),
    closeTransactionBlockHeight: selectedCloseField(
      "closeTransactionBlockHeight",
    ),
    closedBlockIndex: selectedCloseAliasField(
      "closedBlockIndex",
      "blockIndex",
    ),
    closedByCanonicalOutpointSpend:
      selectedCloseField("closedByCanonicalOutpointSpend") === true,
    closedBySpendableOutspend:
      selectedCloseField("closedBySpendableOutspend") === true,
    closedConfirmed: selectedCloseField("closedConfirmed") === true,
    closedDataBytes: selectedCloseAliasField(
      "closedDataBytes",
      "dataBytes",
    ),
    closedFrozenNetworkValueSats: selectedCloseField(
      "closedFrozenNetworkValueSats",
    ),
    closedLiveNetworkValueSats: selectedCloseField(
      "closedLiveNetworkValueSats",
    ),
    closedMinerFeeCanonical:
      selectedCloseField("closedMinerFeeCanonical") === true,
    closedMinerFeeSats: selectedCloseField("closedMinerFeeSats"),
    closedMinerFeeSource: selectedCloseAliasField(
      "closedMinerFeeSource",
      "minerFeeSource",
    ),
    closedProtocolVout: selectedCloseAliasField(
      "closedProtocolVout",
      "protocolVout",
    ),
    closedRecordOrdinal: selectedCloseAliasField(
      "closedRecordOrdinal",
      "recordOrdinal",
    ),
    closedTxid: selectedCloseTxid,
    closedVin: selectedCloseField("closedVin"),
    lifecycleStatus: selectedCloseField("lifecycleStatus"),
    saleAt: selectedCloseField("saleAt"),
    saleBlockHash: selectedCloseField("saleBlockHash"),
    saleBlockHeight: selectedCloseField("saleBlockHeight"),
    saleBlockIndex: selectedCloseField("saleBlockIndex"),
    saleBuyerAddress: selectedCloseAliasField(
      "saleBuyerAddress",
      "buyerAddress",
    ),
    saleConfirmed: selectedCloseField("saleConfirmed") === true,
    saleDataBytes: selectedCloseField("saleDataBytes"),
    saleMinerFeeSats: selectedCloseField("saleMinerFeeSats"),
    salePaymentSats: selectedCloseField("salePaymentSats"),
    saleProtocolVout: selectedCloseField("saleProtocolVout"),
    saleRecordOrdinal: selectedCloseField("saleRecordOrdinal"),
    saleTransactionBlockHeight: selectedCloseField(
      "saleTransactionBlockHeight",
    ),
    saleTxid: selectedCloseField("saleTxid"),
    status: selectedCloseField("status"),
  };
}

function mergeTokenListingRecord(current, incoming) {
  if (!current) {
    return incoming;
  }
  if (!incoming) {
    return current;
  }

  const sealSource = preferredTokenListingSealSource(current, incoming);
  const sealed = sealSource
    ? tokenListingWithSealFrom(incoming, sealSource)
    : incoming;
  const exactPositionInteger = (value, minimum) => {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed =
      typeof value === "number"
        ? value
        : typeof value === "string" && /^(?:0|[1-9][0-9]*)$/u.test(value)
          ? Number(value)
          : Number.NaN;
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const completeListingPosition = (listing) =>
    /^[0-9a-f]{64}$/u.test(normalizedLowerText(listing?.blockHash)) &&
    exactPositionInteger(listing?.blockHeight, 1) !== null &&
    exactPositionInteger(listing?.blockIndex, 0) !== null &&
    exactPositionInteger(listing?.protocolVout, 0) !== null &&
    exactPositionInteger(listing?.recordOrdinal, 0) !== null;
  const directPositionAliasesLifecycle = (listing, prefix) => {
    if (!completeListingPosition(listing)) {
      return false;
    }
    const lifecycleHash = normalizedLowerText(
      listing?.[`${prefix}BlockHash`],
    );
    const lifecycleHeight = exactPositionInteger(
      listing?.[`${prefix}BlockHeight`],
      1,
    );
    const lifecycleIndex = exactPositionInteger(
      listing?.[`${prefix}BlockIndex`],
      0,
    );
    const lifecycleVout = exactPositionInteger(
      listing?.[`${prefix}ProtocolVout`],
      0,
    );
    const lifecycleOrdinal = exactPositionInteger(
      listing?.[`${prefix}RecordOrdinal`],
      0,
    );
    return (
      /^[0-9a-f]{64}$/u.test(lifecycleHash) &&
      lifecycleHash === normalizedLowerText(listing.blockHash) &&
      lifecycleHeight !== null &&
      lifecycleHeight === exactPositionInteger(listing.blockHeight, 1) &&
      lifecycleIndex !== null &&
      lifecycleIndex === exactPositionInteger(listing.blockIndex, 0) &&
      lifecycleVout !== null &&
      lifecycleVout === exactPositionInteger(listing.protocolVout, 0) &&
      lifecycleOrdinal !== null &&
      lifecycleOrdinal === exactPositionInteger(listing.recordOrdinal, 0)
    );
  };
  const lifecyclePositionState = (listing, prefix) => {
    const txidField =
      prefix === "closed" ? "closedTxid" : `${prefix}Txid`;
    const positionValues = [
      listing?.[`${prefix}BlockHash`],
      listing?.[`${prefix}BlockHeight`],
      listing?.[`${prefix}BlockIndex`],
      listing?.[`${prefix}ProtocolVout`],
      listing?.[`${prefix}RecordOrdinal`],
    ];
    const present =
      validTxid(listing?.[txidField]) ||
      (prefix === "closed" && validTxid(listing?.closeTxid)) ||
      positionValues.some(
        (value) => value !== undefined && value !== null && value !== "",
      );
    if (!present) {
      return "absent";
    }
    const complete =
      /^[0-9a-f]{64}$/u.test(
        normalizedLowerText(listing?.[`${prefix}BlockHash`]),
      ) &&
      exactPositionInteger(listing?.[`${prefix}BlockHeight`], 1) !== null &&
      exactPositionInteger(listing?.[`${prefix}BlockIndex`], 0) !== null &&
      exactPositionInteger(listing?.[`${prefix}ProtocolVout`], 0) !== null &&
      exactPositionInteger(listing?.[`${prefix}RecordOrdinal`], 0) !== null;
    if (!complete) {
      return "incomplete";
    }
    return directPositionAliasesLifecycle(listing, prefix)
      ? "aliases-opening"
      : "complete";
  };
  const listingPositionKey = (listing) => [
    normalizedLowerText(listing?.blockHash),
    exactPositionInteger(listing?.blockHeight, 1),
    exactPositionInteger(listing?.blockIndex, 0),
    exactPositionInteger(listing?.protocolVout, 0),
    exactPositionInteger(listing?.recordOrdinal, 0),
  ].join(":");
  const candidateListingPositionSources = [incoming, current].filter(
    (listing) =>
      completeListingPosition(listing) &&
      ["seal", "closed", "sale"].every((prefix) =>
        ["absent", "complete"].includes(
          lifecyclePositionState(listing, prefix),
        ),
      ),
  );
  const conflictingListingPositions =
    new Set(candidateListingPositionSources.map(listingPositionKey)).size > 1;
  const canonicalListingPositionSource = conflictingListingPositions
    ? null
    : candidateListingPositionSources[0];
  const unsafeAliasedListingPosition =
    conflictingListingPositions ||
    (
      !canonicalListingPositionSource &&
      [incoming, current].some(completeListingPosition)
    );
  const merged = {
    ...sealed,
    blockHash:
      canonicalListingPositionSource?.blockHash ||
      (
        unsafeAliasedListingPosition
          ? undefined
          : sealed.blockHash || current.blockHash
      ),
    blockHeight:
      canonicalListingPositionSource?.blockHeight ??
      (
        unsafeAliasedListingPosition
          ? undefined
          : sealed.blockHeight ?? current.blockHeight
      ),
    blockIndex:
      canonicalListingPositionSource?.blockIndex ??
      (
        unsafeAliasedListingPosition
          ? undefined
          : sealed.blockIndex ?? current.blockIndex
      ),
    protocolVout:
      canonicalListingPositionSource?.protocolVout ??
      (
        unsafeAliasedListingPosition
          ? undefined
          : sealed.protocolVout ?? current.protocolVout
      ),
    recordOrdinal:
      canonicalListingPositionSource?.recordOrdinal ??
      (
        unsafeAliasedListingPosition
          ? undefined
          : sealed.recordOrdinal ?? current.recordOrdinal
      ),
  };
  return tokenListingCloseRank(current) > tokenListingCloseRank(incoming)
    ? tokenListingWithCloseFrom(merged, current)
    : tokenListingWithCloseFrom(merged, incoming);
}

function walletTokenListingsWithLegacySealEvents(listings, legacySealEvents) {
  const mergedListings = uniqueTokenItems(
    listings,
    tokenListingId,
    mergeTokenListingRecord,
  );
  const listingsById = new Map(
    mergedListings.map((listing) => [tokenListingId(listing), listing]),
  );

  for (const sealEvent of Array.isArray(legacySealEvents)
    ? legacySealEvents
    : []) {
    const listingId = tokenListingId(sealEvent);
    const listing = listingsById.get(listingId);
    const listingVersion = normalizedLowerText(
      listing?.saleAuthorization?.version,
    );
    const version = normalizedLowerText(
      sealEvent?.saleAuthorization?.version,
    );
    const listingSeller = normalizedText(listing?.sellerAddress);
    const sealSeller = normalizedText(sealEvent?.sellerAddress);
    const sealMinerFeeSats = Number(sealEvent?.sealMinerFeeSats);
    if (
      !listing ||
      listing?.confirmed !== true ||
      !isWorkTokenId(listing?.tokenId) ||
      ![TOKEN_SALE_AUTH_VERSION, "pwt-sale-v2"].includes(listingVersion) ||
      !isWorkTokenId(sealEvent?.tokenId) ||
      ![TOKEN_SALE_AUTH_VERSION, "pwt-sale-v2"].includes(version) ||
      listingVersion !== version ||
      !listingSeller ||
      listingSeller !== sealSeller ||
      sealEvent?.confirmed !== true ||
      sealEvent?.sealConfirmed !== true ||
      sealEvent?.sealMinerFeeCanonical !== true ||
      !Number.isSafeInteger(sealMinerFeeSats) ||
      sealMinerFeeSats < 0 ||
      !validTxid(sealEvent?.sealTxid)
    ) {
      continue;
    }

    const sealSource = preferredTokenListingSealSource(listing, sealEvent);
    if (sealSource) {
      listingsById.set(
        listingId,
        tokenListingWithSealFrom(listing, sealSource),
      );
    }
  }

  return [...listingsById.values()].sort(compareTokenItemsByTime);
}

function mergeCanonicalTokenSaleRecord(current, incoming) {
  if (!current) {
    return incoming;
  }
  if (!incoming) {
    return current;
  }
  return {
    ...incoming,
    ...current,
    createdAt: current.createdAt ?? incoming.createdAt,
  };
}

function canonicalTokenSaleProjectionKey(sale, network) {
  const normalizedNetwork = normalizedLowerText(sale?.network ?? network);
  const txid = normalizedLowerText(sale?.txid);
  const blockHeight =
    typeof sale?.blockHeight === "number"
      ? sale.blockHeight
      : typeof sale?.blockHeight === "string" &&
          /^(?:0|[1-9][0-9]*)$/u.test(sale.blockHeight)
        ? Number(sale.blockHeight)
        : null;
  if (
    sale?.confirmed === true &&
    Number.isSafeInteger(blockHeight) &&
    blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    const exactPositionInteger = (value) =>
      typeof value === "number"
        ? Number.isSafeInteger(value) && value >= 0
          ? value
          : null
        : typeof value === "string" &&
            /^(?:0|[1-9][0-9]*)$/u.test(value) &&
            Number.isSafeInteger(Number(value))
          ? Number(value)
          : null;
    const blockIndex = exactPositionInteger(sale?.blockIndex);
    const protocolVout = exactPositionInteger(sale?.protocolVout);
    const recordOrdinal = exactPositionInteger(sale?.recordOrdinal);
    if (
      !/^[0-9a-f]{64}$/u.test(txid) ||
      blockIndex === null ||
      protocolVout === null ||
      recordOrdinal === null
    ) {
      return "";
    }
    return [
      normalizedNetwork,
      txid,
      "v5",
      blockHeight,
      blockIndex,
      protocolVout,
      recordOrdinal,
    ].join(":");
  }
  const listingId = normalizedLowerText(sale?.listingId);
  return `${normalizedNetwork}:${txid}:${listingId}`;
}

function isWorkAmoV5ListingSaleProjection(sale) {
  const saleAuthorization = objectRecord(sale?.saleAuthorization);
  return (
    isWorkTokenId(sale?.tokenId ?? saleAuthorization.tokenId) &&
    [
      WORK_AMO_V5_AUTH_VERSION,
      WORK_AMO_V6_AUTH_VERSION,
      WORK_AMO_V8_AUTH_VERSION,
    ].includes(normalizedLowerText(saleAuthorization.version))
  );
}

function canonicalTokenSalesWithListingEnrichment(
  marketSales,
  listingSales,
  network,
) {
  const canonicalSales = Array.isArray(marketSales) ? marketSales : [];
  const projectedSales = Array.isArray(listingSales) ? listingSales : [];
  const canonicalSaleKeys = new Set(
    canonicalSales.map((sale) =>
      canonicalTokenSaleProjectionKey(sale, network),
    ),
  );
  const admissibleListingSales = projectedSales.filter(
    (sale) =>
      !isWorkAmoV5ListingSaleProjection(sale) ||
      canonicalSaleKeys.has(canonicalTokenSaleProjectionKey(sale, network)),
  );
  return uniqueTokenItems(
    [...canonicalSales, ...admissibleListingSales],
    (sale) => canonicalTokenSaleProjectionKey(sale, network),
    mergeCanonicalTokenSaleRecord,
  );
}

function mergeCanonicalTokenClosedListingRecord(current, incoming) {
  if (!current) {
    return incoming;
  }
  if (!incoming) {
    return current;
  }
  const merged = mergeTokenListingRecord(current, incoming);
  return {
    ...merged,
    closedAt: current.closedAt ?? incoming.closedAt,
    createdAt: current.createdAt ?? incoming.createdAt,
  };
}

function mergeTokenHistoryMarketItem(current, incoming, safeKind) {
  if (!current) {
    return incoming;
  }
  if (!incoming) {
    return current;
  }

  if (safeKind === "listings" || safeKind === "closedListings") {
    return mergeTokenListingRecord(current, incoming);
  }

  if (safeKind === "market-log") {
    if (current.kind === "listing" && incoming.kind === "listing") {
      return {
        ...current,
        ...incoming,
        listing: mergeTokenListingRecord(current.listing, incoming.listing),
      };
    }
    if (
      current.kind === "closed-listing" &&
      incoming.kind === "closed-listing"
    ) {
      return {
        ...current,
        ...incoming,
        closedListing: mergeTokenListingRecord(
          current.closedListing,
          incoming.closedListing,
        ),
      };
    }
  }

  return incoming;
}

function tokenHistoryPageFromItems({
  indexedAt,
  indexedThroughBlock,
  items,
  kind,
  network,
  pagination,
  source,
  snapshot,
}) {
  const needles = tokenHistoryFilterNeedles(new URLSearchParams(), pagination);
  const filtered = historyItemsMatchingNeedles(items, needles);
  const totalCount = filtered.length;
  const start = Math.min(pagination.offset, totalCount);
  const end = Math.min(totalCount, start + pagination.limit);
  const snapshotId = snapshot?.snapshot_id ?? "";
  const cursor = historyCursor(snapshotId, start);
  const nextCursor = end < totalCount ? historyCursor(snapshotId, end) : "";
  const page = {
    cursor,
    end,
    indexedAt,
    indexedThroughBlock:
      indexedThroughBlock ?? indexedThroughBlockFromItems(filtered),
    items: filtered.slice(start, end),
    kind,
    limit: pagination.limit,
    network,
    nextCursor,
    page: Math.floor(start / pagination.limit),
    pageCount: Math.max(1, Math.ceil(totalCount / pagination.limit)),
    pageSize: pagination.limit,
    query: pagination.query,
    source,
    start,
    totalCount,
  };
  if (snapshotId) {
    return {
      ...page,
      consistency: snapshot?.consistency ?? undefined,
      ledgerGeneratedAt: dateIso(snapshot?.generated_at),
      snapshotId,
    };
  }
  return page;
}

function mergedSourceLabel(...sources) {
  return [
    ...new Set(
      sources
        .flatMap((source) => String(source ?? "").split("+"))
        .map((source) => source.trim())
        .filter(Boolean),
    ),
  ].join("+");
}

function mergeTokenHistoryPages(basePage, overlayPage, safeKind, pagination) {
  if (!overlayPage || !Array.isArray(overlayPage.items) || overlayPage.items.length === 0) {
    return basePage;
  }
  if (!basePage) {
    return overlayPage;
  }

  const byKey = new Map();
  for (const item of [
    ...(Array.isArray(basePage.items) ? basePage.items : []),
    ...overlayPage.items,
  ]) {
    const key = tokenHistoryItemKey(item, safeKind);
    byKey.set(
      key,
      mergeTokenHistoryMarketItem(byKey.get(key), item, safeKind),
    );
  }
  const items = [...byKey.values()].sort(compareTokenHistoryMarketItems);
  return {
    ...tokenHistoryPageFromItems({
      indexedAt: dateIso(overlayPage.indexedAt ?? basePage.indexedAt),
      indexedThroughBlock:
        overlayPage.indexedThroughBlock ?? basePage.indexedThroughBlock,
      items,
      kind: safeKind,
      network: basePage.network ?? overlayPage.network,
      pagination: {
        ...pagination,
        offset: 0,
      },
      source: mergedSourceLabel(basePage.source, overlayPage.source),
      snapshot: {
        consistency: basePage.consistency ?? overlayPage.consistency,
        generated_at:
          basePage.ledgerGeneratedAt ?? overlayPage.ledgerGeneratedAt,
        snapshot_id: basePage.snapshotId ?? overlayPage.snapshotId ?? "",
      },
    }),
    totalCount: Math.max(
      Number(basePage.totalCount ?? 0),
      Number(overlayPage.totalCount ?? 0),
      items.length,
    ),
  };
}

function tokenMintQueryScopeCondition(scope, param) {
  if (!scope || scope === "all") {
    return "";
  }
  return `(
    lower(e.payload->>'tokenId') = ${param}
    OR lower(cd.token_id) = ${param}
    OR lower(cd.ticker) = lower(${param})
    OR lower(e.payload->>'ticker') = lower(${param})
  )`;
}

function tokenMintEventQueryParts(network, tokenScope, searchParams, pagination) {
  const scope = tokenScopeKey(tokenScope);
  const conditions = [
    "e.network = $1",
    "e.protocol = 'pwt1'",
    "e.valid IS DISTINCT FROM false",
    "e.kind = 'token-mint'",
    "COALESCE(t.status, e.status) IN ('confirmed', 'pending')",
  ];
  const params = [network];

  if (scope && scope !== "all") {
    params.push(scope);
    conditions.push(tokenMintQueryScopeCondition(scope, `$${params.length}`));
  }

  const needles = tokenHistoryFilterNeedles(searchParams, pagination);
  const txidNeedles = needles.map(normalizedTxid).filter(Boolean);
  if (txidNeedles.length > 0) {
    params.push([...new Set(txidNeedles)]);
    const param = `$${params.length}`;
    conditions.push(
      `(
        lower(e.txid) = ANY(${param}::text[])
        OR lower(e.payload->>'txid') = ANY(${param}::text[])
        OR EXISTS (
          SELECT 1
          FROM proof_indexer.event_refs erq
          WHERE erq.event_id = e.event_id
            AND lower(erq.ref_value) = ANY(${param}::text[])
        )
      )`,
    );
  }

  for (const needle of needles.filter((value) => !normalizedTxid(value))) {
    params.push(`%${needle}%`);
    const param = `$${params.length}`;
    conditions.push(
      `lower(concat_ws(
        ' ',
        e.txid,
        e.payload::text,
        cd.token_id,
        cd.ticker,
        cd.registry_address
      )) LIKE ${param}`,
    );
  }

  const candidateCte = `
    WITH mint_candidates AS (
      SELECT
        e.payload,
        e.protocol,
        e.kind,
        e.status,
        COALESCE(t.status, e.status) AS effective_status,
        e.event_time,
        COALESCE(e.block_time, t.block_time) AS block_time,
        e.created_at,
        e.block_height,
        e.block_index,
        e.op_return_vout,
        e.record_ordinal,
        t.status AS transaction_status,
        t.block_height AS transaction_block_height,
        t.block_index AS transaction_block_index,
        t.block_hash AS block_hash,
        canonical_block.block_hash AS canonical_block_hash,
        e.txid,
        e.event_id,
        e.amount_sats,
        e.data_bytes,
        e.network,
        t.confirmed_at,
        t.last_seen_at,
        t.updated_at AS tx_updated_at,
        COALESCE(cd.token_id, lower(e.payload->>'tokenId')) AS token_id,
        cd.ticker,
        cd.registry_address,
        NULLIF(e.payload->>'attachedWorkLiveFloorAtSendSats', '')
          AS attached_work_live_floor_at_send_sats_text,
        NULLIF(e.payload->>'attachedWorkLiveValueAtSendSats', '')
          AS attached_work_live_value_at_send_sats_text,
        NULLIF(e.payload->>'issuanceDustSats', '')
          AS issuance_dust_sats_text,
        NULLIF(e.payload->>'issuanceFloorSats', '')
          AS issuance_floor_sats_text,
        NULLIF(e.payload->>'issuanceNetworkValueSats', '')
          AS issuance_network_value_sats_text,
        NULLIF(e.payload->>'issuanceValueSnapshotWorkNetworkValueSats', '')
          AS issuance_value_snapshot_work_network_value_sats_text,
        CASE
          WHEN COALESCE(t.status, e.status) = 'confirmed'
            AND e.block_height >= ${WORK_AMO_V5_ACTIVATION_HEIGHT}
            THEN NULL
          WHEN e.payload->>'eventKeyVout' ~ '^[0-9]{1,9}$'
            THEN (e.payload->>'eventKeyVout')::integer
          ELSE 0
        END AS mint_ordinal,
        (
          COALESCE(t.status, e.status) = 'confirmed'
          AND e.block_height >= ${WORK_AMO_V5_ACTIVATION_HEIGHT}
        ) AS canonical_v5_position,
        COALESCE(
          NULLIF(btrim(e.payload->>'minterAddress'), ''),
          NULLIF(btrim(e.payload->>'actor'), ''),
          NULLIF(btrim(e.payload->>'senderAddress'), ''),
          ''
        ) AS mint_recipient_address
      FROM proof_indexer.events e
      LEFT JOIN proof_indexer.transactions t
        ON t.network = e.network
       AND t.txid = e.txid
      LEFT JOIN proof_indexer.blocks canonical_block
        ON canonical_block.network = t.network
       AND canonical_block.block_hash = t.block_hash
       AND canonical_block.height = t.block_height
       AND canonical_block.canonical = true
      LEFT JOIN proof_indexer.credit_definitions cd
        ON cd.network = e.network
       AND cd.token_id = lower(e.payload->>'tokenId')
      WHERE ${conditions.join(" AND ")}
    )
  `;
  const cte = `
    ${candidateCte},
    mint_events AS (
      SELECT DISTINCT ON (
        lower(txid),
        lower(COALESCE(token_id, '')),
        canonical_v5_position,
        CASE WHEN canonical_v5_position THEN block_height ELSE NULL END,
        CASE WHEN canonical_v5_position THEN block_index ELSE NULL END,
        CASE WHEN canonical_v5_position THEN op_return_vout ELSE NULL END,
        CASE WHEN canonical_v5_position THEN record_ordinal ELSE NULL END,
        CASE WHEN canonical_v5_position THEN NULL ELSE mint_ordinal END,
        lower(mint_recipient_address)
      )
        *
      FROM mint_candidates
      ORDER BY
        lower(txid),
        lower(COALESCE(token_id, '')),
        canonical_v5_position,
        CASE WHEN canonical_v5_position THEN block_height ELSE NULL END,
        CASE WHEN canonical_v5_position THEN block_index ELSE NULL END,
        CASE WHEN canonical_v5_position THEN op_return_vout ELSE NULL END,
        CASE WHEN canonical_v5_position THEN record_ordinal ELSE NULL END,
        CASE WHEN canonical_v5_position THEN NULL ELSE mint_ordinal END,
        lower(mint_recipient_address),
        CASE effective_status
          WHEN 'confirmed' THEN 0
          WHEN 'pending' THEN 1
          ELSE 2
        END,
        CASE WHEN block_height IS NULL THEN 1 ELSE 0 END,
        COALESCE(block_time, event_time, confirmed_at, last_seen_at, created_at) DESC,
        event_id DESC
    )
  `;

  return { candidateCte, cte, params };
}

function tokenMintSortSql() {
  return `
    COALESCE(block_time, event_time, confirmed_at, last_seen_at, created_at) DESC,
    block_height DESC NULLS LAST,
    txid DESC,
    mint_ordinal ASC,
    lower(mint_recipient_address) ASC,
    event_id DESC
  `;
}

function canonicalTokenMintCandidateRows(rows) {
  const byMintKey = new Map();
  const integer = (value) => {
    try {
      return BigInt(String(value ?? "0"));
    } catch {
      return 0n;
    }
  };
  const ordinal = (value) => {
    const parsed = Number.parseInt(String(value ?? "0"), 10);
    return Number.isSafeInteger(parsed) ? parsed : 0;
  };
  const statusRank = (row) => {
    const status = String(row?.effective_status ?? row?.status ?? "")
      .trim()
      .toLowerCase();
    return status === "confirmed" ? 0 : status === "pending" ? 1 : 2;
  };
  const exactNonNegativeInteger = (value, minimum = 0) =>
    value !== undefined &&
    value !== null &&
    value !== "" &&
    Number.isSafeInteger(Number(value)) &&
    Number(value) >= minimum
      ? Number(value)
      : null;
  const canonicalV5Position = (row) => {
    if (statusRank(row) !== 0) {
      return null;
    }
    const blockHeight = exactNonNegativeInteger(row?.block_height, 1);
    if (
      blockHeight === null ||
      blockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT
    ) {
      return null;
    }
    const blockIndex = exactNonNegativeInteger(row?.block_index);
    const protocolVout = exactNonNegativeInteger(row?.op_return_vout);
    const recordOrdinal = exactNonNegativeInteger(row?.record_ordinal);
    if (
      blockIndex === null ||
      protocolVout === null ||
      recordOrdinal === null
    ) {
      throw new Error(
        "Canonical AMO V5 mint candidate position is incomplete.",
      );
    }
    return {
      blockHeight,
      blockIndex,
      protocolVout,
      recordOrdinal,
    };
  };
  const candidateWins = (candidate, current) => {
    const candidateStatusRank = statusRank(candidate);
    const currentStatusRank = statusRank(current);
    if (candidateStatusRank !== currentStatusRank) {
      return candidateStatusRank < currentStatusRank;
    }
    const candidateHeightRank = candidate?.block_height == null ? 1 : 0;
    const currentHeightRank = current?.block_height == null ? 1 : 0;
    if (candidateHeightRank !== currentHeightRank) {
      return candidateHeightRank < currentHeightRank;
    }
    const candidateTime = integer(candidate?.mint_winner_time_us);
    const currentTime = integer(current?.mint_winner_time_us);
    if (candidateTime !== currentTime) {
      return candidateTime > currentTime;
    }
    return integer(candidate?.event_id) > integer(current?.event_id);
  };
  const comparePublishedRows = (left, right) => {
    const leftTime = integer(left?.mint_winner_time_us);
    const rightTime = integer(right?.mint_winner_time_us);
    if (leftTime !== rightTime) {
      return leftTime > rightTime ? -1 : 1;
    }
    const leftHeight = left?.block_height == null ? null : integer(left.block_height);
    const rightHeight = right?.block_height == null ? null : integer(right.block_height);
    if (leftHeight !== rightHeight) {
      if (leftHeight === null) return 1;
      if (rightHeight === null) return -1;
      return leftHeight > rightHeight ? -1 : 1;
    }
    const leftTxid = String(left?.txid ?? "").trim().toLowerCase();
    const rightTxid = String(right?.txid ?? "").trim().toLowerCase();
    if (leftTxid !== rightTxid) {
      return leftTxid < rightTxid ? 1 : -1;
    }
    const leftPosition = canonicalV5Position(left);
    const rightPosition = canonicalV5Position(right);
    if (leftPosition || rightPosition) {
      if (!leftPosition) return 1;
      if (!rightPosition) return -1;
      const positionComparison =
        leftPosition.blockIndex - rightPosition.blockIndex ||
        leftPosition.protocolVout - rightPosition.protocolVout ||
        leftPosition.recordOrdinal - rightPosition.recordOrdinal;
      if (positionComparison !== 0) {
        return positionComparison;
      }
    }
    const leftOrdinal = ordinal(left?.mint_ordinal);
    const rightOrdinal = ordinal(right?.mint_ordinal);
    if (leftOrdinal !== rightOrdinal) {
      return leftOrdinal < rightOrdinal ? -1 : 1;
    }
    const leftRecipient = String(left?.mint_recipient_address ?? "")
      .trim()
      .toLowerCase();
    const rightRecipient = String(right?.mint_recipient_address ?? "")
      .trim()
      .toLowerCase();
    if (leftRecipient !== rightRecipient) {
      return leftRecipient < rightRecipient ? -1 : 1;
    }
    const leftEventId = integer(left?.event_id);
    const rightEventId = integer(right?.event_id);
    if (leftEventId === rightEventId) return 0;
    return leftEventId > rightEventId ? -1 : 1;
  };

  for (const row of Array.isArray(rows) ? rows : []) {
    const position = canonicalV5Position(row);
    const key = JSON.stringify([
      String(row?.txid ?? "").trim().toLowerCase(),
      String(row?.token_id ?? "").trim().toLowerCase(),
      position
        ? [
            "v5",
            position.blockHeight,
            position.blockIndex,
            position.protocolVout,
            position.recordOrdinal,
          ]
        : ["legacy", ordinal(row?.mint_ordinal)],
      String(row?.mint_recipient_address ?? "").trim().toLowerCase(),
    ]);
    const current = byMintKey.get(key);
    if (!current || candidateWins(row, current)) {
      byMintKey.set(key, row);
    }
  }
  return [...byMintKey.values()].sort(comparePublishedRows);
}

async function proofIndexTokenMintRows(
  pool,
  network,
  tokenScope,
  searchParams,
  pagination,
) {
  const { candidateCte, params } = tokenMintEventQueryParts(
    network,
    tokenScope,
    searchParams,
    pagination,
  );
  const result = await pool.query(
    `
      ${candidateCte}
      SELECT
        *,
        floor(
          extract(epoch FROM COALESCE(
            block_time,
            event_time,
            confirmed_at,
            last_seen_at,
            created_at
          )) * 1000000
        )::bigint AS mint_winner_time_us
      FROM mint_candidates
    `,
    params,
  );
  // Full token-state and mint-stat reads consume the complete result. Selecting
  // and ordering the canonical rows in JavaScript here
  // avoids carrying the large event payload through two PostgreSQL sorts while
  // preserving the same winner rules as the paginated history query.
  return canonicalTokenMintCandidateRows(result.rows);
}

export async function proofIndexTokenMintStatsPayload(
  network,
  tokenScope,
  options = {},
) {
  const pool = proofIndexPool();
  if (!pool) {
    return null;
  }
  await assertCurrentAmoV5CanonicalPositionUniqueness(pool, network);
  const scope = tokenScopeKey(tokenScope);
  if (!scope || scope === "all") {
    return null;
  }
  const targetTxid = normalizedTxid(options.targetTxid);
  const workScoped = isWorkTokenId(scope);
  const workStorageModel = workScoped
    ? await currentWorkAmountStorageModel(pool, network)
    : "";
  if (workScoped && !workStorageModel) {
    throw new Error(
      "Proof index WORK mint statistics require one canonical Q8 or Q16 definition.",
    );
  }
  const precisionCheckpointBefore =
    workScoped &&
    workStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? await proofIndexWalletCheckpointMetadata(pool, network)
      : null;
  if (
    workScoped &&
    workStorageModel === WORK_SUBATOM_PROJECTION_MODEL &&
    !precisionCheckpointBefore
  ) {
    return null;
  }

  const rows = await proofIndexTokenMintRows(
    pool,
    network,
    scope,
    new URLSearchParams(),
    { limit: TOKEN_STATE_EVENT_READ_LIMIT, offset: 0, page: 0, query: "", snapshotId: "" },
  );
  // Parse every selected row before publishing any aggregate. In particular,
  // confirmed INCB rows pass through the same full issuance and bond-binding
  // validator as history and current token-state reads.
  const mints = rows.map((row) =>
    tokenMintFromEventPayload(objectRecord(row.payload), row),
  );
  const totalMints = mints.length;
  if (totalMints <= 0) {
    return null;
  }

  const exactWholeUnits = isBondTokenId(scope);
  const exactIntegerUnits = exactWholeUnits || workScoped;
  let confirmedMints = 0;
  let confirmedSupply = exactIntegerUnits ? 0n : 0;
  let pendingMints = 0;
  let pendingSupply = exactIntegerUnits ? 0n : 0;
  let targetConfirmedMints = 0;
  let targetPendingMints = 0;
  const pendingCandidatesByTxid = new Map();
  for (const mint of mints) {
    const amount = workScoped
      ? BigInt(
          workAmountUnitsForStorageModel(
            mint,
            workStorageModel,
            { allowZero: true },
          ),
        )
      : exactWholeUnits
        ? integerBigInt(mint.amount)
        : Number(mint.amount);
    if (
      amount === null ||
      (typeof amount === "number" &&
        (!Number.isSafeInteger(amount) || amount < 0)) ||
      (typeof amount === "bigint" && amount < 0n)
    ) {
      throw new Error(
        `Proof index mint statistics contain an inexact amount for ${mint.txid || "an unknown transaction"}.`,
      );
    }
    if (mint.confirmed) {
      confirmedMints += 1;
      confirmedSupply += amount;
      if (targetTxid && normalizedTxid(mint.txid) === targetTxid) {
        targetConfirmedMints += 1;
      }
      if (
        typeof confirmedSupply === "number" &&
        !Number.isSafeInteger(confirmedSupply)
      ) {
        throw new Error("Proof index confirmed mint supply is inexact.");
      }
    } else {
      pendingMints += 1;
      pendingSupply += amount;
      const mintTxid = normalizedTxid(mint.txid);
      if (!mintTxid) {
        throw new Error("Proof index pending mint statistics contain an invalid txid.");
      }
      const existingCandidate = pendingCandidatesByTxid.get(mintTxid);
      const candidateAmount =
        (existingCandidate?.amount ?? (exactIntegerUnits ? 0n : 0)) + amount;
      if (
        typeof candidateAmount === "number" &&
        !Number.isSafeInteger(candidateAmount)
      ) {
        throw new Error("Proof index pending mint candidate supply is inexact.");
      }
      pendingCandidatesByTxid.set(mintTxid, {
        amount: candidateAmount,
        txid: mintTxid,
      });
      if (targetTxid && mintTxid === targetTxid) {
        targetPendingMints += 1;
      }
      if (
        typeof pendingSupply === "number" &&
        !Number.isSafeInteger(pendingSupply)
      ) {
        throw new Error("Proof index pending mint supply is inexact.");
      }
    }
  }

  const indexedThroughBlock = Math.max(
    0,
    ...rows.map((row) => rowNumber(row, "block_height")),
  );
  const pendingCandidateRows = [...pendingCandidatesByTxid.values()].sort(
    (left, right) => compareCanonicalUtf8(left.txid, right.txid),
  );
  const pendingCandidateSupply = pendingCandidateRows.reduce(
    (total, candidate) => total + candidate.amount,
    exactIntegerUnits ? 0n : 0,
  );
  if (
    typeof pendingCandidateSupply === "number" &&
    !Number.isSafeInteger(pendingCandidateSupply)
  ) {
    throw new Error("Proof index pending mint witness supply is inexact.");
  }
  const workSupply = workScoped
    ? workSupplyFieldsForStorageModel(
        confirmedSupply.toString(),
        pendingSupply.toString(),
        workStorageModel,
      )
    : null;
  const workPendingCandidateSupply = workScoped
    ? workSupplyFieldsForStorageModel(
        "0",
        pendingCandidateSupply.toString(),
        workStorageModel,
      )
    : null;
  if (precisionCheckpointBefore) {
    const precisionCheckpointAfter =
      await proofIndexWalletCheckpointMetadata(pool, network);
    if (
      !precisionCheckpointAfter ||
      precisionCheckpointAfter.indexedThroughBlock !==
        precisionCheckpointBefore.indexedThroughBlock ||
      precisionCheckpointAfter.indexedThroughBlockHash !==
        precisionCheckpointBefore.indexedThroughBlockHash
    ) {
      return null;
    }
    const precisionProbe =
      await payloadWithCurrentWorkPrecisionReadPolicy(
        network,
        {
          indexedThroughBlock:
            precisionCheckpointAfter.indexedThroughBlock,
          indexedThroughBlockHash:
            precisionCheckpointAfter.indexedThroughBlockHash,
          source: "proof-indexer-token-mint-stats",
          tokens: [{
            amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
            decimals: WORK_SUBATOM_DECIMALS,
            precisionModel: WORK_PRECISION_V2_MODEL,
            tokenId: scope,
            unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
          }],
        },
        {
          requireExactCheckpoint: true,
          requireSupplyEnvelope: false,
        },
      );
    if (!precisionProbe) {
      return null;
    }
  }
  return {
    confirmedMints,
    ...(workSupply ?? {
      confirmedSupply: exactWholeUnits
        ? confirmedSupply.toString()
        : confirmedSupply,
    }),
    indexedAt: newestDateIso(
      rows.flatMap((row) => [
        row.block_time,
        row.event_time,
        row.confirmed_at,
        row.last_seen_at,
        row.created_at,
      ]),
    ),
    indexedThroughBlock:
      (
        precisionCheckpointBefore?.indexedThroughBlock ??
        indexedThroughBlock
      ) ||
      undefined,
    network,
    pendingCandidateCount: pendingCandidateRows.length,
    pendingCandidates: pendingCandidateRows
      .slice(0, TOKEN_PENDING_MINT_WITNESS_LIMIT)
      .map((candidate) => ({
        txid: candidate.txid,
        amount: workScoped
          ? formatWorkAmountByProjectionMeta(
              candidate.amount.toString(),
              workSupply,
            )
          : exactWholeUnits
            ? candidate.amount.toString()
            : candidate.amount,
        ...(workScoped
          ? {
              amountStorageModel: workStorageModel,
              decimals: workSupply.decimals,
              ...(workStorageModel ===
                WORK_SUBATOM_PROJECTION_MODEL
                ? {
                    amountSubatoms: candidate.amount.toString(),
                    precisionModel: WORK_PRECISION_V2_MODEL,
                  }
                : { amountAtoms: candidate.amount.toString() }),
              unitScale: workSupply.unitScale,
            }
          : {}),
      })),
    pendingCandidatesComplete:
      pendingCandidateRows.length <= TOKEN_PENDING_MINT_WITNESS_LIMIT,
    pendingCandidateSupply: workScoped
      ? workPendingCandidateSupply.pendingSupply
      : exactWholeUnits
        ? pendingCandidateSupply.toString()
        : pendingCandidateSupply,
    ...(workScoped &&
      workStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? {
          pendingCandidateSupplySubatoms:
            pendingCandidateSupply.toString(),
        }
      : workScoped
        ? {
            pendingCandidateSupplyAtoms:
              pendingCandidateSupply.toString(),
          }
        : {}),
    pendingMints,
    ...(workSupply
      ? {}
      : {
          pendingSupply: exactWholeUnits
            ? pendingSupply.toString()
            : pendingSupply,
        }),
    pendingWitnessLimit: TOKEN_PENDING_MINT_WITNESS_LIMIT,
    source: "proof-indexer-token-mint-events",
    ...(targetTxid
      ? {
          targetMintStats: {
            confirmedMints: targetConfirmedMints,
            pendingMints: targetPendingMints,
            totalMints: targetConfirmedMints + targetPendingMints,
            txid: targetTxid,
          },
        }
      : {}),
    tokenId: scope,
    totalMints,
  };
}

async function exactTokenMintHistoryPage(
  pool,
  network,
  tokenScope,
  searchParams,
  pagination,
  snapshot,
) {
  const { cte, params } = tokenMintEventQueryParts(
    network,
    tokenScope,
    searchParams,
    pagination,
  );
  const countResult = await pool.query(
    `
      ${cte}
      SELECT
        count(*) AS total_count,
        max(block_height) AS indexed_through_block,
        max(COALESCE(block_time, event_time, confirmed_at, last_seen_at, created_at)) AS indexed_at
      FROM mint_events
    `,
    params,
  );
  const totalCount = rowNumber(countResult.rows[0], "total_count");
  if (totalCount === 0) {
    return null;
  }

  const rowParams = [...params, pagination.limit, pagination.offset];
  const limitParam = rowParams.length - 1;
  const offsetParam = rowParams.length;
  const rowsResult = await pool.query(
    `
      ${cte}
      SELECT *
      FROM mint_events
      ORDER BY ${tokenMintSortSql()}
      LIMIT $${limitParam}
      OFFSET $${offsetParam}
    `,
    rowParams,
  );
  const items = rowsResult.rows
    .map((row) => tokenMintFromEventPayload(objectRecord(row.payload), row))
    .filter(
      (item) =>
        item.txid &&
        item.tokenId &&
        tokenAmountIsPositive(item),
    );
  const start = Math.min(pagination.offset, totalCount);
  const end = Math.min(totalCount, start + pagination.limit);
  const snapshotId = snapshot?.snapshot_id ?? "";
  const page = {
    cursor: historyCursor(snapshotId, start),
    end,
    indexedAt: dateIso(countResult.rows[0]?.indexed_at ?? snapshot?.generated_at),
    indexedThroughBlock:
      rowNumber(countResult.rows[0], "indexed_through_block") || undefined,
    items,
    kind: "mints",
    limit: pagination.limit,
    network,
    nextCursor: end < totalCount ? historyCursor(snapshotId, end) : "",
    page: Math.floor(start / pagination.limit),
    pageCount: Math.max(1, Math.ceil(totalCount / pagination.limit)),
    pageSize: pagination.limit,
    query: pagination.query,
    source: "proof-indexer-token-mint-events",
    start,
    totalCount,
  };
  if (snapshotId) {
    return {
      ...page,
      consistency: snapshot?.consistency ?? undefined,
      ledgerGeneratedAt: dateIso(snapshot?.generated_at),
      snapshotId,
    };
  }
  return page;
}

export function exactBondTokenIdForMintOverlay(scope, payload, mints) {
  const scopedTokens = (Array.isArray(payload?.tokens) ? payload.tokens : [])
    .filter((token) => tokenMatchesScope(token, scope));
  const scopedBondTokenId =
    scopedTokens.length === 1 && isBondTokenId(scopedTokens[0]?.tokenId)
      ? scopedTokens[0].tokenId
      : "";
  return scopedBondTokenId &&
    Array.isArray(mints) &&
    mints.length > 0 &&
    mints.every((mint) => mint?.tokenId === scopedBondTokenId)
    ? scopedBondTokenId
    : "";
}

async function tokenStateWithMintEventOverlay(pool, network, scope, payload, snapshot) {
  if (!payload || !scope || scope === "all") {
    return payload;
  }

  const pagination = { limit: 100_000, offset: 0, page: 0, query: "", snapshotId: "" };
  const rows = await proofIndexTokenMintRows(
    pool,
    network,
    scope,
    new URLSearchParams(),
    pagination,
  );
  const mints = rows
    .map((row) => tokenMintFromEventPayload(objectRecord(row.payload), row))
    .filter((item) => {
      if (!item.txid || !item.tokenId) return false;
      if (isWorkTokenId(item.tokenId)) {
        return BigInt(
          String(item.amountSubatoms ?? item.amountAtoms ?? "0"),
        ) > 0n;
      }
      if (!isBondTokenId(item.tokenId)) return Number(item.amount) > 0;
      const amount = exactBondUnits(item.amount, { positive: true });
      return Boolean(amount) && BigInt(amount) > 0n;
    });
  if (mints.length === 0) {
    return payload;
  }

  const confirmedMints = mints.filter((mint) => mint.confirmed);
  const pendingMints = mints.filter((mint) => !mint.confirmed);
  const scopedBondTokenId = exactBondTokenIdForMintOverlay(
    scope,
    payload,
    mints,
  );
  const bondScoped = Boolean(scopedBondTokenId);
  const scopedWorkTokens = (
    Array.isArray(payload.tokens) ? payload.tokens : []
  ).filter(
    (token) =>
      tokenMatchesScope(token, scope) &&
      isWorkTokenId(token?.tokenId),
  );
  const workScoped = scopedWorkTokens.length === 1;
  const workStorageModel = workScoped
    ? scopedWorkTokens[0].amountStorageModel
    : "";
  if (
    workScoped &&
    workStorageModel !== WORK_ATOMIC_PROJECTION_MODEL &&
    workStorageModel !== WORK_SUBATOM_PROJECTION_MODEL
  ) {
    throw new Error(
      "WORK mint overlay requires an explicit Q8 or Q16 token definition.",
    );
  }
  const confirmedWorkUnits = workScoped
    ? confirmedMints.reduce(
        (total, mint) =>
          total +
          BigInt(
            workAmountUnitsForStorageModel(
              mint,
              workStorageModel,
              { allowZero: true },
            ),
          ),
        0n,
      )
    : 0n;
  const pendingWorkUnits = workScoped
    ? pendingMints.reduce(
        (total, mint) =>
          total +
          BigInt(
            workAmountUnitsForStorageModel(
              mint,
              workStorageModel,
              { allowZero: true },
            ),
          ),
        0n,
      )
    : 0n;
  const workSupply = workScoped
    ? workSupplyFieldsForStorageModel(
        confirmedWorkUnits.toString(),
        pendingWorkUnits.toString(),
        workStorageModel,
      )
    : null;
  const confirmedSupply = workSupply
    ? workSupply.confirmedSupply
    : bondScoped
      ? confirmedMints
        .reduce(
          (total, mint) => total + BigInt(exactBondUnits(mint.amount)),
          0n,
        )
        .toString()
      : confirmedMints.reduce(
          (total, mint) => total + Number(mint.amount ?? 0),
          0,
        );
  const pendingSupply = workSupply
    ? workSupply.pendingSupply
    : bondScoped
      ? pendingMints
        .reduce(
          (total, mint) => total + BigInt(exactBondUnits(mint.amount)),
          0n,
        )
        .toString()
      : pendingMints.reduce(
          (total, mint) => total + Number(mint.amount ?? 0),
          0,
        );
  const tokens = (Array.isArray(payload.tokens) ? payload.tokens : []).map((token) => {
    if (!tokenMatchesScope(token, scope)) {
      return token;
    }
    return {
      ...token,
      confirmedMints: confirmedMints.length,
      ...(workSupply ?? { confirmedSupply, pendingSupply }),
      pendingMints: pendingMints.length,
    };
  });
  const nextPayload = {
    ...payload,
    ...(workSupply ?? { confirmedSupply, pendingSupply }),
    indexedAt: newestDateIso([
      payload.indexedAt,
      snapshot?.generated_at,
      ...mints.map((mint) => mint.createdAt),
    ]),
    indexedThroughBlock:
      Math.max(
        rowNumber(payload, "indexedThroughBlock"),
        rowNumber(snapshot, "indexed_through_block"),
        indexedThroughBlockFromItems(mints) ?? 0,
      ) || undefined,
    mints,
    source: mergedSourceLabel(payload.source, "proof-indexer-token-mint-events"),
    tokens,
  };
  return {
    ...nextPayload,
    stats: tokenStateStats(
      nextPayload,
      tokens,
      mints,
      Array.isArray(nextPayload.transfers) ? nextPayload.transfers : [],
      Array.isArray(nextPayload.invalidEvents) ? nextPayload.invalidEvents : [],
    ),
  };
}

async function filterClosedTokenListingHistoryPage(pool, page, network) {
  if (!page || !Array.isArray(page.items) || page.items.length === 0) {
    return page;
  }

  const listingIds = [...new Set(page.items.map(tokenListingId).filter(Boolean))];
  if (listingIds.length === 0) {
    return page;
  }

  const result = await pool.query(
    `
      SELECT closed_listing.listing_id
      FROM (
        SELECT DISTINCT
          lower(COALESCE(e.payload->>'listingId', e.txid)) AS listing_id
        FROM proof_indexer.events e
        WHERE e.network = $1
          AND e.protocol = 'pwt1'
          AND e.valid = true
          AND e.kind = 'token-listing'
          AND e.status = 'dropped'
          AND lower(
            COALESCE(e.payload->>'listingId', e.txid)
          ) = ANY($2::text[])
        UNION
        SELECT DISTINCT lower(spent_listing.listing_id) AS listing_id
        FROM proof_indexer.credit_listings spent_listing
        JOIN proof_indexer.tx_inputs spend_input
          ON spend_input.network = spent_listing.network
         AND spend_input.prev_txid = lower(
           COALESCE(
             NULLIF(spent_listing.sale_ticket_txid, ''),
             spent_listing.listing_id
           )
         )
         AND spend_input.prev_vout = spent_listing.sale_ticket_vout
        JOIN proof_indexer.transactions spend_tx
          ON spend_tx.network = spend_input.network
         AND spend_tx.txid = spend_input.txid
         AND spend_tx.status = 'confirmed'
        JOIN proof_indexer.blocks spend_block
          ON spend_block.network = spend_tx.network
         AND spend_block.block_hash = spend_tx.block_hash
         AND spend_block.height = spend_tx.block_height
         AND spend_block.canonical = true
        WHERE spent_listing.network = $1
          AND lower(spent_listing.listing_id) = ANY($2::text[])
      ) closed_listing
    `,
    [network, listingIds],
  );
  const closedListingIds = new Set(
    result.rows
      .map((row) => String(row?.listing_id ?? "").trim().toLowerCase())
      .filter(Boolean),
  );
  if (closedListingIds.size === 0) {
    return page;
  }

  const items = page.items.filter(
    (item) => !closedListingIds.has(tokenListingId(item)),
  );
  return {
    ...page,
    items,
    totalCount: Math.max(
      0,
      Number(page.totalCount ?? page.items.length) -
        (page.items.length - items.length),
    ),
  };
}

async function exactActiveTokenListingHistoryPage(
  pool,
  network,
  tokenScope,
  searchParams,
  pagination,
  snapshot,
) {
  const needles = tokenHistoryFilterNeedles(searchParams, pagination);
  const txidNeedles = needles.map(normalizedTxid).filter(Boolean);
  if (
    txidNeedles.length === 0 ||
    needles.some((value) => !normalizedTxid(value))
  ) {
    return null;
  }

  const scope = tokenScopeKey(tokenScope);
  const uniqueTxids = [...new Set(txidNeedles)];
  const params = [network, uniqueTxids];
  const snapshotHeight = rowNumber(snapshot, "indexed_through_block");
  const workMarketV4Activation = await verifiedWorkMarketV4Activation(
    pool,
    network,
    snapshotHeight,
  );
  const currentWorkMarketAuthorizationVersions =
    await currentWorkMarketAuthorizationVersionsAtSnapshot(
      network,
      snapshotHeight,
      workMarketV4Activation,
    );
  const workMarketV2Active =
    network === "livenet" &&
    (snapshotHeight === 0 ||
      snapshotHeight >= WORK_MARKET_V2_ACTIVATION_HEIGHT);
  const conditions = [
    "cl.network = $1",
    `(
      cl.listing_id = ANY($2::text[])
      OR cl.sale_ticket_txid = ANY($2::text[])
      OR cl.seal_txid = ANY($2::text[])
      OR cl.close_txid = ANY($2::text[])
    )`,
    canonicalWorkMarketV3ListingProjectionSql("cl"),
    tokenListingActiveLifecycleSql("cl"),
  ];
  let currentWorkMarketAuthorizationVersionsParam = "";
  if (scope && scope !== "all") {
    params.push(scope);
    conditions.push("cl.token_id = $3");
  }
  if (workMarketV2Active) {
    params.push(WORK_TOKEN_ID, currentWorkMarketAuthorizationVersions);
    currentWorkMarketAuthorizationVersionsParam = `$${params.length}`;
    const workTokenParam = `$${params.length - 1}`;
    conditions.push(
      `(
        lower(COALESCE(cl.token_id, '')) <> ${workTokenParam}
        OR lower(COALESCE(
          cl.payload->'saleAuthorization'->>'version',
          ''
        )) = ANY(${currentWorkMarketAuthorizationVersionsParam}::text[])
      )`,
    );
  }

  const whereClause = conditions.join(" AND ");
  const countResult = await pool.query(
    `
      SELECT
        count(*) AS total_count,
        max(cl.updated_at) AS indexed_at
      FROM proof_indexer.credit_listings cl
      WHERE ${whereClause}
    `,
    params,
  );
  const totalCount = rowNumber(countResult.rows[0], "total_count");
  let terminalMiss = false;
  if (totalCount === 0) {
    const terminalParams = [network, uniqueTxids];
    let workMarketCutoverMissSql = "";
    if (workMarketV2Active) {
      terminalParams.push(
        WORK_TOKEN_ID,
        currentWorkMarketAuthorizationVersions,
      );
      const workTokenParam = `$${terminalParams.length - 1}`;
      const workMarketAuthorizationVersionParam =
        `$${terminalParams.length}`;
      workMarketCutoverMissSql = `OR EXISTS (
        SELECT 1
        FROM proof_indexer.credit_listings cutover_listing
        WHERE cutover_listing.network = $1
          AND (
            cutover_listing.listing_id = ANY($2::text[])
            OR cutover_listing.sale_ticket_txid = ANY($2::text[])
            OR cutover_listing.seal_txid = ANY($2::text[])
            OR cutover_listing.close_txid = ANY($2::text[])
          )
          AND lower(cutover_listing.token_id) = ${workTokenParam}
          AND lower(COALESCE(
            cutover_listing.payload->'saleAuthorization'->>'version',
            ''
          )) <> ALL(${workMarketAuthorizationVersionParam}::text[])
      )`;
    }
    const terminalResult = await pool.query(
      `
        WITH candidate_events AS (
          SELECT direct.event_id
          FROM proof_indexer.events direct
          WHERE direct.network = $1
            AND direct.txid = ANY($2::text[])
          UNION
          SELECT refs.event_id
          FROM proof_indexer.event_refs refs
          JOIN proof_indexer.events referenced
            ON referenced.event_id = refs.event_id
           AND referenced.network = $1
          WHERE refs.ref_value = ANY($2::text[])
        )
        SELECT (
          EXISTS (
            SELECT 1
            FROM proof_indexer.transactions terminal_tx
            WHERE terminal_tx.network = $1
              AND terminal_tx.txid = ANY($2::text[])
              AND terminal_tx.status IN ('dropped', 'orphaned')
          )
          OR EXISTS (
            SELECT 1
            FROM proof_indexer.credit_listings terminal_listing
            WHERE terminal_listing.network = $1
              AND (
                terminal_listing.listing_id = ANY($2::text[])
                OR terminal_listing.sale_ticket_txid = ANY($2::text[])
                OR terminal_listing.seal_txid = ANY($2::text[])
                OR terminal_listing.close_txid = ANY($2::text[])
              )
              AND terminal_listing.status IN (
                'dropped',
                'orphaned'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM proof_indexer.credit_listings spent_terminal_listing
            JOIN proof_indexer.tx_inputs terminal_spend_input
              ON terminal_spend_input.network =
                spent_terminal_listing.network
             AND terminal_spend_input.prev_txid = lower(
               COALESCE(
                 NULLIF(spent_terminal_listing.sale_ticket_txid, ''),
                 spent_terminal_listing.listing_id
               )
             )
             AND terminal_spend_input.prev_vout =
               spent_terminal_listing.sale_ticket_vout
            JOIN proof_indexer.transactions terminal_spend_tx
              ON terminal_spend_tx.network = terminal_spend_input.network
             AND terminal_spend_tx.txid = terminal_spend_input.txid
             AND terminal_spend_tx.status = 'confirmed'
            JOIN proof_indexer.blocks terminal_spend_block
              ON terminal_spend_block.network = terminal_spend_tx.network
             AND terminal_spend_block.block_hash =
               terminal_spend_tx.block_hash
             AND terminal_spend_block.height =
               terminal_spend_tx.block_height
             AND terminal_spend_block.canonical = true
            WHERE spent_terminal_listing.network = $1
              AND (
                spent_terminal_listing.listing_id = ANY($2::text[])
                OR spent_terminal_listing.sale_ticket_txid =
                  ANY($2::text[])
              )
          )
          ${workMarketCutoverMissSql}
          OR EXISTS (
            SELECT 1
            FROM candidate_events candidate
            JOIN proof_indexer.events terminal_event
              ON terminal_event.event_id = candidate.event_id
            WHERE terminal_event.protocol = 'pwt1'
              AND terminal_event.txid = ANY($2::text[])
              AND (
                terminal_event.valid = false
                OR terminal_event.status IN ('dropped', 'orphaned')
              )
          )
        ) AS terminal
      `,
      terminalParams,
    );
    terminalMiss = terminalResult.rows[0]?.terminal === true;
    if (!terminalMiss) {
      return null;
    }
  }
  const rowParams = [...params, pagination.limit, pagination.offset];
  const limitParam = rowParams.length - 1;
  const offsetParam = rowParams.length;
  const rowsResult =
    totalCount > 0
      ? await pool.query(
          `
            SELECT
              cl.listing_id,
              cl.status,
              cl.token_id,
              cl.seller_address,
              cl.buyer_address,
              cl.amount,
              cl.price_sats,
              cl.sale_ticket_txid,
              cl.sale_ticket_vout,
              cl.sale_ticket_value_sats,
              cl.seal_txid,
              cl.close_txid,
              cl.payload,
              cl.updated_at,
              listing_tx.block_hash AS listing_block_hash,
              listing_tx.block_height AS listing_block_height,
              listing_tx.block_index AS listing_transaction_block_index,
              listing_tx.block_time AS listing_block_time,
              listing_tx.status AS listing_tx_status,
              canonical_listing_event.listing_event_status,
              canonical_listing_event.listing_event_block_hash,
              canonical_listing_event.listing_event_block_height,
              canonical_listing_event.listing_event_block_index,
              canonical_listing_event.listing_event_protocol_vout,
              canonical_listing_event.listing_event_record_ordinal,
              canonical_listing_event.listing_event_match_count,
              seal_tx.status AS seal_tx_status,
              seal_tx.block_height AS seal_transaction_block_height,
              canonical_seal_event.seal_event_status,
              canonical_seal_event.seal_event_block_hash,
              canonical_seal_event.seal_event_block_height,
              canonical_seal_event.seal_event_block_index,
              canonical_seal_event.seal_event_protocol_vout,
              canonical_seal_event.seal_event_record_ordinal,
              canonical_seal_event.seal_event_match_count,
              cd.ticker,
              cd.registry_address,
              cd.metadata AS token_metadata
            FROM proof_indexer.credit_listings cl
            LEFT JOIN proof_indexer.transactions listing_tx
              ON listing_tx.network = cl.network
             AND listing_tx.txid = cl.listing_id
            ${canonicalTokenListingEventJoinSql("cl")}
            LEFT JOIN proof_indexer.transactions seal_tx
              ON seal_tx.network = cl.network
             AND seal_tx.txid = cl.seal_txid
            ${canonicalTokenListingSealEventJoinSql("cl")}
            LEFT JOIN proof_indexer.credit_definitions cd
              ON cd.network = cl.network
             AND cd.token_id = cl.token_id
            WHERE ${whereClause}
            ORDER BY cl.updated_at DESC, cl.listing_id ASC
            LIMIT $${limitParam}
            OFFSET $${offsetParam}
          `,
          rowParams,
        )
      : { rows: [] };
  const closeResult =
    totalCount > 0
      ? await pool.query(
          `
            SELECT closed_listing.listing_id
            FROM (
              SELECT DISTINCT lower(spent_listing.listing_id) AS listing_id
              FROM proof_indexer.credit_listings spent_listing
              JOIN proof_indexer.tx_inputs spend_input
                ON spend_input.network = spent_listing.network
               AND spend_input.prev_txid = lower(
                 COALESCE(
                   NULLIF(spent_listing.sale_ticket_txid, ''),
                   spent_listing.listing_id
                 )
               )
               AND spend_input.prev_vout = spent_listing.sale_ticket_vout
              JOIN proof_indexer.transactions spend_tx
                ON spend_tx.network = spend_input.network
               AND spend_tx.txid = spend_input.txid
               AND spend_tx.status = 'confirmed'
              JOIN proof_indexer.blocks spend_block
                ON spend_block.network = spend_tx.network
               AND spend_block.block_hash = spend_tx.block_hash
               AND spend_block.height = spend_tx.block_height
               AND spend_block.canonical = true
              WHERE spent_listing.network = $1
                AND lower(spent_listing.listing_id) = ANY($2::text[])
            ) closed_listing
          `,
          [network, uniqueTxids],
        )
      : { rows: [] };
  const closedListingIds = new Set(
    closeResult.rows
      .map((row) => String(row?.listing_id ?? "").trim().toLowerCase())
      .filter(Boolean),
  );

  const items = rowsResult.rows
    .map((row) => {
      const listing = activeTokenListingFromCreditListingRow(row, network);
      const sealTxid = normalizedLowerText(
        row?.seal_txid ?? row?.payload?.sealTxid,
      );
      return {
        ...listing,
        sealConfirmed: tokenListingSealConfirmedFromTransaction(
          row,
          sealTxid,
        ),
      };
    })
    .filter(activeTokenListingHistoryItem)
    .filter((item) => !closedListingIds.has(tokenListingId(item)))
    .sort(compareTokenHistoryMarketItems);

  const page = tokenHistoryPageFromItems({
    indexedAt: dateIso(
      countResult.rows[0]?.indexed_at ?? snapshot?.generated_at,
    ),
    indexedThroughBlock:
      rowNumber(snapshot, "indexed_through_block") || undefined,
    items,
    kind: "listings",
    network,
    pagination,
    source: terminalMiss
      ? "proof-indexer-credit-listings-terminal"
      : "proof-indexer-credit-listings-exact",
    snapshot,
  });
  return workMarketV4Activation
    ? { ...page, workMarketV4Activation }
    : page;
}

export function proofIndexLogHistoryReadEligibility(kind, searchParams) {
  const requestedKind = String(kind ?? "").trim().toLowerCase();
  const pagination = historyPaginationFromSearch(searchParams);
  const params = searchParams ?? new URLSearchParams();
  const cursorRaw = String(params.get("cursor") ?? "").trim();

  if (requestedKind) {
    return {
      eligible: true,
      pagination,
      reason: "kind-filter",
    };
  }

  if (pagination.query) {
    return {
      eligible: true,
      pagination,
      reason: "query",
    };
  }

  if (cursorRaw || pagination.snapshotId || pagination.offset > 0) {
    return {
      eligible: true,
      pagination,
      reason: "snapshot-pinned-activity",
    };
  }

  return {
    eligible: false,
    pagination,
    reason: "volatile-first-page-canonical",
  };
}

export function proofIndexTokenHistoryReadEligibility(
  tokenScope,
  kind,
  searchParams,
) {
  const pagination = historyPaginationFromSearch(searchParams);
  const params = searchParams ?? new URLSearchParams();
  const walletScoped = /^(?:1|true|yes)$/iu.test(
    String(params.get("wallet") ?? "").trim(),
  );
  if (walletScoped) {
    return {
      eligible: false,
      kind: tokenHistorySafeKind(kind),
      pagination,
      reason: "wallet-scoped-canonical",
      scope: tokenScopeKey(tokenScope),
    };
  }

  const safeKind = tokenHistorySafeKind(kind);
  return {
    eligible: true,
    kind: safeKind,
    pagination,
    reason:
      pagination.query || tokenHistoryFilterNeedles(params, pagination).length > 0
        ? "query"
        : "snapshot-pinned-token-history",
    scope: tokenScopeKey(tokenScope),
  };
}

export function proofIndexTokenReadEligibility(tokenScope, searchParams) {
  const params = searchParams ?? new URLSearchParams();
  const walletScoped = /^(?:1|true|yes)$/iu.test(
    String(params.get("wallet") ?? "").trim(),
  );
  const scopedAddressParams = [
    "address",
    "owner",
    "ownerAddress",
    "seller",
    "sellerAddress",
    "buyer",
    "buyerAddress",
  ].some((key) => params.has(key));
  const query = String(params.get("q") ?? params.get("search") ?? "").trim();
  if (walletScoped || scopedAddressParams || query) {
    return {
      eligible: false,
      reason: walletScoped ? "wallet-scoped-canonical" : "query-scoped-canonical",
      scope: tokenScopeKey(tokenScope),
    };
  }

  return {
    eligible: true,
    reason: "snapshot-pinned-token-state",
    scope: tokenScopeKey(tokenScope),
  };
}

function rowNumber(row, key) {
  const number = Number(row?.[key]);
  return Number.isFinite(number) ? number : 0;
}

function workAmountProjectionMetadata(record, metadata = {}) {
  const item = objectRecord(record);
  const normalizedMetadata = objectRecord(metadata);
  const explicitMetadata = [
    normalizedMetadata,
    item,
  ].flatMap((candidate) =>
    validateWorkPrecisionMetadata(candidate)
      ? [{
          amountStorageModel: candidate.amountStorageModel,
          decimals: Number(candidate.decimals),
          unitScale: String(candidate.unitScale),
        }]
      : [],
  );
  if (
    explicitMetadata.length === 2 &&
    JSON.stringify(explicitMetadata[0]) !==
      JSON.stringify(explicitMetadata[1])
  ) {
    throw new Error("WORK precision metadata aliases conflict.");
  }

  const saleAuthorization =
    item.saleAuthorization &&
    typeof item.saleAuthorization === "object" &&
    !Array.isArray(item.saleAuthorization)
      ? item.saleAuthorization
      : {};
  const listingAuthorization =
    item.listingAuthorization &&
    typeof item.listingAuthorization === "object" &&
    !Array.isArray(item.listingAuthorization)
      ? item.listingAuthorization
      : {};
  const tokenId = String(
    item.tokenId ??
      item.payload?.tokenId ??
      saleAuthorization.tokenId ??
      listingAuthorization.tokenId ??
      item.token_id ??
      "",
  )
    .trim()
    .toLowerCase();
  const frozenTerms =
    item.frozenTerms &&
    typeof item.frozenTerms === "object" &&
    !Array.isArray(item.frozenTerms)
      ? item.frozenTerms
      : {};
  const workAmoFrozenTerms =
    item.workAmoFrozenTerms &&
    typeof item.workAmoFrozenTerms === "object" &&
    !Array.isArray(item.workAmoFrozenTerms)
      ? item.workAmoFrozenTerms
      : {};
  const listingFrozenTerms =
    item.listingFrozenTerms &&
    typeof item.listingFrozenTerms === "object" &&
    !Array.isArray(item.listingFrozenTerms)
      ? item.listingFrozenTerms
      : {};
  const metadataVersion = String(
    item.version ??
      item.amountVersion ??
      item.transferVersion ??
      saleAuthorization.version ??
      listingAuthorization.version ??
      item.authorizationVersion ??
      frozenTerms.version ??
      workAmoFrozenTerms.version ??
      listingFrozenTerms.version ??
      "",
  )
    .trim()
    .toLowerCase();
  const versionModel =
    tokenId === WORK_TOKEN_ID &&
    (
      metadataVersion === WORK_AMO_V8_AUTH_VERSION ||
      metadataVersion === WORK_AMO_V8_TRANSFER_VERSION
    )
      ? WORK_SUBATOM_PROJECTION_MODEL
      : "";
  if (
    explicitMetadata.length > 0 &&
    versionModel &&
    explicitMetadata[0].amountStorageModel !== versionModel
  ) {
    throw new Error(
      "WORK authorization version conflicts with precision metadata.",
    );
  }
  if (explicitMetadata.length > 0) {
    return explicitMetadata[0];
  }

  if (versionModel === WORK_SUBATOM_PROJECTION_MODEL) {
    return {
      amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
      decimals: WORK_SUBATOM_DECIMALS,
      unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
    };
  }

  return {
    amountStorageModel: WORK_LEGACY_ATOMIC_PROJECTION_MODEL,
    decimals: WORK_DECIMALS,
    unitScale: WORK_UNIT_SCALE_TEXT,
  };
}

function workAmountProjectionMetadataForAmount(workAmount) {
  if (
    !workAmount ||
    typeof workAmount !== "object" ||
    Array.isArray(workAmount)
  ) {
    return {};
  }
  const subatomic =
    workAmount.amountStorageModel ===
      WORK_SUBATOM_PROJECTION_MODEL;
  return {
    amountStorageModel: workAmount.amountStorageModel,
    decimals: workAmount.decimals,
    ...(subatomic
      ? {
          amountSubatoms: workAmount.amountSubatoms,
          precisionModel: WORK_PRECISION_V2_MODEL,
        }
      : { amountAtoms: workAmount.amountAtoms }),
    unitScale: workAmount.unitScale,
  };
}

function recordWithoutWorkAmountAliases(record) {
  const {
    amount: ignoredAmount,
    amountAtoms: ignoredAmountAtoms,
    amountStorageModel: ignoredAmountStorageModel,
    amountSubatoms: ignoredAmountSubatoms,
    decimals: ignoredDecimals,
    precisionModel: ignoredPrecisionModel,
    tokenAmount: ignoredTokenAmount,
    tokenAmountAtoms: ignoredTokenAmountAtoms,
    tokenAmountSubatoms: ignoredTokenAmountSubatoms,
    unitScale: ignoredUnitScale,
    ...remainder
  } = objectRecord(record);
  void ignoredAmount;
  void ignoredAmountAtoms;
  void ignoredAmountStorageModel;
  void ignoredAmountSubatoms;
  void ignoredDecimals;
  void ignoredPrecisionModel;
  void ignoredTokenAmount;
  void ignoredTokenAmountAtoms;
  void ignoredTokenAmountSubatoms;
  void ignoredUnitScale;
  return remainder;
}

function payloadWithWorkAmountProjection(record, workAmount) {
  const item = objectRecord(record);
  return {
    ...recordWithoutWorkAmountAliases(item),
    amount: workAmount.amount,
    ...workAmountProjectionMetadataForAmount(workAmount),
  };
}

function formatWorkAmountByProjectionMeta(amountUnits, amountMetadata = {}) {
  if (
    amountMetadata.amountStorageModel ===
      WORK_SUBATOM_PROJECTION_MODEL &&
    Number(amountMetadata.decimals) === WORK_SUBATOM_DECIMALS &&
    String(amountMetadata.unitScale ?? "") ===
      WORK_SUBATOM_UNIT_SCALE_TEXT
  ) {
    return formatWorkSubatoms(amountUnits);
  }
  return formatWorkAtoms(amountUnits);
}

function workAtomicProjectionMetadata(metadata) {
  return validateWorkPrecisionMetadata(objectRecord(metadata));
}

function storedWorkAtoms(value, metadata, { signed = false } = {}) {
  const amountMetadata = workAmountProjectionMetadata({}, metadata);
  if (
    amountMetadata.amountStorageModel ===
      WORK_SUBATOM_PROJECTION_MODEL
  ) {
    return normalizeWorkSubatoms(value, {
      allowNegative: signed,
      allowZero: true,
    });
  }
  if (workAtomicProjectionMetadata(metadata)) {
    return normalizeWorkAtoms(value, {
      allowNegative: signed,
      allowZero: true,
    });
  }
  return signed
    ? parseSignedWorkAmountToAtoms(value)
    : parseWorkAmountToAtoms(value, { allowZero: true });
}

function workAmountProjection(
  record,
  {
    metadata = {},
    storedAmount,
    storedAmountIsAtoms = false,
    allowZero = false,
    targetStorageModel = "",
  } = {},
) {
  let amountMetadata = workAmountProjectionMetadata(record, metadata);
  let subatomic =
    amountMetadata.amountStorageModel ===
      WORK_SUBATOM_PROJECTION_MODEL;
  const item = objectRecord(record);
  const topLevelSubatomAliases = [
    item.amountSubatoms,
    item.tokenAmountSubatoms,
  ].filter(
    (candidate) =>
      candidate !== undefined && candidate !== null && candidate !== "",
  );
  const topLevelAtomAliases = [
    item.amountAtoms,
    item.tokenAmountAtoms,
  ].filter(
    (candidate) =>
      candidate !== undefined && candidate !== null && candidate !== "",
  );
  let amountUnits =
    storedAmount !== undefined
      ? storedAmountIsAtoms || workAtomicProjectionMetadata(metadata)
        ? subatomic
          ? normalizeWorkSubatoms(storedAmount, { allowZero })
          : normalizeWorkAtoms(storedAmount, { allowZero })
        : subatomic
          ? parseWorkAmountToSubatoms(storedAmount, { allowZero })
          : parseWorkAmountToAtoms(storedAmount, { allowZero })
      : subatomic
        ? topLevelSubatomAliases.length > 0
          ? topLevelSubatomAliases.length === 1 &&
            topLevelAtomAliases.length === 0
            ? normalizeWorkSubatoms(topLevelSubatomAliases[0], {
                allowZero,
              })
            : (() => {
                throw new TypeError(
                  "Current Q16 WORK projection aliases are ambiguous.",
                );
              })()
          : workAmountSubatomsFromRecord(record, {
              allowZero,
              sourceModel: amountMetadata.amountStorageModel,
            })
        : workAmountAtomsFromRecord(record, { allowZero });
  const normalizedTargetStorageModel = String(
    targetStorageModel ?? "",
  ).trim();
  if (
    normalizedTargetStorageModel &&
    normalizedTargetStorageModel !== amountMetadata.amountStorageModel
  ) {
    if (
      amountMetadata.amountStorageModel !==
        WORK_ATOMIC_PROJECTION_MODEL ||
      normalizedTargetStorageModel !==
        WORK_SUBATOM_PROJECTION_MODEL
    ) {
      throw new TypeError(
        "Native Q16 WORK cannot be projected back into historical Q8 atoms.",
      );
    }
    amountUnits = (
      BigInt(normalizeWorkAtoms(amountUnits, { allowZero })) *
      WORK_SUBATOM_CONVERSION_FACTOR
    ).toString();
    amountMetadata = {
      amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
      decimals: WORK_SUBATOM_DECIMALS,
      unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
    };
    subatomic = true;
  } else if (
    normalizedTargetStorageModel &&
    normalizedTargetStorageModel !== WORK_ATOMIC_PROJECTION_MODEL &&
    normalizedTargetStorageModel !== WORK_SUBATOM_PROJECTION_MODEL
  ) {
    throw new TypeError(
      "WORK projection target requires an explicit Q8 or Q16 storage model.",
    );
  }
  return {
    amount: formatWorkAmountByProjectionMeta(
      amountUnits,
      amountMetadata,
    ),
    amountStorageModel: amountMetadata.amountStorageModel,
    units: amountUnits,
    ...(subatomic
      ? { amountSubatoms: amountUnits }
      : { amountAtoms: amountUnits }),
    decimals: amountMetadata.decimals,
    unitScale: amountMetadata.unitScale,
  };
}

function workListingAmountProjection(
  record,
  {
    metadata = {},
    storedAmount,
  } = {},
) {
  const item = objectRecord(record);
  const saleAuthorization = objectRecord(
    item.saleAuthorization ?? item.listingAuthorization,
  );
  const authorizationVersion = String(
    saleAuthorization.version ?? item.authorizationVersion ?? "",
  ).trim();
  const currentMetadata = workAmountProjectionMetadata({}, metadata);
  if (
    currentMetadata.amountStorageModel ===
      WORK_SUBATOM_PROJECTION_MODEL &&
    authorizationVersion &&
    authorizationVersion !== WORK_AMO_V8_AUTH_VERSION
  ) {
    const legacyProjection = workAmountProjection(item);
    if (
      legacyProjection.amountStorageModel !==
        WORK_ATOMIC_PROJECTION_MODEL ||
      storedAmount === undefined ||
      normalizeWorkSubatoms(storedAmount, {
        allowZero: true,
      }) !==
        legacyWorkAtomsToSubatoms(
          legacyProjection.amountAtoms,
          { allowZero: true },
        )
    ) {
      throw new Error(
        "Migrated legacy WORK listing does not conserve its immutable Q8 amount.",
      );
    }
    return workAmountProjection(
      {},
      {
        metadata: currentMetadata,
        storedAmount,
        storedAmountIsAtoms: true,
      },
    );
  }
  return workAmountProjection(item, {
    metadata,
    storedAmount,
    storedAmountIsAtoms: true,
  });
}

export function workBalanceProjection(
  value,
  metadata,
  { signed = false } = {},
) {
  const units = storedWorkAtoms(value, metadata, { signed });
  const amountMetadata = workAmountProjectionMetadata({}, metadata);
  const subatomic =
    amountMetadata.amountStorageModel ===
      WORK_SUBATOM_PROJECTION_MODEL;
  return {
    amount: formatWorkAmountByProjectionMeta(units, amountMetadata),
    amountStorageModel: amountMetadata.amountStorageModel,
    decimals: amountMetadata.decimals,
    units,
    ...(subatomic ? { subatoms: units } : { atoms: units }),
    unitScale: amountMetadata.unitScale,
  };
}

function workBalanceUnitFields(
  projection,
  {
    atomField,
    subatomField,
  },
) {
  const subatomic =
    projection?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL;
  if (
    !projection ||
    (!subatomic &&
      projection.amountStorageModel !== WORK_ATOMIC_PROJECTION_MODEL)
  ) {
    throw new TypeError(
      "WORK balance fields require an explicit Q8 or Q16 projection.",
    );
  }
  return {
    amountStorageModel: projection.amountStorageModel,
    decimals: projection.decimals,
    ...(subatomic
      ? {
          [subatomField]: projection.subatoms,
          precisionModel: WORK_PRECISION_V2_MODEL,
        }
      : { [atomField]: projection.atoms }),
    unitScale: projection.unitScale,
  };
}

export function workAmountUnitsForStorageModel(
  record,
  targetStorageModel,
  { allowZero = true } = {},
) {
  if (
    targetStorageModel !== WORK_ATOMIC_PROJECTION_MODEL &&
    targetStorageModel !== WORK_SUBATOM_PROJECTION_MODEL
  ) {
    throw new TypeError(
      "WORK aggregate target requires an explicit Q8 or Q16 storage model.",
    );
  }
  const projected = workAmountProjection(record, { allowZero });
  if (projected.amountStorageModel === targetStorageModel) {
    return projected.units;
  }
  if (
    projected.amountStorageModel === WORK_ATOMIC_PROJECTION_MODEL &&
    targetStorageModel === WORK_SUBATOM_PROJECTION_MODEL
  ) {
    return legacyWorkAtomsToSubatoms(projected.amountAtoms, {
      allowZero,
    });
  }
  throw new TypeError(
    "Native Q16 WORK cannot be projected back into historical Q8 atoms.",
  );
}

export function workSupplyFieldsForStorageModel(
  confirmedUnits,
  pendingUnits,
  storageModel,
) {
  const subatomic = storageModel === WORK_SUBATOM_PROJECTION_MODEL;
  if (!subatomic && storageModel !== WORK_ATOMIC_PROJECTION_MODEL) {
    throw new TypeError(
      "WORK supply requires an explicit Q8 or Q16 storage model.",
    );
  }
  const normalize = subatomic ? normalizeWorkSubatoms : normalizeWorkAtoms;
  const format = subatomic ? formatWorkSubatoms : formatWorkAtoms;
  const confirmed = normalize(confirmedUnits, { allowZero: true });
  const pending = normalize(pendingUnits, {
    allowNegative: true,
    allowZero: true,
  });
  return {
    amountStorageModel: storageModel,
    confirmedSupply: format(confirmed),
    decimals: subatomic ? WORK_SUBATOM_DECIMALS : WORK_DECIMALS,
    pendingSupply: format(pending, { allowNegative: true }),
    ...(subatomic
      ? {
          confirmedSupplySubatoms: confirmed,
          pendingSupplySubatoms: pending,
          precisionModel: WORK_PRECISION_V2_MODEL,
        }
      : {
          confirmedSupplyAtoms: confirmed,
          pendingSupplyAtoms: pending,
        }),
    unitScale: subatomic
      ? WORK_SUBATOM_UNIT_SCALE_TEXT
      : WORK_UNIT_SCALE_TEXT,
  };
}

function tokenAmountIsPositive(item) {
  if (isWorkTokenId(item?.tokenId)) {
    const storageModel = item?.amountStorageModel;
    if (storageModel === WORK_SUBATOM_PROJECTION_MODEL) {
      return BigInt(String(item?.amountSubatoms ?? "0")) > 0n;
    }
    if (storageModel === WORK_ATOMIC_PROJECTION_MODEL) {
      return BigInt(String(item?.amountAtoms ?? "0")) > 0n;
    }
    throw new Error(
      "WORK amount requires an explicit Q8 or Q16 projection.",
    );
  }
  if (isBondTokenId(item?.tokenId)) {
    const amount = integerBigInt(item?.amount);
    return amount !== null && amount > 0n;
  }
  const amount = Number(item?.amount);
  return Number.isFinite(amount) && amount > 0;
}

function addAtomicStrings(left, right) {
  return (BigInt(String(left ?? "0")) + BigInt(String(right ?? "0"))).toString();
}

function maxAtomicStrings(left, right) {
  const leftValue = BigInt(String(left ?? "0"));
  const rightValue = BigInt(String(right ?? "0"));
  return (leftValue >= rightValue ? leftValue : rightValue).toString();
}

function canonicalEventIdentityDetails(item = {}) {
  return [
    "_powEventIndex",
    "eventKeyVout",
    "protocolVout",
    "recordOrdinal",
    "eventId",
  ]
    .reduce((details, key) => {
      const rawValue = item?.[key];
      if (
        rawValue === undefined ||
        rawValue === null ||
        rawValue === ""
      ) {
        return details;
      }
      const value = Number(rawValue);
      if (Number.isSafeInteger(value) && value >= 0) {
        details[key] = value;
      }
      return details;
    }, {});
}

function objectRecord(value) {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value
    : {};
}

function inputAddressesFromRawTransaction(rawTx) {
  const tx = objectRecord(rawTx);
  const vin = Array.isArray(tx.vin) ? tx.vin : [];
  return [
    ...new Set(
      vin
        .map((input) =>
          String(input?.prevout?.scriptpubkey_address ?? input?.address ?? "")
            .trim(),
        )
        .filter(Boolean),
    ),
  ];
}

function canonicalEventPayload(payload) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return {};
  }
  const { indexedFrom, ...item } = payload;
  return item;
}

function rawTransactionItemPayload(row) {
  const raw = row?.transaction_raw_tx;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return {};
  }
  const item = raw.item;
  if (item && typeof item === "object" && !Array.isArray(item)) {
    return item;
  }
  return raw;
}

function normalizedText(value) {
  return String(value ?? "").trim();
}

function normalizedLowerText(value) {
  return normalizedText(value).toLowerCase();
}

function bondTagForMemo(value) {
  const memo = normalizedLowerText(value);
  return BOND_TAGS.find((tag) => tag.memo === memo) ?? null;
}

function bondTagForKind(value) {
  const kind = normalizedLowerText(value);
  return BOND_TAGS.find((tag) => tag.kind === kind) ?? null;
}

function bondTagForEventPayload(payload, row = {}) {
  const kind = normalizedLowerText(payload?.kind ?? row.kind);
  const direct = bondTagForKind(kind);
  if (direct) {
    return direct;
  }
  if (kind !== "mail") {
    return null;
  }
  for (const value of [
    payload?.detail,
    payload?.memo,
    payload?.body,
    payload?.message,
    row.body_text,
  ]) {
    const tag = bondTagForMemo(value);
    if (tag) {
      return tag;
    }
  }
  return null;
}

function isInfinityBondEventPayload(payload, row = {}) {
  return bondTagForEventPayload(payload, row)?.kind === INFINITY_BOND_KIND;
}

function normalizedBondTags(tags, bondTag) {
  const bondLabels = new Set(BOND_TAGS.map((tag) => tag.label.toLowerCase()));
  const normalized = [];
  for (const tag of Array.isArray(tags) ? tags : []) {
    const value = String(tag ?? "").trim();
    if (!value) {
      continue;
    }
    if (bondLabels.has(value.toLowerCase())) {
      continue;
    }
    normalized.push(/^message$/iu.test(value) ? bondTag.label : value);
  }
  if (!normalized.some((tag) => tag.toLowerCase() === bondTag.label.toLowerCase())) {
    normalized.push(bondTag.label);
  }
  return normalized;
}

function normalizedBondTitle(payload, row = {}, bondTag) {
  const title = normalizedText(payload?.title);
  if (title && !/^(?:mail|message)\b/iu.test(title)) {
    return title;
  }
  const confirmed = row.status
    ? normalizedLowerText(row.status) === "confirmed"
    : payload?.confirmed !== false;
  return `${bondTag.label} ${confirmed ? "sent" : "pending"}`;
}

function normalizeEventPayload(payload, row = {}) {
  const bondTag = bondTagForEventPayload(payload, row);
  if (!bondTag) {
    return payload;
  }
  return {
    ...payload,
    detail: normalizedText(payload?.detail) || bondTag.memo,
    kind: bondTag.kind,
    tags: normalizedBondTags(payload?.tags, bondTag),
    title: normalizedBondTitle(payload, row, bondTag),
  };
}

function eventKindSqlCondition(kind, addValue) {
  const normalizedKind = normalizedLowerText(kind);
  const bondTag = bondTagForKind(normalizedKind);
  if (!bondTag) {
    return `e.kind = ${addValue(normalizedKind)}`;
  }

  const bondKindParam = addValue(bondTag.kind);
  const mailKindParam = addValue("mail");
  const memoParam = addValue(bondTag.memo);
  return `
    (
      e.kind = ${bondKindParam}
      OR (
        e.kind = ${mailKindParam}
        AND (
          lower(coalesce(e.payload->>'detail', '')) = ${memoParam}
          OR lower(coalesce(e.payload->>'memo', '')) = ${memoParam}
          OR lower(coalesce(e.payload->>'body', '')) = ${memoParam}
          OR lower(coalesce(e.payload->>'message', '')) = ${memoParam}
        )
      )
    )
  `;
}

function valueSearchText(value) {
  if (value === null || value === undefined) {
    return "";
  }
  if (Array.isArray(value)) {
    return value.map(valueSearchText).join(" ");
  }
  if (typeof value === "object") {
    return Object.values(value).map(valueSearchText).join(" ");
  }
  return String(value);
}

function historyItemsMatchingQuery(items, query) {
  if (!query) {
    return items;
  }
  return items.filter((item) =>
    valueSearchText(item).toLowerCase().includes(query),
  );
}

function itemCreatedAtMs(item) {
  const parsed = Date.parse(item?.createdAt);
  return Number.isFinite(parsed) ? parsed : 0;
}

function compareHistoryItems(left, right) {
  return (
    itemCreatedAtMs(right) - itemCreatedAtMs(left) ||
    compareCanonicalUtf8(right?.txid, left?.txid)
  );
}

function historyActivityKey(item) {
  const blockHeight =
    item?.blockHeight !== undefined &&
    item?.blockHeight !== null &&
    item?.blockHeight !== "" &&
    Number.isSafeInteger(Number(item.blockHeight)) &&
    Number(item.blockHeight) >= 1
      ? Number(item.blockHeight)
      : null;
  const governedTokenActivity = normalizedLowerText(item?.kind).startsWith(
    "token-",
  );
  const legacyPositionExempt =
    item?.relic === true || item?.canonicalSynthetic === true;
  if (
    item?.confirmed === true &&
    governedTokenActivity &&
    blockHeight === null &&
    !legacyPositionExempt
  ) {
    throw new Error(
      "Canonical post-AMO-V5 activity position is incomplete.",
    );
  }
  if (
    item?.confirmed === true &&
    blockHeight !== null &&
    blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    const exactPositionInteger = (field) => {
      const value = item?.[field];
      return value !== undefined &&
        value !== null &&
        value !== "" &&
        Number.isSafeInteger(Number(value)) &&
        Number(value) >= 0
        ? Number(value)
        : null;
    };
    const blockIndex = exactPositionInteger("blockIndex");
    const protocolVout = exactPositionInteger("protocolVout");
    const recordOrdinal = exactPositionInteger("recordOrdinal");
    if (
      blockIndex === null ||
      protocolVout === null ||
      recordOrdinal === null
    ) {
      throw new Error(
        "Canonical post-AMO-V5 activity position is incomplete.",
      );
    }
    return [
      item?.network,
      item?.txid,
      "v5",
      blockHeight,
      blockIndex,
      protocolVout,
      recordOrdinal,
    ].join(":");
  }
  if (item?.kind === "token-listing-closed" && item?.txid) {
    return `${item.kind}:${item.network}:${item.txid}`;
  }

  return [
    item?.kind,
    item?.network,
    item?.txid,
    item?.listingId ?? "",
    item?.id ?? "",
  ].join(":");
}

function historyActivityRichness(item) {
  return [
    item?.title,
    item?.description,
    item?.detail,
    item?.listingId,
    item?.tokenId,
    item?.actor,
    item?.counterparty,
    ...(Array.isArray(item?.tags) ? item.tags : []),
    ...(Array.isArray(item?.participants) ? item.participants : []),
  ].filter(Boolean).length;
}

function eventKindTitle(kind, confirmed) {
  const label = String(kind ?? "")
    .split(/[-_]+/u)
    .filter(Boolean)
    .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join(" ");
  return `${label || "ProofOfWork event"} ${confirmed ? "confirmed" : "pending"}`;
}

function safeEventTags(item, network, confirmed) {
  const tags = (Array.isArray(item?.tags) ? item.tags : [])
    .map((tag) => normalizedText(tag))
    .filter(Boolean);
  if (tags.length > 0) {
    return tags;
  }

  return [
    confirmed ? "Confirmed" : "Pending",
    network === "livenet" ? "Mainnet" : network,
    normalizedText(item?.kind),
  ].filter(Boolean);
}

function normalizeHistoryEventItem(item, network, { publicOnly = false } = {}) {
  const kind = normalizedLowerText(item?.kind);
  if (
    publicOnly &&
    (item?.valid === false || !PUBLIC_LOG_EVENT_KINDS.has(kind))
  ) {
    return null;
  }

  const txid = normalizedLowerText(item?.txid);
  if (!txid) {
    return null;
  }

  const confirmed =
    typeof item?.confirmed === "boolean"
      ? item.confirmed
      : normalizedLowerText(item?.status) === "confirmed";
  const createdAt = dateIso(
    plausibleBitcoinEventTime(
      item?.createdAt,
      item?.blockTime,
      item?.timestamp,
      item?.confirmedAt,
      item?.indexedAt,
    ),
  );
  const title = normalizedText(item?.title) || eventKindTitle(kind, confirmed);
  const description =
    normalizedText(item?.description) ||
    normalizedText(item?.detail) ||
    `${title} for ${txid.slice(0, 8)}...${txid.slice(-8)}.`;

  return {
    ...item,
    confirmed,
    createdAt,
    description,
    kind,
    network: normalizedText(item?.network) || network,
    tags: safeEventTags(item, network, confirmed),
    title,
    txid,
  };
}

function normalizeHistoryEventRows(rows, network, options = {}) {
  const merged = new Map();

  for (const row of Array.isArray(rows) ? rows : []) {
    const item = normalizeHistoryEventItem(eventRowPayload(row, network), network, options);
    if (!item) {
      continue;
    }

    const key = historyActivityKey(item);
    const current = merged.get(key);
    if (
      !current ||
      (item.confirmed && !current.confirmed) ||
      (item.confirmed === current.confirmed &&
        historyActivityRichness(item) > historyActivityRichness(current))
    ) {
      merged.set(key, item);
    }
  }

  return [...merged.values()].sort(compareHistoryItems);
}

function indexedThroughBlockFromItems(items) {
  const heights = (Array.isArray(items) ? items : [])
    .map((item) => Number(item?.blockHeight))
    .filter((height) => Number.isSafeInteger(height) && height > 0);
  return heights.length > 0 ? Math.max(...heights) : undefined;
}

function completeStoredItems(storedPayload) {
  if (
    !storedPayload ||
    storedPayload.complete === false ||
    !Array.isArray(storedPayload.items)
  ) {
    return null;
  }
  if (
    storedPayload.items.length === 0 &&
    Number(storedPayload.totalCount ?? 0) > 0
  ) {
    return null;
  }
  return storedPayload.items;
}

function salePriceSats(sale) {
  const value = Number(
    sale?.priceSats ?? sale?.salePriceSats ?? sale?.amountSats ?? 0,
  );
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function salesStats(sales) {
  const items = Array.isArray(sales) ? sales : [];
  let confirmedSales = 0;
  let confirmedSalesVolumeSats = 0;
  let pendingSales = 0;
  let pendingSalesVolumeSats = 0;
  for (const sale of items) {
    if (sale?.confirmed) {
      confirmedSales += 1;
      confirmedSalesVolumeSats += salePriceSats(sale);
    } else {
      pendingSales += 1;
      pendingSalesVolumeSats += salePriceSats(sale);
    }
  }
  return {
    confirmedSales,
    confirmedSalesVolumeSats,
    pendingSales,
    pendingSalesVolumeSats,
    sales: confirmedSales + pendingSales,
    salesVolumeSats: confirmedSalesVolumeSats + pendingSalesVolumeSats,
  };
}

function uniqueTxidCount(items) {
  const txids = new Set();
  for (const item of Array.isArray(items) ? items : []) {
    const txid = String(item?.txid ?? "").trim().toLowerCase();
    if (/^[0-9a-f]{64}$/u.test(txid)) {
      txids.add(txid);
    }
  }
  return txids.size;
}

function normalizedStatus(status) {
  const value = String(status ?? "").toLowerCase();
  if (value === "confirmed" || value === "pending" || value === "dropped") {
    return value;
  }
  return value === "orphaned" ? "dropped" : "";
}

export async function proofIndexTxStatusPayload(txid, network, options = {}) {
  const pool = proofIndexPool();
  if (!pool) {
    return null;
  }

  const result = await pool.query(
    `
      SELECT
        transaction_row.txid,
        transaction_row.status,
        transaction_row.first_seen_at,
        transaction_row.confirmed_at,
        transaction_row.dropped_at,
        transaction_row.last_seen_at,
        transaction_row.updated_at,
        transaction_row.block_hash,
        transaction_row.block_height,
        transaction_row.block_time,
        CASE
          WHEN jsonb_typeof(transaction_row.raw_tx->'canonicalBlockScan') = 'object'
            AND transaction_row.raw_tx->'canonicalBlockScan'->>'network' = $1
            AND transaction_row.raw_tx->'canonicalBlockScan'->>'height' ~ '^[0-9]+$'
            AND (transaction_row.raw_tx->'canonicalBlockScan'->>'height')::integer =
              transaction_row.block_height
            AND transaction_row.raw_tx->'canonicalBlockScan'->>'blockHash' ~
              '^[0-9a-fA-F]{64}$'
            AND lower(transaction_row.raw_tx->'canonicalBlockScan'->>'blockHash') =
              lower(transaction_row.block_hash)
          THEN true
          ELSE false
        END AS canonical_scan_proof,
        canonical_block.canonical AS block_canonical
      FROM proof_indexer.transactions transaction_row
      LEFT JOIN proof_indexer.blocks canonical_block
        ON canonical_block.network = transaction_row.network
       AND canonical_block.block_hash = transaction_row.block_hash
       AND canonical_block.height = transaction_row.block_height
       AND canonical_block.canonical = true
      WHERE transaction_row.network = $1 AND transaction_row.txid = $2
      LIMIT 1
    `,
    [network, String(txid ?? "").toLowerCase()],
  );
  const row = result.rows[0];
  if (!row) {
    return null;
  }

  const status = normalizedStatus(row.status);
  if (!status) {
    return null;
  }
  const blockTimeMs = new Date(row.block_time ?? "").getTime();
  const blockTime = Number.isFinite(blockTimeMs)
    ? new Date(blockTimeMs).toISOString()
    : "";
  if (status === "confirmed") {
    const blockHeight = Number(row.block_height);
    const blockHash = String(row.block_hash ?? "").trim().toLowerCase();
    if (
      !Number.isSafeInteger(blockHeight) ||
      blockHeight <= 0 ||
      !/^[0-9a-f]{64}$/u.test(blockHash) ||
      row.block_canonical !== true ||
      row.canonical_scan_proof !== true ||
      !blockTime ||
      blockTimeMs < BITCOIN_GENESIS_TIME_MS
    ) {
      return null;
    }
  }
  if (status !== "confirmed" && !options.includeUnconfirmed) {
    return null;
  }

  const observedAt = dateIso(
    row.updated_at ?? row.confirmed_at ?? row.dropped_at ?? row.last_seen_at,
  );
  const payload = {
    confirmed: status === "confirmed",
    contract: "proof-of-work-tx-status-v2",
    indexedAt: observedAt,
    network,
    observedAt,
    sources: ["proof-indexer-canonical-block-scan"],
    status,
    txid: row.txid,
  };
  if (status === "confirmed") {
    return {
      ...payload,
      blockHash: String(row.block_hash).trim().toLowerCase(),
      blockHeight: Number(row.block_height),
      blockTime,
      canonical: true,
    };
  }
  if (status === "pending") {
    const firstSeenMs = new Date(row.first_seen_at ?? "").getTime();
    return {
      ...payload,
      ...(Number.isFinite(firstSeenMs) && firstSeenMs >= BITCOIN_GENESIS_TIME_MS
        ? { mempoolFirstSeenAt: new Date(firstSeenMs).toISOString() }
        : {}),
      mempoolSeen: true,
    };
  }
  return payload;
}

async function ledgerSnapshot(pool, network, snapshotId = "") {
  const pinnedSnapshotId = normalizedSnapshotId(snapshotId);
  if (pinnedSnapshotId) {
    const pinnedResult = await pool.query(
      `
        SELECT
          snapshot_id,
          generated_at,
          indexed_through_block,
          consistency,
          payload
        FROM proof_indexer.ledger_snapshots
        WHERE network = $1
          AND snapshot_id = $2
          AND payload->>'workAmountStorageModel' =
            ANY($3::text[])
        LIMIT 1
      `,
      [
        network,
        pinnedSnapshotId,
        [
          WORK_ATOMIC_PROJECTION_MODEL,
          WORK_SUBATOM_PROJECTION_MODEL,
        ],
      ],
    );
    return pinnedResult.rows[0] ?? null;
  }
  const workAmountStorageModel =
    await currentWorkAmountStorageModel(pool, network);
  if (!workAmountStorageModel) {
    return null;
  }

  const snapshotResult = await pool.query(
    `
      SELECT
        snapshot_id,
        generated_at,
        indexed_through_block,
        consistency,
        payload
      FROM proof_indexer.ledger_snapshots
      WHERE network = $1
        AND payload ? 'snapshotId'
        AND payload->>'workAmountStorageModel' = $2
      ORDER BY
        CASE
          WHEN payload->>'snapshotId' = snapshot_id
            AND payload ? 'activityPayload'
            AND payload ? 'registryHistoryPayloads'
            AND payload ? 'summaryPayloads'
            AND payload ? 'tokenHistoryPayloads'
            AND payload ? 'tokenStatePayloads'
          THEN 0
          ELSE 1
        END,
        generated_at DESC
      LIMIT 1
    `,
    [network, workAmountStorageModel],
  );
  return snapshotResult.rows[0] ?? null;
}

